/* شوية نجوم لامعة أكبر مع توهّج بسيط، بإيقاع لمعان مختلف تمامًا */
.prayer-sky-stars::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(1.9px 1.9px at 12.2% 44.7%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
    radial-gradient(2.2px 2.2px at 46.1% 84.7%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
    radial-gradient(2.1px 2.1px at 31.4% 84.6%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
    radial-gradient(2.4px 2.4px at 91.0% 65.5%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
