    radial-gradient(2.4px 2.4px at 56.0% 20.6%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
    radial-gradient(2.0px 2.0px at 37.4% 15.6%, #fff 0%, rgba(255,255,255,.35) 60%, transparent 100%),
