  left: 50%;
  bottom: 7px;
  transform: translateX(-50%);
  margin-top: 0;
}
.khatma-home-card-full .khatma-home-card-dots.hidden { display: none; }
.khatma-home-card-full .khatma-home-card-bottom-row {
  margin-top: 0;
  width: auto;
  flex-shrink: 0;
}
.khatma-home-card-full .khatma-home-card-kind { font-size: 9px; padding: 3px 8px; }
.khatma-home-card-full .khatma-home-card-live-badge { font-size: 9px; padding: 3px 8px 3px 6px; }

/* =========================================================================
   صفحة "أدوات المسلم" الكاملة + البار السفلي الخاص بها
   ========================================================================= */
.tools-page {
  /* مسافة فوق = ارتفاع هيدر العنوان الثابت الجديد (تحته) عشان أول كارت
     (مواقيت الصلاة) ميبدأش تحت العنوان المثبّت.
     ملحوظة: من غير + env(safe-area-inset-top) هنا عن قصد — الأب #app-main
     في وضع header-hidden (اللي الصفحة دي بتفتح فيه دايمًا) بيضيف الـ
     safe-area-inset-top ده أصلًا كـ padding-top بتاعه، فلو ضفناها هنا كمان
     هتتحسب مرتين وتبان مسافة فاضية كبيرة غلط بين العنوان والكارت (زي ما كان
     بيحصل على الموبايلات اللي عندها شريط حالة/notch) */
  padding-top: calc(var(--tools-title-h) + 4px);
  padding-bottom: calc(110px + env(safe-area-inset-bottom));
}

/* عنوان "أدوات المسلم": هيدر ثابت (Fixed) فعليًا فوق الصفحة كلها — مش جزء
   من المحتوى اللي بيعمل سكرول. الفرق عن position: sticky القديمة إن العنصر
   الثابت هنا خارج تدفق السكرول تمامًا، فمستحيل أي كارت/محتوى يظهر فوقه أو
   يومض فوقه لحظة السكرول السريع (زي ما كان بيحصل قبل كده)، ولأنه بارتفاع
   صغير مضبوط على ارتفاع الكلمة نفسها (مش هيدر التطبيق الكبير) بيوفر أكبر
   مساحة ممكنة لباقي الصفحة */
.tools-page-title {
  position: fixed;
  top: 0; left: 0; right: 0;
  max-width: 560px;
  margin: 0 auto;
  height: calc(var(--tools-title-h) + env(safe-area-inset-top));
  padding-top: env(safe-area-inset-top);
  display: flex;
  align-items: center;
  justify-content: flex-start;
  /* padding-inline-start (بدل padding-right) عشان الهامش يفضل قبل
     الكلمة دايمًا — يمين في RTL (عربي) وشمال في LTR (لما تتغيّر اللغة
     لإنجليزي أو أي لغة تانية بيتغيّر dir لـ #view-tools) — بدل ما
     يفضل مثبّت على اليمين بس فتلزق الكلمة في حافة الشمال في اللغات
     التانية */
  padding-inline-start: 16px;
  font-family: var(--font-ui);
  color: var(--brown-light);
  font-size: 27px;
  font-weight: 700;
  text-align: start;
  white-space: nowrap;
  background: var(--paper);
  z-index: 50;
}
.home-theme-switch {
  position: absolute;
  inset-inline-end: 16px;
  top: calc(env(safe-area-inset-top) + (var(--tools-title-h) - 42px) / 2);
  width: 42px;
  height: 42px;
  padding: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--ap-olive) 22%, var(--ap-line));
  border-radius: 50%;
  color: var(--ap-olive);
  background: color-mix(in srgb, var(--ap-card) 90%, transparent);
  box-shadow: 0 5px 15px rgba(39, 45, 28, .12), inset 0 1px 0 rgba(255,255,255,.72);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform .24s cubic-bezier(.2,.8,.2,1), color .3s ease, background .3s ease, box-shadow .3s ease;
}
.home-theme-switch:active { transform: scale(.9) rotate(-8deg); }
.home-theme-switch:focus-visible { outline: 3px solid color-mix(in srgb, var(--ap-gold) 68%, transparent); outline-offset: 3px; }
.theme-switch-icon { position: absolute; width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: opacity .28s ease, transform .48s cubic-bezier(.2,.8,.2,1); }
.theme-switch-sun { opacity: 1; transform: rotate(0) scale(1); }
.theme-switch-moon { opacity: 0; transform: rotate(-70deg) scale(.45); }
.home-theme-switch[data-night="true"] .theme-switch-sun { opacity: 0; transform: rotate(70deg) scale(.45); }
.home-theme-switch[data-night="true"] .theme-switch-moon { opacity: 1; transform: rotate(0) scale(1); }
.theme-switch-glint { position: absolute; inset: -45% auto -45% -85%; width: 45%; transform: rotate(24deg); background: linear-gradient(90deg, transparent, rgba(255,255,255,.72), transparent); opacity: 0; pointer-events: none; }
.home-theme-switch:active .theme-switch-glint { opacity: 1; animation: theme-switch-glint .55s ease; }
@keyframes theme-switch-glint { from { left: -85%; } to { left: 145%; } }
body.theme-night .home-theme-switch { color: #e5c779; border-color: rgba(229,199,121,.25); background: rgba(42,43,37,.9); box-shadow: 0 6px 18px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.08); }
@media (max-width: 380px) { .home-theme-switch { inset-inline-end: 12px; width: 38px; height: 38px; } .theme-switch-icon { width: 19px; height: 19px; } }
@media (prefers-reduced-motion: reduce) { .home-theme-switch, .theme-switch-icon { transition-duration: .01ms; } .home-theme-switch:active .theme-switch-glint { animation: none; } }
html.theme-transitioning body,
html.theme-transitioning body *:not(.home-theme-switch):not(.theme-switch-icon):not(.theme-switch-glint),
html.theme-transitioning body *:not(.home-theme-switch):not(.theme-switch-icon):not(.theme-switch-glint)::before,
html.theme-transitioning body *:not(.home-theme-switch):not(.theme-switch-icon):not(.theme-switch-glint)::after {
  transition: background-color .76s cubic-bezier(.2,.75,.2,1), color .76s cubic-bezier(.2,.75,.2,1), border-color .76s cubic-bezier(.2,.75,.2,1), box-shadow .76s cubic-bezier(.2,.75,.2,1), fill .76s cubic-bezier(.2,.75,.2,1), stroke .76s cubic-bezier(.2,.75,.2,1);
}
@supports (view-transition-name: root) {
  ::view-transition-group(root) { animation-duration: .82s; animation-timing-function: cubic-bezier(.2,.75,.2,1); }
  ::view-transition-old(root) { animation: none; }
  ::view-transition-new(root) { animation: theme-circle-reveal .82s cubic-bezier(.2,.75,.2,1) both; }
  @keyframes theme-circle-reveal { from { clip-path: circle(0 at var(--theme-switch-x, 50%) var(--theme-switch-y, 50%)); } to { clip-path: circle(160vmax at var(--theme-switch-x, 50%) var(--theme-switch-y, 50%)); } }
}
