  flex-direction: column;
}

.stats-week {
  padding: 22px 0;
  border-top: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
}
body.theme-night .stats-week { border-top-color: #363636; }
.stats-week:first-child { border-top: none; padding-top: 6px; }

.stats-week-range {
  font-size: 15px;
  font-weight: 700;
