  stroke-width: 9;
  stroke-linecap: round;
  stroke-dasharray: 0.1 13.5;
  opacity: .55;
}
.misbaha-progress-arc {
  fill: none;
  stroke: var(--gold);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 678.6;
  stroke-dashoffset: 678.6;
  transition: stroke-dashoffset .35s ease;
}
.misbaha-center-btn {
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 38%, #FFFFFF, #FFFFFF 70%);
  border: 1px solid var(--paper-line);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 22px rgba(90, 70, 30, .12), inset 0 1px 3px rgba(255,255,255,.6);
}
body.theme-night .misbaha-center-btn {
  background: radial-gradient(circle at 50% 38%, #1E1E1E, #141414 70%);
  box-shadow: 0 8px 22px rgba(0,0,0,.4);
}
.misbaha-center-btn:active { transform: scale(.96); }
.misbaha-center-count {
  font-family: var(--font-ui);
  font-size: 64px;
  font-weight: 800;
  color: var(--ink);
  line-height: 1;
}
.misbaha-target-pill {
  position: absolute;
  bottom: -42px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: 999px;
  background: var(--paper-deep);
  border: 1px solid var(--paper-line);
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  font-family: inherit;
  box-shadow: 0 4px 10px rgba(0,0,0,.08);
}
.misbaha-target-pill svg { width: 14px; height: 14px; color: var(--gold-deep); }
body.theme-night .misbaha-target-pill svg { color: var(--gold-soft); }
.misbaha-target-pill:active { transform: translateX(-50%) scale(.96); }

.misbaha-actions-row { display: flex; justify-content: center; margin-top: 2px; }

/* استبعاد الأخضر من مفتاح اختيار الهدف داخل شاشة التسبيح تحديدًا */
#tasbih-target-control .segmented-btn.active {
  background: linear-gradient(135deg, var(--gold-bright), var(--gold));
  color: var(--ink-fixed);
}

/* =========================================================================
   أقرب مسجد — خريطة تفاعلية حقيقية (Leaflet + بلاطات OpenStreetMap) بدل
   قائمة نصية بسيطة: خريطة ملء الشاشة + شريط علوي عائم + شيت سفلي قابل
   للسحب فيه قائمة المساجد + زرار "+" عائم لإضافة مسجد ناقص مباشرة لبيانات
   OpenStreetMap (عبر نظام الملاحظات الرسمي note الخاص بيها)
   ========================================================================= */
.mosque-map-page {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
  background: var(--paper-deep);
}

.mosque-map-canvas {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: #F0F2E8;
}
body.theme-night .mosque-map-canvas { background: #1a1a1a; }
/* بلاطات OSM بتبقى فاتحة دايمًا (صور خريطة حقيقية)، فبنلطّفها شوية بس في
   الوضع الداكن عشان ميضربش عين المستخدم وسط باقي واجهة داكنة */
body.theme-night .mosque-map-canvas .leaflet-tile-pane { filter: brightness(.8) saturate(1.05) invert(1) hue-rotate(180deg); }
.mosque-map-canvas .leaflet-control-attribution {
  font-size: 9.5px;
  background: rgba(251, 246, 231, .82);
  padding: 1px 6px;
}
body.theme-night .mosque-map-canvas .leaflet-control-attribution { background: rgba(20,20,20,.75); color: #ccc; }
body.theme-night .mosque-map-canvas .leaflet-control-attribution a { color: var(--gold-soft); }

/* ---- شريط علوي عائم شفّاف فوق الخريطة ---- */
.mosque-map-topbar {
  position: absolute;
  top: calc(12px + env(safe-area-inset-top));
  right: 14px; left: 14px;
  z-index: 500;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.mosque-map-title {
  display: flex;
  align-items: center;
  gap: 8px;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 9px 18px;
  border-radius: 999px;
  font-family: var(--font-ui);
  font-size: 15.5px;
  font-weight: 800;
  color: var(--ink);
  box-shadow: 0 4px 16px rgba(0,0,0,.14);
}
body.theme-night .mosque-map-title { background: color-mix(in srgb, var(--paper-deep) 85%, transparent); color: var(--gold-soft); }
.mosque-map-title-icon { display: flex; color: var(--gold-deep); }
.mosque-map-title-icon svg { width: 18px; height: 18px; }
body.theme-night .mosque-map-title-icon { color: var(--gold-soft); }

/* ---- أزرار عائمة دائرية (فابس) تُستخدم فوق الخريطة في أكتر من مكان ---- */
.mosque-fab {
  border: none;
  background: color-mix(in srgb, var(--paper) 92%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: var(--ink);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 4px 16px rgba(0,0,0,.16);
  flex-shrink: 0;
}
.mosque-fab:active { transform: scale(.92); }
body.theme-night .mosque-fab { background: color-mix(in srgb, var(--paper-deep) 88%, transparent); color: var(--ink); }
.mosque-fab-sm { width: 42px; height: 42px; border-radius: 50%; }
.mosque-fab-accent {
  background: var(--gold-deep);
  color: var(--paper);
}
body.theme-night .mosque-fab-accent { background: var(--gold); color: var(--paper-deep); }

.mosque-locate-fab {
  position: absolute;
  z-index: 500;
  width: 44px; height: 44px;
  border-radius: 50%;
  color: var(--gold-deep);
  bottom: calc(var(--mosque-sheet-h, 34vh) + 18px);
  left: 14px;
  transition: bottom .3s ease;
}
body.theme-night .mosque-locate-fab { color: var(--gold-soft); }
.mosque-map-page:has(#mosque-sheet.mosque-sheet-expanded) .mosque-locate-fab { bottom: calc(78vh + 18px); }

/* ---- الشيت السفلي القابل للسحب: قائمة المساجد ---- */
.mosque-sheet {
  --mosque-sheet-h: 34vh;
  position: absolute;
  z-index: 400;
  left: 0; right: 0; bottom: 0;
  height: var(--mosque-sheet-h);
  max-height: 78vh;
  background: var(--paper);
  border-radius: 22px 22px 0 0;
  box-shadow: 0 -8px 30px rgba(0,0,0,.18);
  display: flex;
  flex-direction: column;
  transition: height .32s cubic-bezier(.22,.9,.32,1);
  touch-action: none;
}
.mosque-sheet.mosque-sheet-expanded { height: 78vh; }
.mosque-sheet.mosque-sheet-dragging { transition: none; }
body.theme-night .mosque-sheet { background: var(--paper-deep); }

.mosque-sheet-handle {
  width: 100%;
  padding: 10px 0 4px;
  background: none;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  touch-action: none;
  cursor: grab;
}
.mosque-sheet-handle span {
  width: 40px; height: 4.5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--gold-deep) 35%, transparent);
  display: block;
}
body.theme-night .mosque-sheet-handle span { background: rgba(255,255,255,.22); }

.mosque-sheet-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 18px 10px;
  flex-shrink: 0;
}
#mosque-count-label {
  font-size: 15.5px;
  font-weight: 800;
  color: var(--ink);
}
body.theme-night #mosque-count-label { color: var(--gold-soft); }
.mosque-sheet-osm-badge {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--gold-deep);
  background: color-mix(in srgb, var(--gold-deep) 10%, transparent);
  padding: 4px 9px;
  border-radius: 999px;
  flex-shrink: 0;
  white-space: nowrap;
}
body.theme-night .mosque-sheet-osm-badge { color: var(--gold-soft); background: rgba(255,255,255,.08); }

.mosque-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 14px calc(16px + env(safe-area-inset-bottom));
}

.mosque-item-card {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--paper-deep);
  border: 1px solid transparent;
  border-radius: 16px;
  padding: 12px 14px;
  text-decoration: none;
}
.mosque-item-card:active { transform: scale(0.98); }
.mosque-item-card.mosque-item-active {
  border-color: color-mix(in srgb, var(--gold-deep) 45%, transparent);
  background: color-mix(in srgb, var(--gold-deep) 8%, var(--paper-deep));
}
body.theme-night .mosque-item-card { background: rgba(255,255,255,.05); }
body.theme-night .mosque-item-card.mosque-item-active { background: rgba(201,162,39,.14); border-color: color-mix(in srgb, var(--gold) 45%, transparent); }

.mosque-item-pin {
  width: 38px; height: 38px;
  flex-shrink: 0;
  border-radius: 11px;
  background: var(--gold-deep);
  color: var(--paper);
  display: flex; align-items: center; justify-content: center;
}
.mosque-item-pin svg { width: 19px; height: 19px; }
body.theme-night .mosque-item-pin { background: var(--gold); color: var(--paper-deep); }
.mosque-item-pin-mine { background: var(--emerald, #0B3D2E); }
body.theme-night .mosque-item-pin-mine { background: #2E8B57; color: #fff; }

.mosque-item-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: right;
}
.mosque-item-name {
  font-size: 15px;
  font-weight: 800;
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
body.theme-night .mosque-item-name { color: var(--gold-soft); }
.mosque-item-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-soft);
}
.mosque-item-distance { color: var(--gold-deep); }
body.theme-night .mosque-item-distance { color: var(--gold-soft); }
.mosque-item-pending-badge {
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
  background: var(--emerald, #0B3D2E);
  padding: 1px 7px;
  border-radius: 999px;
}
.mosque-item-directions {
  width: 34px; height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold-deep) 10%, transparent);
  color: var(--gold-deep);
  display: flex; align-items: center; justify-content: center;
}
body.theme-night .mosque-item-directions { color: var(--gold-soft); background: rgba(255,255,255,.08); }
.mosque-item-directions svg { width: 16px; height: 16px; }

.mosque-empty-state, .mosque-loading-state {
  text-align: center;
  padding: 30px 16px;
  color: var(--ink-soft);
  font-size: 13.5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.mosque-empty-state-icon { display: inline-grid; place-items: center; width: 34px; height: 34px; }
.mosque-empty-state-icon svg { width: 100%; height: 100%; fill: none !important; stroke: currentColor; }
.mosque-empty-state-icon svg path,
.mosque-empty-state-icon svg circle { fill: none !important; stroke: currentColor; }
.mosque-loading-spinner {
  width: 26px; height: 26px;
  border-radius: 50%;
  border: 3px solid rgba(139, 105, 20, .22);
  border-top-color: var(--gold-deep);
  animation: mosque-spin .8s linear infinite;
}
@keyframes mosque-spin { to { transform: rotate(360deg); } }
.mosque-fallback-link {
  font-size: 13px;
  font-weight: 700;
  color: var(--gold-deep);
  text-decoration: underline;
}
body.theme-night .mosque-fallback-link { color: var(--gold-soft); }

/* ---- تخصيص شكل الدبابيس والنوافذ المنبثقة الخاصة بـ Leaflet على الخريطة ---- */
.mosque-leaflet-pin { background: none; border: none; }
.mosque-leaflet-pin-inner {
  width: 34px; height: 34px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: var(--gold-deep);
  border: 2px solid var(--paper);
  box-shadow: 0 3px 8px rgba(0,0,0,.3);
  display: flex; align-items: center; justify-content: center;
}
.mosque-leaflet-pin-inner svg { transform: rotate(45deg); width: 17px; height: 17px; color: var(--paper); }
.mosque-leaflet-pin-mine .mosque-leaflet-pin-inner { background: var(--emerald, #0B3D2E); }
.mosque-leaflet-pin-user {
  display: block;
  width: 28px; height: 34px;
  fill: none;
  stroke: #2E7CF6;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 2px 3px rgba(0,0,0,.35));
}
.leaflet-popup-content-wrapper {
  background: var(--paper);
  border-radius: 14px;
  color: var(--ink);
  box-shadow: 0 6px 20px rgba(0,0,0,.22);
}
body.theme-night .leaflet-popup-content-wrapper { background: var(--paper-deep); color: var(--ink); }
.leaflet-popup-tip { background: var(--paper); }
body.theme-night .leaflet-popup-tip { background: var(--paper-deep); }
.mosque-popup { text-align: right; font-family: var(--font-ui); min-width: 150px; }
.mosque-popup-name { font-weight: 800; font-size: 14.5px; display: block; margin-bottom: 3px; }
.mosque-popup-dist { font-size: 12px; color: var(--gold-deep); font-weight: 700; display: block; margin-bottom: 8px; }
body.theme-night .mosque-popup-dist { color: var(--gold-soft); }
.mosque-popup-link {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 12.5px; font-weight: 800; color: #fff;
  background: var(--gold-deep); padding: 6px 12px; border-radius: 999px; text-decoration: none;
}

/* =========================================================================
   إضافة مسجد جديد إلى OpenStreetMap — صفحة كاملة تُحاكي تدفّق تطبيقات
   الخرائط المعروفة: خريطة بمؤشر ثابت في المنتصف + بطاقة معلومات + اسم
   المسجد، وعند "إضافة" يُرسل اقتراحًا كملاحظة (note) رسمية على
   OpenStreetMap يراجعها المتطوّعون، مع ظهوره فورًا على خريطتك كـ"مُقترح"
   ========================================================================= */
.mosque-add-sheet { display: flex; flex-direction: column; }
.mosque-add-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  flex-shrink: 0;
}
.mosque-add-topbar h3 { font-family: var(--font-ui); font-size: 19px; font-weight: 800; color: var(--ink); margin: 0; }
body.theme-night .mosque-add-topbar h3 { color: var(--gold-soft); }
.mosque-add-topbar-icon {
  width: 38px; height: 38px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--gold-deep) 12%, transparent);
  color: var(--gold-deep);
  display: flex; align-items: center; justify-content: center;
}
.mosque-add-topbar-icon svg { width: 19px; height: 19px; }
body.theme-night .mosque-add-topbar-icon { color: var(--gold-soft); }

.mosque-add-step {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 14px 0 10px;
  flex-shrink: 0;
}
.mosque-add-step-num {
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--gold-deep);
  color: var(--paper);
  font-size: 12.5px;
  font-weight: 800;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
body.theme-night .mosque-add-step-num { background: var(--gold); color: var(--paper-deep); }
.mosque-add-step-title { font-size: 15.5px; font-weight: 800; color: var(--ink); }
body.theme-night .mosque-add-step-title { color: var(--ink); }

.mosque-add-map-wrap {
  position: relative;
  height: 240px;
  border-radius: 20px;
  overflow: hidden;
  flex-shrink: 0;
  box-shadow: 0 4px 16px rgba(0,0,0,.14);
}
.mosque-add-map { position: absolute; inset: 0; }
body.theme-night .mosque-add-map .leaflet-tile-pane { filter: brightness(.8) saturate(1.05) invert(1) hue-rotate(180deg); }
.mosque-add-map-wrap .leaflet-control-attribution { font-size: 9px; }

.mosque-add-map-pin {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -100%);
  z-index: 450;
  pointer-events: none;
  display: flex; align-items: center; justify-content: center;
}
.mosque-add-map-pin-icon { position: relative; z-index: 2; filter: drop-shadow(0 3px 5px rgba(0,0,0,.35)); }
.mosque-add-map-pin-accuracy {
  position: absolute;
  bottom: 6px; left: 50%;
  transform: translateX(-50%);
  width: 70px; height: 70px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold-deep) 16%, transparent);
  border: 1.5px solid color-mix(in srgb, var(--gold-deep) 45%, transparent);
  animation: mosque-pin-pulse 2.2s ease-in-out infinite;
}
@keyframes mosque-pin-pulse { 0%,100% { opacity: .55; } 50% { opacity: 1; } }

.mosque-add-map-btn {
  position: absolute;
  z-index: 460;
  border: none;
  background: color-mix(in srgb, var(--paper) 94%, transparent);
  color: var(--gold-deep);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 3px 10px rgba(0,0,0,.2);
}
body.theme-night .mosque-add-map-btn { background: color-mix(in srgb, var(--paper-deep) 90%, transparent); color: var(--gold-soft); }
.mosque-add-locate-btn { width: 38px; height: 38px; border-radius: 50%; bottom: 10px; left: 10px; }
.mosque-add-map-zoom {
  position: absolute;
  top: 10px; left: 10px;
  z-index: 460;
  display: flex; flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 10px rgba(0,0,0,.2);
}
.mosque-add-map-zoom button {
  width: 32px; height: 32px;
  border: none;
  background: color-mix(in srgb, var(--paper) 94%, transparent);
  color: var(--gold-deep);
  font-size: 17px;
  font-weight: 800;
  line-height: 1;
}
body.theme-night .mosque-add-map-zoom button { background: color-mix(in srgb, var(--paper-deep) 90%, transparent); color: var(--gold-soft); }
.mosque-add-map-zoom button:first-child { border-bottom: 1px solid rgba(0,0,0,.08); }

.mosque-add-hint {
  font-size: 12px;
  color: var(--ink-soft);
  margin: 8px 2px 0;
  line-height: 1.6;
  flex-shrink: 0;
}

.mosque-add-info-card {
  background: var(--paper-deep);
  border-radius: 16px;
  padding: 4px 14px;
  margin-top: 12px;
  flex-shrink: 0;
}
body.theme-night .mosque-add-info-card { background: rgba(255,255,255,.05); }
.mosque-add-info-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--gold-deep) 12%, transparent);
}
body.theme-night .mosque-add-info-row { border-bottom-color: rgba(255,255,255,.08); }
.mosque-add-info-row:last-of-type { border-bottom: none; }
.mosque-add-info-label { font-size: 13px; font-weight: 700; color: var(--ink-soft); flex-shrink: 0; }
.mosque-add-info-value {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--ink);
  text-align: left;
  direction: ltr;
  unicode-bidi: plaintext;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
body.theme-night .mosque-add-info-value { color: var(--gold-soft); }
.mosque-add-info-note {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 10px 0 12px;
  font-size: 11.5px;
  color: var(--ink-soft);
  line-height: 1.6;
}
.mosque-add-info-note svg { flex-shrink: 0; margin-top: 1px; color: var(--gold-deep); }
body.theme-night .mosque-add-info-note svg { color: var(--gold-soft); }

.mosque-add-field { margin-bottom: 4px; flex-shrink: 0; }
.mosque-add-input {
  width: 100%;
  background: var(--paper-deep);
  border: 1.5px solid transparent;
  border-radius: 14px;
  padding: 14px 16px;
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
  text-align: right;
  font-family: var(--font-ui);
}
.mosque-add-input:focus { outline: none; border-color: var(--gold-deep); }
body.theme-night .mosque-add-input { background: rgba(255,255,255,.06); color: var(--ink); }
body.theme-night .mosque-add-input:focus { border-color: var(--gold); }
.mosque-add-input::placeholder { color: var(--ink-soft); opacity: .7; }

.mosque-add-submit-btn {
  margin-top: 16px;
  width: 100%;
  border: none;
  border-radius: 16px;
  padding: 16px;
  background: var(--gold-deep);
  color: var(--paper);
  font-family: var(--font-ui);
  font-size: 16px;
  font-weight: 800;
  flex-shrink: 0;
}
.mosque-add-submit-btn:active { opacity: .85; }
.mosque-add-submit-btn:disabled { background: color-mix(in srgb, var(--ink-soft) 30%, var(--paper-deep)); color: var(--ink-soft); }
body.theme-night .mosque-add-submit-btn { background: var(--gold); color: var(--paper-deep); }
body.theme-night .mosque-add-submit-btn:disabled { background: rgba(255,255,255,.08); color: var(--ink-soft); }

/* =========================================================================
   Toast الإشعارات المؤقتة — تصميم عصري هادي (كارت مستطيل ناعم الحواف
   بدرجات محايدة تتماشى مع باقي التطبيق) بدل الكبسولة البيضاوية الغامقة
   القديمة، مع نبضة أيقونة ذهبية صغيرة وحركة دخول ناعمة من أسفل
   ========================================================================= */
.toast {
  position: fixed;
  bottom: calc(env(safe-area-inset-bottom) + 20px);
  left: 50%;
  transform: translateX(-50%) translateY(14px) scale(.96);
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: rgba(255, 255, 255, .92);
  color: var(--ink);
  border: 1px solid rgba(139, 105, 20, .12);
  backdrop-filter: blur(20px) saturate(160%);
  -webkit-backdrop-filter: blur(20px) saturate(160%);
  box-shadow: 0 10px 30px -10px rgba(36, 22, 8, .22), 0 2px 8px rgba(36, 22, 8, .08);
  padding: 12px 16px;
  border-radius: 14px;
  font-family: var(--font-ui);
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.45;
  z-index: 300;
  opacity: 0;
  pointer-events: none;
  transition: opacity .28s cubic-bezier(.4,0,.2,1), transform .28s cubic-bezier(.4,0,.2,1);
  /* عرض واسع قريب من عرض الشاشة (زي إشعارات iOS/الأندرويد الحديثة) بدل
     مستطيل ضيّق بيرمي النص على أسطر كتير فوق بعض ويطوّل ارتفاع التوست
     رأسيًا؛ نفس منطق max-width: 430px المستخدم في باقي نوافذ التطبيق */
  width: calc(100% - 32px);
  max-width: 430px;
  box-sizing: border-box;
  text-align: start;
}
.toast::before {
  content: '';
  flex-shrink: 0;
  width: 7px;
  height: 7px;
  margin-top: 6px;
  border-radius: 50%;
  background: linear-gradient(155deg, var(--gold-bright), var(--gold-deep));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--gold-deep) 14%, transparent);
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0) scale(1); }

body.theme-night .toast {
  background: rgba(36, 36, 36, .92);
  color: var(--ink);
  border-color: rgba(255, 255, 255, .08);
  box-shadow: 0 10px 30px -10px rgba(0, 0, 0, .5), 0 2px 8px rgba(0, 0, 0, .25);
}

/* =========================================================================
   بانر الإشعار المنبثق (Pop-up) — يظهر أعلى الشاشة بشعار "أشرف" الدائري،
   بنفس أسلوب إشعارات واتساب/فيسبوك داخل التطبيق نفسه
   ========================================================================= */
.notif-popup {
  position: fixed;
  top: env(safe-area-inset-top, 10px);
  left: 10px;
  right: 10px;
  z-index: 500;
  display: flex;
  align-items: center;
  gap: 12px;
  background: linear-gradient(160deg, var(--paper-deep), var(--paper));
  border: 1px solid var(--gold);
  border-radius: 16px;
  padding: 12px 14px;
  box-shadow: 0 10px 28px rgba(0,0,0,.35);
  transform: translateY(calc(-100% - 20px));
  opacity: 0;
  transition: transform .32s cubic-bezier(.22,.61,.36,1), opacity .32s;
  pointer-events: none;
  max-width: 480px;
  margin: 0 auto;
}
.notif-popup.show {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}
.notif-popup-icon {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 0 0 1px rgba(201,162,39,.4);
}
.notif-popup-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}
.notif-popup-text strong {
  font-size: 14.5px;
  color: var(--mushaf-ink);
}
.notif-popup-text span {
  font-size: 12.5px;
  color: var(--gold-deep);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.notif-popup-close {
  flex-shrink: 0;
  width: 26px; height: 26px;
  border-radius: 50%;
  color: var(--gold-deep);
  background: rgba(201,162,39,.12);
  display: flex; align-items: center; justify-content: center;
  font-size: 12px;
}

/* =========================================================================
   بانر تثبيت التطبيق (PWA Install Banner) — نفس أسلوب notif-popup،
   يظهر أعلى الشاشة بزر "تثبيت" مباشر بدل قائمة المتصفح
   ========================================================================= */
.pwa-install-banner {
  position: fixed;
  top: env(safe-area-inset-top, 10px);
  left: 10px;
  right: 10px;
  z-index: 500;
  display: flex;
  align-items: center;
  gap: 10px;
  background: linear-gradient(160deg, var(--paper-deep), var(--paper));
  border: 1px solid var(--gold);
  border-radius: 16px;
  padding: 12px 14px;
  box-shadow: 0 10px 28px rgba(0,0,0,.35);
  transform: translateY(calc(-100% - 20px));
  opacity: 0;
  transition: transform .32s cubic-bezier(.22,.61,.36,1), opacity .32s;
  pointer-events: none;
  max-width: 480px;
  margin: 0 auto;
}
.pwa-install-banner.show {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}
.pwa-install-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  flex-shrink: 0;
  box-shadow: 0 0 0 1px rgba(201,162,39,.4);
}
.pwa-install-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}
.pwa-install-text strong {
  font-size: 14.5px;
  color: var(--mushaf-ink);
}
.pwa-install-text span {
  font-size: 12px;
  color: var(--gold-deep);
  line-height: 1.4;
}
.pwa-install-btn {
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--gold), var(--gold-deep));
  color: #fff;
  border: none;
  padding: 8px 16px;
  border-radius: 20px;
  font-weight: bold;
  font-size: 13px;
  white-space: nowrap;
  cursor: pointer;
}
.pwa-install-close {
  flex-shrink: 0;
  width: 26px; height: 26px;
  border-radius: 50%;
  color: var(--gold-deep);
  background: rgba(201,162,39,.12);
  display: flex; align-items: center; justify-content: center;
  font-size: 12px;
}

/* =========================================================================
   الاستجابة للشاشات (Responsive)
   ========================================================================= */
/* =========================================================================
   تبويب الحديث الشريف
   ========================================================================= */
.hadith-intro-note { margin: -4px 0 14px; }

.hadith-search-card {
  background: linear-gradient(160deg, var(--paper-deep), var(--paper));
  border: 1px solid var(--gold);
  border-radius: var(--radius-lg);
  padding: 16px;
  margin-bottom: 20px;
  box-shadow: 0 3px 12px rgba(0,0,0,.1);
}
.hadith-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,.5);
  border: 1px solid var(--paper-line);
  border-radius: 999px;
  padding: 10px 14px;
  margin-bottom: 12px;
}
body.theme-night .hadith-search-row { background: rgba(0,0,0,.2); }
.hadith-search-icon { width: 17px; height: 17px; color: var(--gold-deep); flex-shrink: 0; }
.hadith-search-input {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--font-ui);
  font-size: 14px;
  color: var(--ink);
}
body.theme-night .hadith-search-input { color: var(--gold-soft); }
.hadith-search-input::placeholder { color: var(--ink-soft); opacity: .7; }

.btn-primary {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: linear-gradient(135deg, var(--gold), var(--gold-deep));
  color: var(--emerald);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 14.5px;
  padding: 13px 16px;
  border-radius: 999px;
  box-shadow: 0 4px 12px rgba(0,0,0,.2);
  transition: transform .12s;
}
.btn-primary svg { width: 17px; height: 17px; }
.btn-primary:active { transform: scale(.97); }

/* محدد نطاق الآيات لمشاركتها كصورة واحدة */

.share-options-picker { display: flex; flex-direction: column; gap: 12px; }
.share-options-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.share-option-card {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 14px 12px; border: 1px solid var(--paper-line);
  border-radius: var(--radius-md); background: var(--paper-deep);
  color: var(--ink); text-align: right; font-family: inherit; cursor: pointer;
  transition: transform .15s ease, border-color .15s ease, background .15s ease;
}
.share-option-card:active { transform: scale(.98); }
.share-option-card:hover { border-color: var(--gold); background: rgba(201,162,39,.08); }
.share-option-icon { font-size: 25px; flex-shrink: 0; }
.share-option-card strong { display: block; font-size: 13.5px; margin-bottom: 3px; }
.share-option-card small { display: block; font-size: 10.5px; line-height: 1.5; color: var(--ink-soft); }
.share-video-reciter {
  width: 100%; padding: 10px 12px; border-radius: 12px;
  border: 1px solid var(--paper-line); background: var(--paper-deep);
  color: var(--ink); font-family: inherit; font-size: 13px;
}
@media (max-width: 430px) {
  .share-options-grid { grid-template-columns: 1fr; }
}
.share-range-picker { display: flex; flex-direction: column; gap: 12px; }
.share-range-row { display: flex; gap: 14px; }
.share-range-field { flex: 1; display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; color: var(--ink-soft); }
.share-range-field .time-input { width: 100%; text-align: center; font-size: 15px; padding: 9px 6px; }

.hadith-section-title {
  font-family: var(--font-display);
  color: var(--gold-soft);
  font-size: 16px;
  margin: 4px 2px 10px;
}

.hadith-links-card {
  background: linear-gradient(160deg, var(--paper-deep), var(--paper));
  border: 1px solid var(--paper-line);
  border-radius: var(--radius-lg);
  padding: 4px 14px;
  margin-bottom: 16px;
}
/* صف "كتب السنة" بقى بيتكوّن من طبقتين رأسيًا: صف علوي (أيقونة+نص+زر تحميل+
   سهم) وشريط تقدّم تحميل يظهر تحته فقط أثناء التحميل الفعلي، بدل الصف الأفقي
   المفرد القديم — عشان زر التحميل يقدر يظهر شريط تقدّمه من غير ما يكسر شكل
   الصف أو يحتاج <button> جوه <button> (كل من الصف والزر عناصر مستقلة) */
.hadith-link-row {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  cursor: default;
}
.hadith-row-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
}
.hadith-dl-actions {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}
/* صفوف خدمات الموسوعة الحديثية عناصر <a> (روابط لموقع الدرر السنية)، ومكانش
   عليها أي reset فكان المتصفح بيرسملها بخط أزرق تحتها ولون الرابط الافتراضي.
   بنشيل الخط واللون، ونرجّع الصف أفقي (السهم جنب النص) بدل عمودي زي صفوف
   كتب السنة (اللي بتحتاج شريط التقدّم تحت الصف) */
a.hadith-link-row,
a.hadith-link-row:link,
a.hadith-link-row:visited,
a.hadith-link-row:hover,
a.hadith-link-row:active {
  text-decoration: none;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}
a.hadith-link-row * { text-decoration: none; }
a.hadith-link-row {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
}
.hadith-link-arrow {
  width: 15px; height: 15px;
  color: var(--gold-deep);
  flex-shrink: 0;
  transform: scaleX(-1);
  opacity: .6;
}

/* زر تحميل/حذف الكتاب — دائرة صغيرة زي أزرار التحميل التانية في التطبيق */
.hadith-dl-btn {
  flex-shrink: 0;
  width: 30px; height: 30px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--ink-soft);
  background: rgba(0,0,0,.05);
}
body.theme-night .hadith-dl-btn { background: rgba(255,255,255,.08); }
.hadith-dl-btn svg { width: 16px; height: 16px; }
.hadith-dl-btn.is-downloaded { color: var(--gold-deep); background: color-mix(in srgb, var(--gold-deep) 14%, transparent); }
body.theme-night .hadith-dl-btn.is-downloaded { color: var(--gold-soft); }
.hadith-dl-btn.is-busy { opacity: .45; pointer-events: none; }

/* شريط تقدّم تحميل كتاب سنة كامل — نفس تقنية الخط المتحرك (indeterminate)
   المستخدَمة في تحميل سور التلاوات، لأن أول كتاب فرعي بياخد وقت قبل ما
   يخلص فيبان الشريط واقف على ٠٪ غير كده */
.hadith-dl-progress {
  display: none;
  align-items: center;
  gap: 8px;
  padding-bottom: 4px;
}
.hadith-dl-progress.active { display: flex; }
.hadith-dl-progress-track {
  flex: 1 1 auto;
  height: 6px;
  min-width: 40px;
  border-radius: 999px;
  background: rgba(139,105,20,.16);
  overflow: hidden;
}
body.theme-night .hadith-dl-progress-track { background: rgba(255,255,255,.16); }
.hadith-dl-progress-fill {
  height: 100%;
  width: 0%;
  background: var(--gold-deep);
  border-radius: 999px;
  transition: width .18s linear;
}
.hadith-dl-progress-track.indeterminate .hadith-dl-progress-fill {
  width: 100% !important;
  transition: none;
  background-color: var(--gold-deep);
  background-image: repeating-linear-gradient(
    45deg,
    rgba(255,255,255,.55) 0, rgba(255,255,255,.55) 8px,
    transparent 8px, transparent 16px
  );
  background-size: 32px 32px;
  animation: surah-dl-indeterminate .9s linear infinite;
}
.hadith-dl-progress-label {
  flex-shrink: 0;
  font-family: var(--font-ui);
  font-size: 11.5px;
  color: var(--ink-soft);
  white-space: nowrap;
}
.hadith-dl-cancel {
  flex-shrink: 0;
  width: 22px; height: 22px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--ink-soft);
  background: rgba(0,0,0,.06);
}
body.theme-night .hadith-dl-cancel { background: rgba(255,255,255,.1); }
.hadith-dl-cancel svg { width: 12px; height: 12px; }

.hadith-trust-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: rgba(27, 110, 81, .08);
  border: 1px dashed var(--emerald-light);
  border-radius: var(--radius-md);
  padding: 12px 14px;
}
body.theme-night .hadith-trust-note { background: rgba(234,201,108,.06); }
.hadith-trust-note .opt-icon { font-size: 16px; flex-shrink: 0; margin-top: 1px; }
.hadith-trust-note p { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-soft); }
body.theme-night .hadith-trust-note p { color: rgba(234,201,108,.75); }

@media (max-width: 360px) {
  .mushaf-text { font-size: calc(19px * var(--ayah-font-scale) * var(--autofit-scale)); }
  .p-name { font-size: 10px; }
  .p-time { font-size: 11px; }
  .next-prayer-time-big { font-size: 34px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

/* =========================================================================
   تسميع القرآن — اختبار الحفظ بالتعرّف الصوتي
   ========================================================================= */
.memorization-mode-sheet,
.written-quiz-sheet {
  --ap-bg: #FFFFFF;
  --ap-card: #FFFFFF;
  --ap-line: rgba(90, 84, 60, .11);
  --ap-ink: #211F1A;
  --ap-ink-2: #5A574D;
  --ap-ink-3: #8E8A7D;
  --ap-olive: #6F7752;
  --ap-olive-soft: #F0F2E8;
  --ap-gold: #B8892B;
  --ap-gold-soft: rgba(184, 137, 43, .14);
  --ap-font: 'Tajawal', sans-serif;
  max-width: 500px;
  max-height: 88vh;
  overflow-y: auto;
  padding: 14px 16px calc(20px + env(safe-area-inset-bottom));
  color: var(--ap-ink);
  background: var(--ap-bg);
  font-family: var(--ap-font);
}
.memorization-mode-sheet .overlay-head,
.written-quiz-sheet .overlay-head { align-items: center; margin-bottom: 12px; }
.memorization-mode-sheet .overlay-head h3,
.written-quiz-sheet .overlay-head h3 { color: var(--ap-ink); font: 700 18px/1.4 var(--ap-font); }
.memorization-mode-caption,
.written-quiz-caption { margin: 3px 0 0; color: var(--ap-ink-2); font: 12px/1.5 var(--ap-font); }
.memorization-mode-options { display: grid; gap: 9px; }
.memorization-mode-option {
  display: flex; align-items: center; gap: 11px; width: 100%; min-height: 70px;
  padding: 10px 12px; text-align: right; color: var(--ap-ink);
  background: var(--ap-card); border: 1px solid var(--ap-line);
  border-radius: 17px; font-family: var(--ap-font); cursor: pointer; transition: border-color .18s ease, transform .18s ease;
}
.memorization-mode-option:active { transform: scale(.99); }
.memorization-mode-option:hover { border-color: var(--ap-olive); }
.memorization-mode-icon { display: grid; place-items: center; width: 42px; height: 42px; flex: 0 0 42px; border-radius: 14px; color: var(--ap-olive); background: var(--ap-olive-soft); }
.memorization-mode-icon--written { color: var(--ap-gold); background: var(--ap-gold-soft); }
.memorization-mode-icon svg { width: 21px; height: 21px; }
.memorization-mode-copy { display: grid; gap: 3px; flex: 1 1 auto; min-width: 0; }
.memorization-mode-copy strong { font: 700 14px/1.4 var(--font-ui); }
.memorization-mode-copy small { color: var(--ap-ink-2); font: 11px/1.45 var(--ap-font); }
.memorization-mode-arrow { width: 15px; height: 15px; flex: 0 0 15px; color: var(--ap-ink-3); }

.written-quiz-sheet [hidden] { display: none !important; }
.written-quiz-setup { display: grid; gap: 11px; }
.written-quiz-field { display: grid; gap: 5px; color: var(--ap-ink-2); font: 600 12px/1.4 var(--ap-font); }
.written-quiz-field select {
  width: 100%; min-height: 42px; padding: 8px 11px; color: var(--ap-ink);
  background: var(--ap-card); border: 1px solid var(--ap-line);
  border-radius: 12px; font: 13px var(--ap-font); outline: none;
}
.written-quiz-field select:focus { border-color: var(--ap-gold); box-shadow: 0 0 0 3px var(--ap-gold-soft); }
.written-quiz-note,
.written-quiz-loading { margin: 0; color: var(--ap-ink-2); font: 11px/1.6 var(--ap-font); }
.written-quiz-loading { text-align: center; }
.written-quiz-primary,
.written-quiz-secondary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px;
  padding: 8px 14px; border: 0; border-radius: 13px; font: 700 13px var(--ap-font); cursor: pointer;
}
.written-quiz-primary { color: #fff; background: var(--ap-olive); }
.written-quiz-primary:disabled { opacity: .45; cursor: default; }
.written-quiz-primary svg { width: 15px; height: 15px; }
.written-quiz-secondary { color: var(--ap-ink); background: var(--ap-olive-soft); border: 1px solid var(--ap-line); font-family: var(--ap-font); }
.written-quiz-play { display: grid; gap: 10px; }
.written-quiz-progress-row { display: flex; justify-content: space-between; gap: 10px; color: var(--ap-ink-2); font: 600 11px var(--ap-font); }
.written-quiz-progress-track { height: 4px; overflow: hidden; border-radius: 9px; background: var(--ap-olive-soft); }
.written-quiz-progress-track span { display: block; width: 0; height: 100%; border-radius: inherit; background: var(--ap-gold); transition: width .25s ease; }
.written-quiz-ayah-card { padding: 12px 13px 13px; border: 1px solid var(--ap-line); border-radius: 16px; background: var(--ap-card); }
.written-quiz-ayah-number { display: inline-flex; padding: 3px 8px; border-radius: 999px; color: var(--ap-olive); background: var(--ap-olive-soft); font: 600 10px var(--ap-font); }
.written-quiz-ayah-text { margin: 9px 0 0; color: var(--ap-ink); text-align: justify; font: 22px/2 var(--font-quran, 'Amiri Quran', serif); }
.written-quiz-blank { display: inline-block; min-width: 58px; margin: 0 3px; color: var(--ap-gold); text-align: center; border-bottom: 2px dashed var(--ap-gold); line-height: 1.1; vertical-align: baseline; }
.written-quiz-feedback { min-height: 18px; margin: 0; color: var(--ap-ink-2); text-align: center; font: 11px/1.5 var(--ap-font); }
.written-quiz-feedback.is-correct { color: var(--ap-olive); }
.written-quiz-feedback.is-wrong { color: var(--ruby); }
.written-quiz-choices { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 7px; }
.written-quiz-choice { min-width: 0; min-height: 44px; padding: 7px 8px; color: var(--ap-ink); background: var(--ap-card); border: 1px solid var(--ap-line); border-radius: 12px; font: 600 15px/1.5 var(--font-quran, 'Amiri Quran', serif); cursor: pointer; transition: background .18s ease, border-color .18s ease; }
.written-quiz-choice:disabled { cursor: default; }
.written-quiz-choice.is-correct { color: var(--ap-olive); background: var(--ap-olive-soft); border-color: var(--ap-olive); }
.written-quiz-choice.is-wrong { color: var(--ruby); background: rgba(122,35,49,.09); border-color: var(--ruby); }
.written-quiz-result { padding: 10px 0 2px; text-align: center; }
.written-quiz-result-mark { display: grid; place-items: center; width: 52px; height: 52px; margin: 0 auto 7px; border-radius: 50%; color: var(--ap-olive); background: var(--ap-olive-soft); }
.written-quiz-result-mark svg { width: 27px; height: 27px; }
.written-quiz-result-kicker { margin: 0; color: var(--ink-soft); font: 12px var(--font-ui); }
.written-quiz-result h4 { margin: 4px 0; color: var(--ap-olive); font: 800 22px var(--ap-font); }
.written-quiz-result > p:last-of-type { margin: 0 0 13px; color: var(--ap-ink-2); font: 12px var(--ap-font); }
.written-quiz-result-actions { display: grid; gap: 7px; }
body.theme-night .memorization-mode-sheet,
body.theme-night .written-quiz-sheet {
  --ap-bg: #121211; --ap-card: #1C1C1A; --ap-line: rgba(255,255,255,.08);
  --ap-ink: #EFEDE6; --ap-ink-2: #B5B2A6; --ap-ink-3: #85826F;
  --ap-olive: #98A278; --ap-olive-soft: #262820; --ap-gold: #D6AE55; --ap-gold-soft: rgba(214,174,85,.16);
}
body.theme-night .written-quiz-primary { color: #15160f; }
@media (max-width: 420px) {
  .memorization-mode-sheet, .written-quiz-sheet { padding-right: 13px; padding-left: 13px; }
  .written-quiz-ayah-text { font-size: 20px; }
  .written-quiz-choice { font-size: 14px; }
}

.tasmee-sheet {
  max-height: 92vh;
  padding-top: 14px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
body:not(.theme-night) #tasmee-overlay .tasmee-sheet { background: var(--ap-bg, #FFFFFF); }

.tasmee-steps-head { margin-bottom: 14px; flex-shrink: 0; }
.tasmee-dots { display: flex; align-items: center; justify-content: center; gap: 8px; margin-bottom: 10px; }
.tasmee-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--paper-line);
  transition: all .25s ease;
}
.tasmee-dot.tasmee-dot-active { width: 26px; border-radius: 5px; background: var(--gold-deep); }
.tasmee-dot.tasmee-dot-done { background: var(--emerald-light); }
body.theme-night .tasmee-dot.tasmee-dot-active { background: var(--gold); }
.tasmee-step-label { text-align: center; font-family: var(--font-ui); font-size: 13.5px; color: var(--ink-soft); margin: 0; }

.tasmee-step { display: none; }
.tasmee-step.active {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1 1 auto;
  animation: tasmee-fade-in .25s ease;
}
@keyframes tasmee-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

/* المحتوى القابل للتمرير داخل كل خطوة، مع إبقاء أزرار التنقّل (تالي/سابق) ثابتة
   وظاهرة دائمًا أسفل الشاشة دون الحاجة للنزول لآخر القائمة للوصول إليها */
.tasmee-step-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 4px;
}

.tasmee-step .tasmee-nav-row {
  flex-shrink: 0;
  padding-top: 12px;
  margin-top: 4px;
  border-top: 1px solid var(--paper-line);
}

/* الخطوة ١: اختيار السورة */
#tasmee-surah-list .surah-item.tasmee-item-selected {
  background: rgba(201, 162, 39, 0.16);
  border-radius: var(--radius-md);
}
#tasmee-surah-list .surah-item.tasmee-item-selected .surah-item-num {
  background: var(--gold-deep); color: var(--paper);
}
body.theme-night #tasmee-surah-list .surah-item.tasmee-item-selected .surah-item-num { background: var(--gold); color: var(--emerald); }

/* الخطوة ٢: خيارات التسميع */
.tasmee-selected-surah-card {
  display: flex; align-items: center; justify-content: space-between;
  background: rgba(201, 162, 39, 0.1);
  border: 1px solid var(--gold);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  margin-bottom: 14px;
}
.tasmee-selected-surah-card strong { display: block; font-family: var(--font-display); font-size: 18px; color: var(--emerald); }
body.theme-night .tasmee-selected-surah-card strong { color: var(--gold-soft); }
.tasmee-num-badge {
  min-width: 34px; height: 34px; padding: 0 6px;
  display: flex; align-items: center; justify-content: center;
  background: var(--gold-deep); color: var(--paper);
  border-radius: 50%; font-weight: 700; font-family: var(--font-ui);
}

.tasmee-range-row { display: flex; gap: 12px; margin-bottom: 14px; }
.tasmee-range-field { flex: 1 1 0; display: flex; flex-direction: column; gap: 6px; font-family: var(--font-ui); font-size: 13px; color: var(--ink-soft); }
.tasmee-range-field select {
  padding: 10px 10px; border-radius: var(--radius-md); border: 1px solid var(--paper-line);
  background: var(--paper-deep); color: var(--ink); font-family: var(--font-ui); font-size: 15px; font-weight: 700;
}

.tasmee-toggle-row { padding: 10px 2px; border-bottom: 1px solid var(--paper-line); margin-bottom: 12px; }
.tasmee-level-title { margin: 0 0 8px; }
.tasmee-level-group { display: flex; gap: 8px; margin-bottom: 14px; }
.tasmee-level-btn {
  flex: 1 1 0; padding: 11px 6px; border-radius: var(--radius-md);
  border: 1px solid var(--paper-line); background: var(--paper-deep);
  color: var(--ink); font-family: var(--font-ui); font-size: 14px; font-weight: 700;
}
.tasmee-level-btn.active { background: var(--emerald); color: var(--gold-soft); border-color: var(--emerald); }

.tasmee-offline-note {
  display: flex; align-items: center; gap: 8px;
  background: rgba(201, 162, 39, 0.08); border-radius: var(--radius-md);
  padding: 10px 12px; margin: 0 0 16px; font-size: 12.5px; color: var(--ink-soft);
}
.tasmee-dot-live { width: 8px; height: 8px; border-radius: 50%; background: var(--emerald-light); flex-shrink: 0; }

.tasmee-nav-row { display: flex; gap: 10px; }
.tasmee-nav-btn {
  flex: 1 1 0; display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 13px 10px; border-radius: var(--radius-md); font-family: var(--font-ui); font-size: 15px; font-weight: 700;
}
.tasmee-nav-btn svg { width: 16px; height: 16px; }
.tasmee-nav-primary { background: var(--gold-deep); color: var(--paper); }
.tasmee-nav-secondary { background: var(--paper-deep); color: var(--ink); border: 1px solid var(--paper-line); }
.tasmee-nav-btn:disabled { opacity: .5; pointer-events: none; }

/* الخطوة ٣: التسميع الفعلي */
.tasmee-recite-head {
  display: flex; align-items: center; justify-content: space-between;
  font-family: var(--font-display); color: var(--emerald); font-size: 16px; margin-bottom: 10px;
}
body.theme-night .tasmee-recite-head { color: var(--gold-soft); }
#tasmee-recite-progress { font-family: var(--font-ui); font-size: 13px; color: var(--ink-soft); }

.tasmee-recite-card {
  min-height: 160px;
  background: var(--paper-deep);
  border: 1px solid var(--paper-line);
  border-radius: var(--radius-lg);
  padding: 20px 18px;
  margin-bottom: 12px;
  display: flex; align-items: center; justify-content: center;
}
.tasmee-recite-text {
  margin: 0; text-align: center; direction: rtl;
  font-family: var(--font-quran); font-size: 26px; line-height: 2.3;
  color: var(--ink);
}
.tasmee-recite-text .tw-word { display: inline-block; padding: 1px 3px; border-radius: 6px; transition: all .2s ease; }
.tasmee-recite-text .tw-correct { background: rgba(27, 110, 81, .18); color: var(--emerald-light); }
.tasmee-recite-text .tw-current { border-bottom: 3px dashed var(--ruby); animation: tasmee-pulse 1s ease-in-out infinite; }
.tasmee-recite-text .tw-pending { color: var(--ink); }
.tasmee-recite-text .tw-hidden { color: transparent; background: var(--paper-line); border-radius: 6px; user-select: none; }
.tasmee-recite-text .tw-hidden.tw-current { background: var(--gold-bright); }
@keyframes tasmee-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }

.tasmee-recite-status { text-align: center; font-family: var(--font-ui); font-size: 13.5px; color: var(--ink-soft); min-height: 18px; margin: 0 0 14px; }

.tasmee-mic-wrap { display: flex; justify-content: center; margin-bottom: 16px; }
.tasmee-mic-btn {
  width: 78px; height: 78px; border-radius: 50%;
  background: var(--ruby); color: #fff;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 6px 22px rgba(122,35,49,.4);
}
.tasmee-mic-btn svg { width: 30px; height: 30px; }
.tasmee-mic-btn.listening { background: var(--emerald-light); animation: tasmee-mic-glow 1.4s ease-in-out infinite; }
@keyframes tasmee-mic-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(27,110,81,.5); }
  50% { box-shadow: 0 0 0 14px rgba(27,110,81,0); }
}
.tasmee-finish-btn {
  display: block; width: 100%; padding: 13px; border-radius: var(--radius-md);
  background: rgba(122,35,49,.1); color: var(--ruby); border: 1px solid rgba(122,35,49,.3);
  font-family: var(--font-ui); font-size: 15px; font-weight: 700;
}

/* الخطوة ٤: النتيجة */
.tasmee-result-ring-wrap { position: relative; width: 150px; height: 150px; margin: 6px auto 6px; }
.tasmee-result-ring { width: 150px; height: 150px; transform: rotate(-90deg); }
.tasmee-ring-bg { fill: none; stroke: var(--paper-deep); stroke-width: 12; }
.tasmee-ring-fill {
  fill: none; stroke: var(--emerald-light); stroke-width: 12; stroke-linecap: round;
  stroke-dasharray: 377; stroke-dashoffset: 377; transition: stroke-dashoffset .7s ease;
}
.tasmee-result-ring-center {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
}
.tasmee-result-book { width: 26px; height: 26px; color: var(--emerald-light); }
#tasmee-result-percent { font-family: var(--font-ui); font-size: 30px; font-weight: 900; color: var(--emerald-light); }
.tasmee-result-badge {
  display: block; width: fit-content; margin: 0 auto 18px;
  background: rgba(27,110,81,.12); color: var(--emerald-light);
  padding: 6px 18px; border-radius: 999px; font-family: var(--font-ui); font-weight: 700; font-size: 14px;
}

.tasmee-stats-row { display: flex; gap: 10px; margin-bottom: 18px; }
.tasmee-stat-card {
  flex: 1 1 0; display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 14px 6px; border-radius: var(--radius-md); border: 1px solid var(--paper-line);
  background: var(--paper-deep);
}
.tasmee-stat-card span { font-size: 26px; font-weight: 900; font-family: var(--font-ui); }
.tasmee-stat-card small { font-size: 12.5px; color: var(--ink-soft); font-family: var(--font-ui); }
.tasmee-stat-total span { color: var(--gold-deep); }
.tasmee-stat-wrong { background: rgba(122,35,49,.08); border-color: rgba(122,35,49,.25); }
.tasmee-stat-wrong span { color: var(--ruby); }
.tasmee-stat-correct { background: rgba(27,110,81,.08); border-color: rgba(27,110,81,.25); }
.tasmee-stat-correct span { color: var(--emerald-light); }

.tasmee-errors-wrap { margin-bottom: 18px; }
.tasmee-errors-title {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-ui); font-size: 15px; color: var(--ink); margin: 0 0 10px;
}
.tasmee-errors-count {
  background: rgba(122,35,49,.14); color: var(--ruby); border-radius: 999px;
  min-width: 22px; height: 22px; display: inline-flex; align-items: center; justify-content: center;
  font-size: 12.5px; font-weight: 700;
}
.tasmee-error-card {
  background: rgba(122,35,49,.05); border: 1px solid rgba(122,35,49,.2);
  border-radius: var(--radius-md); padding: 12px 14px; margin-bottom: 10px;
}
.tasmee-error-ayah-num {
  display: inline-block; background: rgba(122,35,49,.12); color: var(--ruby);
  font-size: 12px; font-weight: 700; padding: 2px 10px; border-radius: 999px; margin-bottom: 8px; font-family: var(--font-ui);
}
.tasmee-error-said, .tasmee-error-correct {
  display: flex; align-items: flex-start; gap: 8px; font-family: var(--font-quran); font-size: 18px; line-height: 1.9; margin: 4px 0;
}
.tasmee-error-said { color: var(--ruby); }
.tasmee-error-correct { color: var(--emerald-light); }
.tasmee-error-said svg, .tasmee-error-correct svg { width: 16px; height: 16px; flex-shrink: 0; margin-top: 6px; }

@media (prefers-reduced-motion: reduce) {
  .tasmee-mic-btn.listening, .tasmee-recite-text .tw-current { animation: none !important; }
}

/* =========================================================================
   تسميع مباشر فوق صفحة المصحف نفسها: بدل بطاقة نص منفصلة، بنطبّق نفس
   كلاسات tw-word/tw-correct/tw-current/tw-hidden مباشرة على كلمات المصحف
   الحقيقية (.qcf-word) أثناء القراءة، فتُكتب/تُظلَّم كل كلمة في مكانها
   بالظبط زي المصحف المطبوع، بدل عرضها في كارت نص عادي منفصل
   ========================================================================= */
.qcf-word.tw-correct { background: rgba(27, 110, 81, .18); border-radius: 6px; }
body.theme-night .qcf-word.tw-correct { background: rgba(196, 165, 92, .22); }
.qcf-word.tw-current { position: relative; }
.qcf-word.tw-current::after {
  content: ''; position: absolute; left: 6%; right: 6%; bottom: -2px; height: 3px;
  border-radius: 2px; background: var(--ruby); animation: tasmee-pulse 1s ease-in-out infinite;
}
.qcf-word.tw-hidden { color: transparent !important; background: var(--paper-line); border-radius: 6px; user-select: none; }
.qcf-word.tw-hidden.tw-current { background: var(--gold-bright); }
.susi-ayah.tw-hidden { color: transparent !important; text-shadow: none !important; user-select: none; }
.susi-ayah.tw-hidden.tw-current { background: color-mix(in srgb, var(--gold-bright) 18%, transparent); }

@media (prefers-reduced-motion: reduce) {
  .qcf-word.tw-current::after { animation: none !important; }
}

/* الشريط العلوي الرفيع أثناء التسميع المباشر: اسم السورة/التقدّم + إغلاق + إعادة الآية */
.tasmee-live-top {
  position: fixed; top: env(safe-area-inset-top); left: 50%; transform: translateX(-50%);
  width: calc(100% - 24px); max-width: 430px; z-index: 151;
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  background: var(--paper); border-radius: 0 0 18px 18px;
  padding: 10px 14px; box-shadow: 0 8px 20px color-mix(in srgb, var(--shadow) 30%, transparent);
}
.tasmee-live-bar.hidden, .tasmee-live-top.hidden { display: none; }
.tasmee-live-icon-btn {
  width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  background: var(--paper-deep); color: var(--ink); flex-shrink: 0;
}
.tasmee-live-icon-btn svg { width: 18px; height: 18px; }
.tasmee-live-title { display: flex; flex-direction: column; align-items: center; gap: 1px; text-align: center; }
.tasmee-live-title strong { font-family: var(--font-display); font-size: 16px; color: var(--emerald); }
body.theme-night .tasmee-live-title strong { color: var(--gold-soft); }
#tasmee-live-progress { font-family: var(--font-ui); font-size: 12px; color: var(--ink-soft); }

/* الشريط السفلي العائم: مايك/إيقاف مؤقت كبير + إظهار/إخفاء النص + إنهاء */
.tasmee-live-bar {
  position: fixed; bottom: calc(env(safe-area-inset-bottom) + 16px); left: 50%; transform: translateX(-50%);
  width: calc(100% - 24px); max-width: 430px; z-index: 151;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
}
.tasmee-live-status {
  position: fixed; bottom: calc(env(safe-area-inset-bottom) + 110px); left: 50%; transform: translateX(-50%);
  z-index: 151; font-family: var(--font-ui); font-size: 13px; color: var(--ink-soft);
  background: var(--paper); padding: 5px 14px; border-radius: 999px;
  box-shadow: 0 6px 16px color-mix(in srgb, var(--shadow) 26%, transparent);
  white-space: nowrap;
}
.tasmee-live-transcript {
  position: fixed; bottom: calc(env(safe-area-inset-bottom) + 166px); left: 50%; transform: translateX(-50%);
  z-index: 151; width: min(calc(100% - 28px), 440px); max-height: 112px; overflow: auto;
  padding: 9px 13px; border: 1px solid color-mix(in srgb, var(--gold-soft) 35%, transparent); border-radius: 14px;
  background: color-mix(in srgb, var(--paper) 96%, transparent); color: var(--ink); box-shadow: 0 8px 20px color-mix(in srgb, var(--shadow) 28%, transparent);
  -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
}
.tasmee-transcript-label { display: block; margin-bottom: 4px; color: var(--ink-soft); font: 600 10px/1.4 var(--font-ui); }
#tasmee-live-heard-text { margin: 0; font: 14px/1.8 'Amiri', serif; overflow-wrap: anywhere; }
.tasmee-live-transcript.hidden { display: none; }
.tasmee-transcript-result { margin: 18px 0; padding: 14px; border: 1px solid var(--border, rgba(190,164,104,.2)); border-radius: 16px; background: color-mix(in srgb, var(--paper-deep) 52%, transparent); }
.tasmee-transcript-result-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.tasmee-transcript-result-head h4 { margin: 0; color: var(--ink); font-family: var(--font-display); }
.tasmee-transcript-result-head button { padding: 7px 12px; border: 1px solid color-mix(in srgb, var(--gold-soft) 42%, transparent); border-radius: 10px; background: transparent; color: var(--ink); font: inherit; }
#tasmee-transcript-result-text { max-height: 260px; overflow: auto; margin: 10px 0 0; color: var(--ink); font: 16px/2 'Amiri', serif; overflow-wrap: anywhere; }
.tasmee-live-eye-btn, .tasmee-live-finish-btn {
  width: 52px; height: 52px; border-radius: 50%; flex-shrink: 0;
  background: var(--paper); color: var(--ink); display: flex; align-items: center; justify-content: center;
  font-size: 20px; box-shadow: 0 8px 20px color-mix(in srgb, var(--shadow) 30%, transparent);
}
.tasmee-live-finish-btn { width: auto; height: 44px; padding: 0 18px; border-radius: 999px; background: rgba(122,35,49,.1); color: var(--ruby); font-family: var(--font-ui); font-weight: 700; font-size: 14px; }
.tasmee-live-mic-btn {
  width: 74px; height: 74px; border-radius: 50%; flex-shrink: 0;
  background: var(--ruby); color: #fff; display: flex; align-items: center; justify-content: center;
  box-shadow: 0 6px 22px rgba(122,35,49,.4);
}
.tasmee-live-mic-btn svg { width: 28px; height: 28px; }
.tasmee-live-mic-btn.listening { background: var(--ruby); animation: tasmee-mic-glow-ruby 1.4s ease-in-out infinite; }
@keyframes tasmee-mic-glow-ruby {
  0%, 100% { box-shadow: 0 0 0 0 rgba(122,35,49,.5); }
  50% { box-shadow: 0 0 0 14px rgba(122,35,49,0); }
}
@media (prefers-reduced-motion: reduce) {
  .tasmee-live-mic-btn.listening { animation: none !important; }
}

.playlist-create-btn { font-size: 14px; padding: 13px; }

/* -------- محرِّر قائمة التشغيل -------- */
.playlist-editor-sheet { max-height: 90vh; }

.playlist-name-input { font-weight: 700; font-size: 15px; margin-bottom: 4px; }

.playlist-play-btn { margin: 10px 0 4px; }

.playlist-editor-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.playlist-editor-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--paper-deep) 45%, transparent);
