  background: color-mix(in srgb, var(--gold) 18%, transparent);
  color: var(--brown-deep);
  font-size: 11px;
  font-weight: 800;
}
body.theme-night .playlist-editor-item-num { color: var(--gold-bright); }

.playlist-editor-item-info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
  text-align: right;
}
.playlist-editor-item-name {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.playlist-editor-item-sub { font-size: 11px; color: var(--ink-soft); }

.playlist-editor-item-remove {
  flex-shrink: 0;
  width: 26px; height: 26px;
  color: var(--ink-soft);
}
.playlist-editor-item-remove svg { width: 14px; height: 14px; }
.playlist-editor-item-remove:active { color: #C0392B; }

.playlist-add-icon {
  flex-shrink: 0;
  width: 26px; height: 26px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--gold-deep);
}
.playlist-add-icon svg { width: 18px; height: 18px; }

/* عنوان قائمة التشغيل الحالية وموضع السورة داخلها، تحت اسم القارئ في نافذة
   المشغّل الكامل — يظهر بس أثناء تشغيل قائمة تشغيل شخصية (مش سورة منفردة) */
.player-playlist-context {
  display: block;
  font-size: 11.5px;
  color: var(--ink-soft);
  margin-top: 2px;
  position: relative;
  z-index: 1;
}

/* =========================================================================
   صفحة "تفاصيل قائمة التشغيل": معلومات القائمة، أزرار التحميل/التكرار/
   العشوائي/التشغيل، إحصائية المساحة، بحث وفلترة، وقائمة السور
   ========================================================================= */
.playlist-detail-sheet { max-height: 92vh; }

.playlist-detail-head { position: relative; justify-content: space-between; }
.playlist-detail-fav-btn { color: var(--ink-soft); }
.playlist-detail-fav-btn.active { color: var(--gold-deep); }
.playlist-detail-fav-btn.active svg { fill: var(--gold-deep); }
body.theme-night .playlist-detail-fav-btn.active { color: var(--gold-bright); }
body.theme-night .playlist-detail-fav-btn.active svg { fill: var(--gold-bright); }

.playlist-detail-head-menu-panel {
  position: absolute;
  top: 46px; inset-inline-start: 46px;
  min-width: 190px;
}

.playlist-detail-info {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin: 6px 0 18px;
}
.playlist-detail-avatar {
  flex-shrink: 0;
  width: 66px; height: 66px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 20px;
  background: color-mix(in srgb, var(--gold) 18%, transparent);
  color: var(--gold-deep);
}
.playlist-detail-avatar svg { width: 30px; height: 30px; }
body.theme-night .playlist-detail-avatar { color: var(--gold-soft); }
.playlist-detail-titles { flex: 1 1 auto; min-width: 0; text-align: right; }
.playlist-detail-titles h2 {
  margin: 0 0 4px;
  font-family: var(--font-display);
  font-size: 22px;
  color: var(--ink);
}
.playlist-detail-sub { margin: 0; font-size: 12.5px; color: var(--ink-soft); }

.playlist-detail-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.playlist-detail-action-btn {
  flex-shrink: 0;
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 14px;
  background: color-mix(in srgb, var(--paper-deep) 55%, transparent);
  color: var(--ink-soft);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
}
.playlist-detail-action-btn svg { width: 19px; height: 19px; }
.playlist-detail-action-btn[data-active="true"] {
  background: var(--gold-deep);
  color: var(--paper);
  border-color: var(--gold-deep);
}
.playlist-detail-play-btn {
  flex: 1 1 auto;
  display: flex; align-items: center; justify-content: center;
  gap: 8px;
  height: 44px;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 700;
}
.playlist-detail-play-btn svg { width: 15px; height: 15px; }
.playlist-detail-play-btn.hidden { display: none; }

.playlist-detail-stats {
  display: flex;
  gap: 10px;
  margin-bottom: 16px;
}
.playlist-detail-stat-pill {
  flex: 1 1 0;
  text-align: center;
  padding: 9px 10px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--paper-deep) 55%, transparent);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
  font-size: 12.5px;
  font-weight: 700;
  color: var(--gold-deep);
}
body.theme-night .playlist-detail-stat-pill { color: var(--gold-soft); }

.playlist-detail-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}
.playlist-detail-search-wrap { position: relative; flex: 1 1 auto; }
.playlist-detail-search-input { padding-inline-end: 40px; }
.playlist-detail-search-icon {
  position: absolute;
  top: 50%; inset-inline-end: 12px;
  transform: translateY(-50%);
  width: 17px; height: 17px;
  color: var(--ink-soft);
  pointer-events: none;
}
.playlist-detail-filter-btn {
  flex-shrink: 0;
  width: 42px; height: 42px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--paper-deep) 55%, transparent);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
  color: var(--ink-soft);
}

.playlist-detail-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
}
.playlist-detail-tab {
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--ink-soft);
  background: color-mix(in srgb, var(--paper-deep) 55%, transparent);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
}
.playlist-detail-tab.active {
  background: var(--gold-deep);
  color: var(--paper);
  border-color: var(--gold-deep);
}

.playlist-detail-items {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-bottom: 6px;
}

.playlist-detail-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  background: var(--surface, #FFFFFF);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
  border-radius: 16px;
}
body.theme-night .playlist-detail-item {
  background: var(--paper-deep);
  border-color: #363636;
}

.playlist-detail-item-menu-btn {
  flex-shrink: 0;
  width: 28px; height: 28px;
  color: var(--ink-soft);
}
.playlist-detail-item-menu-btn svg { width: 16px; height: 16px; }

.playlist-detail-item-download {
  flex-shrink: 0;
  width: 30px; height: 30px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--ink-soft);
}
.playlist-detail-item-download svg { width: 17px; height: 17px; }
.playlist-detail-item-download.is-downloaded { color: var(--gold-deep); }
body.theme-night .playlist-detail-item-download.is-downloaded { color: var(--gold-soft); }
.playlist-detail-item-download.is-busy { opacity: .4; pointer-events: none; }

.playlist-detail-item-info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: right;
}
.playlist-detail-item-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.playlist-detail-item-sub { font-size: 11.5px; color: var(--ink-soft); }

.playlist-detail-item-num {
  flex-shrink: 0;
  width: 26px; height: 26px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold) 16%, transparent);
  color: var(--gold-deep);
  font-size: 12px;
  font-weight: 800;
}
body.theme-night .playlist-detail-item-num { color: var(--gold-bright); }

/* -------- قائمة خيارات كل سورة (وقائمة خيارات القائمة أعلى الصفحة) -------- */
.playlist-item-menu-panel {
  position: absolute;
  z-index: 5;
  top: 40px; inset-inline-start: 8px;
  min-width: 200px;
  background: var(--surface, #FFFDF6);
  border: 1px solid color-mix(in srgb, var(--gold) 25%, transparent);
  border-radius: 16px;
  box-shadow: 0 14px 32px rgba(40, 30, 10, .18);
  padding: 6px;
  display: flex;
  flex-direction: column;
}
body.theme-night .playlist-item-menu-panel {
  background: #221C10;
  border-color: #3a3018;
  box-shadow: 0 14px 32px rgba(0,0,0,.5);
}
.playlist-item-menu-panel.hidden { display: none; }
.playlist-item-menu-panel button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 10px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
}
.playlist-item-menu-panel button:active { background: color-mix(in srgb, var(--gold) 12%, transparent); }
.playlist-item-menu-panel button svg { width: 16px; height: 16px; flex-shrink: 0; color: var(--ink-soft); }
.playlist-item-menu-panel button.hidden { display: none; }
.playlist-item-menu-panel hr {
  border: none;
  border-top: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
  margin: 4px 2px;
}
.playlist-item-menu-danger { color: #C0392B !important; }
.playlist-item-menu-danger svg { color: #C0392B !important; }

/* =========================================================================
   يوتيليتي: إجبار خط Tajawal (بدل الخط الزخرفي الافتراضي للعناوين) على
   عناصر محدّدة بالاسم فقط — طُلب صراحة لعناوين صفحة "الصوتيات" الأربعة
   ========================================================================= */
.font-tagawal { font-family: 'Tajawal', sans-serif !important; }

/* =========================================================================
   محرِّر قائمة التشغيل — تصميم جديد (غلاف/إحصائيات/إضافة سور كاملة أو مقطع)
   ========================================================================= */
.playlist-editor-sheet-v2 { padding-top: 16px; }

.playlist-editor-head-v2 {
  position: relative;
  justify-content: center;
}
.playlist-editor-head-v2 h3 {
  flex: 1;
  text-align: center;
  font-family: var(--font-ui);
  font-weight: 800;
  color: var(--gold-deep);
}
body.theme-night .playlist-editor-head-v2 h3 { color: var(--gold-soft); }
.playlist-editor-head-v2 #btn-close-playlist-editor { position: absolute; inset-inline-end: 0; }
.playlist-editor-save-btn {
  position: absolute;
  inset-inline-start: 0;
  background: var(--gold-deep);
  color: var(--paper);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 14px;
  padding: 10px 20px;
  border-radius: 999px;
}
.playlist-editor-save-btn:active { transform: scale(.96); }

.playlist-editor-top-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.playlist-editor-top-row .playlist-name-input { flex: 1 1 auto; margin-bottom: 0; }
.playlist-cover-preview {
  flex-shrink: 0;
  width: 52px; height: 52px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 16px;
  background: color-mix(in srgb, var(--gold) 14%, var(--paper-deep));
  border: 1.5px solid var(--gold-deep);
  color: var(--gold-deep);
}
.playlist-cover-preview svg { width: 24px; height: 24px; }
body.theme-night .playlist-cover-preview { color: var(--gold-soft); border-color: var(--gold-soft); }

.playlist-cover-title { margin-top: 4px; margin-bottom: 8px; }

.playlist-cover-choices {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
  margin-bottom: 16px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.playlist-cover-choices::-webkit-scrollbar { display: none; }
.playlist-cover-choice {
  flex-shrink: 0;
  width: 52px; height: 52px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 16px;
  background: var(--paper-deep);
  border: 1.5px solid color-mix(in srgb, var(--gold) 25%, transparent);
  color: var(--gold-deep);
}
.playlist-cover-choice svg { width: 22px; height: 22px; }
.playlist-cover-choice.active {
  border-color: var(--gold-deep);
  background: color-mix(in srgb, var(--gold) 16%, var(--paper-deep));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--gold) 30%, transparent);
}
body.theme-night .playlist-cover-choice { color: var(--gold-soft); }
body.theme-night .playlist-cover-choice.active { border-color: var(--gold-soft); }

.playlist-editor-stats {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-bottom: 16px;
}
.playlist-editor-stat-pill {
  flex: 1;
  text-align: center;
  padding: 10px 6px;
  border-radius: 999px;
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 18%, transparent);
  font-size: 12.5px;
  color: var(--ink-soft);
  font-family: var(--font-ui);
}
.playlist-editor-stat-pill b {
  color: var(--gold-deep);
  font-size: 14px;
  margin-inline-end: 3px;
}
body.theme-night .playlist-editor-stat-pill b { color: var(--gold-soft); }

.playlist-editor-add-row {
  display: flex;
  gap: 10px;
  margin-bottom: 8px;
}
.playlist-editor-add-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 13px 10px;
  border-radius: var(--radius-md);
  font-family: var(--font-ui);
  font-size: 13.5px;
  font-weight: 700;
}
.playlist-editor-add-btn svg { width: 17px; height: 17px; flex-shrink: 0; }
.playlist-editor-add-btn-outline {
  background: var(--paper);
  color: var(--ink);
  border: 1.3px solid color-mix(in srgb, var(--gold) 35%, transparent);
}
.playlist-editor-add-btn-filled {
  background: var(--gold-deep);
  color: var(--paper);
}
.playlist-editor-add-plus { font-size: 16px; font-weight: 800; line-height: 1; }
.playlist-editor-add-btn:active { transform: scale(.97); }
body.theme-night .playlist-editor-add-btn-outline { background: var(--paper-deep); color: var(--ink); }

.playlist-editor-empty-box {
  margin-top: 14px;
  padding: 22px 16px;
  border-radius: var(--radius-lg);
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 15%, transparent);
  text-align: center;
  font-size: 13.5px;
  color: var(--ink-soft);
  line-height: 1.7;
}
.playlist-editor-empty-box.hidden { display: none; }

/* =========================================================================
   نافذة "إضافة سور كاملة" — شيكليست بكل الـ ١١٤ سورة
   ========================================================================= */
.add-full-surahs-sheet { display: flex; flex-direction: column; max-height: 90vh; }
.add-full-surahs-search-wrap { margin-bottom: 10px; flex-shrink: 0; }
.add-full-surahs-list {
  flex: 1 1 auto;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-bottom: 8px;
  -webkit-overflow-scrolling: touch;
}
.add-full-surah-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 14px;
  border-radius: var(--radius-md);
  background: var(--paper-deep);
  border: 1px solid transparent;
  text-align: end;
}
.add-full-surah-row.checked {
  border-color: var(--gold-deep);
  background: color-mix(in srgb, var(--gold) 10%, var(--paper-deep));
}
.add-full-surah-checkbox {
  flex-shrink: 0;
  width: 24px; height: 24px;
  border-radius: 8px;
  border: 1.6px solid color-mix(in srgb, var(--gold) 45%, var(--ink-soft));
  background: var(--paper);
  display: flex; align-items: center; justify-content: center;
  color: var(--paper);
}
.add-full-surah-row.checked .add-full-surah-checkbox {
  background: var(--gold-deep);
  border-color: var(--gold-deep);
}
.add-full-surah-checkbox svg { width: 14px; height: 14px; opacity: 0; }
.add-full-surah-row.checked .add-full-surah-checkbox svg { opacity: 1; }
.add-full-surah-info { flex: 1 1 auto; min-width: 0; text-align: end; }
.add-full-surah-name { display: block; font-size: 15px; font-weight: 800; color: var(--ink); }
.add-full-surah-sub { display: block; font-size: 12px; color: var(--ink-soft); margin-top: 2px; }

.add-full-surahs-footer {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--gold) 15%, transparent);
}
.add-full-surahs-count-text {
  flex-shrink: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-soft);
  font-family: var(--font-ui);
}
.add-full-surahs-confirm-btn { flex: 1; margin: 0; }

/* =========================================================================
   نافذة "إضافة مقطع" — نطاق آيات (من/إلى) + قارئ + تكرار
   ========================================================================= */
.add-segment-sheet { position: relative; }

.add-segment-summary-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 16px 14px;
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--gold) 10%, var(--paper-deep));
  border: 1px solid color-mix(in srgb, var(--gold) 20%, transparent);
  text-align: center;
  margin-bottom: 16px;
}
#add-segment-summary-title { font-size: 18px; font-weight: 800; color: var(--gold-deep); font-family: var(--font-ui); }
body.theme-night #add-segment-summary-title { color: var(--gold-soft); }
.add-segment-summary-sub { font-size: 12.5px; color: var(--ink-soft); }

.add-segment-section-title { margin-top: 16px; }

.add-segment-field-card {
  border-radius: var(--radius-md);
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 15%, transparent);
  overflow: hidden;
}
.add-segment-field-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 14px;
  background: none;
  text-align: end;
}
.add-segment-field-chevron { width: 16px; height: 16px; flex-shrink: 0; color: var(--ink-soft); transform: rotate(90deg); }
.add-segment-field-text { flex: 1; display: flex; flex-direction: column; gap: 2px; text-align: end; }
.add-segment-field-label { font-size: 11.5px; color: var(--ink-soft); }
.add-segment-field-value { font-size: 15px; font-weight: 800; color: var(--ink); }
.add-segment-field-divider { height: 1px; background: color-mix(in srgb, var(--gold) 15%, transparent); margin: 0 14px; }
.add-segment-reciter-text { flex-direction: row-reverse; justify-content: flex-end; align-items: center; }
.add-segment-reciter-text .add-segment-field-value,
.add-segment-reciter-text { font-size: 15px; font-weight: 800; color: var(--ink); }

.add-segment-repeat-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 4px 4px 12px;
}
.add-segment-repeat-label { flex: 1; text-align: end; font-size: 13.5px; color: var(--ink); font-weight: 700; }
.add-segment-repeat-value { min-width: 24px; text-align: center; font-size: 17px; font-weight: 800; color: var(--gold-deep); }
body.theme-night .add-segment-repeat-value { color: var(--gold-soft); }
.add-segment-repeat-step {
  flex-shrink: 0;
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--gold-deep);
  color: var(--paper);
  font-size: 18px;
  font-weight: 800;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}
.add-segment-repeat-step:active { transform: scale(.94); }

.add-segment-repeat-presets {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.add-segment-repeat-preset {
  flex: 1;
  min-width: 40px;
  padding: 10px 4px;
  border-radius: 999px;
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 20%, transparent);
  color: var(--ink-soft);
  font-size: 12.5px;
  font-weight: 700;
}
.add-segment-repeat-preset.active {
  background: color-mix(in srgb, var(--gold) 18%, var(--paper-deep));
  border-color: var(--gold-deep);
  color: var(--gold-deep);
}
body.theme-night .add-segment-repeat-preset.active { color: var(--gold-soft); border-color: var(--gold-soft); }

.add-segment-confirm-btn { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 4px; }
.add-segment-confirm-btn svg { width: 18px; height: 18px; }

.add-segment-picker-panel {
  position: absolute;
  inset: 0;
  background: var(--paper);
  border-radius: 24px 24px 0 0;
  padding: 16px 18px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  z-index: 6;
}
.add-segment-picker-panel.hidden { display: none; }
.add-segment-picker-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.add-segment-picker-head h4 { margin: 0; font-family: var(--font-ui); font-weight: 800; color: var(--gold-deep); font-size: 16px; }
body.theme-night .add-segment-picker-head h4 { color: var(--gold-soft); }
#segment-surah-picker-list, #segment-ayah-picker-list, #segment-reciter-picker-list { flex: 1 1 auto; overflow-y: auto; -webkit-overflow-scrolling: touch; }

.add-segment-ayah-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}
.add-segment-ayah-choice {
  padding: 10px 4px;
  border-radius: 12px;
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 15%, transparent);
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  text-align: center;
}
.add-segment-ayah-choice.active {
  background: var(--gold-deep);
  color: var(--paper);
  border-color: var(--gold-deep);
}

#lsp-surah-picker-list, #lsp-ayah-picker-list, #lsp-reciter-picker-list { flex: 1 1 auto; overflow-y: auto; -webkit-overflow-scrolling: touch; }

/* ---- "تحديد المقطع" (المزيد من خيارات الاستماع): شبكة من/إلى مضغوطة
   ٢×٢ بدل التصميم الرأسي المستخدم في "إضافة مقطع" ---- */
.lsp-range-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.lsp-field-row { justify-content: center; padding: 14px 10px; }
.lsp-field-row .add-segment-field-value { text-align: center; }
.lsp-grid-divider { grid-column: 1 / -1; margin: 0 14px; }
.lsp-repeat-row { padding: 12px 4px; }
.lsp-repeat-stepper { display: flex; align-items: center; gap: 14px; flex-shrink: 0; }

.lsp-speed-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.lsp-speed-btn {
  flex: 1;
  min-width: 56px;
  padding: 11px 6px;
  border-radius: 999px;
  background: var(--paper-deep);
  border: 1px solid color-mix(in srgb, var(--gold) 20%, transparent);
  color: var(--ink-soft);
  font-size: 13px;
  font-weight: 700;
}
.lsp-speed-btn.active {
  background: color-mix(in srgb, var(--gold) 18%, var(--paper-deep));
  border-color: var(--gold-deep);
  color: var(--gold-deep);
}
body.theme-night .lsp-speed-btn.active { color: var(--gold-soft); border-color: var(--gold-soft); }

.reciter-choice-list { display: flex; flex-direction: column; gap: 6px; }
.reciter-choice-list .reciter-choice {
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: var(--paper-deep);
  text-align: end;
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
}
.reciter-choice-list .reciter-choice.active {
  background: color-mix(in srgb, var(--gold) 16%, var(--paper-deep));
  color: var(--gold-deep);
  border: 1px solid var(--gold-deep);
}
body.theme-night .reciter-choice-list .reciter-choice.active { color: var(--gold-soft); border-color: var(--gold-soft); }

/* حالة "محدَّد" لعنصر السورة داخل لوحة اختيار السورة الخاصة بـ"إضافة مقطع" */
#segment-surah-picker-list .surah-item.tasmee-item-selected {
  background: rgba(201, 162, 39, 0.16);
  border-radius: var(--radius-md);
}
#segment-surah-picker-list .surah-item.tasmee-item-selected .surah-item-num {
  background: var(--gold-deep); color: var(--paper);
}
body.theme-night #segment-surah-picker-list .surah-item.tasmee-item-selected .surah-item-num { background: var(--gold); color: var(--emerald); }

/* =========================================================================
   أدوات القراءة العائمة لصفحة المصحف — تظهر بلمسة خفيفة (مش سحبة تقليب)
   في أي مكان بالصفحة، وتختفي بنفس الطريقة أو بزرار الإخفاء المخصّص.
   الشريط العلوي ينزلق نازلًا من فوق، وبطاقة المعلومات + الأزرار العائمة
   السفلية تنزلق طالعة من تحت — مطابقة لتصميم تطبيق "المصحف الذهبي":
   شرائح بيضاء نقية (#fff) وأزرار دائرية بنية غامقة (--gold-deep).
   كل العناصر دي خاصة بتبويب القرآن فقط: body.header-hidden (يتفعّل تلقائيًا
   في أي تبويب غير القرآن) بيضمن إنها تفضل مخفية تمامًا برّه صفحة القرآن.
   ========================================================================= */

/* -------- الشريط العلوي: إعدادات + قلب الصفحة بالعرض / بحث / تقليب تلقائي + فهرس -------- */
/* شريط بصفّين معلّق بمنتصف الشاشة، بخلفية غامقة شبه شفافة وأيقونات ذهبية
   صغيرة — بنفس روح شريط تطبيق "المصحف الذهبي" المرجعي، لكن بألوان هوية
   التطبيق (أسود/ذهبي) بدل الأبيض. الصف الأول: مجموعة (إعدادات+قلب الصفحة)
   على البداية، حقل البحث في النص ياخد المساحة المتبقية، ومجموعة (تقليب
   تلقائي+فهرس) على النهاية. الصف الثاني: كبسولة الفرض القادم ومعاده */
#mushaf-top-toolbar {
  position: fixed;
  top: calc(env(safe-area-inset-top) + 8px);
  left: 50%;
  transform: translate(-50%, -160%);
  width: calc(100% - 20px);
  max-width: 520px;
  z-index: 55;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  opacity: 0;
  pointer-events: none;
  transition: transform .32s cubic-bezier(.22, .61, .36, 1), opacity .26s ease;
}
body.mushaf-chrome-open:not(.header-hidden) #mushaf-top-toolbar {
  transform: translate(-50%, 0);
  opacity: 1;
  pointer-events: auto;
}

.mtt-row {
  width: 100%;
  display: flex;
  /* row-reverse: بيبدّل جهة مجموعة (إعدادات+قلب الصفحة) مع مجموعة (تقليب
     تلقائي+فهرس) بالكامل — اللي كانت يمين بقت شمال والعكس، بناءً على طلب
     المستخدم، من غير ما يتغيّر الترتيب الداخلي لعناصر كل مجموعة مع بعضها */
  flex-direction: row-reverse;
  align-items: center;
  gap: 4px;
  padding: 5px;
  background: rgba(20, 16, 8, .88);
  border: 1px solid rgba(201, 162, 39, .28);
  border-radius: 999px;
  box-shadow: 0 10px 26px color-mix(in srgb, var(--shadow) 34%, transparent);
  backdrop-filter: blur(6px);
}
body.theme-night .mtt-row {
  /* توحيد خلفية أدوات القراءة العلوية مع البار السفلي في الدارك مود،
     بما في ذلك الأسود الحقيقي، حتى تظل كل عناصر التحكم واضحة فوق المصحف. */
  background: #242424;
  border-color: rgba(255, 255, 255, .08);
  box-shadow: 0 10px 26px rgba(0, 0, 0, .3);
}

.mtt-side {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 2px;
}

/* أيقونات صغيرة موحّدة (إعدادات/قلب الصفحة/تقليب تلقائي/فهرس) — نفس
   المقاس بالظبط عشان الشريط يفضل خفيف واحترافي، مش كبير ولا مبعثر */
.mtt-icon-btn {
  width: 34px; height: 34px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: transparent;
  color: var(--gold-soft);
  border: none;
  transition: transform .12s, background .15s, color .15s;
}
.mtt-icon-btn svg { width: 17px; height: 17px; }
.mtt-icon-btn:active { transform: scale(.88); background: rgba(201, 162, 39, .16); }
.mtt-icon-btn.is-active { color: var(--emerald); background: var(--gold-soft); }

/* حقل البحث ياخد المساحة اللي في النص، بلون أفتح شوية عن الخلفية عشان
   يبان كحقل واضح بس من غير ما يكسر وحدة لون الشريط */
.mtt-search-field {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .06);
  border: none;
  color: var(--gold-soft);
  font-family: var(--font-kufic);
  font-size: 12.5px;
  transition: transform .12s;
}
.mtt-search-field span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mtt-search-field svg { width: 14px; height: 14px; flex-shrink: 0; opacity: .7; }
.mtt-search-field:active { transform: scale(.98); }

/* كبسولة الرواية الحالية أسفل أدوات المصحف؛ تعرض اسم الرواية بوضوح وتفتح
   قائمة الطبعات عند الضغط، من دون إضافة عنصر دائم إلى شريط التنقل السفلي. */
.mtt-edition-pill {
  min-height: 34px;
  max-width: calc(100% - 12px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 2px 10px;
  border: 1px solid rgba(201, 162, 39, .3);
  border-radius: 999px;
  background: #929a78;
  color: #fffdf3;
  box-shadow: 0 6px 18px color-mix(in srgb, var(--shadow) 28%, transparent);
  backdrop-filter: blur(6px);
  font-family: var(--font-kufic);
  line-height: 1.15;
  white-space: nowrap;
  transition: transform .12s, border-color .15s, background .15s;
}
body.theme-night .mtt-edition-pill { background: rgba(10, 10, 10, .94); color: var(--gold-soft); }
.mtt-edition-pill:active { transform: scale(.97); background: rgba(201, 162, 39, .14); }
.mtt-edition-pill:active { background: #7f8864; }
.mtt-edition-pill > svg:first-child { width: 13px; height: 13px; flex: 0 0 auto; color: #fffdf3; }
.mtt-edition-current-label { color: rgba(255, 253, 243, .78); font-size: 9px; }
.mtt-edition-divider { width: 1px; height: 12px; flex: 0 0 auto; background: rgba(255, 253, 243, .4); }
.mtt-edition-name { max-width: min(54vw, 190px); overflow: hidden; text-overflow: ellipsis; color: #fffdf3; font-size: 11px; font-weight: 800; }
.mtt-edition-chevron { width: 10px; height: 10px; flex: 0 0 auto; opacity: .75; }
body.theme-night .mtt-edition-pill > svg:first-child,
body.theme-night .mtt-edition-name { color: var(--gold-bright); }
body.theme-night .mtt-edition-current-label { color: color-mix(in srgb, var(--gold-soft) 72%, transparent); }
body.theme-night .mtt-edition-divider { background: rgba(201, 162, 39, .34); }

/* -------- كبسولة الفرض القادم: صف ثانٍ تحت شريط الأيقونات مباشرة -------- */
.mtt-prayer-pill {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 28px;
  padding: 0 16px;
  max-width: 100%;
  background: rgba(20, 16, 8, .82);
  border: 1px solid rgba(201, 162, 39, .22);
  border-radius: 999px;
  color: var(--gold-soft);
  font-family: var(--font-kufic);
  font-size: 11.5px;
  box-shadow: 0 6px 16px color-mix(in srgb, var(--shadow) 26%, transparent);
  transition: transform .12s;
}
body.theme-night .mtt-prayer-pill { background: rgba(10, 10, 10, .88); }
.mtt-prayer-pill:active { transform: scale(.96); }
.mtt-prayer-pill span { white-space: nowrap; }
.mtt-prayer-name #mtt-prayer-name { color: var(--gold-bright); font-weight: 700; }
.mtt-prayer-sep {
  width: 3px; height: 3px; border-radius: 50%;
  background: var(--gold-deep);
  flex-shrink: 0;
}
.mtt-prayer-time {
  font-weight: 700;
  color: var(--gold-bright);
  letter-spacing: .2px;
}
/* سهم على الشمال (نفس شكل سهم عناصر أقسام "استكشف الأشرف") بيوضّح إن
   الكبسولة بتفتح صفحة مواقيت الصلاة */
.mtt-prayer-arrow {
  width: 14px; height: 14px;
  flex-shrink: 0;
  color: var(--gold-bright);
  opacity: .9;
}

/* -------- كبسولة "تقدّم القراءة": صف ثانٍ فوق كبسولة الفرض القادم مباشرة،
   بنفس ألوانها الزيتونية الغامقة، لكن حجمها أكبر منها (32px بدل 28px)
   وأصغر بفرق بسيط من شريط الأيقونات/البحث فوقها (34px) — عشان الترتيب
   من فوق لتحت يبقى من الأكبر للأصغر. فرقها عن كبسولة الفرض القادم إنها
   فيها شريط تقدّم رفيع صغير جوّه الكبسولة نفسها بدل النقطة الفاصلة -------- */
.mtt-khatma-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
  height: 36px;
  width: 92%;
  padding: 0 18px;
  max-width: 100%;
  background: rgba(20, 16, 8, .88);
  border: 1px solid rgba(201, 162, 39, .28);
  border-radius: 999px;
  color: var(--gold-soft);
  font-family: var(--font-kufic);
  font-size: 12.5px;
  box-shadow: 0 6px 16px color-mix(in srgb, var(--shadow) 26%, transparent);
}
body.theme-night .mtt-khatma-pill { background: rgba(10, 10, 10, .92); }
.mtt-khatma-pill span { white-space: nowrap; }
.mtt-khatma-pill { cursor: pointer; transition: transform .12s; }
.mtt-khatma-pill:active { transform: scale(.96); }

.mtt-khatma-pill-range {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}
.mtt-khatma-pill-icon {
  flex-shrink: 0;
  width: 15px;
  height: 15px;
  color: var(--gold-bright);
}
.mtt-khatma-pill-icon svg { width: 100%; height: 100%; }
#mtt-khatma-pill-range-text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.mtt-khatma-pill-percent {
  flex-shrink: 0;
  font-weight: 700;
  color: var(--gold-bright);
}
.mtt-khatma-pill-track {
  flex-shrink: 0;
  display: block;
  width: 48px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .18);
  overflow: hidden;
}
.mtt-khatma-pill-fill {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: var(--gold-bright);
  transition: width .25s ease;
}

/* -------- الأزرار العائمة: رجوع لآخر صفحة (بعد قفزة مباشرة) / سماعة الاستماع --------
   الارتفاع اتزوّد من 172px لـ 214px عشان الزرارين يفضلوا فوق بطاقة معلومات
   الصفحة (مستطيل التقليب/الاسكرول بار .mushaf-info-popup) بمسافة واضحة،
   بدل ما يركبوا فوقيها زي ما كان بيحصل قبل كده */
#mushaf-fab-cluster {
  position: fixed;
  left: 50%;
  bottom: calc(env(safe-area-inset-bottom) + 204px);
  transform: translate(-50%, 40%);
  width: calc(100% - 24px);
  max-width: 430px;
  z-index: 99;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  opacity: 0;
  pointer-events: none;
  transition: transform .32s cubic-bezier(.22, .61, .36, 1), opacity .26s ease;
}
body.mushaf-chrome-open:not(.header-hidden) #mushaf-fab-cluster {
  transform: translate(-50%, 0);
  opacity: 1;
  pointer-events: auto;
}
/* لما يبقى المشغّل المصغّر (gp-bar) شغّال، الأزرار العائمة بتتخبّى معاه
   (نفس منطق بطاقة المعلومات تحت)، عشان محدش يتراكب فوق التاني. بنستخدم
   كلاس على body (player-bar-live) بدل معتمدية ترتيب العناصر في الـ DOM،
   اللي كانت بتخلّي القاعدة القديمة ما تشتغلش أصلًا */
body.mushaf-chrome-open:not(.header-hidden).player-bar-live #mushaf-fab-cluster {
  transform: translate(-50%, 40%);
  opacity: 0;
  pointer-events: none;
}

.mushaf-fab {
  min-width: 46px; height: 46px;
  padding: 0 15px;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  border-radius: 999px;
  background: var(--gold-deep);
  color: var(--paper);
  border: none;
  box-shadow: 0 8px 20px color-mix(in srgb, var(--shadow) 34%, transparent);
  transition: transform .12s, opacity .18s;
  font-family: var(--font-kufic);
  font-size: 15px;
  font-weight: 700;
}
.mushaf-fab svg { width: 20px; height: 20px; flex-shrink: 0; }
.mushaf-fab:active { transform: scale(.9); }
.mushaf-fab.hidden { display: none; }
#mushaf-fab-headphone { width: 46px; padding: 0; }
body.theme-night .mushaf-fab { background: var(--gold); color: var(--emerald); }

/* زرار "رجوع لآخر صفحة": شكل مصمت أصفر ذهبي مع رقم ولون أيقونة/نص أسود
   بحت، ثابت في كل الأوضاع (نهاري/ليلي) — مطابق للتصميم المرجعي، بدل ما
   يتبع ألوان .mushaf-fab العادية اللي بتتغيّر مع الثيم */
.mushaf-fab-back,
body.theme-night .mushaf-fab-back {
  background: #D9AC3E;
  color: #000;
}
.mushaf-fab-back svg { width: 22px; height: 22px; }

/* -------- زرار "التقليب التلقائي" (فوق، جنب الفهرس) + كبسولة التحكّم بالسرعة --------
   الزرار الدائري الصغير جوه شريط الأدوات العلوي ظاهر لحد ما المستخدم
   يضغط عليه فيبدأ التمرير التلقائي، وساعتها يتخبّى ويظهر بدل منه كبسولة
   السرعة (رقم + شريط سحب + زرار إيقاف/استئناف) كنافذة صغيرة معلّقة تحت
   الشريط مباشرة — لحد ما يوقف الميزة كاملة فيرجع الزرار الدائري تاني */
.autoscroll-control-slot { position: relative; display: flex; align-items: center; }
#mushaf-fab-autoscroll svg { width: 17px; height: 17px; }

.autoscroll-speed-pill {
  /* الكبسولة بقت رأسية (عمودية): الرقم فوق، شريط السرعة الرأسي في النص
     (فوق = أسرع، تحت = أبطأ)، وتحتهم زرار الإيقاف. متوسّطة تحت زرار
     التقليب مباشرة، وضيقة كفاية إنها تفضل جوه حدود الشاشة */
  direction: ltr;
  position: fixed;
  top: 72px;
  left: 12px;
  right: auto;
  /* إزاحة ١٦px ناحية الشمال عن التوسّط الكامل تحت الزرار، عشان الكبسولة
     ما تلزقش في حافة الشاشة اليمين (الزرار نفسه قريب جدًا من الحافة،
     فالتوسّط بالظبط كان بيخلّي الكبسولة تلمس الحافة أو تتقصّ) */
  transform: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 56px;
  max-height: calc(100dvh - 24px);
  padding: 11px 0 8px;
  border: 1px solid color-mix(in srgb, var(--olive) 24%, transparent);
  border-radius: 24px;
  background: color-mix(in srgb, var(--paper) 90%, white);
  color: var(--olive-deep);
  box-shadow: 0 12px 30px color-mix(in srgb, var(--shadow) 28%, transparent), inset 0 1px 0 rgba(255,255,255,.8);
  z-index: 12000;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.autoscroll-speed-pill.hidden { display: none; }
body.theme-night .autoscroll-speed-pill { background: rgba(38, 42, 32, .94); color: var(--gold-soft); border-color: rgba(214,193,123,.24); box-shadow: 0 12px 32px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.08); }

.autoscroll-speed-num {
  font-family: var(--font-kufic);
  font-size: 13px;
  font-weight: 700;
  min-width: 11px;
  text-align: center;
}

.autoscroll-speed-track {
  position: relative;
  width: 8px;
  height: 104px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--olive) 18%, white);
  touch-action: none;
}
body.theme-night .autoscroll-speed-track { background: rgba(255,255,255,.14); }
.autoscroll-speed-fill {
  position: absolute;
  inset: auto 0 0 0;   /* بيتملّي من تحت لفوق */
  height: 0%;
  border-radius: 999px;
  background: color-mix(in srgb, var(--paper) 92%, transparent);
  transition: height .12s ease-out;
  pointer-events: none;
}
body.theme-night .autoscroll-speed-fill { background: var(--emerald); }
.autoscroll-speed-dot {
  position: absolute;
  left: 50%;           /* الـ top بييجي inline من الـ HTML */
  width: 4px; height: 4px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--gold-deep) 55%, var(--paper) 45%);
  transform: translate(-50%, -50%);
  pointer-events: none;
}
body.theme-night .autoscroll-speed-dot { background: color-mix(in srgb, var(--gold) 55%, var(--emerald) 45%); }
.autoscroll-speed-thumb {
  position: absolute;
  left: 50%;
  bottom: 0%;          /* السرعة ١ تحت خالص، ٥ فوق خالص */
  width: 18px; height: 18px;
  border-radius: 50%;
  background: var(--paper);
  border: 2px solid var(--gold-deep);
  box-shadow: 0 2px 6px rgba(0,0,0,.3);
  transform: translate(-50%, 50%);
  transition: bottom .12s ease-out;
}
body.theme-night .autoscroll-speed-thumb { background: var(--emerald); border-color: var(--gold); }
.autoscroll-speed-track.dragging .autoscroll-speed-thumb,
.autoscroll-speed-track.dragging .autoscroll-speed-fill { transition: none; }

.autoscroll-speed-divider {
  width: 18px;
  height: 1.5px;
  background: color-mix(in srgb, var(--paper) 40%, transparent);
  flex-shrink: 0;
}
body.theme-night .autoscroll-speed-divider { background: color-mix(in srgb, var(--emerald) 30%, transparent); }

.autoscroll-playpause-btn {
  width: 30px; height: 30px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: transparent;
  border: none;
  color: var(--paper);
}
body.theme-night .autoscroll-playpause-btn { color: var(--emerald); }
.autoscroll-playpause-btn:active { transform: scale(.9); }
.autoscroll-playpause-btn svg { width: 15px; height: 15px; }
.autoscroll-playpause-btn svg.hidden { display: none; }

/* =========================================================================
   "قلب الصفحة بالعرض": وضع قراءة مخصّص لضعاف النظر، بيستخدم طول الشاشة
   كعرض للصفحة عشان النص يبقى أكبر بكتير من غير تعديل حجم الخط يدويًا.
   المحاولة الأولى الحقيقية: قفل اتجاه الشاشة فعليًا landscape عبر
   Screen Orientation API (شوف enableLandscapeFlip في app.js) — في الحالة
   دي المتصفح نفسه بيعيد رسم الصفحة أفقيًا، فكل اللمسات والتقليب بتشتغل
   طبيعي جدًا من غير أي حيلة CSS (السحب يمين/شمال لتقليب الصفحة، والسحب
   فوق/تحت للسكرول، بيبقوا شغالين صح لأن محاور اللمس نفسها بقت حقيقي
   أفقية، مش مُدارة بصريًا بس). لو الجهاز/المتصفح رفض القفل، بنفعّل بديل
   CSS الأضعف: تدوير حاوية الصفحة بصريًا ٩٠ درجة (وهو اللي كان بيسبب لخبطة
   في محاور اللمس فعليًا، فبنستخدمه بس لو مفيش بديل تاني). شريط الأدوات
   العلوي والأزرار العائمة بتفضل زي ما هي (مش بتتدوّر) عشان تفضل قابلة
   للاستخدام بشكل طبيعي فوق الصفحة المُدارة
   ========================================================================= */
/* بديل الـ CSS بيدوّر الحاوية الأم #app-rotate-wrap (اللي جوّاها الهيدر
   والمحتوى مع بعض) كوحدة واحدة صلبة، بدل ما يدوّر منطقة القراءة بس ويسيب
   الهيدر ثابت زي ما كان قديمًا (وهو اللي كان يخلي الهيدر يفضل غير مقروء
   لأنه ماكانش بيتحرك مع تدوير المستخدم الفعلي للموبايل في إيده). بما إن
   transform هنا بيعمل containing block جديد لكل عناصر position:fixed
   جوّا #app-rotate-wrap (الهيدر ومنطقة المحتوى نفسهم)، فهي بتتحرك تلقائيًا
   مع بعض بنفس علاقاتهم الطبيعية (top/bottom الأصلية) من غير أي تعديل
   إضافي على كل عنصر لوحده */
body.mushaf-landscape-mode.mushaf-landscape-css-fallback #app-rotate-wrap {
  position: fixed;
  top: 50%;
  left: 50%;
  width: 100vh;
  height: 100vw;
  max-width: none;
  transform: translate(-50%, -50%) rotate(90deg);
  transform-origin: center center;
  z-index: 30;
  overflow: hidden;
  /* خلفية صريحة بلون ورق الصفحة عشان أي جزء مايتغطّاش بالهيدر أو المحتوى
     (حواف نادرة وقت الدوران) يبان بلون التطبيق، مش اللون البني لخلفية
     الـ body اللي بيبان من وراه لو فضلت شفافة */
  background: var(--paper);
}

/* -------- ستارة الدوران (#mtt-rotate-curtain): بتغطّي الشاشة كاملة بلون
   التطبيق (var(--paper)) قبل طلب الدوران الحقيقي وبعده لحد ما إعادة
   الرسم تستقر، عشان تمنع فلاش لون خلفية النظام الافتراضي وقت الدوران
   الحقيقي (شوف enableLandscapeFlip في app.js). مخفية تمامًا (opacity 0 +
   pointer-events none + visibility hidden) في الوضع العادي، وبتتفعّل بس
   وقت التبديل نفسه بكلاس .is-active من الجافاسكريبت -------- */
#mtt-rotate-curtain {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--paper);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .22s ease;
}
#mtt-rotate-curtain.is-active {
  opacity: 1;
  visibility: visible;
}
#mtt-rotate-curtain svg {
  width: 44px;
  height: 44px;
  color: var(--emerald, #2f6f5e);
  opacity: .85;
}
/* أيقونة الدوران بتلف بحركة لطيفة طول ما الستارة ظاهرة، عشان تدّي إحساس
   "بيحصل دوران" بصري للمستخدم بدل ما يشوف شاشة فاضية ساكنة وهو مستني */
#mtt-rotate-curtain.is-active svg {
  animation: mtt-rotate-curtain-spin .9s cubic-bezier(.4, 0, .2, 1) 1;
}
@keyframes mtt-rotate-curtain-spin {
  from { transform: rotate(0deg) scale(.85); opacity: .4; }
  60%  { transform: rotate(200deg) scale(1.05); opacity: 1; }
  to   { transform: rotate(360deg) scale(1); opacity: .85; }
}
body.theme-night #mtt-rotate-curtain svg,
body.theme-night.oled-true-black #mtt-rotate-curtain svg { color: var(--gold-soft); }

/* في الوضع العرضي قد يفيض النص المكبّر عن الارتفاع، لذا نحتاج تمريرًا
   رأسيًا أصليًا. pan-y يسمح بتمرير المحتوى ويمنع السحب الأفقي الأصلي،
   بينما يظل التقليب الأفقي مملوكًا لمعالج السحب في app.js. */
body.mushaf-landscape-mode #mushaf-wrap {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  align-items: flex-start;
  touch-action: pan-y;
}
body.mushaf-landscape-mode #mushaf-page {
  position: relative;
  top: auto;
  left: auto;
  transform: translate3d(0, 0, 0);
  height: auto;
  min-height: 100%;
  max-height: none;
  /* حافظ على سكرول الصفحة رأسيًا، لكن اقص أي سطر أفقي يتجاوز حدود لوح
     الصفحة. overflow:visible كان يسمح لحروف الصفحة المجاورة بالظهور فوق
     هذه الصفحة أثناء تحريك اللوحين جنبًا إلى جنب. clip أفقيًا لا ينشئ
     scroll container، لذلك يظل تمرير الصفحة رأسيًا عبر #mushaf-wrap. */
  overflow-x: clip;
  overflow-y: visible;
  cursor: auto;
  /* هامش جانبي إضافي (يمين/شمال) خاص باللاندسكيب بس — الشاشة عريضة هنا
     والسطر بيتمدد على طولها بالكامل، فمحتاج هامش ملموس عشان النص ميلامسش
     حواف الشاشة. *لازم* الرقم ده يفضل مطابق تمامًا لـ PAGE_PAD_X (وضع
     isLandscapeWide) في fitMushafPage بـ app.js — شوف تعليقه هناك. الوضع
     الطولي العادي مالوش أي هامش إضافي هنا (رجع تمامًا لتصميمه الأصلي) */
  padding-left: 1px;
  padding-right: 1px;
}
body.mushaf-landscape-mode #mushaf-wrap > #mushaf-page.mushaf-neighbor-preview {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate3d(-50%, 0, 0);
}
body.mushaf-landscape-mode #mushaf-page:is(.warsh-edition-layout, .riwaya-svg-layout) {
  padding-inline: clamp(4px, 1vw, 8px);
}
body.mushaf-landscape-mode #mushaf-page.susi-edition-layout {
  padding: clamp(8px, 1.5vw, 14px);
}
/* مسافة أكبر بين السطور في اللاندسكيب تحديدًا (المستخدم عايزها أوسع من
   الوضع الطولي بالظبط، مش تغيير عام). القيمتين دول بيستبدلوا قيم
   .qcf-line/.qcf-word الأساسية فوق بس جوه وضع اللاندسكيب */
body.mushaf-landscape-mode .qcf-line {
  margin-bottom: calc(20px * var(--autofit-scale));
}
body.mushaf-landscape-mode .qcf-line:last-child { margin-bottom: 0; }
body.mushaf-landscape-mode .qcf-word {
  line-height: 1.75;
}
/* السبب الحقيقي اللي كان بيخلي السطور "محطوطة في نص الصفحة" وملهاش علاقة
   بالدوران أصلًا: #app-header و#app-main عندهم max-width:560px + توسيط
   (شوف أول قاعدة في الملف ده)، وده تصميم مقصود للوضع الطولي العادي (يمنع
   الصفحة تتمدد بعرض غير طبيعي على الأجهزة اللوحية). لكن في المصحف نفسه
   في وضع اللاندسكيب (سواء بدوران حقيقي أو ببديل الـ CSS)، عرض الشاشة
   الفعلي بعد الدوران غالبًا أكبر من ٥٦٠px، فكانت الصفحة تفضل محبوسة في
   عمود ٥٦٠px في النص وحواليها فراغ كبير يمين وشمال — بالظبط اللي وصفه
   المستخدم. نلغي السقف ده تمامًا في وضع اللاندسكيب فتاخد الصفحة العرض
   الحقيقي المتاح بالكامل */
body.mushaf-landscape-mode #app-header,
body.mushaf-landscape-mode #app-main {
  max-width: none;
}

/* زرار "قلب الصفحة بالعرض" نفسه بيتلوّن ذهبي مليان طول ما الوضع مفعّل،
   بنفس أسلوب حالة is-active العامة لأزرار الشريط العلوي */
#mtt-btn-landscape.is-active { color: var(--emerald); background: var(--gold-soft); }

/* -------- بطاقة معلومات الصفحة (التقليب): اسم السورة/الحزب + منزلق الآيات
   + شريط تقدّم. بتفضل ظاهرة فوق المشغّل المصغّر دايمًا (شوف
   .mushaf-bottom-stack) حتى وقت التلاوة، بدل ما يركب المشغّل فوقيها ويغطّيها -------- */
/* المجموعة كلها (الكبسولتين + المستطيل) هي اللي بتنزلق وتظهر/تختفي مع أدوات
   القراءة العائمة، والمستطيل جواها بقى مجرد بطاقة بيضا قد أرقام التقليب */
.mip-group {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  opacity: 0;
  transform: translateY(130%);
  pointer-events: none;
  transition: transform .32s cubic-bezier(.22, .61, .36, 1), opacity .26s ease;
}
body.mushaf-chrome-open:not(.header-hidden) .mip-group {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}
#mushaf-info-popup {
  position: relative;
  width: 100%;
  background: #FFFFFF;
  border: none;
  border-radius: 22px;
  padding: 4px 18px 7px;
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 32%, transparent);
}
body.theme-night #mushaf-info-popup { background: var(--paper-deep); }
/* نفس تمييز الرمادي المستخدم مع البار السريع تحت (شوف الشرح جنبه) — في
   وضع "أسود OLED" بطاقة معلومات الصفحة كمان لازم تفضل رمادي واضح بدل ما
   تداخل مع أسود صفحة القرآن الخالص -------- */
body.theme-night.oled-true-black #mushaf-info-popup { background: #242424; }

/* -------- بار سريع أسفل بطاقة معلومات الصفحة (.mushaf-bottom-stack)، بنفس
   تصميم بار صفحة "أدوات المسلم" (.tools-bottom-bar/.tools-bar-btn) تمامًا،
   لكنه هنا مش ثابت بنفسه: أبوه .mushaf-bottom-stack هو اللي متثبّت وبيرتّب
   الكروت فوق بعض، وهو بيظهر/يختفي مع باقي أدوات القراءة العائمة
   (mushaf-chrome-open) بدل ما يكون له زرار إخفاء/إغلاق مستقل بتاعه -------- */
.mushaf-quick-bar {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: 2px;
  padding: 5px 10px;
  background: #FFFFFF;
  border-radius: 999px;
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 32%, transparent);
  opacity: 0;
  transform: translateY(130%);
  pointer-events: none;
  transition: transform .32s cubic-bezier(.22, .61, .36, 1), opacity .26s ease;
}
body.mushaf-chrome-open:not(.header-hidden) .mushaf-quick-bar {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}
body.theme-night .mushaf-quick-bar { background: var(--paper-deep); }
/* في وضع "أسود OLED" خلفية صفحة المصحف نفسها بتبقى أسود خالص (#000000)،
   فلو البار اتلوّن بنفس --paper-deep العام في هذا الوضع (#0A0A0A) هيبقى
   شبه مختفي فوقها. عشان كده هنا تحديدًا بنرجّعه لدرجة الرمادي العادية
   المستخدمة في الوضع الليلي الطبيعي (#242424) عشان يفضل مميز وواضح فوق
   خلفية الصفحة السودا اللامعة -------- */
body.theme-night.oled-true-black .mushaf-quick-bar { background: #242424; }

/* صف الكبسولتين (اسم السورة + رقم الآية) فوق مستطيل التقليب */
.mip-caps-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.mip-cap {
  flex: 0 1 auto;
  min-width: 0;
  padding: 6px 16px;
  border-radius: 999px;
  background: #FFFFFF;
  border: none;
  box-shadow: 0 8px 22px color-mix(in srgb, var(--shadow) 26%, transparent);
  font-family: var(--font-kufic);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
body:not(.theme-night) .mip-cap {
  background: #EEF1E4;
  border: 1px solid #D9DECA;
  box-shadow: 0 5px 14px rgba(49, 61, 31, .14);
}
body.theme-night .mip-cap { background: var(--paper-deep); }
body.theme-night.oled-true-black .mip-cap { background: #242424; }
.mip-cap:empty { display: none; }
.mip-surah-name { font-size: 16px; font-weight: 700; color: var(--ink); }

.mip-ayah-pill {
  flex-shrink: 0;
  color: var(--gold-deep);
  font-size: 13.5px;
  font-weight: 700;
}
body.theme-night .mip-ayah-pill { color: var(--gold-soft); }

/* منزلق رقم الآية: صف قابل للسحب بأرقام الآيات، كل رقم ينطبق في المنتصف
   (scroll-snap-align: center) بدل ما نحسب فيزياء السحب يدويًا، مع تلاشي
   الحواف بقناع تدرّج شفاف (نفس تأثير "عجلة الاختيار" في الفيديو المرجعي) */
.mip-scrubber-wrap { position: relative; margin-bottom: 2px; }
.mip-ayah-scrubber {
  display: flex;
  align-items: center;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  height: 30px;
  mask-image: linear-gradient(to right, transparent, black 18%, black 82%, transparent);
  -webkit-mask-image: linear-gradient(to right, transparent, black 18%, black 82%, transparent);
}
.mip-ayah-scrubber::-webkit-scrollbar { display: none; }
.mas-num {
  flex: 0 0 auto;
  scroll-snap-align: center;
  min-width: 30px;
  padding: 3px 7px;
  text-align: center;
  background: none;
  border: none;
  font-family: var(--font-kufic);
  font-size: 14px;
  font-weight: 700;
  color: var(--ink-soft, var(--ink));
  opacity: .32;
  transition: font-size .15s ease, color .15s ease, opacity .15s ease;
}
.mas-num.active {
  font-size: 21px;
  color: var(--gold-deep);
  opacity: 1;
}
body.theme-night .mas-num.active { color: var(--gold-soft); }

.mip-progress-track {
  position: relative;
  height: 4px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--paper-line) 55%, transparent);
  overflow: hidden;
}
.mip-progress-fill {
  position: absolute;
  top: 0; right: 0; bottom: 0;
  width: var(--pct, 0%);
  background: var(--gold-deep);
  transition: width .15s linear;
}
body.theme-night .mip-progress-fill { background: var(--gold); }

/* ================================================================== */
/* صفحة "مباشر": إذاعات القرآن الكريم اللايف                          */
/* ================================================================== */

/* أيقونة "مباشر" في شبكة الإجراءات السريعة: خلفية متدرجة نابضة عشان
   تلفت النظر كعنصر حي/لايف مختلف عن باقي الأيقونات الثابتة */
.nav-item-icon.clr-live {
  position: relative;
  background: rgba(224, 59, 59, .16);
  color: #C6333F;
}
.nav-item-live-dot {
  position: absolute;
  top: -2px;
  left: -2px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #FF3B3B;
  box-shadow: 0 0 0 2px var(--paper, #FFFFFF);
}
.nav-item.live-radio-playing .nav-item-live-dot {
  animation: liveDotPulse 1.6s ease-in-out infinite;
}
body.theme-night .nav-item-live-dot { box-shadow: 0 0 0 2px var(--paper-deep); }
.nav-item.live-radio-playing .nav-item-icon.clr-live {
  animation: liveRadioNavPulse 1.5s ease-in-out infinite;
}
@keyframes liveDotPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.35); opacity: .65; }
}
@keyframes liveRadioNavPulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(224, 59, 59, .05); }
  50% { transform: scale(1.06); box-shadow: 0 0 0 6px rgba(224, 59, 59, .13); }
}

/* ------------------------------------------------------------------
   صفحة "مباشر" — تصميم جديد بطابع صفحة الصوتيات
   (كريمي دافئ / زيتوني + ذهبي / Tajawal / بطاقات مدوّرة 26px وظل ناعم).
   كل الألوان مشتقة من متغيّرات --ap-* المعرّفة على #view-live في
   unified-theme-pages.css، فالوضع الليلي بيشتغل تلقائيًا.
   ------------------------------------------------------------------ */
#view-live {
  --lv-title: color-mix(in srgb, var(--ap-olive) 42%, var(--ap-ink));
  --lv-glass: color-mix(in srgb, var(--ap-gold) 18%, var(--ap-card));
  --lv-live: #C2493F;
  --lv-live-dot: #D9534F;
  --lv-live-bg: rgba(214, 84, 70, .1);
  /* بطاقة "تشغيل الآن" */
  --lv-np-bg-a: #7D8562;
  --lv-np-bg-b: #5C6544;
  --lv-np-ink: #fff;
  --lv-np-ink-2: rgba(255, 255, 255, .74);
  --lv-np-art: #3E4630;
  --lv-np-bar: rgba(255, 255, 255, .9);
  --lv-np-btn-bg: #fff;
  --lv-np-btn-ink: #4A5236;
  /* شريط أخضر أعلى الكارت الشغّال */
  --lv-banner-a: #56603F;
  --lv-banner-b: #7D8562;
  --lv-st-ink: #fff;
}
body.theme-night #view-live {
  --lv-live: #FF8A80;
  --lv-live-dot: #FF6B5E;
  --lv-live-bg: rgba(255, 120, 110, .14);
  --lv-np-bg-a: #363C2B;
  --lv-np-bg-b: #262B1D;
  --lv-np-ink: #EFEDE6;
  --lv-np-ink-2: #B5B2A6;
  --lv-np-art: #1B1E14;
  --lv-np-bar: #98A278;
  --lv-np-btn-bg: #98A278;
  --lv-np-btn-ink: #15160f;
  --lv-banner-a: #3E4530;
  --lv-banner-b: #2F3525;
  --lv-st-ink: #15160f;
}

.live-radio-page { position: relative; padding-bottom: 34px; }
#view-live .list-page.live-radio-page { background: var(--ap-bg); font-family: var(--ap-font); }
#view-live .page-topbar,
.live-radio-head,
.live-now-playing,
.live-radio-list,
.live-radio-note { position: relative; z-index: 1; }

/* ---------- الزخرفة (فوانيس + أغصان + مسجد) ---------- */
.live-radio-deco {
  position: absolute;
  inset: 0 0 auto 0;
  height: 330px;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}
.live-radio-deco svg { position: absolute; display: block; }
.live-deco-lanterns { top: 0; inset-inline-start: 14px; width: 100px; height: 140px; }
.live-deco-leaves   { top: 0; inset-inline-start: 0;    width: 170px; height: 80px; opacity: .6; }
.live-deco-mosque   {
  top: 84px; inset-inline-end: 6px; width: 220px; height: 160px; opacity: .1;
  -webkit-mask-image: linear-gradient(to bottom, #000 45%, transparent 100%);
  mask-image: linear-gradient(to bottom, #000 45%, transparent 100%);
}
#view-live[dir="ltr"] .live-deco-lanterns,
#view-live[dir="ltr"] .live-deco-leaves { transform: scaleX(-1); }
#view-live[dir="ltr"] .live-deco-mosque { transform: scaleX(-1); }
body.theme-night .live-radio-deco { opacity: .62; }

.lv-olive  { fill: var(--ap-olive); }
.lv-gold   { fill: var(--ap-gold); }
.lv-gold-stroke { stroke: var(--ap-gold); stroke-width: 1.6; }
.lv-glass  { fill: var(--lv-glass); stroke: var(--ap-olive); stroke-width: 1.6; }
.lv-rib    { stroke: var(--ap-olive); stroke-width: .9; opacity: .55; }
.lv-cord   { stroke: var(--ap-gold); stroke-width: 1; opacity: .8; }
.lv-leaves use { fill: var(--ap-olive); }
.lv-stem   { stroke: var(--ap-olive); stroke-width: 1.2; opacity: .6; }
.lv-mosque * { fill: var(--ap-olive); }

/* ---------- زر الإغلاق ---------- */
#view-live .page-topbar { margin-bottom: 0; }
#view-live .page-close-btn {
  width: 42px;
  height: 42px;
  background: var(--ap-card);
  color: var(--ap-ink);
  border: 1px solid color-mix(in srgb, var(--ap-gold) 32%, var(--ap-line));
  box-shadow: var(--ap-shadow);
}
#view-live .page-close-btn svg { width: 20px; height: 20px; }
#view-live .page-close-btn:active { background: var(--ap-olive-soft); }

/* ---------- الرأس ---------- */
.live-radio-head { padding: 18px 4px 18px; text-align: center; }
.live-radio-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px;
  margin-bottom: 14px;
  border-radius: 999px;
  font-family: var(--ap-font);
  font-size: 12.5px;
  font-weight: 700;
  color: var(--lv-live);
  background: var(--lv-live-bg);
}
.live-radio-eyebrow-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--lv-live-dot);
  animation: liveDotPulse 1.6s ease-in-out infinite;
}
.live-radio-title {
  margin: 0 0 8px;
  font-family: var(--ap-font);
  font-size: 30px;
  font-weight: 900;
  line-height: 1.3;
  color: var(--lv-title);
}
.live-radio-subtitle {
  margin: 0;
  font-family: var(--ap-font);
  font-size: 13px;
  line-height: 1.7;
  color: var(--ap-ink-2);
}

/* ---------- بطاقة "تشغيل الآن" ---------- */
.live-now-playing {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 60px;
  margin-bottom: 14px;
  padding: 7px 16px;
  border-radius: 22px;
  color: var(--lv-np-ink);
  background: linear-gradient(135deg, var(--lv-np-bg-a), var(--lv-np-bg-b));
  box-shadow: 0 14px 30px color-mix(in srgb, var(--lv-np-bg-b) 34%, transparent), 0 1px 2px rgba(50, 55, 30, .14);
}
.live-now-playing[hidden] { display: none; }
.live-now-playing-art {
  flex-shrink: 0;
  width: 46px;
  height: 46px;
  border-radius: 14px;
  background: var(--lv-np-art);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .14);
}
.live-now-playing-art img { width: 100%; height: 100%; object-fit: cover; background: #fff; }
.live-now-playing-info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.live-now-playing-label {
  font-family: var(--ap-font);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--lv-np-ink-2);
}
.live-now-playing-name {
  font-family: var(--ap-font);
  font-size: 15.5px;
  font-weight: 800;
  line-height: 1.35;
  color: var(--lv-np-ink);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
/* موجة الصوت: أعمدة رفيعة بتخفت ناحية زر التشغيل */
.live-now-playing-vis {
  flex: 0 0 76px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  -webkit-mask-image: linear-gradient(to left, transparent 0, #000 58%);
  mask-image: linear-gradient(to left, transparent 0, #000 58%);
}
#view-live[dir="ltr"] .live-now-playing-vis {
  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 58%);
  mask-image: linear-gradient(to right, transparent 0, #000 58%);
}

/* اتجاه التخطيط للصفحات المترجمة: العناوين لا تكسر الكلمة اللاتينية،
   ومحاذاة المحتوى تتبع LTR بدل قواعد المحاذاة العربية الثابتة. */
#view-home[dir="ltr"] .khatma-hero .ap-hero-text {
  width: min(62%, 34rem) !important;
  max-width: 62% !important;
  margin-inline-end: auto !important;
  margin-inline-start: 0 !important;
  text-align: left !important;
  align-items: flex-start !important;
}
#view-home[dir="ltr"] .khatma-hero .ap-title {
  width: 100% !important;
  max-width: 100% !important;
  overflow-wrap: normal !important;
  word-break: normal !important;
  hyphens: none !important;
  text-align: left !important;
}
#view-home[dir="ltr"] .khatma-hero .ap-subtitle {
  width: 100% !important;
  max-width: 100% !important;
  text-align: left !important;
}
#view-home[dir="ltr"] .khatma-section-title,
#view-home[dir="ltr"] .khatma-list-card-main,
#view-home[dir="ltr"] .khatma-list-card-members {
  text-align: left !important;
}
#view-home[dir="ltr"] .khatma-list-card-fill { inset-inline: 0 auto; }

#islamic-occasions-overlay[dir="ltr"] .occ-body { direction: ltr; text-align: left; }
#islamic-occasions-overlay[dir="ltr"] .occ-next-info,
#islamic-occasions-overlay[dir="ltr"] .occ-row-info,
#islamic-occasions-overlay[dir="ltr"] .occ-month-title { text-align: left !important; }
#islamic-occasions-overlay[dir="ltr"] .occ-row,
#islamic-occasions-overlay[dir="ltr"] .occ-next-row,
#islamic-occasions-overlay[dir="ltr"] .occ-reminder-row { direction: ltr; }

#view-live[dir="ltr"] .live-radio-head,
#view-live[dir="ltr"] .live-radio-feature-copy,
#view-live[dir="ltr"] .live-radio-list-heading { direction: ltr; }
#view-live[dir="ltr"] .live-radio-head { text-align: center !important; }
#view-live[dir="ltr"] .live-radio-card { direction: ltr; }
#view-live[dir="ltr"] .live-radio-card-body,
#view-live[dir="ltr"] .live-radio-card-name,
#view-live[dir="ltr"] .live-radio-card-desc { text-align: left !important; }
.live-now-playing-vis span {
  flex: 0 0 2px;
  height: var(--h, 50%);
  border-radius: 3px;
  background: var(--lv-np-bar);
  animation: liveVisBar var(--d, 1.1s) ease-in-out infinite;
  animation-delay: var(--dl, 0s);
  transform-origin: center;
}
.live-now-playing.paused .live-now-playing-vis span {
  animation-play-state: paused;
  opacity: .45;
  transform: scaleY(.35);
}
.live-now-playing.loading .live-now-playing-vis span {
  animation-play-state: paused;
  opacity: .28;
  transform: scaleY(.35);
}
/* شاشات ضيقة (٣٦٠px وأقل): موجة أقصر عشان اسم الإذاعة ياخد مساحة أكبر */
@media (max-width: 380px) {
  .live-now-playing-vis { flex-basis: 50px; }
  .live-now-playing-vis span:nth-child(n+14) { display: none; }
}
@keyframes liveVisBar {
  0%   { transform: scaleY(.3); }
  25%  { transform: scaleY(1); }
  50%  { transform: scaleY(.55); }
  75%  { transform: scaleY(.9); }
  100% { transform: scaleY(.3); }
}
.live-now-playing-btn {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--lv-np-btn-bg);
  color: var(--lv-np-btn-ink);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(0, 0, 0, .16);
  transition: transform .12s;
}
.live-now-playing-btn:active { transform: scale(.92); }
.live-now-playing-btn svg { width: 17px; height: 17px; fill: currentColor; }
.live-now-playing-btn .icon-pause,
.live-now-playing-btn .icon-loading { display: none; }
.live-now-playing:not(.paused) .live-now-playing-btn .icon-play { display: none; }
.live-now-playing:not(.paused) .live-now-playing-btn .icon-pause { display: block; }
.live-now-playing.loading .live-now-playing-btn .icon-play,
.live-now-playing.loading .live-now-playing-btn .icon-pause { display: none; }
.live-now-playing.loading .live-now-playing-btn .icon-loading {
  display: block;
  animation: liveSpin .8s linear infinite;
}

/* ---------- شبكة الإذاعات (٣ في الصف، وآخر صف متوسّط) ---------- */
.live-radio-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}
.live-radio-card {
  --st: var(--ap-olive);
  position: relative;
  overflow: hidden;
  flex: 0 0 calc((100% - 24px) / 3);
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 6px 10px;
  text-align: center;
  font-family: var(--ap-font);
  color: var(--ap-ink);
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 22px;
  box-shadow: var(--ap-shadow);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: border-color .2s, box-shadow .2s, transform .12s;
}
.live-radio-card:active { transform: scale(.97); }
.live-radio-card:focus-visible { outline: 2px solid var(--ap-olive); outline-offset: 2px; }
/* لون كل محطة (زرار التشغيل + الأيقونة الاحتياطية) — مستوحى من شعارها */
.live-radio-card.art-1 { --st: #3E5A4A; }
.live-radio-card.art-2 { --st: #BBA36B; }
.live-radio-card.art-3 { --st: #C99A34; }
.live-radio-card.art-4 { --st: #5B9A93; }
.live-radio-card.art-5 { --st: #B4607A; }
body.theme-night .live-radio-card.art-1 { --st: #86A793; }
body.theme-night .live-radio-card.art-2 { --st: #CDB988; }
body.theme-night .live-radio-card.art-3 { --st: #D6AE55; }
body.theme-night .live-radio-card.art-4 { --st: #7DBBB2; }
body.theme-night .live-radio-card.art-5 { --st: #D48DA3; }
/* نقط خافتة أسفل الكارت (إيحاء موجة صوت) */
.live-radio-card::after {
  content: '';
  position: absolute;
  inset: auto 0 0 0;
  height: 0;
  display: none;
  background-image: radial-gradient(circle, var(--st) 1.1px, transparent 1.5px);
  background-size: 6px 6px;
  opacity: .14;
  -webkit-mask-image: linear-gradient(to top, #000, transparent);
  mask-image: linear-gradient(to top, #000, transparent);
  pointer-events: none;
}

/* شريط أخضر متدرّج أعلى الكارت — بيظهر بس وقت التشغيل */
.live-radio-card-banner {
  position: absolute;
  inset: 0 0 auto 0;
  height: 58%;
  background: linear-gradient(180deg, var(--lv-banner-a) 0%, var(--lv-banner-b) 55%, transparent 100%);
  opacity: 0;
  transition: opacity .3s;
  pointer-events: none;
}
.live-radio-card.playing .live-radio-card-banner { opacity: 1; }

/* شارة "لايف" الذهبية أعلى الكارت الشغّال */
.live-radio-card-badge {
  position: absolute;
  z-index: 3;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
  display: none;
  align-items: center;
  gap: 4px;
  height: 17px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 800;
  white-space: nowrap;
  color: #fff;
  background: var(--ap-gold);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--ap-gold) 45%, transparent);
}
body.theme-night .live-radio-card-badge { color: #15160f; }
.live-radio-card.playing .live-radio-card-badge { display: flex; }
.live-radio-card-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: liveDotPulse 1.6s ease-in-out infinite;
}

/* مربع الشعار الأبيض */
.live-radio-card-art {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 62px;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 18px;
  background: #fff;
  color: var(--st);
  box-shadow: 0 6px 16px rgba(60, 55, 30, .13), 0 0 0 1px rgba(90, 84, 60, .07);
}
.live-radio-card-icon { width: 44%; height: 44%; color: var(--st); }
/* لو الشعار فشل يتحمّل، العنصر بيتشال (onerror) وبتظهر الأيقونة الاحتياطية */
.live-radio-card-logo-plate {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 9%;
  background: #fff;
}
.live-radio-card-logo { width: 100%; height: 100%; object-fit: contain; border-radius: 8px; }

.live-radio-card-body { width: 100%; min-width: 0; margin-top: 12px; }
.live-radio-card-name {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 10.5px;
  font-weight: 800;
  line-height: 1.4;
  color: var(--ap-ink);
}

/* زرار التشغيل الدائري بلون المحطة */
.live-radio-card-play {
  position: absolute;
  z-index: 2;
  /* دايرة صغيرة داخل ركن مربع الشعار (بدل صف مستقل تحت الاسم) */
  top: 54px;
  left: calc(50% + 10px);
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lv-st-ink);
  background: var(--st);
  box-shadow: 0 5px 12px color-mix(in srgb, var(--st) 38%, transparent);
  transition: box-shadow .2s;
}
.live-radio-card-play svg { width: 11px; height: 11px; fill: currentColor; }
.live-radio-card-play .icon-pause,
.live-radio-card-play .icon-loading { display: none; }
.live-radio-card.playing .live-radio-card-play .icon-play { display: none; }
.live-radio-card.playing .live-radio-card-play .icon-pause { display: block; }
.live-radio-card.loading .live-radio-card-play .icon-play,
.live-radio-card.loading .live-radio-card-play .icon-pause { display: none; }
.live-radio-card.loading .live-radio-card-play .icon-loading {
  display: block;
  animation: liveSpin .8s linear infinite;
}

/* حالة "شغّال": إطار ذهبي + حلقة حوالين الزرار */
.live-radio-card.playing {
  border-color: var(--ap-gold);
  box-shadow: 0 0 0 1px var(--ap-gold), var(--ap-shadow);
}
.live-radio-card.playing .live-radio-card-art { box-shadow: 0 8px 20px rgba(30, 35, 15, .28); }
.live-radio-card.playing .live-radio-card-play {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--st) 22%, transparent), 0 4px 10px color-mix(in srgb, var(--st) 38%, transparent);
}
/* حالة "بيحمّل": الكارت يخفّ شوية بوهج دافي */
.live-radio-card.loading {
  border-color: color-mix(in srgb, var(--ap-gold) 55%, var(--ap-line));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-gold) 28%, transparent), 0 10px 28px color-mix(in srgb, var(--ap-gold) 22%, transparent);
}
.live-radio-card.loading .live-radio-card-body { opacity: .6; }
.live-radio-card-loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: rgba(255, 255, 255, .94);
}
.live-radio-card.loading .live-radio-card-loading-overlay { display: flex; }
.live-radio-card-loading-icon {
  width: 24px;
  height: 24px;
  color: var(--st);
  animation: liveSpin .8s linear infinite;
}
.live-radio-card-loading-text {
  font-family: var(--ap-font);
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
  color: #5A574D;
}
@keyframes liveSpin { to { transform: rotate(360deg); } }

/* ---------- ملحوظة البث الخارجي ---------- */
.live-radio-note {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 16px;
  padding: 12px 16px;
  background: var(--ap-olive-soft);
  border: 1px solid var(--ap-line);
  border-radius: 26px;
}
.live-radio-note-icon {
  flex-shrink: 0;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ap-olive);
  background: color-mix(in srgb, var(--ap-olive) 20%, transparent);
}
.live-radio-note-icon svg { width: 26px; height: 26px; }
.live-radio-footnote {
  margin: 0;
  font-family: var(--ap-font);
  font-size: 11.5px;
  line-height: 1.9;
  color: var(--ap-ink-2);
  text-align: start;
}

/* لمسات إضافية لصفحة «مباشر»: مساحة أوضح للمحطات على الهاتف، مع نفس
   ألوان صفحة الصوتيات ودون تغيير أي سلوك للتشغيل. */
#view-live .live-radio-head { padding: 14px 4px 22px; }
#view-live .live-radio-title {
  margin-bottom: 7px;
  font-size: clamp(28px, 7vw, 34px);
  letter-spacing: -.35px;
}
#view-live .live-radio-subtitle { max-width: 360px; margin-inline: auto; }
#view-live .live-radio-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: 100%;
  max-width: 920px;
  margin-inline: auto;
  gap: 14px;
}
#view-live .live-radio-card {
  min-height: 166px;
  padding: 18px 10px 14px;
  border-radius: 22px;
  box-shadow: 0 8px 22px rgba(60, 55, 30, .07), inset 0 1px 0 rgba(255,255,255,.76);
  transition: transform .2s ease, border-color .2s ease, box-shadow .2s ease, background-color .2s ease;
}
body.theme-night #view-live .live-radio-card {
  box-shadow: 0 10px 26px rgba(0,0,0,.24), inset 0 1px 0 rgba(255,255,255,.035);
}
#view-live .live-radio-card-art {
  max-width: 68px;
  border: 1px solid rgba(90,84,60,.08);
  border-radius: 19px;
  box-shadow: 0 7px 17px rgba(60,55,30,.12);
}
#view-live .live-radio-card-body { margin-top: 14px; }
#view-live .live-radio-card-name { font-size: 12px; line-height: 1.55; }
#view-live .live-radio-card-play { top: 62px; left: calc(50% + 12px); width: 29px; height: 29px; }
#view-live .live-radio-card.playing {
  border-color: color-mix(in srgb, var(--ap-gold) 72%, var(--ap-line));
  background: linear-gradient(155deg, color-mix(in srgb, var(--ap-gold-soft) 52%, var(--ap-card)), var(--ap-card) 68%);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-gold) 50%, transparent), 0 12px 28px rgba(70,60,30,.13);
}
body.theme-night #view-live .live-radio-card.playing {
  background: linear-gradient(155deg, color-mix(in srgb, var(--ap-olive-soft) 75%, var(--ap-card)), var(--ap-card) 72%);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-gold) 46%, transparent), 0 12px 28px rgba(0,0,0,.3);
}
#view-live .live-now-playing { margin-bottom: 18px; border: 1px solid rgba(255,255,255,.12); }
#view-live .live-radio-note { margin-top: 20px; }
@media (max-width: 600px) {
  #view-live .live-radio-list { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
  #view-live .live-radio-card { flex: 0 0 calc((100% - 24px) / 3); min-height: 154px; padding: 15px 5px 12px; }
  #view-live .live-radio-card-art { max-width: 58px; }
  #view-live .live-radio-card-body { margin-top: 12px; }
  #view-live .live-radio-card-name { font-size: 10.5px; line-height: 1.45; }
  #view-live .live-radio-card-play { top: 52px; left: calc(50% + 9px); width: 26px; height: 26px; }
  #view-live .live-radio-note { gap: 11px; padding: 12px 14px; border-radius: 21px; }
  #view-live .live-radio-note-icon { width: 44px; height: 44px; }
}
@media (min-width: 1100px) {
  #view-live .live-radio-list { grid-template-columns: repeat(5, minmax(0, 1fr)); }
}
@media (hover: hover) {
  #view-live .live-radio-card:hover { transform: translateY(-3px); border-color: color-mix(in srgb, var(--ap-olive) 42%, var(--ap-line)); }
}

@media (prefers-reduced-motion: reduce) {
  .live-now-playing-vis span,
  .live-radio-eyebrow-dot,
  .live-radio-card-dot,
  .nav-item.live-radio-playing .nav-item-live-dot,
  .nav-item.live-radio-playing .nav-item-icon.clr-live { animation: none; }
}

/* =========================================================================
   صفحة "حاسبة الزكاة" — وضعان (مبسّط/متقدم)، كارت أسعار المعادن قابل
   للتعديل، وملخّص لحظي مع شريط سفلي ثابت لمبلغ الزكاة المستحقة
   ========================================================================= */
.zakat-sheet {
  display: flex;
  flex-direction: column;
  max-height: 88vh;
  padding: 0;
  overflow: hidden;
}

.zakat-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 16px 18px 8px;
}
.zakat-title {
  flex: 1 1 auto;
  text-align: center;
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 700;
  color: var(--gold-deep);
  margin: 0;
}
body.theme-night .zakat-title { color: var(--gold-soft); }

.zakat-body {
  flex: 1 1 auto;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 4px 18px calc(18px + env(safe-area-inset-bottom));
}

.zakat-tabs {
  display: flex;
  gap: 4px;
  background: var(--paper-deep);
  border-radius: 14px;
  padding: 4px;
  margin-bottom: 14px;
}
.zakat-tab {
  flex: 1;
  text-align: center;
  padding: 10px 0;
  border-radius: 10px;
  font-size: 14.5px;
  font-weight: 700;
  color: var(--ink-soft);
}
.zakat-tab.active {
  color: var(--gold-deep);
  background: var(--surface);
  box-shadow: 0 3px 10px rgba(0,0,0,.08);
}
body.theme-night .zakat-tab.active { color: var(--gold-soft); }

.zakat-metals-card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  padding: 14px 16px;
  margin-bottom: 14px;
  box-shadow: 0 6px 16px rgba(40, 30, 10, .05);
}
body.theme-night .zakat-metals-card { box-shadow: 0 6px 16px rgba(0,0,0,.25); }
.zakat-metals-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.zakat-metals-info { flex: 1 1 auto; min-width: 0; }
.zakat-metals-heading { font-size: 14.5px; font-weight: 700; color: var(--gold-deep); margin: 0 0 6px; text-align: right; }
body.theme-night .zakat-metals-heading { color: var(--gold-soft); }
.zakat-metals-values { font-size: 13px; color: var(--ink); text-align: right; line-height: 1.6; }
.zakat-metals-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.zakat-icon-action {
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: var(--paper-deep);
  color: var(--gold-deep);
}
body.theme-night .zakat-icon-action { color: var(--gold-soft); }
.zakat-currency-pill {
  display: flex; align-items: center; gap: 6px;
  background: var(--paper-deep);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--gold-deep);
}
body.theme-night .zakat-currency-pill { color: var(--gold-soft); }

.zakat-metals-footer { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-top: 12px; }
.zakat-metals-note { flex: 1 1 auto; font-size: 11.5px; line-height: 1.6; color: var(--ink-soft); text-align: right; }
.zakat-edit-link { flex-shrink: 0; font-size: 13px; font-weight: 700; color: var(--gold-deep); }
body.theme-night .zakat-edit-link { color: var(--gold-soft); }

.zakat-price-editor { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--paper-line); }
.zakat-field { margin-bottom: 10px; }
.zakat-field label { display: block; font-size: 12px; color: var(--ink-soft); margin-bottom: 4px; text-align: right; }
.zakat-editor-actions { display: flex; gap: 8px; margin-top: 4px; }
.zakat-btn-primary, .zakat-btn-secondary {
  flex: 1;
  padding: 10px 0;
  border-radius: 10px;
  font-size: 13.5px;
  font-weight: 700;
}
.zakat-btn-primary { background: var(--gold-deep); color: #FFF7E6; }
body.theme-night .zakat-btn-primary { background: var(--gold-soft); color: #1A1509; }
.zakat-btn-secondary { background: var(--paper-deep); color: var(--ink-soft); }

.zakat-section-title { font-size: 13.5px; font-weight: 700; color: var(--ink-soft); margin: 4px 2px 8px; }

.zakat-card { background: var(--surface); border-radius: var(--radius-lg); padding: 2px 16px; margin-bottom: 14px; }
.zakat-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 0; }
.zakat-row + .zakat-row { border-top: 1px solid var(--paper-line); }
.zakat-row-label { flex: 1 1 auto; text-align: right; font-size: 14.5px; color: var(--ink); line-height: 1.35; }

.zakat-amount-wrap {
  flex-shrink: 0;
  width: 148px;
  display: flex; align-items: center; gap: 6px;
  background: var(--paper-deep);
  border-radius: 12px;
  padding: 10px 12px;
}
.zakat-unit { font-size: 12px; color: var(--ink-soft); white-space: nowrap; }
.zakat-amount-wrap input {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: var(--ink);
  font-size: 14.5px;
  text-align: left;
  direction: ltr;
}
.zakat-amount-wrap input::placeholder { color: var(--ink-soft); opacity: .6; }
.zakat-amount-wrap input::-webkit-outer-spin-button,
.zakat-amount-wrap input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.zakat-amount-wrap input[type=number] { -moz-appearance: textfield; }

.zakat-karat-block { padding: 12px 0 14px; border-top: 1px solid var(--paper-line); }
.zakat-karat-label { font-size: 12.5px; color: var(--ink-soft); margin: 0 0 8px; text-align: right; }
.zakat-karat-group { display: flex; gap: 8px; }
.zakat-karat-btn {
  flex: 1;
  text-align: center;
  padding: 10px 0;
  border-radius: 10px;
  background: var(--paper-deep);
  color: var(--ink-soft);
  font-size: 12.5px;
  font-weight: 700;
  border: 1.5px solid transparent;
}
.zakat-karat-btn.selected {
  border-color: var(--gold-deep);
  color: var(--gold-deep);
  background: color-mix(in srgb, var(--gold) 16%, transparent);
}
body.theme-night .zakat-karat-btn.selected {
  border-color: var(--gold-soft);
  color: var(--gold-soft);
  background: rgba(234, 201, 108, .14);
}

.zakat-nisab-group { display: flex; gap: 10px; margin-bottom: 16px; }
.zakat-nisab-btn {
  flex: 1;
  text-align: center;
  padding: 14px 6px;
  border-radius: var(--radius-md);
  background: var(--surface);
  color: var(--ink-soft);
  font-size: 13.5px;
  font-weight: 700;
  border: 1.5px solid transparent;
}
.zakat-nisab-btn.selected {
  border-color: var(--gold-deep);
  color: var(--gold-deep);
  background: color-mix(in srgb, var(--gold) 14%, transparent);
}
body.theme-night .zakat-nisab-btn.selected {
  border-color: var(--gold-soft);
  color: var(--gold-soft);
  background: rgba(234, 201, 108, .12);
}

.zakat-summary-card { background: var(--surface); border-radius: var(--radius-lg); padding: 16px; margin-bottom: 12px; }
.zakat-summary-title { font-family: var(--font-display); font-size: 17px; color: var(--gold-deep); text-align: right; margin: 0 0 10px; }
body.theme-night .zakat-summary-title { color: var(--gold-soft); }
.zakat-summary-row { display: flex; align-items: baseline; justify-content: space-between; padding: 6px 0; }
.zakat-summary-label { font-size: 13.5px; color: var(--ink-soft); }
.zakat-summary-label.strong { color: var(--ink); font-weight: 700; }
.zakat-summary-value { font-size: 14.5px; color: var(--ink); font-weight: 600; direction: ltr; }
.zakat-summary-value.strong { font-weight: 800; }

.zakat-nisab-message {
  display: flex; align-items: center; gap: 8px; justify-content: flex-end;
  margin-top: 12px; padding-top: 12px;
  border-top: 1px solid var(--paper-line);
  font-size: 13.5px; color: var(--ink); text-align: right;
}
.zakat-nisab-message.negative { color: var(--ink-soft); }
.zakat-check-badge {
  flex-shrink: 0;
  width: 20px; height: 20px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 11.5px; font-weight: 900;
  background: var(--emerald);
  color: #fff;
}
body.theme-night .zakat-check-badge { background: #6FBF8C; color: #0B2016; }
.zakat-nisab-message.negative .zakat-check-badge { background: var(--paper-line); color: var(--ink-soft); }

.zakat-disclaimer { font-size: 11.5px; line-height: 1.7; color: var(--ink-soft); text-align: center; padding: 6px 6px 4px; opacity: .85; }

.zakat-bottom-bar {
  flex-shrink: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 14px 18px calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--paper-line);
  background: var(--paper);
}
.zakat-bottom-amount { font-size: 22px; font-weight: 800; color: var(--gold-deep); direction: ltr; }
body.theme-night .zakat-bottom-amount { color: var(--gold-soft); }
.zakat-bottom-label { font-size: 12.5px; color: var(--ink-soft); }

/* في الوضع الليلي، --paper-deep قريب جداً من --surface فتختفي حدود
   صناديق الإدخال والأزرار الفاتحة داخل بطاقات الزكاة؛ نضيف لها حدّاً
   واضحاً بلون --paper-line ليبقى شكلها مميزاً كما في الوضع النهاري */
body.theme-night .zakat-amount-wrap,
body.theme-night .zakat-icon-action,
body.theme-night .zakat-currency-pill,
body.theme-night .zakat-karat-btn:not(.selected) {
  border: 1px solid var(--paper-line);
}

/* =========================================================================
   توحيد ألوان اللايت مود لصفحة "الفهرس" وباقي الصفحات المدرجة أدناه
   (صفحات الصوتيات لها ملف مستقل: style.css) مع صور تطبيق "Golden Quran"
   المرجعية بالظبط: خلفية كريمي فاتح (#F9F6EF) + لون ذهبي-زيتوني غامق واحد (#695010)
   للعناوين والبادچات والكروت المميَّزة وأزرار "أضف"/التبويب النشط، بدل
   التدرّج الذهبي اللامع المستخدم في باقي التطبيق.

   الحيلة: بنعيد تعريف المتغيّرات --paper و--gold-deep و--btn-grad محليًا
   جوه حاوية كل صفحة من الاتنين بس، وبس في الوضع النهاري (body:not(.theme-night))،
   فكل قاعدة تحتهم أصلاً بتستخدم var(--paper)/var(--gold-deep)/var(--btn-grad)
   بتاخد اللون الجديد تلقائيًا من غير ما نلمس تعريف المتغيّر الأصلي ولا أي
   صفحة تانية في التطبيق ولا الوضع الليلي (لسه زي ما هو طبق الأصل)
   ========================================================================= */
body:not(.theme-night) #index-overlay.overlay.overlay-fullpage,
body:not(.theme-night) #playlist-detail-overlay.overlay.overlay-fullpage,
body:not(.theme-night) #settings-overlay.overlay.overlay-fullpage,
body:not(.theme-night) #nawawi-overlay.overlay.overlay-fullpage,
body:not(.theme-night) #nawawi-detail-overlay.overlay.overlay-fullpage,
body:not(.theme-night) #tasmee-overlay,
body:not(.theme-night) #zakat-overlay,
body:not(.theme-night) #view-azkar,
body:not(.theme-night) #view-duas,
body:not(.theme-night) #view-hadith,
body:not(.theme-night) #view-prayer,
body:not(.theme-night) #view-tools {
  --paper: #F9F6EF;
  --paper-deep: #F1ECDD;
  --gold-deep: #695010;
  --btn-grad: #695010;
  --btn-grad-fg: #FFFFFF;
  --btn-shadow: 0 4px 12px rgba(105, 80, 16, .22);
  --btn-shadow-press: 0 1px 4px rgba(105, 80, 16, .20);
}
/* #view-tools مالوش خلفية خاصة بيه أصلًا (بيورّث خلفية #app-main المشتركة
   مع صفحة المصحف)، فلازم نديله خلفية صريحة هنا عشان يتلوّن فعليًا بالكريمي
   الجديد من غير ما يأثر على خلفية صفحة المصحف نفسها */
body:not(.theme-night) #view-tools { background: var(--paper); }

/* بار "أدوات المسلم"/"الصوتيات" السفلي (.tools-bottom-bar) بقى بنفس شكل
   وألوان بار صفحة المصحف السفلي (.mushaf-quick-bar) بالظبط: خلفية بيضاء
   صرفة من غير حدود، بدل الكريمي مع الحدّ الذهبي الخفيف اللي كان قبل كده */
body:not(.theme-night) .tools-bottom-bar {
  background: #FFFFFF;
  border-color: transparent;
  box-shadow: 0 14px 34px rgba(6, 41, 31, .07);
}

/* =========================================================================
   فهرس السور والأجزاء — سكِن خاص بـ #index-overlay بس. في الوضع الليلي
   (theme-night) الشكل زي ما هو طبق الأصل من الفيديو المرجعي (خلفية سودة
   صافية + كروت غامقة وذهبي). في الوضع النهاري بقى بيتلوّن بألوان فاتحة
   متناسقة مع باقي صفحات التطبيق بدل الأسود الثابت
   ========================================================================= */
#index-overlay.overlay.overlay-fullpage {
  background: var(--paper);
}
body.theme-night #index-overlay.overlay.overlay-fullpage {
  background: #000;
}
#index-overlay .overlay-sheet.fullpage-shell {
  background: var(--paper);
}
body.theme-night #index-overlay .overlay-sheet.fullpage-shell {
  background: #000;
}

/* -------- الهيدر: زرار إغلاق مربّع + عنوان ذهبي كوفي كبير -------- */
#index-overlay .fullpage-shell > .overlay-head {
  border-bottom: none;
  padding-bottom: 6px;
}
#index-overlay #index-overlay-title {
  font-family: var(--font-kufic);
  color: var(--gold-deep);
  font-size: 25px;
  font-weight: 700;
}
body.theme-night #index-overlay #index-overlay-title { color: var(--gold); }
#index-overlay .icon-btn#btn-close-index {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: var(--paper-deep);
  color: var(--ink);
}
body.theme-night #index-overlay .icon-btn#btn-close-index {
  background: #1c1c1e;
  color: #fff;
}
#index-overlay .icon-btn#btn-close-index:hover,
#index-overlay .icon-btn#btn-close-index:active {
  background: var(--paper-line);
}
body.theme-night #index-overlay .icon-btn#btn-close-index:hover,
body.theme-night #index-overlay .icon-btn#btn-close-index:active {
  background: #29292b;
}
#index-overlay .icon-btn#btn-close-index svg { width: 18px; height: 18px; }

/* -------- حاوية ثابتة (sticky) لكارت "فاصل الصفحة" + شريط البحث: تفضل
   ظاهرة فوق التبويب أثناء سكرول قائمة السور، من غير ما يحتاج المستخدم
   يرجع لفوق عشان يوصلهم -------- */
/* -------- حاوية ثابتة (sticky) لكارت "فاصل الصفحة" + شريط البحث: تفضل
   ظاهرة فوق التبويب أثناء سكرول قائمة السور، من غير ما يحتاج المستخدم
   يرجع لفوق عشان يوصلهم. بتاخد سالب مارجن بمقاس بادنج .fullpage-scroll
   وتضيفه بادنج لنفسها، عشان تغطي فراغ البادنج دا كمان بخلفيتها ومايبانش
   من تحتها أي حاجة وهي بتسكرول -------- */
#index-overlay #index-tab-surah .index-sticky-top {
  position: sticky;
  top: -14px;
  z-index: 5;
  background: var(--ap-bg, var(--paper));
  margin: -14px -18px 0;
  padding: 14px 18px 2px;
}

/* -------- كارت "فاصل الصفحة" -------- */
#index-overlay .index-resume-card {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  background: #FFFFFF;
  border-radius: 18px;
  padding: 14px 16px;
  margin-bottom: 14px;
  text-align: right;
  transition: transform .12s ease, background .15s;
}
body.theme-night #index-overlay .index-resume-card { background: #29292b; }
#index-overlay .index-resume-card:active { transform: scale(.98); background: var(--paper-deep); }
body.theme-night #index-overlay .index-resume-card:active { background: #313133; }
#index-overlay .index-resume-card[hidden] { display: none; }
#index-overlay .index-resume-icon-circle {
  flex-shrink: 0;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(201, 162, 39, .16);
  color: var(--gold-deep);
}
body.theme-night #index-overlay .index-resume-icon-circle { color: var(--gold-soft); }
#index-overlay .index-resume-icon-circle svg { width: 21px; height: 21px; }
#index-overlay .index-resume-text {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
#index-overlay .index-resume-title {
  font-family: var(--font-kufic);
  font-weight: 700;
  font-size: 16.5px;
  color: var(--ink);
}
body.theme-night #index-overlay .index-resume-title { color: #fff; }
#index-overlay .index-resume-sub {
  font-family: var(--font-ui);
  font-size: 13.5px;
  color: var(--gold-deep);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
body.theme-night #index-overlay .index-resume-sub { color: var(--gold-soft); }
#index-overlay .index-resume-arrow {
  flex-shrink: 0;
  display: flex;
  color: var(--gold);
  transform: scaleX(-1);
}
#index-overlay .index-resume-arrow svg { width: 21px; height: 21px; }

/* -------- شريط البحث -------- */
#index-overlay .index-search-row {
  background: #FFFFFF;
  border: none;
  border-radius: 16px;
  padding: 13px 16px;
}
body.theme-night #index-overlay .index-search-row { background: #29292b; }
#index-overlay .hadith-search-icon { color: var(--ink-soft); }
body.theme-night #index-overlay .hadith-search-icon { color: #8e8e93; }
#index-overlay .hadith-search-input { color: var(--ink); }
body.theme-night #index-overlay .hadith-search-input { color: #fff; }
#index-overlay .hadith-search-input::placeholder { color: var(--ink-soft); opacity: 1; }
body.theme-night #index-overlay .hadith-search-input::placeholder { color: #8e8e93; }

/* -------- قائمتا فهرس السور وفهرس الأجزاء: كل صف كارت مستقل — البادنج
   العمودي اتنصّف عشان الكارت يبقى أقصر ارتفاعًا -------- */
#index-overlay .surah-list { gap: 8px; }
#index-overlay .surah-item,
#index-overlay .hizb-quarter-item {
  background: #FFFFFF;
  border-bottom: none;
  border-radius: 18px;
  padding: 7px 16px;
}
body.theme-night #index-overlay .surah-item,
body.theme-night #index-overlay .hizb-quarter-item {
  background: #333335;
}
#index-overlay .surah-item:hover, #index-overlay .surah-item:active,
#index-overlay .hizb-quarter-item:hover, #index-overlay .hizb-quarter-item:active {
  background: var(--paper-deep);
}
body.theme-night #index-overlay .surah-item:hover, body.theme-night #index-overlay .surah-item:active,
body.theme-night #index-overlay .hizb-quarter-item:hover, body.theme-night #index-overlay .hizb-quarter-item:active {
  background: #3c3c3e;
}

#index-overlay .surah-item-name,
#index-overlay .hizb-quarter-text {
  color: var(--ink);
  font-size: 17px;
}
body.theme-night #index-overlay .surah-item-name,
body.theme-night #index-overlay .hizb-quarter-text {
  color: #fff;
}
#index-overlay .surah-item-sub,
#index-overlay .hizb-quarter-sub {
  color: var(--ink-soft);
  font-size: 13px;
}
body.theme-night #index-overlay .surah-item-sub,
body.theme-night #index-overlay .hizb-quarter-sub {
  color: #9a9a9e;
}

/* بادچ رقم السورة/الربع — مستطيل مدوّر بيچ مطفّي في اللايت مود، بنفس درجة
   الصورة المرجعية (أبيض/بني/بيچ) بدل الشفافية الذهبية القديمة */
#index-overlay .surah-item-num,
#index-overlay .hizb-quarter-badge {
  min-width: 26px;
  height: 22px;
  padding: 0 5px;
  border-radius: 8px;
  background: var(--paper-deep);
  color: var(--gold-deep);
  font-size: 11px;
}
body.theme-night #index-overlay .surah-item-num,
body.theme-night #index-overlay .hizb-quarter-badge {
  background: rgba(201, 162, 39, .18);
  color: var(--gold-soft);
}
#index-overlay .hizb-quarter-badge-full {
  background: var(--gold-deep);
  color: #fff;
}

/* دائرة رقم الصفحة — بيچ فاتح في اللايت مود بدل التان الغامق القديم */
#index-overlay .surah-item-page,
#index-overlay .hizb-quarter-page {
  min-width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--paper-deep);
  color: var(--ink);
  font-size: 13px;
  margin-inline-start: 0;
  padding-inline-start: 0;
}
body.theme-night #index-overlay .surah-item-page,
body.theme-night #index-overlay .hizb-quarter-page {
  background: #000;
  color: #fff;
}

/* الصف المطابق للصفحة المفتوحة حاليًا — كارت بني/زيتوني صلب في اللايت مود
   (بدل التدرّج الذهبي اللامع القديم)، طبق الصورة المرجعية بالظبط */
#index-overlay .surah-item-current,
#index-overlay .hizb-quarter-item-current {
  background: var(--gold-deep);
  border-radius: 18px;
}
body.theme-night #index-overlay .surah-item-current,
body.theme-night #index-overlay .hizb-quarter-item-current {
  background: linear-gradient(135deg, var(--gold-bright), var(--gold));
}
#index-overlay .surah-item-current:hover, #index-overlay .surah-item-current:active,
#index-overlay .hizb-quarter-item-current:hover, #index-overlay .hizb-quarter-item-current:active {
  background: var(--gold-deep);
}
body.theme-night #index-overlay .surah-item-current:hover, body.theme-night #index-overlay .surah-item-current:active,
body.theme-night #index-overlay .hizb-quarter-item-current:hover, body.theme-night #index-overlay .hizb-quarter-item-current:active {
  background: linear-gradient(135deg, var(--gold-bright), var(--gold));
}
#index-overlay .surah-item-current .surah-item-name,
#index-overlay .surah-item-current .surah-item-sub,
#index-overlay .hizb-quarter-item-current .hizb-quarter-text,
#index-overlay .hizb-quarter-item-current .hizb-quarter-sub {
  color: #fff;
}
#index-overlay .surah-item-current .surah-item-num,
#index-overlay .surah-item-current .surah-item-page,
#index-overlay .hizb-quarter-item-current .hizb-quarter-badge,
#index-overlay .hizb-quarter-item-current .hizb-quarter-page {
  background: rgba(255, 255, 255, .55);
  color: var(--gold-deep);
}
#index-overlay .hizb-quarter-item-current .hizb-quarter-badge-full {
  background: rgba(255, 255, 255, .55);
  color: var(--gold-deep);
}

/* عناوين "الجزء N" الفاصلة داخل القائمتين */
#index-overlay .surah-juz-divider span { color: var(--gold-deep); font-size: 15px; }
body.theme-night #index-overlay .surah-juz-divider span { color: var(--gold-soft); }
#index-overlay .surah-juz-divider::after { background: var(--gold); }
body.theme-night #index-overlay .surah-juz-divider::after { background: var(--gold-soft); }
#index-overlay .ajza-juz-divider { background: var(--paper); }
body.theme-night #index-overlay .ajza-juz-divider { background: #000; }
#index-overlay .ajza-juz-divider span:first-child { color: var(--gold-deep); }
body.theme-night #index-overlay .ajza-juz-divider span:first-child { color: var(--gold-soft); }
#index-overlay .ajza-juz-divider-bar { background: var(--gold); }
body.theme-night #index-overlay .ajza-juz-divider-bar { background: var(--gold-soft); }

/* -------- البار السفلي -------- */
#index-overlay .fullpage-bottom-bar {
  background: var(--paper-deep);
  border-top: none;
}
body.theme-night #index-overlay .fullpage-bottom-bar { background: #232325; }
#index-overlay .fullpage-bar-btn {
  color: var(--ink-soft);
}
body.theme-night #index-overlay .fullpage-bar-btn { color: #c9c2b2; }
#index-overlay .fullpage-bar-btn.active {
  color: var(--gold);
  background: rgba(169, 116, 63, .28);
}

/* البار السفلي هنا بقى 5 أزرار (فهرس السور / فهرس الأجزاء / بحث في الآيات /
   المرجعيات / الملاحظات) بدل 3، فبنصغّر الأيقونة والخط والمسافات الداخلية
   مخصوص للفهرس عشان الخمسة يبانوا كاملين. والاسم بقى يلف على سطرين بدل
   الـ ellipsis، فحتى في اللغات اللي أسماؤها أطول من العربي مفيش كلمة بتتقص */
#index-overlay .fullpage-bottom-bar {
  gap: 0;
  padding-left: 1px;
  padding-right: 1px;
}
#index-overlay .fullpage-bar-btn {
  gap: 3px;
  padding: 7px 1px;
  border-radius: 12px;
  font-size: clamp(8.5px, 2.6vw, 11px);
  letter-spacing: -.2px;
}
#index-overlay .fullpage-bar-icon svg { width: 19px; height: 19px; }
#index-overlay .fullpage-bar-btn span:last-child {
  white-space: normal;
  text-overflow: clip;
  overflow-wrap: anywhere;
  line-height: 1.2;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* =========================================================================
   ميزة "أدعية الأحبة" (دعاء بالاسم) — طبق الأصل من الفيديو المرجعي:
   خلفية سوداء صرفة دايمًا (بغض النظر عن ثيم الورق/الليل بتاع باقي التطبيق)،
   وعنوان بخط Tajawal بولد ذهبي بدل خط العرض الزخرفي (Aref Ruqaa) المستخدم
   في باقي عناوين الـ overlays
   ========================================================================= */
.overlay.loved-ones-overlay { background: #000; }
.overlay.loved-ones-overlay .loved-ones-sheet { background: #000; }
body.theme-night .overlay.loved-ones-overlay { background: #000; }

/* صفحة "أدعية الأحبة" في اللايت مود بس: نفس الخلفية الكريمي والذهبي-الزيتوني
   المستخدمين في باقي الصفحات (بدل التصميم الأسود الثابت اللي كان مطلوب
   قبل كده لكل الأوضاع). الوضع الليلي فاضل زي ما هو أسود بالظبط */
body:not(.theme-night) .overlay.loved-ones-overlay,
body:not(.theme-night) .overlay.loved-ones-overlay .loved-ones-sheet {
  background: #F9F6EF;
}
body:not(.theme-night) .loved-ones-close-btn {
  background: #F1ECDD;
  color: #695010;
}
body:not(.theme-night) .loved-ones-close-btn:hover,
body:not(.theme-night) .loved-ones-close-btn:active {
  background: #E6DFC8;
}
body:not(.theme-night) .loved-ones-dots-btn {
  background: #F1ECDD;
  color: #695010;
}
body:not(.theme-night) .loved-ones-dots-btn:hover,
body:not(.theme-night) .loved-ones-dots-btn:active {
  background: #E6DFC8;
}
body:not(.theme-night) .loved-ones-title { color: #695010 !important; }
body:not(.theme-night) .loved-ones-hint { color: #5C6250; }
body:not(.theme-night) .loved-ones-name-input {
  border-color: #D9E0CC;
  color: #1F211A;
}
body:not(.theme-night) .loved-ones-name-input::placeholder { color: #9a8f78; }
body:not(.theme-night) .loved-ones-name-input:focus {
  border-color: #695010;
  color: #695010;
}
body:not(.theme-night) .loved-ones-rel-btn {
  background: #FFFFFF;
  color: #1F211A;
  box-shadow: 0 2px 8px rgba(105, 80, 16, .1);
}
body:not(.theme-night) .loved-ones-rel-btn:active { background: #F1ECDD; }
body:not(.theme-night) .loved-ones-change-btn { color: #695010; }
body:not(.theme-night) .loved-ones-dua-card {
  background: #FFFFFF;
  color: #1F211A;
  box-shadow: 0 2px 8px rgba(105, 80, 16, .1);
}
body:not(.theme-night) .loved-ones-dua-card .loved-ones-dua-name { color: #695010; }

.loved-ones-head {
  direction: ltr;
  border-bottom: none !important;
  padding-top: calc(16px + env(safe-area-inset-top)) !important;
}

.loved-ones-close-btn {
  width: 38px; height: 38px;
  border-radius: 50%;
  background: #262626;
  color: #fff;
}
.loved-ones-close-btn svg { width: 18px; height: 18px; }
.loved-ones-close-btn:hover, .loved-ones-close-btn:active { background: #333; }

.loved-ones-dots-btn {
  width: 42px; height: 42px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #4a3418, #2a1d0c);
  color: var(--gold-bright, #F3D889);
}
.loved-ones-dots-btn svg { width: 19px; height: 19px; }
.loved-ones-dots-btn:hover, .loved-ones-dots-btn:active { background: radial-gradient(circle at 35% 30%, #5a4020, #2a1d0c); }

/* العنوان: Tajawal بولد ذهبي — بلا خط Aref Ruqaa إطلاقًا، بالظبط زي الفيديو */
.loved-ones-title {
  direction: rtl;
  font-family: var(--font-ui) !important;
  font-weight: 700;
  color: var(--gold-soft, #EAC96C) !important;
  font-size: 22px;
  margin: 0;
  flex: 1;
  text-align: center;
}

.loved-ones-hint {
  color: #9a9a9a;
  font-family: var(--font-ui);
  font-size: 14.5px;
  line-height: 1.8;
  text-align: right;
  margin: 4px 2px 18px;
}

/* حقل إدخال الاسم — حدود رمادية عادي، وتبقى ذهبية وقت التركيز، زي الفيديو */
.loved-ones-input-wrap { margin-bottom: 22px; }
.loved-ones-name-input {
  width: 100%;
  box-sizing: border-box;
  background: transparent;
  border: 1.6px solid #4a4a4a;
  border-radius: 16px;
  padding: 16px 18px;
  color: #fff;
  font-family: var(--font-ui);
  font-size: 16px;
  text-align: right;
  transition: border-color .18s;
}
.loved-ones-name-input::placeholder { color: #8a8a8a; }
.loved-ones-name-input:focus {
  outline: none;
  border-color: var(--gold-soft, #EAC96C);
  color: var(--gold-soft, #EAC96C);
}

/* شبكة صلات القرابة: عمودين، كروت رمادية غامقة */
.loved-ones-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding-bottom: 12px;
}
.loved-ones-rel-btn {
  position: relative;
  overflow: hidden;
  background: #222222;
  border: none;
  border-radius: 16px;
  padding: 18px 10px;
  color: #f2f2f2;
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 16px;
  text-align: center;
  transition: background .15s, transform .1s;
}
.loved-ones-rel-btn:active { transform: scale(.97); background: #2a2a2a; }

/* رابط "تغيير الشخص" أعلى قائمة النتيجة */
.loved-ones-change-btn {
  display: flex;
  direction: rtl;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  width: 100%;
  background: none;
  border: none;
  color: var(--gold-soft, #EAC96C);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 15px;
  padding: 0 2px 18px;
}

/* قائمة كروت الدعاء — نص بخط Amiri مشكّل، متمركز، فاصل مريح بين كل كارت */
.loved-ones-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-bottom: 24px;
}
.loved-ones-dua-card {
  background: #1d1d1d;
  border-radius: 18px;
  padding: 20px 18px;
  color: #f2f2f2;
  font-family: var(--font-badge);
  font-size: 17px;
  line-height: 2;
  text-align: center;
}
.loved-ones-dua-card .loved-ones-dua-name { color: var(--gold-soft, #EAC96C); }

/* =========================================================================
   i18n — قائمة اختيار اللغة في الإعدادات + دعم اتجاه LTR للقوائم المترجمة
   ========================================================================= */
.language-row .language-check {
  width: 20px; height: 20px;
  color: var(--accent, #2E7A5B);
  opacity: 1;
  flex-shrink: 0;
  animation: langCheckPop .22s cubic-bezier(.34,1.56,.64,1);
}
@keyframes langCheckPop {
  0% { transform: scale(0.4); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}
.language-row.is-active-lang { background: rgba(46, 122, 91, .06); transition: background .18s ease; }
body.theme-night .language-row.is-active-lang { background: rgba(255,255,255,.05); }
.language-row { transition: background .15s ease; }
.language-row .settings-card-title { font-weight: 600; }

/* قائمة اللغة: مطوية افتراضيًا، تنسدل عند الضغط على الصف الرئيسي */
.language-dropdown-chevron {
  transition: transform .18s ease;
}
.language-dropdown-chevron.is-open {
  transform: rotate(-90deg);
}
.language-dropdown-panel {
  border-top: 1px solid var(--paper-line);
  max-height: 320px;
  overflow-y: auto;
}
.language-dropdown-panel.hidden {
  display: none;
}
#language-picker-trigger { width: 100%; }

/* العناصر المترجمة (الهيدر، صفحة أدوات المسلم، البار السفلي، الإعدادات)
   تقبل dir="ltr" ديناميكيًا عند اختيار لغة لاتينية/غير عربية، بينما تبقى
   بقية صفحات التطبيق (المصحف، الأذكار، الأدعية، الحديث...) بالعربية RTL
   دائمًا لأنها نص ديني غير مترجم بعد */
#view-tools[dir="ltr"],
.tools-bottom-bar[dir="ltr"],
#settings-overlay[dir="ltr"],
#view-home[dir="ltr"],
#view-azkar[dir="ltr"],
#view-live[dir="ltr"],
#view-duas[dir="ltr"],
#view-hadith[dir="ltr"],
#view-prayer[dir="ltr"],
#view-qibla[dir="ltr"],
#view-tasbih[dir="ltr"],
#view-mosque[dir="ltr"],
#index-overlay[dir="ltr"],
#qadaa-overlay[dir="ltr"],
#zakat-overlay[dir="ltr"],
#bookmarks-overlay[dir="ltr"],
#notes-overlay[dir="ltr"],
#tasmee-overlay[dir="ltr"],
#loved-ones-select-overlay[dir="ltr"],
#loved-ones-result-overlay[dir="ltr"],
#reminders-overlay[dir="ltr"] {
  direction: ltr;
}
#view-tools[dir="ltr"] .nav-grid,
.tools-bottom-bar[dir="ltr"] {
  direction: ltr;
}
#settings-overlay[dir="ltr"] .settings-card-row,
#settings-overlay[dir="ltr"] .settings-card-label {
  direction: ltr;
}
#settings-overlay[dir="ltr"] .settings-card-arrow {
  transform: scaleX(-1);
}

/* =========================================================================
   ★ نظام الأزرار الحديث (Modern Button System)
   -------------------------------------------------------------------------
   الهدف: نوحّد شكل أزرار التطبيق كله على أسلوب التطبيقات العالمية الحديثة
   بدل اللون الأصفر الكموني المسطّح (--gold-deep: #8B6914) اللي كان محطوط
   كـ background صريح في أماكن كتير. الفكرة إن الزرار الأساسي يبقى:
     • تدرّج ذهبي ناعم (مش لون مسطّح واحد)
     • ظل ملوّن خفيف تحته (elevation) بيختفي وقت الضغط
     • لمعة داخلية بسيطة من فوق (inset highlight) بتدّي إحساس زجاجي
     • حركة ضغط سريعة بمنحنى spring مش linear
   وفي الوضع الليلي بنقلب المعادلة: التدرّج يبقى ذهبي فاتح والنص غامق،
   لأن (ذهبي غامق + نص غامق) كان تباينه وحش جدًا في الدارك مود.
   ========================================================================= */
:root {
  --btn-grad: linear-gradient(135deg, #E0B94A 0%, #C9A227 48%, #9C7818 100%);
  --btn-grad-fg: #FFFFFF;
  --btn-grad-ring: rgba(255, 255, 255, .28);
  --btn-shadow: 0 4px 14px rgba(139, 105, 20, .30), 0 1px 2px rgba(60, 45, 10, .18);
  --btn-shadow-press: 0 1px 4px rgba(139, 105, 20, .26);
  --btn-ease: cubic-bezier(.2, .8, .3, 1);
}
body.theme-night {
  --btn-grad: linear-gradient(135deg, #F3D889 0%, #E0B94A 50%, #C9A227 100%);
  --btn-grad-fg: #1C1710;
  --btn-grad-ring: rgba(255, 255, 255, .40);
  --btn-shadow: 0 4px 16px rgba(0, 0, 0, .45), 0 0 0 1px rgba(234, 201, 108, .14);
  --btn-shadow-press: 0 1px 5px rgba(0, 0, 0, .40);
}

/* الطبقة المشتركة: أي زرار أساسي في التطبيق بياخد نفس المعاملة بالظبط */
.playlist-detail-play-btn,
.playlist-detail-action-btn[data-active="true"],
.reciter-quick-picker-check,
.btn-primary,
.city-gps-btn,
.city-search-btn,
.gp-play-btn,
.playlist-create-btn {
  background: var(--btn-grad);
  color: var(--btn-grad-fg);
  border: none;
  box-shadow: var(--btn-shadow), inset 0 1px 0 var(--btn-grad-ring);
  transition:
    transform .16s var(--btn-ease),
    box-shadow .18s var(--btn-ease),
    filter .18s var(--btn-ease);
}
.playlist-detail-play-btn:active,
.playlist-detail-action-btn[data-active="true"]:active,
.btn-primary:active,
.city-gps-btn:active,
.city-search-btn:active,
.gp-play-btn:active,
.playlist-create-btn:active {
  transform: scale(.955);
  box-shadow: var(--btn-shadow-press), inset 0 1px 0 var(--btn-grad-ring);
  filter: saturate(1.08) brightness(.97);
}

/* تحسينات لمسية عامة على كل أزرار التطبيق: من غير وميض رمادي عند اللمس
   (سلوك الويب-فيو الافتراضي اللي بيفضح إن ده موقع مش تطبيق نيتيف)، ومع
   حلقة تركيز واضحة لمستخدمي الكيبورد/الأكسسبيليتي فقط */
button, .option-btn, [role="button"] {
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}
button:focus-visible,
[role="button"]:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: inherit;
}

/* =========================================================================
   ★ انتقال فتح صفحة "أدوات المسلم" من زرار النقط في هيدر المصحف
   -------------------------------------------------------------------------
   أسلوب iOS الحديث (الـ zoom transition بتاع iOS 18): الصفحة الجديدة بتتولد
   من مكان الزرار اللي اتضغط نفسه مش من وسط الشاشة — بنحسب إحداثيات الزرار
   في app.js ونحطها كـ transform-origin، فالصفحة بتتفتّح "من تحت صباعه".
   منحنى الحركة spring خفيف (بيعدّي ١ بشكل بسيط قبل ما يستقر) عشان يبقى
   ليه وزن حقيقي بدل الحركة الميكانيكية.

   ملحوظة مهمة: الأنيميشن متطبّق على .tools-page بس (مش على #view-tools)،
   لنفس السبب المشروح فوق عند .view-enter-active — أي transform على الأب
   بيكسر الـ position:fixed بتاع العنوان والبار السفلي. فالعنوان والبار
   ليهم أنيميشن منفصل خاص بيهم.
   ========================================================================= */
@keyframes toolsZoomIn {
  0%   { opacity: 0; transform: scale(.80); }
  60%  { opacity: 1; }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes toolsTitleIn {
  from { opacity: 0; transform: translateY(-14px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes toolsBarIn {
  from { opacity: 0; transform: translateY(130%); }
  to   { opacity: 1; transform: translateY(0); }
}

#view-tools.tools-zoom-enter .tools-page {
  transform-origin: var(--tools-zoom-x, 50%) var(--tools-zoom-y, 0%);
  animation: toolsZoomIn .54s cubic-bezier(.17, .89, .28, 1.08) both;
  will-change: transform, opacity;
}
#view-tools.tools-zoom-enter .tools-page-title {
  animation: toolsTitleIn .46s cubic-bezier(.16, 1, .3, 1) .06s both;
}
#view-tools.tools-zoom-enter .tools-bottom-bar {
  animation: toolsBarIn .52s cubic-bezier(.17, .89, .28, 1.06) .1s both;
}

/* زرار النقط نفسه بياخد ردّ فعل لمسي أوضح: بيتكمش جوه لمسة ذهبية دايرية
   بدل مجرد تغيير خلفية مفاجئ */
.menu-dot-btn {
  transition:
    background .2s var(--btn-ease, cubic-bezier(.2,.8,.3,1)),
    transform .18s var(--btn-ease, cubic-bezier(.2,.8,.3,1));
}
.menu-dot-btn:active {
  transform: scale(.86);
  background: radial-gradient(circle, rgba(201,162,39,.26) 0%, rgba(201,162,39,.06) 70%);
}

/* احترام تفضيل النظام "تقليل الحركة" — ضروري في أي تطبيق محترم */
@media (prefers-reduced-motion: reduce) {
  #view-tools.tools-zoom-enter .tools-page,
  #view-tools.tools-zoom-enter .tools-page-title,
  #view-tools.tools-zoom-enter .tools-bottom-bar {
    animation: none;
  }
}

