/* -------- الشريطان العائمان أثناء التسميع المباشر فوق صفحة المصحف -------- */
#tasmee-live-top.tasmee-live-top {
  background: var(--ap-card);
  box-shadow: var(--ap-shadow);
}
#tasmee-live-top .tasmee-live-icon-btn {
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
}
#tasmee-live-top .tasmee-live-title strong,
body.theme-night #tasmee-live-top .tasmee-live-title strong {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#tasmee-live-top #tasmee-live-progress { color: var(--ap-ink-2); font-family: var(--ap-font); }
#tasmee-live-status.tasmee-live-status {
  background: var(--ap-card);
  color: var(--ap-ink-2);
  font-family: var(--ap-font);
  box-shadow: var(--ap-shadow);
}
#tasmee-live-bar.tasmee-live-bar {
  background: transparent;
}
#tasmee-live-bar .tasmee-live-eye-btn {
  background: var(--ap-card);
  color: var(--ap-ink);
  box-shadow: var(--ap-shadow);
}
#tasmee-live-bar .tasmee-live-finish-btn {
  background: rgba(192, 57, 43, .1);
  color: #C0392B;
  font-family: var(--ap-font);
}
#tasmee-live-bar .tasmee-live-mic-btn { background: var(--ap-gold); box-shadow: 0 6px 22px color-mix(in srgb, var(--ap-gold) 40%, transparent); }
#tasmee-live-bar .tasmee-live-mic-btn.listening { background: var(--ap-olive); }

/* =========================================================================
   توحيد طابع "الختمة" (الصفحة الرئيسية + إضافة/تفاصيل/سجل/ختمات خاصة)،
   "الأذكار" و"الأدعية" (والقائمة التفصيلية المشتركة #dhikr-list-overlay)،
   و"المسبحة" (الصفحة + إدارة الأذكار والتسابيح + محرّر الذكر) مع طابع
   صفحة "الصوتيات" — نفس آلية الأقسام السابقة أعلاه بالظبط: خلفية كريمية
   دافئة، بطاقات بيضاء بحواف دائرية وظل ناعم، ولون زيتوني/ذهبي موحّد بدل
   الذهبي/الكهرماني الكلاسيكي، وخط تجوال بدل خطوط العرض/الكوفي الزخرفية.
   القواعد تعتمد على متغيّرات --ap-* (style.css) بعد إضافة الحاويات
   دي لقائمة المتغيّرات هناك. لازم القواعد تيجي في آخر الملف عشان تكسب أي
   قاعدة سابقة بنفس درجة التحديد
   ========================================================================= */

/* -------- الأذكار والأدعية (#view-azkar / #view-duas) -------- */
#view-azkar .list-page, #view-duas .list-page { background: var(--ap-bg); }
#view-azkar .page-close-btn, #view-duas .page-close-btn {
  background: var(--ap-card);
  color: var(--ap-ink);
  border: 1px solid var(--ap-line);
}
#view-azkar .page-close-btn:active, #view-duas .page-close-btn:active { background: var(--ap-olive-soft); }
#view-azkar .azkar-page-eyebrow, #view-duas .azkar-page-eyebrow,
body.theme-night #view-azkar .azkar-page-eyebrow, body.theme-night #view-duas .azkar-page-eyebrow {
  color: var(--ap-gold);
  font-family: var(--ap-font);
}
#view-azkar .azkar-page-title, #view-duas .azkar-page-title {
  font-family: var(--ap-font);
  font-weight: 900;
  color: var(--ap-ink);
}
#view-azkar .azkar-modern-row, #view-duas .azkar-modern-row {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  box-shadow: var(--ap-shadow);
}
#view-azkar .azkar-modern-row:active, #view-duas .azkar-modern-row:active { background: var(--ap-olive-soft); }
#view-azkar .azkar-modern-row .settings-card-icon, #view-duas .azkar-modern-row .settings-card-icon {
  background: var(--ap-olive-soft) !important;
  color: var(--ap-olive) !important;
}
#view-azkar .azkar-modern-row .settings-card-title, #view-duas .azkar-modern-row .settings-card-title {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#view-azkar .azkar-modern-row .settings-card-sub, #view-duas .azkar-modern-row .settings-card-sub { color: var(--ap-ink-2); }
#view-azkar .azkar-modern-row .acc-chevron, #view-duas .azkar-modern-row .acc-chevron { color: var(--ap-gold); opacity: 1; }

/* هيرو صفحتي الأذكار/الأدعية: نفس طابع هيرو صفحة الصوتيات بالظبط (أيقونة
   زخرفية شفافة كبيرة بدل صورة فوتوغرافية، زي هيرو صفحة "استكشف الأشرف")،
   بدل الرأس النصي البسيط القديم. زرار الإغلاق بقى عايم فوق الهيرو بدل
   ما ياخد صف مستقل فوقه (نفس الإصلاح المطبّق على #view-hadith) */
#view-azkar .list-page, #view-duas .list-page { position: relative; padding-top: 0; }
#view-azkar .page-topbar, #view-duas .page-topbar {
  position: absolute;
  top: calc(12px + env(safe-area-inset-top, 0px));
  inset-inline-end: 14px;
  z-index: 3;
  margin: 0;
}
#view-azkar .azkar-hero, #view-duas .azkar-hero {
  min-height: calc(190px + env(safe-area-inset-top, 0px));
  margin: 0 -14px 6px;
  padding-top: calc(46px + env(safe-area-inset-top, 0px));
}
#view-azkar .azkar-hero-art, #view-duas .azkar-hero-art {
  background: none;
  -webkit-mask-image: none;
  mask-image: none;
  width: 100%;
  max-width: none;
  inset-inline-end: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
}
#view-azkar .azkar-hero-icon, #view-duas .azkar-hero-icon {
  width: 118px; height: 118px;
  margin-top: 18px;
  color: var(--ap-olive);
  opacity: .16;
  fill: none;
  stroke: currentColor;
}
body.theme-night #view-azkar .azkar-hero-art, body.theme-night #view-duas .azkar-hero-art { filter: none; opacity: 1; }
body.theme-night #view-azkar .azkar-hero-icon, body.theme-night #view-duas .azkar-hero-icon { opacity: .2; }
#view-azkar .ap-hero-text, #view-duas .ap-hero-text { max-width: 100%; position: relative; z-index: 2; }
#view-duas .azkar-page-eyebrow { margin-bottom: 6px; }
/* في صفحة الأذكار بس، العنوان قبل "حصن المسلم" (عكس ترتيب صفحة الأدعية)،
   فالمسافة لازم تبقى فوق الـ eyebrow (تفصله عن العنوان) مش تحته */
#view-azkar .azkar-page-eyebrow { margin-bottom: 0; margin-top: 6px; }

/* -------- قوائم الأذكار/الأدعية جوّه "استكشف الأشرف" (#explore-category-overlay،
   تصنيف azkar_duas عبر #explore-azkar-list / #explore-duas-list) — نفس
   الكروت المستخدمة في صفحتي الأذكار/الأدعية الأصليتين (.azkar-modern-row)،
   بس من غير تخصيص لطابع صفحة الصوتيات زي ما اتعمل لـ #view-azkar/#view-duas،
   فكانت لسه واخدة الشكل القديم (بيج/ذهبي عن طريق --paper-deep الافتراضي).
   نفس التخصيص بالظبط هنا عشان تاخد طابع وألوان صفحة الصوتيات */
#explore-category-overlay .azkar-modern-row {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  box-shadow: var(--ap-shadow);
}
#explore-category-overlay .azkar-modern-row:active { background: var(--ap-olive-soft); }
#explore-category-overlay .azkar-modern-row .settings-card-icon {
  background: var(--ap-olive-soft) !important;
  color: var(--ap-olive) !important;
}
#explore-category-overlay .azkar-modern-row .settings-card-title {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#explore-category-overlay .azkar-modern-row .settings-card-sub { color: var(--ap-ink-2); }
#explore-category-overlay .azkar-modern-row .acc-chevron { color: var(--ap-gold); opacity: 1; }

/* -------- القائمة التفصيلية المشتركة لقسم أذكار/أدعية (#dhikr-list-overlay) -------- */
#dhikr-list-overlay .overlay-sheet { background: var(--ap-bg); }
#dhikr-list-overlay .dhikr-list-sheet .overlay-head { background: var(--ap-card) !important; border-bottom-color: transparent !important; }
#dhikr-list-overlay .overlay-head h3,
body.theme-night #dhikr-list-overlay .overlay-head h3 {
  font-family: var(--ap-font);
  font-weight: 900;
  color: var(--ap-ink);
}
#dhikr-list-overlay .icon-btn {
  background: var(--ap-card);
  color: var(--ap-ink);
  border: 1px solid var(--ap-line);
}
#dhikr-list-overlay .icon-btn:hover, #dhikr-list-overlay .icon-btn:active { background: var(--ap-olive-soft); }
#dhikr-list-overlay .dhikr-card {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 22px;
  box-shadow: var(--ap-shadow);
}
#dhikr-list-overlay .dhikr-text { font-family: var(--ap-font); color: var(--ap-ink); }
#dhikr-list-overlay .dhikr-source { color: var(--ap-ink-3); font-family: var(--ap-font); }
#dhikr-list-overlay .dhikr-count { background: var(--ap-olive); color: #fff; }
body.theme-night #dhikr-list-overlay .dhikr-count { color: #15160f; }
#dhikr-list-overlay .dhikr-note { color: #C0392B; }
#dhikr-list-overlay .tasbih-counter,
#dhikr-list-overlay .tasbih-counter-value { font-family: var(--ap-font); }

/* اجمع زر استماع الأذكار وتشغيلها في كبسولة واحدة، ووسّطها بين العنوان والإغلاق. */
#dhikr-list-overlay .dhikr-list-sheet > .overlay-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(40px, 1fr);
  align-items: center;
  gap: clamp(8px, 2vw, 14px);
}
#dhikr-list-overlay .dhikr-list-sheet > .overlay-head h3 { min-width: 0; }
#dhikr-list-overlay .dhikr-audio-actions { justify-self: center; margin: 0; }
#dhikr-list-overlay #btn-close-dhikr-list { justify-self: end; }
#dhikr-list-overlay .dhikr-audio-listen {
  position: relative;
  overflow: hidden;
  min-height: 38px;
  gap: 7px;
  padding-inline: 10px;
  padding-bottom: 7px;
  padding-top: 7px;
}
#dhikr-list-overlay .dhikr-audio-headphones { width: 16px; height: 16px; flex: 0 0 16px; }
#dhikr-list-overlay .dhikr-audio-toggle-icon {
  display: inline-flex;
  align-items: center;
  padding-inline-start: 7px;
  border-inline-start: 1px solid rgba(255, 255, 255, .42);
}
#dhikr-list-overlay .dhikr-audio-toggle-icon svg { width: 16px; height: 16px; }
#dhikr-list-overlay .dhikr-audio-toggle-icon .icon-pause,
#dhikr-list-overlay .dhikr-audio-listen.playing .dhikr-audio-toggle-icon .icon-play { display: none; }
#dhikr-list-overlay .dhikr-audio-listen.playing .dhikr-audio-toggle-icon .icon-pause { display: block; }
#dhikr-list-overlay .dhikr-audio-time {
  min-width: 34px;
  color: rgba(255, 255, 255, .9);
  font: 700 10px/1 var(--ap-font);
  font-variant-numeric: tabular-nums;
}
#dhikr-list-overlay .dhikr-audio-progress {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 3px;
  background: rgba(255, 255, 255, .25);
}
#dhikr-list-overlay .dhikr-audio-progress > span {
  display: block;
  width: 100%;
  height: 100%;
  transform: scaleX(0);
  transform-origin: left center;
  background: var(--ap-gold);
  transition: transform .2s linear;
}
html[dir="rtl"] #dhikr-list-overlay .dhikr-audio-progress > span { transform-origin: right center; }

/* -------- المسبحة (#view-tasbih) -------- */
#view-tasbih .misbaha-page { background: var(--ap-bg); }
#view-tasbih .misbaha-icon-btn {
  background: var(--ap-card);
  color: var(--ap-olive);
  border: 1px solid var(--ap-line);
}
body.theme-night #view-tasbih .misbaha-icon-btn { color: var(--ap-olive); }
#view-tasbih .misbaha-icon-btn:active { background: var(--ap-olive-soft); }
/* عنوان "المسبحة": نفس مقاس وخط وسُمك عناوين باقي الصفحات (زي "الفهرس") */
#view-tasbih .misbaha-top-title,
body.theme-night #view-tasbih .misbaha-top-title { font-family: var(--ap-font); color: var(--ap-ink); font-size: 25px; font-weight: 700; }
