#view-tasbih .misbaha-dhikr-sub { color: var(--ap-ink-2); }
#view-tasbih .misbaha-stat-value { color: var(--ap-ink); font-family: var(--ap-font); }
#view-tasbih .misbaha-stat-label { color: var(--ap-ink-2); }
#view-tasbih .misbaha-badge,
body.theme-night #view-tasbih .misbaha-badge {
  background: var(--ap-card);
