  border: 1px solid var(--ap-line);
  font-family: var(--ap-font);
}
#view-tasbih .misbaha-badge-streak { background: rgba(192, 57, 43, .1); color: #C0392B; border-color: rgba(192, 57, 43, .18); }
#view-tasbih .misbaha-tool-icon { background: var(--ap-card); color: var(--ap-ink-2); border: 1px solid var(--ap-line); }
#view-tasbih .misbaha-tool-btn.active .misbaha-tool-icon { background: var(--ap-olive); color: #fff; border-color: var(--ap-olive); }
body.theme-night #view-tasbih .misbaha-tool-btn.active .misbaha-tool-icon { color: #15160f; }
#view-tasbih .misbaha-tool-btn.active,
body.theme-night #view-tasbih .misbaha-tool-btn.active { color: var(--ap-olive); }
#view-tasbih .misbaha-quick-chip {
  background: var(--ap-card);
