#view-tasbih .misbaha-beads-track { stroke: var(--ap-line); }
#view-tasbih .misbaha-progress-arc { stroke: var(--ap-gold); }
#view-tasbih .misbaha-center-btn {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  box-shadow: var(--ap-shadow);
}
body.theme-night #view-tasbih .misbaha-center-btn { background: var(--ap-card); }
#view-tasbih .misbaha-center-count { color: var(--ap-ink); font-family: var(--ap-font); }
#view-tasbih .misbaha-target-pill {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  color: var(--ap-ink);
  box-shadow: var(--ap-shadow);
  font-family: var(--ap-font);
}
#view-tasbih .misbaha-target-pill svg,
body.theme-night #view-tasbih .misbaha-target-pill svg { color: var(--ap-gold); }
#view-tasbih .tasbih-mini-btn {
  background: var(--ap-card);
  color: var(--ap-ink-2);
  border: 1px solid var(--ap-line);
  font-family: var(--ap-font);
}
#view-tasbih .tasbih-mini-btn-reset { color: #C0392B; }
#view-tasbih .tasbih-cycles-note,
body.theme-night #view-tasbih .tasbih-cycles-note { color: var(--ap-gold); font-family: var(--ap-font); }
#view-tasbih .qibla-tip-card { background: var(--ap-gold-soft); }
#view-tasbih .qibla-tip-card p { color: var(--ap-ink-2); }

/* -------- إدارة الأذكار والتسابيح + محرّر الذكر (#misbaha-manage-overlay / #misbaha-editor-overlay) -------- */
#misbaha-manage-overlay.misbaha-manage-overlay,
#misbaha-editor-overlay.misbaha-editor-overlay {
