/* كبسولة "آية N": سهم صغير يوضّح إنها بتفتح قايمة، وبيتقلب لما القايمة تفتح */
.mip-ayah-pill { display: inline-flex; align-items: center; gap: 7px; cursor: pointer; transition: opacity .15s ease; }
.mip-ayah-pill::after {
  content: '';
  width: 6px; height: 6px;
  border-inline-end: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(-135deg) translate(-1px, -1px);
  transition: transform .2s ease;
  opacity: .8;
}
.mip-ayah-pill.open::after { transform: rotate(45deg) translate(-1px, -1px); }

/* فهرس آيات السورة المنسدل — بيطلع لفوق من بطاقة المعلومات */
.mip-ayah-menu {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 10px);
  width: min(340px, 100%);
  background: #FFFFFF;
  border-radius: 20px;
  padding: 12px 12px 10px;
  box-shadow: 0 16px 38px color-mix(in srgb, var(--shadow) 38%, transparent);
  z-index: 5;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translate(-50%, 10px) scale(.97);
  transform-origin: 50% 100%;
  transition: transform .2s cubic-bezier(.22, .61, .36, 1), opacity .16s ease, visibility 0s linear .2s;
}
.mip-ayah-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translate(-50%, 0) scale(1);
  transition: transform .2s cubic-bezier(.22, .61, .36, 1), opacity .16s ease, visibility 0s;
}
body.theme-night .mip-ayah-menu { background: var(--paper-deep); }
body.theme-night.oled-true-black .mip-ayah-menu { background: #242424; }

.mam-head {
  display: flex; align-items: baseline; justify-content: space-between;
  padding: 0 6px 8px; margin-bottom: 6px;
  border-bottom: 1px solid color-mix(in srgb, var(--paper-line) 60%, transparent);
  font-family: var(--font-kufic);
}
.mam-title { font-size: 16px; font-weight: 700; color: var(--ink); }
.mam-count { font-size: 12.5px; font-weight: 600; color: var(--ink-soft, var(--ink)); opacity: .65; }

.mam-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 4px;
  max-height: min(240px, 38vh);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 2px;
  position: relative;
}
.mam-grid::-webkit-scrollbar { display: none; }
.mam-num {
  height: 38px;
  border: none;
  border-radius: 12px;
  background: transparent;
  font-family: var(--font-kufic);
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
  -webkit-tap-highlight-color: transparent;
}
.mam-num:active { background: color-mix(in srgb, var(--paper-line) 45%, transparent); }
.mam-num.current {
  background: color-mix(in srgb, var(--ap-olive, var(--gold-deep)) 16%, transparent);
  color: var(--ap-olive, var(--gold-deep));
}

