.sunnah-feature-card { position: relative; display: flex; gap: 14px; align-items: flex-start; padding: 18px; border: 1px solid color-mix(in srgb, var(--sf-accent) 26%, transparent); border-radius: 18px; background: color-mix(in srgb, var(--surface-2, #202019) 88%, transparent); color: var(--text-primary, #f5f0e6); }
.sunnah-feature-card h3 { margin: 0 0 7px; font-size: 1.05rem; }
.sunnah-feature-card p { margin: 0; line-height: 1.9; color: var(--text-secondary, #c7c0b3); }
.sunnah-feature-index { flex: 0 0 34px; width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; color: var(--sf-accent); background: color-mix(in srgb, var(--sf-accent) 14%, transparent); font-weight: 800; }
.sunnah-feature-meta, .sunnah-feature-source-note { color: var(--text-tertiary, #999184); font-size: .88rem; line-height: 1.8; }
.sunnah-feature-meta { display: block; margin-top: 8px; }
.sunnah-feature-source-note { margin: 14px 2px 18px; }
.sunnah-daily-hadith { display: block; padding: clamp(20px, 5vw, 34px); }
.sunnah-feature-kicker { color: var(--sf-accent); font-weight: 700; }
.sunnah-feature-hadith { margin: 20px 0 !important; font-family: 'Amiri Quran', Amiri, serif; font-size: clamp(1.35rem, 4vw, 1.8rem); line-height: 2.1 !important; }
.sunnah-feature-action { margin-top: 16px; }
.sunnah-explanation { display: block; }
.sunnah-explanation summary { display: flex; align-items: center; gap: 12px; cursor: pointer; list-style: none; }
.sunnah-explanation summary::-webkit-details-marker { display: none; }
.sunnah-explanation summary span:last-child { display: grid; gap: 5px; }
.sunnah-explanation summary small { color: var(--text-secondary, #c7c0b3); line-height: 1.7; }
.sunnah-explanation[open] summary { margin-bottom: 14px; }
.sunnah-explanation h4 { margin: 14px 0 8px; color: var(--sf-accent); }
.sunnah-explanation dl { margin: 0; }
.sunnah-explanation dl div { display: grid; grid-template-columns: minmax(90px, .35fr) 1fr; gap: 10px; padding: 9px 0; border-top: 1px solid color-mix(in srgb, var(--sf-accent) 16%, transparent); }
.sunnah-explanation dt { color: var(--sf-accent); font-weight: 700; }
.sunnah-explanation dd { margin: 0; line-height: 1.7; color: var(--text-secondary, #c7c0b3); }
.sunnah-progress-summary { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 18px; border: 1px solid color-mix(in srgb, var(--sf-accent) 26%, transparent); border-radius: 18px; background: color-mix(in srgb, var(--surface-2, #202019) 88%, transparent); }
.sunnah-progress-summary > div:not(.sunnah-progress-track) { display: grid; gap: 5px; text-align: center; }
.sunnah-progress-summary strong { color: var(--sf-accent); font-size: 1.45rem; }
.sunnah-progress-summary span { color: var(--text-secondary, #c7c0b3); font-size: .88rem; }
.sunnah-progress-track { grid-column: 1 / -1; height: 8px; overflow: hidden; border-radius: 9px; background: color-mix(in srgb, var(--sf-accent) 15%, transparent); }
.sunnah-progress-track span { display: block; height: 100%; border-radius: inherit; background: var(--sf-accent); transition: width .25s ease; }
.sunnah-tracker-list { display: grid; gap: 8px; }
.sunnah-tracker-row { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 14px; padding: 13px 15px; border: 1px solid color-mix(in srgb, var(--sf-accent) 17%, transparent); border-radius: 14px; background: color-mix(in srgb, var(--surface-2, #202019) 78%, transparent); }
.sunnah-tracker-row > div { display: grid; gap: 4px; }
.sunnah-tracker-row small { color: var(--text-tertiary, #999184); }
.sunnah-tracker-row label { display: flex; gap: 6px; align-items: center; color: var(--text-secondary, #c7c0b3); font-size: .9rem; white-space: nowrap; }
.sunnah-tracker-row input { accent-color: var(--sf-accent); width: 18px; height: 18px; }
@media (max-width: 520px) { .sunnah-tracker-row { grid-template-columns: 1fr auto auto; gap: 8px; padding: 11px; } .sunnah-tracker-row label { font-size: .78rem; } }
.sunnah-explanation-source { display: inline-flex; margin-top: 12px; color: var(--sf-accent); text-decoration: underline; text-underline-offset: 3px; }

/* تقليص شريط الأعلى في صفحات السنة الجديدة: الهيرو يبدأ من حافة الشاشة */
#sunnah-feature-overlay .fullpage-shell { position: relative; }
#sunnah-feature-overlay .fullpage-shell > .overlay-head.nawawi-topbar {
  position: absolute; top: 0; inset-inline: 0; z-index: 8;
  justify-content: flex-end; padding: calc(8px + env(safe-area-inset-top)) 16px 0;
  border: 0; background: transparent;
}
#sunnah-feature-overlay .fullpage-shell > .fullpage-scroll { padding: 0 16px 24px; }
#sunnah-feature-overlay .sunnah-feature-hero {
  position: relative; isolation: isolate; min-height: 190px;
  margin: 0 -16px 22px; padding: calc(58px + env(safe-area-inset-top)) 24px 24px;
  display: flex; align-items: flex-end; overflow: hidden;
  background: radial-gradient(ellipse at 78% 30%, rgba(198,164,94,.25), transparent 44%), linear-gradient(135deg, #202920, #111512 72%);
}
#sunnah-feature-overlay .sunnah-feature-hero::after {
  content: ''; position: absolute; z-index: -1; inset: 0;
  background: url('images/nawawi/hero-nawawi.webp') center 34% / cover no-repeat;
  opacity: .22; mask-image: linear-gradient(to left, #000, transparent 90%);
}
#sunnah-feature-overlay .sunnah-feature-hero .ap-title { font-size: clamp(30px, 8vw, 48px); line-height: 1.25; }
#sunnah-feature-overlay .sunnah-feature-hero .ap-subtitle { max-width: 80%; font-size: 14px; }
#view-hadith .hadith-hero { min-height: calc(172px + env(safe-area-inset-top, 0px)); padding-top: calc(30px + env(safe-area-inset-top, 0px)); }
#view-hadith .hadith-search-status { font-size: 12px; line-height: 1.65; }

/* بطاقة حديث اليوم داخل لوحة قسم السنة مباشرة */
.sunnah-home-hadith {
  grid-column: 1 / -1; position: relative; overflow: hidden;
  margin: 0 0 8px; padding: 4px 16px;
  border: 1px solid var(--ap-line);
  border-radius: 26px; background: var(--ap-card);
  box-shadow: var(--ap-shadow);
}
.sunnah-home-hadith::before { content: none; }
.sunnah-home-hadith-head, .sunnah-home-hadith-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.sunnah-home-hadith-mark { display: inline-flex; padding: 4px 10px; border-radius: 999px; background: var(--ap-olive-soft); color: var(--ap-olive); font: 800 12px var(--ap-font); }
.sunnah-home-hadith-date { color: var(--ap-ink-3); font: 600 11px var(--ap-font); }
.sunnah-home-hadith-text { position: relative; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; margin: 4px 0; color: var(--ap-ink); font: 600 clamp(16px, 3.8vw, 20px)/1.65 var(--ap-font, sans-serif); }
.sunnah-home-hadith-foot { align-items: flex-end; padding-top: 5px; border-top: 1px solid var(--ap-line); }
.sunnah-home-hadith-source { color: var(--ap-ink-3); font: 600 11px/1.6 var(--ap-font); }
.sunnah-home-hadith-open { flex: 0 0 auto; color: var(--ap-olive); font: 800 12px var(--ap-font); text-decoration: none; }

/* السيرة تعرض كحكاية مصورة على خط زمني */
.seerah-storyline { position: relative; display: grid; gap: 22px; padding-inline-start: 18px; }
.seerah-storyline::before { content: ''; position: absolute; inset-block: 10px; inset-inline-start: 5px; width: 2px; background: linear-gradient(var(--ap-gold), color-mix(in srgb, var(--ap-olive) 20%, transparent)); }
.seerah-story-card { position: relative; overflow: hidden; border: 1px solid var(--ap-line); border-radius: 22px; background: var(--ap-card); box-shadow: var(--ap-shadow); }
.seerah-story-card::before { content: ''; position: absolute; inset-inline-start: -18px; top: 22px; width: 12px; height: 12px; border: 3px solid var(--ap-gold); border-radius: 50%; background: var(--ap-bg); }
.seerah-story-image { position: relative; height: clamp(150px, 48vw, 250px); overflow: hidden; background: var(--ap-card-2); }
.seerah-story-image img { display: block; width: 100%; height: 100%; object-fit: cover; }
.seerah-story-image::after { content: ''; position: absolute; inset: 30% 0 0; background: linear-gradient(transparent, rgba(10,14,11,.55)); }
.seerah-story-period { position: absolute; z-index: 1; bottom: 12px; inset-inline-start: 14px; padding: 6px 10px; border-radius: 999px; background: rgba(18,22,17,.76); color: #f4dfaa; font: 700 11px var(--ap-font); }
.seerah-story-body { position: relative; padding: 17px 18px 20px; }
.seerah-story-body .sunnah-feature-index { position: absolute; top: 15px; inset-inline-end: 15px; }
.seerah-story-body h3 { margin: 0 48px 9px 0; color: var(--ap-ink); font: 900 19px var(--ap-font); }
.seerah-story-body p { margin: 0; color: var(--ap-ink-2); font: 500 15px/2 var(--ap-font); }

/* الشمائل: بطاقات معرض بلا صور أشخاص، بعناصر زخرفية مختلفة */
.shamail-gallery { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 13px; }
.shamail-card { overflow: hidden; border: 1px solid var(--ap-line); border-radius: 20px; background: var(--ap-card); box-shadow: var(--ap-shadow); }
.shamail-card-art { position: relative; display: grid; place-items: center; min-height: 112px; overflow: hidden; background: radial-gradient(circle at 50% 125%, rgba(210,177,106,.44), transparent 58%), linear-gradient(145deg, #344238, #18211b); color: #ead59c; }
.shamail-card-art::before, .shamail-card-art::after { content: ''; position: absolute; width: 92px; height: 92px; border: 1px solid rgba(234,213,156,.25); border-radius: 28px; transform: rotate(45deg); }
.shamail-card-art::after { width: 64px; height: 64px; border-radius: 50%; }
.shamail-card-art span { z-index: 1; font: 900 20px 'Aref Ruqaa', serif; }
.shamail-card-art b { position: absolute; top: 9px; inset-inline-end: 10px; color: rgba(234,213,156,.7); font: 800 12px var(--ap-font); }
.shamail-tone-1 .shamail-card-art { background: radial-gradient(circle at 50% 125%, rgba(186,147,84,.5), transparent 58%), linear-gradient(145deg, #514331, #241e18); }
.shamail-tone-2 .shamail-card-art { background: radial-gradient(circle at 50% 125%, rgba(150,162,122,.4), transparent 58%), linear-gradient(145deg, #414b38, #20251d); }
.shamail-tone-3 .shamail-card-art { background: radial-gradient(circle at 50% 125%, rgba(157,131,83,.42), transparent 58%), linear-gradient(145deg, #3d3930, #1c1b17); }
.shamail-card-copy { padding: 14px; }
.shamail-card-copy h3 { margin: 0 0 7px; color: var(--ap-ink); font: 900 15px/1.5 var(--ap-font); }
.shamail-card-copy p { margin: 0; color: var(--ap-ink-2); font: 500 12px/1.85 var(--ap-font); }
.shamail-card-copy small { display: block; margin-top: 9px; color: var(--ap-ink-3); font: 600 10px/1.6 var(--ap-font); }
@media (max-width: 380px) { .shamail-gallery { grid-template-columns: 1fr; } }

/* تحدّي الحفظ: لوحة تقدم مرئية وقائمة تفاعلية */
.sunnah-progress-summary { position: relative; align-items: center; border-radius: 24px; }
.sunnah-progress-ring { grid-column: 1 / -1; display: flex; align-items: center; justify-content: center; gap: 16px; padding: 8px 0 16px; }
.sunnah-progress-ring-visual { --progress: 0%; display: grid; place-items: center; width: 104px; height: 104px; flex: 0 0 auto; border-radius: 50%; background: conic-gradient(var(--ap-gold) var(--progress), color-mix(in srgb, var(--ap-gold) 16%, transparent) 0); }
.sunnah-progress-ring-visual::before { content: ''; grid-area: 1/1; width: 82px; height: 82px; border-radius: 50%; background: var(--ap-card); }
.sunnah-progress-ring-visual strong { z-index: 1; grid-area: 1/1; color: var(--ap-ink); font: 900 22px var(--ap-font); }
.sunnah-progress-ring-copy { display: grid; gap: 5px; }
.sunnah-progress-ring-copy b { color: var(--ap-ink); font: 900 16px var(--ap-font); }
.sunnah-progress-ring-copy span { color: var(--ap-ink-3); font: 500 12px/1.7 var(--ap-font); }
.sunnah-challenge-targets, .sunnah-tracker-filters { display: flex; gap: 8px; overflow-x: auto; margin: 14px 0; padding: 2px 0 6px; }
.sunnah-challenge-targets button, .sunnah-tracker-filters button { flex: 0 0 auto; border: 1px solid var(--ap-line); border-radius: 999px; padding: 9px 13px; background: var(--ap-card); color: var(--ap-ink-2); font: 700 11px var(--ap-font); }
.sunnah-challenge-targets button.active, .sunnah-tracker-filters button.active { border-color: var(--ap-gold); background: var(--ap-gold-soft); color: var(--ap-ink); }
.sunnah-tracker-row { border-radius: 16px; box-shadow: 0 4px 18px rgba(0,0,0,.06); }
.sunnah-feature-card { border-color: var(--ap-line); background: var(--ap-card); color: var(--ap-ink); }
.sunnah-feature-card p, .sunnah-feature-source-note, .sunnah-feature-meta { color: var(--ap-ink-2); }
.sunnah-feature-index { color: var(--ap-olive); background: var(--ap-olive-soft); }
.sunnah-feature-kicker { color: var(--ap-olive); }
.sunnah-progress-summary { background: var(--ap-card); border-color: var(--ap-line); }
.sunnah-progress-summary strong { color: var(--ap-olive); }
.sunnah-progress-ring-visual::before { background: var(--ap-card); }
.sunnah-progress-ring-visual strong { color: var(--ap-ink); }
.sunnah-tracker-row { color: var(--ap-ink); background: var(--ap-card); border-color: var(--ap-line); }
.sunnah-tracker-row small, .sunnah-tracker-row label { color: var(--ap-ink-2); }
.sunnah-tracker-section-title { margin: 20px 2px 8px; color: var(--ap-ink); font: 900 16px var(--ap-font); }
#view-hadith .hadith-result-meta-note a { color: var(--ap-olive); font-weight: 800; text-underline-offset: 3px; }

/* فتح التحقق من الحديث من صفحة الأدوات كورقة سفلية تتمدّد عند بدء البحث. */
@keyframes hadith-sheet-enter {
  from { transform: translate3d(0, 34px, 0); }
  to { transform: translate3d(0, 0, 0); }
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) {
  z-index: 240;
  max-width: none;
  background: transparent !important;
  isolation: isolate;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: rgba(0, 0, 0, .48);
  animation: hadith-backdrop-in .28s ease both;
}
@keyframes hadith-backdrop-in { from { opacity: 0; } to { opacity: 1; } }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay).view-enter-active { animation: none; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay).view-enter-active .list-page { animation: hadith-sheet-enter .38s cubic-bezier(.2,.75,.3,1) both; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .list-page {
  position: absolute;
  z-index: 1;
  inset-inline: 0;
  bottom: 0;
  width: min(100%, 760px);
  height: clamp(270px, 36dvh, 420px);
  min-height: 0;
  max-height: 92dvh;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow: hidden;
  margin: 0 auto;
  padding: calc(12px + env(safe-area-inset-top, 0px)) 18px max(12px, env(safe-area-inset-bottom, 0px));
  border: 1px solid var(--ap-line);
  border-bottom: 0;
  border-radius: 28px 28px 0 0;
  background: var(--ap-bg, var(--paper)) !important;
  box-shadow: 0 -12px 42px rgba(0,0,0,.2);
  transition: height .48s cubic-bezier(.22,.75,.25,1), border-radius .3s ease;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay).hadith-search-expanding .list-page { height: min(88dvh, 900px); }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .page-topbar {
  position: absolute;
  top: calc(12px + env(safe-area-inset-top, 0px));
  left: 18px;
  z-index: 3;
  width: auto;
  height: 44px;
  margin: 0;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .page-close-btn { width: 42px; height: 42px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-hero {
  flex: 0 0 auto;
  min-height: 44px;
  margin: 0;
  padding: 0 52px 0 0;
  background: transparent;
  box-shadow: none;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-hero .ap-hero-art,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-hero .ap-subtitle,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-btn,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-card .settings-mini-note,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-source-note { display: none !important; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-hero .ap-hero-text { max-width: none; padding: 0; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-hero .ap-title { max-width: none; margin: 0; font-size: clamp(20px, 5vw, 28px); }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-card {
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-form { display: block; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-row {
  min-height: 60px;
  padding-inline: 16px;
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  background: var(--ap-card);
  box-shadow: 0 2px 8px rgba(0,0,0,.08);
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-icon { width: 22px; height: 22px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-input,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-input::placeholder {
  font-size: 13px !important;
  line-height: 1.4;
  -webkit-text-size-adjust: none;
  text-size-adjust: none;
}
#view-hadith .hadith-search-input::-webkit-search-cancel-button,
#view-hadith .hadith-search-input::-webkit-search-decoration { -webkit-appearance: none; appearance: none; display: none; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-results-section {
  display: none;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  margin: 0;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay).hadith-search-expanding .hadith-results-section { display: flex; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-results-heading { flex: 0 0 auto; margin: 0 0 8px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-results-heading h3 { font-size: 14px !important; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-search-status { flex: 0 0 auto; margin: 0 0 10px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-results-list {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 2px 2px 12px;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-results-list { gap: 10px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-card { padding: 14px 16px; border-radius: 20px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-top { margin-bottom: 8px; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-number,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade { font-size: 12px !important; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-text {
  margin: 0 0 10px;
  font-size: clamp(15px, 4vw, 18px) !important;
  line-height: 1.75 !important;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta-note,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-source { font-size: 12px !important; }
@media (prefers-reduced-motion: reduce) {
  #view-hadith:is(.view-card-overlay, .view-explore-child-overlay).view-enter-active .list-page,
  #view-hadith:is(.view-card-overlay, .view-explore-child-overlay)::before { animation: none; }
  #view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .list-page { transition: none; }
}

/* تحسين القراءة والبحث في صفحات السنة الداخلية */
#view-hadith .list-page { width: min(920px, calc(100% - 28px)); margin-inline: auto; padding-bottom: max(28px, env(safe-area-inset-bottom)); }
#view-hadith .hadith-search-card { padding: clamp(16px, 4vw, 24px); border: 1px solid var(--ap-line); border-radius: 26px; background: var(--ap-card); box-shadow: var(--ap-shadow); }
#view-hadith .hadith-search-row { min-height: 58px; border: 1px solid var(--ap-line); border-radius: 18px; }
#view-hadith .hadith-search-btn { min-height: 54px; border-radius: 17px; font-weight: 800; }
#view-hadith .hadith-result-card { padding: clamp(17px, 4vw, 24px); border: 1px solid var(--ap-line); border-radius: 24px; background: var(--ap-card); box-shadow: var(--ap-shadow); }
#view-hadith .hadith-result-text { font-size: clamp(18px, 4.5vw, 23px); line-height: 2; }
#view-hadith .hadith-source-note { padding: 14px 16px; border-inline-start: 3px solid var(--ap-gold); border-radius: 14px; background: var(--ap-gold-soft); color: var(--ap-ink-2); line-height: 1.9; }

/* Khatma refresh: calm, editorial reading dashboard and focused solo flow. */
#view-home .khatma-topbar { padding: calc(18px + env(safe-area-inset-top)) 18px 0; }
#view-home .khatma-topbar-btn { width: 42px; height: 42px; border-radius: 15px; transition: transform .18s ease, background .18s ease, border-color .18s ease; }
#view-home .khatma-topbar-btn:active { transform: scale(.94); }
#view-home .khatma-hero { min-height: 218px; margin: 0 -16px; border-radius: 0 0 30px 30px; overflow: hidden; }
#view-home .khatma-hero::after { content: ''; position: absolute; inset: auto 0 0; height: 52%; background: linear-gradient(0deg, rgba(18, 23, 15, .72), transparent); pointer-events: none; }
