/* حركة موحّدة وسريعة لفتح وإغلاق صفحات التطبيق والنوافذ. */
@keyframes app-page-open {
  from { transform: translate3d(0, 100vh, 0); }
  to { transform: translate3d(0, 0, 0); }
}
@keyframes app-page-close {
  from { transform: translate3d(0, var(--view-exit-offset, 0px), 0); }
  to { transform: translate3d(0, calc(var(--view-exit-offset, 0px) + 100vh), 0); }
}
.view.view-enter-active {
  animation: app-page-open 220ms cubic-bezier(.2,.75,.3,1) both;
  will-change: transform;
}
.view.view-enter-active .nav-grid .nav-item,
.view.view-enter-active .prayer-ap-page > *,
.view.view-enter-active #prayer-grid .p-card,
.view.view-enter-active .nav-prayer-widget-full,
.view.view-enter-active .azkar-audio-card,
.view.view-enter-active .azkar-audio-card .azkar-audio-item {
  animation: none !important;
}
.view.view-enter-active *:not(.tools-page) {
  animation: none !important;
}
#view-tools.view-enter-active {
  animation: none !important;
}
#view-tools.view-enter-active .tools-page {
  animation: app-page-open 220ms cubic-bezier(.2,.75,.3,1) both;
  will-change: transform;
}
.view.view-leaving {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: block;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
  animation: app-page-close 220ms cubic-bezier(.22,.61,.36,1) both;
  will-change: transform;
  transform: translate3d(0, var(--view-exit-offset, 0px), 0);
}
.view.view-card-overlay {
  position: fixed;
  inset: 0;
  z-index: 230;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  max-width: 560px;
  margin: 0 auto;
  padding-top: 0;
  box-sizing: border-box;
  background: var(--ap-bg, var(--paper)) !important;
}
.view.view-explore-child-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 230 !important;
  width: 100vw !important;
  height: 100vh !important;
  height: 100dvh !important;
  max-width: 560px;
  margin: 0 auto;
  padding-top: 0;
  box-sizing: border-box;
  overflow: hidden;
}
.view.view-leaving.view-card-overlay {
  position: fixed;
  inset: 0;
  z-index: 3;
}
#view-tools.view-leaving {
  animation: none;
  transform: none;
}
#view-tools.view-leaving > * {
  animation: app-page-close 220ms cubic-bezier(.22,.61,.36,1) both;
  will-change: transform;
}
.overlay {
  opacity: 1 !important;
  background: transparent !important;
  visibility: hidden;
  transition: visibility 0s linear 240ms !important;
}
/* طبقة تعتيم مستقلة عن خلفية النافذة ومحتواها، عشان تشتغل حتى مع الصفحات
   الكاملة والأوفرلايز التي خلفيتها مخصصة. تتلاشى بسلاسة عند الفتح والإغلاق. */
.overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: rgba(0, 0, 0, .6);
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms cubic-bezier(.22, .72, .25, 1);
}
.overlay > :not(.tools-bottom-bar) {
  position: relative;
  z-index: 1;
}
.overlay.open {
  visibility: visible;
  transition-delay: 0s !important;
}
.overlay.open::before { opacity: 1; }
.overlay.overlay-closing:not(.open) {
  visibility: visible !important;
  pointer-events: none;
  transition: none !important;
}
.overlay.overlay-closing:not(.open) .overlay-sheet {
  will-change: transform;
  transform: translate3d(0, 100vh, 0);
}
.overlay.overlay-close-instant:not(.open) {
  visibility: hidden !important;
  pointer-events: none;
  transition: none !important;
}
.overlay.overlay-fullpage {
  transform: translate3d(0, 100vh, 0);
  transition: transform 160ms cubic-bezier(.2,.75,.3,1) !important;
  will-change: transform;
}
.overlay.overlay-fullpage.open {
  transform: translate3d(0, 0, 0);
}
.overlay.overlay-fullpage.overlay-closing:not(.open) {
  transform: translate3d(0, 100vh, 0);
}
.overlay.overlay-fullpage .overlay-sheet,
.overlay.overlay-fullpage.open .overlay-sheet {
  transform: none !important;
  opacity: 1 !important;
  background: var(--ap-bg, var(--paper)) !important;
}
.overlay-sheet,
.overlay.overlay-fullpage .overlay-sheet {
  transform: translate3d(0, 24px, 0);
  opacity: 1 !important;
  transition: transform 160ms cubic-bezier(.2,.75,.3,1);
}
.overlay.open .overlay-sheet,
.overlay.overlay-fullpage.open .overlay-sheet {
  transform: translate3d(0, 0, 0);
}
.overlay.open .overlay-sheet { will-change: transform; }
.overlay-fullpage#nawawi-overlay,
.overlay-fullpage#nawawi-detail-overlay,
.overlay-fullpage#sunnah-feature-overlay,
.overlay-fullpage#sunnah-books-overlay,
.overlay-fullpage#sunnah-kutub-overlay,
.overlay-fullpage#sunnah-chapters-overlay,
.overlay-fullpage#sunnah-hadiths-overlay,
.overlay-fullpage#sunnah-hadith-detail-overlay {
  /* أثناء دخول صفحات السنة وخروجها نُظهر الصفحة السابقة تحتها؛ الخلفية
     تظل على محتوى .overlay-sheet نفسه فقط. */
  background: transparent !important;
}
.overlay.overlay-no-anim,
.overlay.overlay-no-anim .overlay-sheet,
.overlay.overlay-no-anim::before {
  transition: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .view.view-enter-active,
  .view.view-fade-enter-active,
  .view.view-leaving,
  #view-tools.view-enter-active .tools-page,
  #view-tools.view-leaving > * {
    animation-duration: 1ms;
  }
  .overlay,
  .overlay-sheet,
  .overlay.overlay-fullpage .overlay-sheet {
    transition-duration: 1ms !important;
  }
  .overlay { transition-delay: 0s !important; }
}


/* صفحات تفتح فوق الرئيسية من كروتها: خلفية كاملة، محتوى يبدأ من أعلى الشاشة،
   وانتقال رأسي فقط من دون تكبير أو شفافية. */
.view.view-card-overlay,
.view.view-explore-child-overlay { background: transparent !important; }
.view.view-card-overlay > :is(.prayer-ap-page, .list-page, .misbaha-page) {
  min-height: 100%;
  box-sizing: border-box;
  background: var(--ap-bg, var(--paper)) !important;
}
#view-home, #view-azkar, #view-prayer, #view-tasbih, #view-hadith, #view-live {
  background: transparent !important;
}
#view-home .list-page, #view-azkar .list-page, #view-hadith .list-page, #view-live .list-page {
  width: 100%;
  min-height: 100%;
  margin-inline: 0;
  padding-inline: 14px;
  box-sizing: border-box;
  background: var(--ap-bg, var(--paper)) !important;
}
#view-tasbih .misbaha-page {
  min-height: 100%;
  box-sizing: border-box;
  padding-top: calc(16px + env(safe-area-inset-top, 0px));
  background: var(--ap-bg, var(--paper)) !important;
}
#view-prayer .prayer-ap-page {
  min-height: 100%;
  box-sizing: border-box;
  background: var(--ap-bg, var(--paper)) !important;
}
#view-live .list-page.live-radio-page {
  background: var(--ap-bg, var(--paper)) !important;
}
.view.view-explore-child-overlay > :is(.prayer-ap-page, .list-page, .misbaha-page) {
  background: var(--ap-bg, var(--paper)) !important;
}

/* صفحات القبلة والمساجد والختمة التي تُفتح فوق قسم استكشف الأشرف ليست
   .overlay؛ هذه الطبقة تعتّم القسم الأب أسفل الصفحة الفرعية، بينما تظل
   الصفحة الفرعية نفسها والحوارات التي تفتح منها فوقها. */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 229;
  background: rgba(0, 0, 0, .52);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 240ms cubic-bezier(.22, .72, .25, 1), visibility 0s linear 240ms;
}
body.explore-child-view-open::before {
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}
body.explore-child-view-open .overlay.open:not(#explore-category-overlay) {
  z-index: 240 !important;
}

#khatma-details-overlay { align-items: stretch; justify-content: stretch; }
#khatma-details-overlay .khatma-details-sheet { 
  width: 100%; max-width: 100%; height: 100%; max-height: 100%;
  border-radius: 0; background: var(--ap-bg, var(--paper));
  transform: translate3d(0, 100vh, 0);
  transition: transform 160ms cubic-bezier(.2,.75,.3,1);
}
#khatma-details-overlay.open .khatma-details-sheet { transform: translate3d(0, 0, 0); }

/* أشرطة المصحف تظهر وتختفي أسرع عند لمس صفحة القراءة. */
#mushaf-top-toolbar,
#mushaf-fab-cluster,
.gp-bar,
.mip-group,
.mushaf-quick-bar {
  transition-duration: 150ms, 120ms !important;
}

/* ألوان البوتوم بار في اللايت مود: الأزرار سوداء، والنشط يتحدد بلون
   الأيقونة البني فقط من غير خلفية أو كبسولة تحديد. */
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn,
body:not(.theme-night) .mushaf-quick-bar .tools-bar-btn {
  color: #171713 !important;
}
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn .tools-bar-icon,
body:not(.theme-night) .mushaf-quick-bar .tools-bar-btn .tools-bar-icon {
  color: #171713 !important;
}
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn.active,
body:not(.theme-night) .tools-bottom-bar.has-tools-indicator .tools-bar-btn.active,
body:not(.theme-night) .mushaf-quick-bar .tools-bar-btn.active,
body:not(.theme-night) .mushaf-quick-bar.has-tools-indicator .tools-bar-btn.active {
  color: #171713 !important;
  background: transparent !important;
}
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn.active .tools-bar-icon,
body:not(.theme-night) .mushaf-quick-bar .tools-bar-btn.active .tools-bar-icon {
  color: #8B5E3C !important;
}
body:not(.theme-night) .tools-bottom-bar .tools-bar-indicator,
body:not(.theme-night) .mushaf-quick-bar .tools-bar-indicator {
  background: transparent !important;
  box-shadow: none !important;
}

/* نافذة خيارات الآية: إجراءات صغيرة في صف واحد، والتفسير والترجمات
   مطوية افتراضيًا ويمكن فتحها من سهم العنوان. */
#ayah-options .ayah-actions-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 16px;
}
#ayah-options .ayah-action-btn {
  min-width: 0;
  min-height: 66px;
  gap: 5px;
  padding: 7px 2px;
  border-radius: 15px;
  font-size: 10px;
  line-height: 1.15;
  white-space: nowrap;
}
#ayah-options .ayah-action-icon {
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--gold) 13%, var(--paper));
}
#ayah-options .ayah-action-icon svg { width: 17px; height: 17px; }
#ayah-tafsir-toggle {
  width: 100%;
  border: 0;
  background: transparent;
  cursor: pointer;
  text-align: right;
}
#ayah-tafsir-toggle .ayah-tafsir-chevron {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  transition: transform 150ms ease;
}
#ayah-options.tafsir-collapsed #ayah-tafsir-grid { display: none; }
#ayah-options:not(.tafsir-collapsed) #ayah-tafsir-toggle .ayah-tafsir-chevron {
  transform: rotate(180deg);
}

/* اسم الختمة في بطاقات القائمة أوضح، مع السماح له بالالتفاف عند الحاجة. */
#view-home .khatma-list-card-name {
  font-size: 16px;
  line-height: 1.4;
  white-space: normal;
  overflow-wrap: anywhere;
}

/* كارت الختمة في الرئيسية فقط: كبّر الاسم إذا احتل سطرًا واحدًا. */
#view-tools #btn-menu-khatma-card .khatma-reference-name.is-single-line {
  display: block;
  -webkit-line-clamp: unset;
  font-size: clamp(18px, 5.2cqi, 30px);
  line-height: 1.9;
  min-height: 1.9em;
  max-height: none;
  overflow: visible;
  padding-block: .42em .5em;
}


/* أيقونة الرئيسية في البوتومبار تطابق شكل أيقونة هيدر المصحف؛ لون مستقل عن النص */
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn[data-tools-bar="tools"] .tools-bar-icon { color: #171511; }
body:not(.theme-night) .tools-bottom-bar .tools-bar-btn[data-tools-bar="tools"].active .tools-bar-icon { color: #80532F; }
body.theme-night .tools-bottom-bar .tools-bar-btn[data-tools-bar="tools"] .tools-bar-icon { color: var(--ink-soft); }
body.theme-night .tools-bottom-bar .tools-bar-btn[data-tools-bar="tools"].active .tools-bar-icon { color: var(--gold-soft); }

/* إظهار ملف السماعة مباشرة في أشرطة التنقل السفلية، مع تلوينه حسب الحالة. */
.tools-bar-icon .audio-bottom-icon {
  display: block;
  width: 21px;
  height: 21px;
  object-fit: contain;
  flex: 0 0 21px;
  filter: brightness(0) saturate(100%);
}
body:not(.theme-night) .tools-bar-btn.active .tools-bar-icon .audio-bottom-icon {
  filter: brightness(0) saturate(100%) invert(29%) sepia(20%) saturate(1175%) hue-rotate(346deg) brightness(92%) contrast(86%);
}
body.theme-night .tools-bar-icon .audio-bottom-icon {
  filter: brightness(0) invert(.88);
}
body.theme-night .tools-bar-btn.active .tools-bar-icon .audio-bottom-icon {
  filter: brightness(0) saturate(100%) invert(79%) sepia(22%) saturate(575%) hue-rotate(13deg) brightness(93%) contrast(88%);
}
/* جولة اكتشاف مميزات التطبيق */
#feature-tour-overlay {
  z-index: 250;
  align-items: center;
  padding: max(18px, env(safe-area-inset-top)) 18px max(18px, env(safe-area-inset-bottom));
  background: rgba(17, 20, 14, .62) !important;
  -webkit-backdrop-filter: blur(7px);
  backdrop-filter: blur(7px);
}
.feature-tour-dialog {
  position: relative;
  width: min(100%, 430px);
  max-height: min(88dvh, 680px);
  overflow-y: auto;
  padding: 28px 24px 20px;
  border: 1px solid color-mix(in srgb, var(--gold) 22%, transparent);
  border-radius: 28px;
  background: var(--paper, #FBF8F1);
  color: var(--ink, #29271F);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .25);
  text-align: center;
  transform: translateY(14px) scale(.98);
  transition: transform .24s cubic-bezier(.2,.75,.3,1);
}
#feature-tour-overlay.open .feature-tour-dialog { transform: translateY(0) scale(1); }
.feature-tour-close {
  position: absolute;
  top: 13px;
  inset-inline-end: 13px;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 50%;
  background: color-mix(in srgb, var(--ink) 7%, transparent);
  color: var(--ink);
}
.feature-tour-close svg { width: 19px; height: 19px; }
.feature-tour-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 14px;
  color: var(--gold-deep, #80532F);
  font-size: 13px;
  font-weight: 800;
}
.feature-tour-brand-mark { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 9px; background: color-mix(in srgb, var(--gold) 14%, transparent); }
.feature-tour-brand-mark svg { width: 17px; height: 17px; }
.feature-tour-dialog h2 { margin: 0; font-size: clamp(21px, 5.8vw, 27px); font-weight: 900; }
.feature-tour-intro { margin: 8px 0 18px; color: var(--ink-soft, #777568); font-size: 14px; line-height: 1.7; }
.feature-tour-progress { height: 5px; overflow: hidden; border-radius: 99px; background: color-mix(in srgb, var(--ink) 10%, transparent); }
.feature-tour-progress span { display: block; width: 20%; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--gold, #B68A35), var(--green, #557451)); transition: width .22s ease; }
.feature-tour-slides { min-height: 238px; display: grid; align-items: center; }
.feature-tour-slide { grid-area: 1 / 1; padding: 25px 4px 13px; animation: feature-tour-enter .22s ease both; }
.feature-tour-icon { display: grid; place-items: center; width: 76px; height: 76px; margin: 0 auto 15px; border-radius: 25px; background: color-mix(in srgb, var(--green, #557451) 12%, transparent); color: var(--green, #557451); }
.feature-tour-icon svg { width: 38px; height: 38px; }
.feature-tour-slide h3 { margin: 0 0 8px; font-size: 19px; font-weight: 900; }
.feature-tour-slide p { max-width: 330px; margin: 0 auto; color: var(--ink-soft, #777568); font-size: 14px; line-height: 1.9; }
.feature-tour-step-label { margin: 0 0 13px; color: var(--ink-soft, #777568); font-size: 12px; font-weight: 700; }
.feature-tour-actions { display: flex; align-items: center; gap: 10px; }
.feature-tour-actions button { min-height: 46px; border: 0; border-radius: 15px; font: inherit; font-weight: 800; cursor: pointer; }
.feature-tour-back { min-width: 100px; padding: 0 16px; background: color-mix(in srgb, var(--ink) 7%, transparent); color: var(--ink); }
.feature-tour-back:disabled { visibility: hidden; }
.feature-tour-next { flex: 1; padding: 0 18px; background: linear-gradient(135deg, #617B59, #365943); color: #fff; box-shadow: 0 6px 16px rgba(54, 89, 67, .2); }
.feature-tour-later { margin-top: 11px; padding: 8px 14px; border: 0; background: transparent; color: var(--ink-soft, #777568); font: inherit; font-size: 12px; }
body.theme-night .feature-tour-dialog { background: var(--night-bg, #20211C); color: var(--ink, #F1EEE4); border-color: rgba(255,255,255,.1); }
body.theme-night .feature-tour-close, body.theme-night .feature-tour-back { background: rgba(255,255,255,.09); color: var(--ink); }
body.theme-night .feature-tour-brand { color: var(--gold-soft, #D6C17B); }
body.theme-night .feature-tour-icon { color: var(--gold-soft, #D6C17B); background: rgba(214,193,123,.12); }
@keyframes feature-tour-enter { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: translateY(0); } }

/* الجولة التفاعلية: فتحة على العنصر الفعلي، والشرح قريب منه بألوان الزيتوني والذهبي */
#feature-tour-overlay {
  display: block;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  pointer-events: auto;
}
#feature-tour-overlay.tour-handoff {
  visibility: hidden !important;
  pointer-events: none !important;
}
.feature-tour-spotlight {
  position: fixed;
  z-index: 1;
  left: 0;
  top: 0;
  width: 24px;
  height: 24px;
  border: 2px solid var(--gold, #C9A227);
  border-radius: 16px;
  box-shadow: 0 0 0 100vmax rgba(17, 19, 14, .66), 0 0 0 5px rgba(255,255,255,.8), 0 8px 28px rgba(0,0,0,.22);
  pointer-events: none;
  transition: left .24s cubic-bezier(.2,.75,.3,1), top .24s cubic-bezier(.2,.75,.3,1), width .24s cubic-bezier(.2,.75,.3,1), height .24s cubic-bezier(.2,.75,.3,1);
}
.feature-tour-spotlight-fullscreen {
  border: 0;
  border-radius: 0;
  background: rgba(17, 19, 14, .58);
  box-shadow: none;
  transition: none;
}
.feature-tour-dialog {
  position: fixed;
  z-index: 2;
  width: min(calc(100vw - 28px), 330px);
  max-height: min(40dvh, 300px);
  overflow-y: auto;
  padding: 11px 14px 9px;
  border: 1px solid color-mix(in srgb, var(--gold) 48%, var(--olive) 52%);
  border-radius: 22px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 18px 54px rgba(0,0,0,.3);
  transform: none;
  text-align: start;
  transition: left .22s ease, top .22s ease;
}
#feature-tour-overlay.open .feature-tour-dialog { transform: none; }
.feature-tour-close { top: 10px; inset-inline-end: 10px; width: 32px; height: 32px; background: color-mix(in srgb, var(--olive) 10%, white); color: var(--olive-deep); }
.feature-tour-close svg { width: 16px; height: 16px; }
.feature-tour-brand, .feature-tour-dialog > h2, .feature-tour-intro { display: none; }
.feature-tour-brand { justify-content: flex-start; margin: 0 0 4px; color: var(--gold-deep); font-size: 11px; }
.feature-tour-brand-mark { width: 24px; height: 24px; background: color-mix(in srgb, var(--gold) 18%, white); color: var(--olive-deep); }
.feature-tour-brand-mark svg { width: 15px; height: 15px; }
.feature-tour-dialog h2 { margin: 0; padding-inline-end: 28px; font-size: 16px; color: var(--ink); }
.feature-tour-intro { margin: 4px 0 7px; font-size: 11px; }
.feature-tour-progress { height: 4px; background: color-mix(in srgb, var(--olive) 14%, white); }
.feature-tour-progress span { background: linear-gradient(90deg, var(--olive-deep), var(--gold)); }
.feature-tour-slides { min-height: 78px; }
.feature-tour-slide { padding: 8px 1px 5px; }
.feature-tour-icon { display: none; }
.feature-tour-slide h3 { margin: 0 0 4px; color: var(--olive-deep); font-size: 16px; }
.feature-tour-slide p { max-width: none; margin: 0; color: var(--ink-soft); font-size: 13px; line-height: 1.58; }
.feature-tour-step-label { margin: 0 0 6px; color: var(--gold-deep); font-size: 10px; }
.feature-tour-actions { gap: 7px; }
.feature-tour-actions button { min-height: 36px; border-radius: 11px; font-size: 12px; }
.feature-tour-back { min-width: 74px; }
.feature-tour-next { background: linear-gradient(135deg, var(--olive-deep), var(--gold-deep)); color: #fff; box-shadow: 0 4px 12px color-mix(in srgb, var(--olive-deep) 25%, transparent); }
.feature-tour-later { margin-top: 5px; padding: 5px 8px; font-size: 11px; }
#feature-tour-overlay.tour-dua-state .feature-tour-dialog {
  border-color: var(--gold-deep);
  background: linear-gradient(145deg, color-mix(in srgb, var(--gold-soft) 22%, white), white 58%, color-mix(in srgb, var(--olive-soft) 35%, white));
  text-align: center;
}
#feature-tour-overlay.tour-dua-state .feature-tour-slide h3 { color: var(--gold-deep); }
#feature-tour-overlay.tour-dua-state .feature-tour-slide::before { content: '🤲'; display: block; margin: 0 auto 4px; font-size: 25px; line-height: 1.1; }
#feature-tour-overlay.tour-dua-state .feature-tour-progress,
#feature-tour-overlay.tour-dua-state .feature-tour-later { display: none; }
body.theme-night .feature-tour-dialog { background: #1D1D19; color: var(--ink); border-color: color-mix(in srgb, var(--gold-soft) 56%, var(--olive) 44%); }
body.theme-night .feature-tour-dialog h2 { color: var(--ink); }
body.theme-night .feature-tour-slide h3, body.theme-night .feature-tour-brand { color: var(--gold-soft); }
body.theme-night .feature-tour-close, body.theme-night .feature-tour-back { background: rgba(255,255,255,.09); color: var(--ink); }
body.theme-night .feature-tour-brand-mark { background: rgba(201,162,39,.14); color: var(--gold-soft); }
body.theme-night .feature-tour-progress { background: rgba(255,255,255,.12); }
body.theme-night .feature-tour-progress span { background: linear-gradient(90deg, var(--olive), var(--gold-soft)); }
body.theme-night #feature-tour-overlay.tour-dua-state .feature-tour-dialog { background: linear-gradient(145deg, #29281f, #1d1d19 64%, #20261d); }
@media (max-height: 620px) {
  .feature-tour-dialog { max-height: min(48dvh, 280px); }
  .feature-tour-slides { min-height: 68px; }
}

/* إصلاح عرض الويب على الشاشات الكبيرة: يبقى شريط التنقل السفلي كبسولة
   صغيرة مثبتة أسفل الصفحة، ولا يتمدد رأسيًا مع حاوية الصفحة. الهاتف يحتفظ
   بالتنسيق الحالي كما هو. */
@media (min-width: 900px) {
  /* بعض مسارات التنقل ترفع #app-main فوق الصفحات؛ ارفع صفحة الصوتيات
     فوقه على الويب حتى لا يظهر عمود التطبيق الضيق فوق محتوى الصفحة. */
  #downloaded-audio-overlay.overlay-fullpage,
  #audio-category-overlay.overlay-fullpage,
  #mushaf-editions-overlay.overlay-fullpage {
    z-index: 240;
  }

  /* على الويب تظهر مكتبة الصوتيات كصفحة وسطية بعرض صفحات الختمة ومباشر،
     وتظل مساحة التطبيق المحيطة بها ظاهرة بدل تمددها على كامل الشاشة. */
  #downloaded-audio-overlay.overlay-fullpage {
    align-items: center;
    justify-content: center;
    background: transparent !important;
  }

  #downloaded-audio-overlay.overlay-fullpage > .overlay-sheet {
    width: min(560px, calc(100vw - 32px));
    max-width: 560px;
    height: 100vh;
    height: 100dvh;
    max-height: 100dvh;
    margin-inline: auto;
    border-radius: 0;
    box-shadow: none;
  }

  /* يظل ارتفاع صف الرئيسية ثابتًا على الشاشات الكبيرة كذلك. */
  #view-tools .home-row-60-40 .prayer-mini-card {
    aspect-ratio: auto;
    height: 100%;
    min-height: 0;
    max-height: none;
  }
}

/* صفحات الصوتيات وطبعات المصحف تظهر فوق حاوية التطبيق حتى لو كانت
   صفحة قسم من استكشف الأشرف ما زالت مرفوعة بطبقة أعلى. ينطبق على الهاتف
   والويب؛ خلاف ذلك تغطي الحاوية الضيقة منتصف الصفحة وتترك الجانبين ظاهرين. */
#downloaded-audio-overlay.overlay-fullpage.open,
#audio-category-overlay.overlay-fullpage.open,
#mushaf-editions-overlay.overlay-fullpage.open {
  z-index: 260 !important;
}

/* أيقونة السماعة ملف PNG أحادي اللون؛ خففنا درجتها في التبويب غير النشط
   لتطابق الرمادي المستخدم في بقية أيقونات البوتوم بار في الوضع الليلي. */
body.theme-night .tools-bottom-bar .tools-bar-btn:not(.active) .audio-bottom-icon {
  filter: brightness(0) saturate(100%) invert(68%) !important;
}

/* لوحة الجولة التعريفية في الوضع الداكن: سطح فحمي واضح ولمسات زيتونية وذهبية. */
body.theme-night .feature-tour-dialog {
  color: #F2F0E8;
  background: linear-gradient(145deg, #262820 0%, #1B1D18 68%, #171915 100%);
  border: 1px solid rgba(186, 196, 145, .24);
  box-shadow: 0 22px 64px rgba(0,0,0,.58), inset 0 1px 0 rgba(255,255,255,.045);
}
body.theme-night .feature-tour-dialog h2 { color: #F5F2E8; }
body.theme-night .feature-tour-intro,
body.theme-night .feature-tour-slide p { color: #C3C3B9; }
body.theme-night .feature-tour-slide h3 { color: #D2D8B0; }
body.theme-night .feature-tour-step-label,
body.theme-night .feature-tour-brand { color: #D8BE70; }
body.theme-night .feature-tour-close,
body.theme-night .feature-tour-back {
  border: 1px solid rgba(255,255,255,.09);
