/* الجولة يجب أن تبقى فوق كل الصفحات والأوفرلايز، بما فيها الصوتيات والقبلة. */
#feature-tour-overlay.open { z-index: 10000 !important; }

/* نتائج التحقق: بطاقات قصيرة ومقروءة مثل صفحة النتائج المرجعية. */
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-card {
  position: relative;
  flex: 0 0 auto;
  overflow: hidden;
  padding: 13px 16px 11px !important;
  border: 1px solid var(--ap-line);
  border-top: 4px solid #0B9C70;
  border-radius: 20px;
  background: var(--ap-card);
  box-shadow: var(--ap-shadow);
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-card.is-hasan { border-top-color: #2864E8; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-card.is-weak { border-top-color: #D45555; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 0 0 8px;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-book {
  overflow: hidden;
  color: var(--ap-gold, #806A24);
  font: 500 14px/1.4 var(--ap-font);
  text-overflow: ellipsis;
  white-space: nowrap;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade {
  flex: 0 0 auto;
  padding: 5px 11px;
  border-radius: 999px;
  background: #E5F4EF;
  color: #078862;
  font: 700 13px/1.2 var(--ap-font);
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade.is-hasan { background: #EAF0FF; color: #2864E8; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade.is-weak { background: #FCEBEC; color: #C74444; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-share {
  display: grid;
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--ap-muted, #777);
  cursor: pointer;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-share svg { width: 23px; height: 23px; fill: currentColor; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-text {
  margin: 0 0 9px !important;
  color: var(--ap-ink);
  font-family: var(--ap-font, 'Tajawal', sans-serif) !important;
  font-size: clamp(15px, 3.8vw, 18px) !important;
  font-weight: 600;
  line-height: 1.8 !important;
  white-space: pre-line;
  overflow-wrap: anywhere;
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  margin: 0;
  padding-top: 8px;
  border-top: 1px solid var(--ap-line);
  color: var(--ap-muted, #777);
  font: 400 12px/1.5 var(--ap-font);
}
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta div { display: flex; gap: 4px; min-width: 0; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta dt { font-weight: 600; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta dd { margin: 0; }
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-meta-note,
#view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-result-source { display: none !important; }

/* عند فتح البحث من صفحة السُنّة، طبقة الأب تتولى التعتيم. خفّف الطبقة
   الإضافية فوقها كي تظل الصفحة ظاهرة خلف ورقة النتائج بدل أن تبدو سوداء سادة. */
body.explore-child-view-open #view-hadith.view-explore-child-overlay::before {
  background: rgba(0, 0, 0, .08);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

/* وحّد خلفية الـWebView مع ورقة البحث أثناء فتح لوحة المفاتيح وإغلاق الصفحة؛
   كانت مساحة الـviewport التي يكشفها النظام ترجع إلى البني الافتراضي. */
body.hadith-page-open { background: transparent !important; }
body.theme-night.hadith-page-open { background: transparent !important; }

/* درجات الحديث تبقى واضحة في الوضع الداكن بدل كبسولات فاتحة بنص باهت. */
body.theme-night #view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade.is-sound {
  border: 1px solid rgba(123, 222, 163, .34);
  background: #17392C;
  color: #A7F0C4;
}
body.theme-night #view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade.is-hasan {
  border: 1px solid rgba(135, 171, 255, .34);
  background: #1B2E50;
  color: #B6CCFF;
}
body.theme-night #view-hadith:is(.view-card-overlay, .view-explore-child-overlay) .hadith-grade.is-weak {
  border: 1px solid rgba(255, 141, 148, .34);
  background: #482326;
  color: #FFB4B8;
}


/* Mosque silhouette used for the prayer-times bottom-bar item. */
.tools-bar-icon .prayer-bottom-icon {
  display: block;
  width: 23px;
  height: 23px;
  object-fit: contain;
  flex: 0 0 23px;
  filter: brightness(0) saturate(100%);
}
body:not(.theme-night) .tools-bar-btn.active .tools-bar-icon .prayer-bottom-icon {
  filter: brightness(0) saturate(100%) invert(29%) sepia(20%) saturate(1175%) hue-rotate(346deg) brightness(92%) contrast(86%);
}
body.theme-night .tools-bar-icon .prayer-bottom-icon { filter: brightness(0) invert(.88); }
body.theme-night .tools-bar-btn.active .tools-bar-icon .prayer-bottom-icon {
  filter: brightness(0) saturate(100%) invert(79%) sepia(22%) saturate(575%) hue-rotate(13deg) brightness(93%) contrast(88%);
}
/* Compact live radio cards and a single-line mini-player. */
#view-live .live-radio-head { padding: 10px 4px 12px; }
#view-live .live-radio-eyebrow { margin-bottom: 8px; padding: 5px 11px; font-size: 10.5px; }
#view-live .live-radio-title { margin-bottom: 5px; font-size: clamp(22px, 5.4vw, 27px); line-height: 1.2; }
#view-live .live-radio-subtitle { max-width: 340px; font-size: 11px; line-height: 1.45; }
#view-live .live-radio-card { min-height: 124px; padding: 11px 5px 9px; border-radius: 18px; }
#view-live .live-radio-card-art { max-width: 52px; border-radius: 15px; }
#view-live .live-radio-card-body { margin-top: 7px; }
#view-live .live-radio-card-name {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 9px;
  line-height: 1.2;
  letter-spacing: -.2px;
}
#view-live .live-radio-card-play { top: 45px; left: calc(50% + 9px); width: 24px; height: 24px; }
#view-live .live-now-playing { min-height: 46px; gap: 6px; margin-bottom: 10px; padding: 5px 9px; border-radius: 17px; }
#view-live .live-now-playing-art { width: 36px; height: 36px; flex-basis: 36px; border-radius: 11px; font-size: 16px; }
#view-live .live-now-playing-info { flex-direction: row; align-items: center; gap: 5px; }
#view-live .live-now-playing-label { flex: 0 0 auto; font-size: 8.5px; white-space: nowrap; }
#view-live .live-now-playing-name {
  display: block;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 10px;
  line-height: 1.2;
}
#view-live .live-now-playing-vis { flex: 0 0 42px; height: 20px; }
#view-live .live-now-playing-vis span:nth-child(n+11) { display: none; }
#view-live .live-now-playing-btn { width: 31px; height: 31px; }
#view-live .live-radio-footnote { font-size: 10.5px; line-height: 1.5; }
@media (max-width: 600px) {
  #view-live .live-radio-head { padding: 8px 2px 10px; }
  #view-live .live-radio-title { font-size: clamp(20px, 5.2vw, 25px); }
  #view-live .live-radio-subtitle { font-size: 10.5px; }
  #view-live .live-radio-list { gap: 9px; }
  #view-live .live-radio-card { flex-basis: calc((100% - 18px) / 3); min-height: 112px; padding: 9px 3px 7px; border-radius: 16px; }
  #view-live .live-radio-card-art { max-width: 48px; border-radius: 14px; }
  #view-live .live-radio-card-body { margin-top: 6px; }
  #view-live .live-radio-card-name { font-size: clamp(7.5px, 2.15vw, 8.5px); letter-spacing: -.25px; }
  #view-live .live-radio-card-play { top: 41px; left: calc(50% + 8px); width: 22px; height: 22px; }
  #view-live .live-now-playing { gap: 5px; padding-inline: 7px; }
  #view-live .live-now-playing-art { width: 32px; height: 32px; flex-basis: 32px; }
  #view-live .live-now-playing-label { font-size: 7.5px; }
  #view-live .live-now-playing-name { font-size: 9px; }
  #view-live .live-now-playing-vis { flex-basis: 32px; }
  #view-live .live-now-playing-vis span:nth-child(n+8) { display: none; }
  #view-live .live-now-playing-btn { width: 28px; height: 28px; }
}

/* =========================================================================
   ثبات تخطيط التطبيق بين الهاتف والتابلت والويب واتجاهي الشاشة
   ========================================================================= */
#app-header,
#app-main {
  width: 100%;
  max-width: 560px;
  min-width: 0;
  box-sizing: border-box;
}
#app-main { overflow-x: clip; }
#app-main > .view,
#app-main > .view.active {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}
#app-main .list-page,
#app-main .tools-page {
  width: 100%;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  overflow-x: hidden;
}
#app-main :where(.card, .card-row, .grid, .section, .panel) { min-width: 0; }
#app-main :where(button, input, select, textarea) { max-width: 100%; }

/* أسماء السورة والجزء المرسومة أعلى صورة المصحف تحلّ مكان الكبسولتين
   القديمتين. نُبقي الكبسولتين مخفيتين لكن بأبعادهما نفسها لتحديد موضع
   الرسم المنقول، ونجعل خلفية الهيدر شفافة لظهورهما فوقه. */
body.qcf-svg-meta-controls #header-context,
body.qcf-svg-meta-controls #header-juz {
  visibility: hidden !important;
  pointer-events: none !important;
}
body.qcf-svg-meta-controls #app-header {
  background: transparent !important;
  pointer-events: none;
}
body.qcf-svg-meta-controls #app-header .header-side,
body.qcf-svg-meta-controls #app-header .header-center { pointer-events: none; }
body.qcf-svg-meta-controls #app-header button { pointer-events: auto; }
/* صف الرئيسية لا يتغير ارتفاعه بتغيّر عرض الهاتف أو عند تدويره؛ المحتوى
   الداخلي يصغر داخل المساحة المحددة بدل تضخيم الكارت أو تراكب النصوص. */
#view-tools .home-row-60-40 {
  grid-template-columns: minmax(0, 6fr) minmax(0, 4fr);
  grid-auto-rows: 180px;
  align-items: stretch;
  min-width: 0;
}
#view-tools .home-row-60-40 > * { min-width: 0; min-height: 0; }
#view-tools .home-row-60-40 .prayer-mini-card {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  aspect-ratio: auto;
  padding: 9px 7px;
}
#view-tools .home-row-60-40 .prayer-mini-top { gap: 3px; margin-bottom: 5px; }
#view-tools .home-row-60-40 .prayer-mini-label { font-size: clamp(8px, 2.3vw, 10px); }
#view-tools .home-row-60-40 .prayer-mini-name { font-size: clamp(12px, 3.1vw, 15px); }
#view-tools .home-row-60-40 .prayer-mini-time { font-size: clamp(16px, 4.1vw, 20px); }
#view-tools .home-row-60-40 .prayer-mini-countdown { max-width: 100%; padding: 3px 6px; font-size: 8px; }
#view-tools .home-row-60-40 .home-quiz-heading { gap: 5px; min-width: 0; }
#view-tools .home-row-60-40 .home-quiz-heading strong { font-size: clamp(12px, 3.2vw, 17px); }
#view-tools .home-row-60-40 .home-quiz-brain { width: 25px; height: 25px; flex: 0 0 25px; }
#view-tools .home-row-60-40 .home-quiz-subtitle { font-size: clamp(9px, 2.35vw, 11px); }
#view-tools .home-row-60-40 .home-quiz-cta { max-width: 48%; font-size: clamp(8px, 2.2vw, 10px); gap: 4px; padding: 4px 7px; }
#view-tools .home-row-60-40 .home-quiz-cta svg { width: 11px; height: 11px; }
#view-tools .home-row-60-40 .home-quiz-image { width: 27%; height: 43%; right: 4%; bottom: 4%; }

/* الشاشات القصيرة تظل على نفس مقياس الواجهة؛ الصفحات الطويلة تتمرر بدل
   ضغط مكوناتها رأسيًا أو ترك مساحات ناتجة عن ارتفاعات مرتبطة بالنافذة. */
@media (orientation: landscape) and (max-height: 520px) {
  #app-main .list-page,
  #app-main .tools-page { overscroll-behavior-y: contain; }
  #view-tools .home-row-60-40 { grid-auto-rows: 180px; }
}

/* بطاقات البث: اعرض اسم المحطة كاملًا في سطر واحد، مع تقليل الارتفاع
   والمسافة أسفل الاسم حتى لا تبقى مساحة فارغة داخل الكارت. */
#view-live .live-radio-list { gap: 9px; }
#view-live .live-radio-card {
  min-height: 90px;
  padding: 7px 4px 6px;
}
#view-live .live-radio-card-art { max-width: 44px; }
#view-live .live-radio-card-body { min-width: 0; margin-top: 5px; }
#view-live .live-radio-card-name {
  display: block;
  width: 100%;
  overflow: visible;
  white-space: nowrap;
  text-overflow: clip;
  font-size: 7px;
  line-height: 1.2;
  letter-spacing: -.35px;
}
#view-live .live-radio-card-play { top: 38px; width: 22px; height: 22px; }
@media (max-width: 600px) {
  #view-live .live-radio-card { min-height: 86px; padding: 7px 3px 5px; }
  #view-live .live-radio-card-art { max-width: 42px; }
  #view-live .live-radio-card-name { font-size: 7px; }
  #view-live .live-radio-card-play { top: 36px; width: 21px; height: 21px; }
}

/* رجوع صف الصلاة/اختبر حفظك لنفس المقياس المدمج السابق؛ عرضه هو الذي
   يحدد ارتفاعه بدل فرض 180px ثابتة على كل الهواتف. */
#view-tools .home-row-60-40 {
  grid-auto-rows: auto;
  grid-template-columns: minmax(0, 6fr) minmax(0, 4fr);
}
#view-tools .home-row-60-40 .prayer-mini-card {
  width: 100%;
  height: auto;
  min-height: 0;
  aspect-ratio: 1 / 1;
  padding: 12px;
}
@media (min-width: 900px) {
  #view-tools .home-row-60-40 .prayer-mini-card {
    aspect-ratio: 1 / 1;
    height: auto;
    min-height: 0;
    max-height: none;
  }
}

/* اسم الختمة الطويل: سطران بحد أقصى، وخط ثابت لا يتضخم عند عودتنا
   للرئيسية بعد تغيير عرض الشاشة أو التنقل بين الشرائح. */
#view-tools #btn-menu-khatma-card .khatma-reference-text {
  top: 8%;
  height: 56%;
  min-height: 0;
  gap: 4px;
}
#view-tools #btn-menu-khatma-card .khatma-reference-name,
#view-tools #btn-menu-khatma-card .khatma-reference-name.is-single-line {
  display: -webkit-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  max-height: 2.7em;
  padding-block: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-size: clamp(13px, 3.5cqi, 21px);
  line-height: 1.3;
  overflow-wrap: anywhere;
}
#view-tools #btn-menu-khatma-card .khatma-reference-sub {
  font-size: clamp(9px, 2.3cqi, 12px);
  line-height: 1.3;
}

/* شبكة مباشر بلا بطاقات بيضاء؛ صورة المحطة واسمها وحدهما يظلان ظاهرين،
   والنقر على المساحة كلها يشغّل المحطة. */
#view-live .live-radio-card {
  min-height: 0;
  padding: 4px 2px 6px;
  overflow: visible;
  border-color: transparent;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
#view-live .live-radio-card-art {
  max-width: 58px;
  border: 0;
  border-radius: 15px;
  background: transparent;
  box-shadow: none;
}
#view-live .live-radio-card-body { margin-top: 7px; }
#view-live .live-radio-card-name { color: var(--ap-ink); font-size: 8px; }
#view-live .live-radio-card-play { display: none; }
#view-live .live-radio-card.playing,
#view-live .live-radio-card.loading {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}
#view-live .live-radio-card.playing .live-radio-card-art {
  box-shadow: 0 0 0 2px var(--st), 0 6px 16px color-mix(in srgb, var(--st) 28%, transparent);
}
#view-live .live-radio-card-loading-overlay {
  inset: auto 0 0;
  min-height: 22px;
  flex-direction: row;
  background: color-mix(in srgb, var(--ap-bg) 92%, transparent);
  border-radius: 8px;
}
#view-live .live-radio-card-loading-icon { width: 14px; height: 14px; }
#view-live .live-radio-card-loading-text { font-size: 8px; }

/* كبسولتا القبلة: مكان ثابت للنص والأيقونة، مع قصّ حالة التحميل داخل
   الكبسولة بدل خروجها أسفل الصف. */
#view-qibla .qibla-hero-card { overflow: hidden; }
#view-qibla .qibla-quick-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: stretch;
  gap: 10px;
  width: 100%;
  margin-top: 10px;
}
#view-qibla .qibla-quick-pill {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  min-height: 44px;
  max-height: 48px;
  margin: 0;
  padding: 8px 12px;
  overflow: hidden;
  border: 1px solid var(--paper-line);
  border-radius: 999px;
  background: var(--paper-deep);
  color: var(--olive);
  font: 700 12px/1.2 var(--font-ui);
  text-align: center;
  white-space: nowrap;
}
#view-qibla .qibla-quick-pill svg {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
}
#view-qibla #qibla-nearby-count-label {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#view-qibla .qibla-add-mosque-pill {
  border-color: var(--gold-deep);
  background: var(--gold-deep);
  color: #fff;
}
body.theme-night #view-qibla .qibla-quick-pill {
  border-color: rgba(255,255,255,.12);
  background: #252720;
  color: #e7e8db;
}
body.theme-night #view-qibla .qibla-add-mosque-pill {
  border-color: var(--olive-soft);
  background: var(--olive-soft);
  color: #171810;
}

/* نافذة المسجد الأقرب: معلومات مرتبة وبارزة وزر اتجاهات واضح في كل
   الأوضاع، بدون نص أبيض منفصل أو خارج حدود الورقة. */
#qibla-nearest-overlay { z-index: 230; }
#qibla-nearest-overlay .qibla-nearest-sheet {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: min(100%, 560px);
  max-height: min(64dvh, 520px);
  padding: 12px 22px calc(22px + env(safe-area-inset-bottom));
  overflow-x: hidden;
  overflow-y: auto;
  border-radius: 30px 30px 0 0;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 -12px 36px rgba(0,0,0,.16);
}
.qibla-nearest-handle { display: flex; justify-content: center; padding: 2px 0 4px; touch-action: pan-y; }
.qibla-nearest-handle span { width: 42px; height: 5px; border-radius: 999px; background: var(--ink-soft); opacity: .42; }
.qibla-nearest-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-width: 0; }
.qibla-nearest-head h3 { min-width: 0; margin: 0; font: 800 20px/1.3 var(--font-display); color: var(--ink); }
.qibla-nearest-close { display: grid; place-items: center; flex: 0 0 40px; width: 40px; height: 40px; border: 1px solid var(--paper-line); border-radius: 50%; background: var(--paper-deep); color: var(--ink); }
.qibla-nearest-close svg { width: 19px; height: 19px; }
.qibla-nearest-state { margin: 0; padding: 14px 12px; border-radius: 16px; background: var(--paper-deep); color: var(--ink-soft); text-align: center; font-size: 14px; line-height: 1.6; }
.qibla-nearest-content { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.qibla-nearest-content.hidden { display: none; }
.qibla-nearest-mosque-name { display: flex; align-items: center; gap: 12px; min-width: 0; padding: 12px 14px; border: 1px solid var(--paper-line); border-radius: 18px; background: var(--paper-deep); }
.qibla-nearest-icon { display: grid; place-items: center; flex: 0 0 42px; width: 42px; height: 42px; border-radius: 14px; background: color-mix(in srgb, var(--gold) 18%, var(--paper)); color: var(--gold-deep); }
.qibla-nearest-icon svg { width: 22px; height: 22px; }
.qibla-nearest-mosque-name strong { min-width: 0; overflow-wrap: anywhere; font-size: 17px; line-height: 1.45; color: var(--ink); }
.qibla-nearest-facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.qibla-nearest-fact { display: flex; flex-direction: column; gap: 5px; min-width: 0; padding: 11px 13px; border-radius: 15px; background: var(--paper-deep); color: var(--ink-soft); font-size: 13px; }
.qibla-nearest-fact strong { color: var(--ink); font-size: 17px; font-weight: 800; font-variant-numeric: tabular-nums; }
.qibla-nearest-directions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: 100%;
  min-height: 54px;
  margin: 0;
  padding: 12px 16px;
  border: 0;
  border-radius: 16px;
  background: var(--gold-deep);
  color: #fff !important;
  font: 800 15px/1.3 var(--font-ui);
  text-align: center;
  text-decoration: none;
  white-space: normal;
}
.qibla-nearest-directions:visited,
.qibla-nearest-directions:hover,
.qibla-nearest-directions:active { color: #fff !important; text-decoration: none; }
.qibla-nearest-directions svg { flex: 0 0 19px; width: 19px; height: 19px; fill: currentColor; }
body.theme-night #qibla-nearest-overlay .qibla-nearest-sheet { background: #1d1e19; color: #f3f0e7; }
body.theme-night .qibla-nearest-head h3,
body.theme-night .qibla-nearest-mosque-name strong,
body.theme-night .qibla-nearest-fact strong { color: #f3f0e7; }
body.theme-night .qibla-nearest-close { border-color: rgba(255,255,255,.14); background: #292b24; color: #f3f0e7; }
body.theme-night .qibla-nearest-mosque-name,
body.theme-night .qibla-nearest-fact,
body.theme-night .qibla-nearest-state { background: #292b24; border-color: rgba(255,255,255,.1); }
body.theme-night .qibla-nearest-directions { background: var(--olive-soft); color: #181a13 !important; }
body.theme-night .qibla-nearest-directions:visited,
body.theme-night .qibla-nearest-directions:hover,
body.theme-night .qibla-nearest-directions:active { color: #181a13 !important; }
@media (max-width: 360px) {
  #view-qibla .qibla-quick-actions { gap: 7px; }
  #view-qibla .qibla-quick-pill { gap: 5px; padding-inline: 8px; font-size: 10px; }
  #qibla-nearest-overlay .qibla-nearest-sheet { padding-inline: 16px; }
}

/* وحّد تحديد كل تبويبات البوتوم بار في الدارك مود على كبسولة المؤشر،
   بما فيها الصلاة والصوتيات والمصحف. */
body.theme-night .tools-bottom-bar.has-tools-indicator > .tools-bar-btn.active,
body.theme-night .mushaf-quick-bar.has-tools-indicator > .tools-bar-btn.active {
  color: var(--olive-soft) !important;
  background: transparent !important;
  box-shadow: none !important;
}
body.theme-night .tools-bottom-bar.has-tools-indicator > .tools-bar-btn.active .tools-bar-icon,
body.theme-night .mushaf-quick-bar.has-tools-indicator > .tools-bar-btn.active .tools-bar-icon {
  color: var(--olive-soft) !important;
}
body.theme-night .tools-bottom-bar.has-tools-indicator > .tools-bar-indicator,
body.theme-night .mushaf-quick-bar.has-tools-indicator > .tools-bar-indicator {
  background: color-mix(in srgb, var(--olive-soft) 14%, transparent) !important;
  box-shadow: none !important;
  animation: none !important;
}
/* الإعدادات إذا فُتحت من صفحة الصوتيات تظهر فوقها وتُغلق عائدةً إليها. */
#settings-overlay.overlay-fullpage.open { z-index: 270 !important; }

/* اجعل خلفية الإذاعة النشطة محصورة حول الشعار نفسه بدل تدرّج مستطيل
   يغطي مساحة الكارت الفارغة. */
#view-live .live-radio-card-banner { display: none; }
#view-live .live-radio-card.playing .live-radio-card-art {
  border-radius: 15px;
  box-shadow: 0 0 0 2px var(--st), 0 6px 16px color-mix(in srgb, var(--st) 28%, transparent);
}

/* خانات البوتوم بار متساوية، مع مساحة موحدة للأيقونات مهما اختلف ملفها. */
.tools-bottom-bar > .tools-bar-btn,
.mushaf-quick-bar > .tools-bar-btn {
  box-sizing: border-box;
  flex: 1 1 0;
  flex-shrink: 1;
  min-width: 0;
  height: 48px;
  padding: 4px 2px;
}
.tools-bottom-bar .tools-bar-icon,
.mushaf-quick-bar .tools-bar-icon {
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
}
.tools-bottom-bar .tools-bar-icon > svg,
.mushaf-quick-bar .tools-bar-icon > svg,
.tools-bottom-bar .tools-bar-icon > img,
.mushaf-quick-bar .tools-bar-icon > img,
.tools-bottom-bar .tools-bar-icon > .tools-bar-icon-logo,
.mushaf-quick-bar .tools-bar-icon > .tools-bar-icon-logo {
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  object-fit: contain;
}

/* تحديد التبويب يظهر على الأيقونة وحدها؛ الاسم يبقى بلون الأيقونات
   غير النشطة، ولا تُرسم خلفية دائرية أو كبسولة خلف الزر. */
body.theme-night .tools-bottom-bar > .tools-bar-btn.active,
body.theme-night .mushaf-quick-bar > .tools-bar-btn.active {
  color: var(--ink-soft) !important;
  background: transparent !important;
  box-shadow: none !important;
}
body.theme-night .tools-bottom-bar > .tools-bar-btn:active,
body.theme-night .mushaf-quick-bar > .tools-bar-btn:active {
  background: transparent !important;
  transform: none !important;
}
body.theme-night .tools-bottom-bar > .tools-bar-btn.active > span:last-child,
body.theme-night .mushaf-quick-bar > .tools-bar-btn.active > span:last-child {
  color: var(--ink-soft) !important;
}
body.theme-night .tools-bottom-bar > .tools-bar-btn.active .tools-bar-icon,
body.theme-night .mushaf-quick-bar > .tools-bar-btn.active .tools-bar-icon {
  filter: brightness(0) saturate(100%) invert(79%) sepia(21%) saturate(624%) hue-rotate(25deg) brightness(96%) contrast(87%);
}

/* ثبّت موضع الأيقونة وسطر الاسم في كل زر؛ التبويب النشط يحتفظ بمساحة
   الاسم نفسها بدل أن يقفز محتواه للأعلى أو الأسفل مقارنة بباقي العناصر. */
.tools-bottom-bar > .tools-bar-btn,
.mushaf-quick-bar > .tools-bar-btn {
  display: flex !important;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 0;
  height: 44px;
  padding: 0 1px;
  overflow: visible;
}
.tools-bottom-bar > .tools-bar-btn.active,
.mushaf-quick-bar > .tools-bar-btn.active { flex: 2.2 1 0; gap: 5px; }
.tools-bottom-bar > .tools-bar-btn > .tools-bar-icon,
.mushaf-quick-bar > .tools-bar-btn > .tools-bar-icon {
  width: 24px;
  height: 24px;
  margin: 0;
  align-self: center;
}
.tools-bottom-bar > .tools-bar-btn > span:last-child,
.mushaf-quick-bar > .tools-bar-btn > span:last-child {
  display: none !important;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  font-size: 10.5px;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
  text-overflow: clip;
}
.tools-bottom-bar > .tools-bar-btn.active > span:last-child,
.mushaf-quick-bar > .tools-bar-btn.active > span:last-child {
  display: block !important;
  animation: bottom-bar-label-enter 220ms cubic-bezier(.2,.75,.3,1) both;
}
@keyframes bottom-bar-label-enter {
  from { opacity: 0; translate: 9px 0; }
  to { opacity: 1; translate: 0 0; }
}
@media (prefers-reduced-motion: reduce) {
  .tools-bottom-bar > .tools-bar-btn.active > span:last-child,
  .mushaf-quick-bar > .tools-bar-btn.active > span:last-child { animation: none; }
}
body.theme-night .tools-bottom-bar.has-tools-indicator > .tools-bar-indicator,
body.theme-night .mushaf-quick-bar.has-tools-indicator > .tools-bar-indicator {
  background: transparent !important;
  box-shadow: none !important;
  animation: none !important;
}
body.theme-night .tools-bottom-bar .tools-bar-btn > .ripple-clip,
body.theme-night .mushaf-quick-bar .tools-bar-btn > .ripple-clip { display: none !important; }

/* ارتفاع موحد صريح لكل أشرطة التنقل، بدل أن يتمدد الشريط حسب محتوى الصفحة. */
.tools-bottom-bar,
.mushaf-quick-bar {
  box-sizing: border-box;
  height: 46px;
  min-height: 46px;
  max-height: 46px;
  padding-block: 0;
}

/* في OLED تظهر صفحة مباشر بتدرّج فحمي هادئ بدل سطح أسود/موحّد. */
body.theme-night.oled-true-black #view-live .list-page.live-radio-page {
  background: linear-gradient(180deg, #24251F 0%, #151612 38%, #000 100%) !important;
}

/* لا تعرض إطار تركيز مستطيلاً على كارت المحطة؛ أبقِ إشارة التركيز حول
   صورة الإذاعة نفسها كي لا تحيط مساحة فارغة بالكارت. */
#view-live .live-radio-card:focus-visible {
  outline: none;
  outline-offset: 0;
}
#view-live .live-radio-card:focus-visible .live-radio-card-art {
  outline: 2px solid var(--ap-olive);
  outline-offset: 3px;
  border-radius: 15px;
}

/* ===== إضافات أدوات المسلم (كانت في style.css) ===== */
/* ============================================================================
   style.css — إضافات صفحة "أدوات المسلم" بعد ما بقت الواجهة الرئيسية
   للتطبيق. الملف ده إضافي بالكامل فوق style.css الأصلي: مفيش أي تغيير في
   ألوان أو هوية التصميم — نفس الورقي/الذهبي وكل التوكنز الأصلية
   (--paper / --gold / --ink …)، وبس بيضيف:
     1) كارت "متابعة القراءة"
     2) تصغير كارت مواقيت الصلاة للنص مع إعادة ترتيب عناصره
     3) قوس الأدوات نصف الدائري بدل شبكات الإجراءات السريعة
   ========================================================================= */

/* ============================================================================
   1) كارت متابعة القراءة — أول كارت في الصفحة
   ========================================================================= */
.resume-card {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 100%;
  margin: 0 0 14px;
  padding: 14px 16px;
  background: #FFFFFF;
  border: 1px solid rgba(255, 255, 255, .5);
  border-radius: 26px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, .7) inset,
              0 14px 32px -20px rgba(90, 70, 30, .38),
              0 2px 8px rgba(90, 70, 30, .06);
  text-align: start;
  overflow: hidden;
  transition: transform .18s cubic-bezier(.4, 0, .2, 1), box-shadow .18s ease;
}
.resume-card:active {
  transform: scale(.985);
  box-shadow: 0 1px 0 rgba(255, 255, 255, .7) inset, 0 8px 18px -14px rgba(90, 70, 30, .4);
}
body.theme-night .resume-card {
  background: var(--paper-deep);
  border-color: rgba(255, 255, 255, .06);
  box-shadow: 0 10px 26px -18px rgba(0, 0, 0, .8);
}

.resume-ring {
  position: relative;
  flex: 0 0 auto;
  width: 52px; height: 52px;
  display: flex; align-items: center; justify-content: center;
  /* ألوان تدرّج الحلقة: زيتوني صفحة الصوتيات ممزوج ببني، بنفس روح
     المشغّل الصوتي الجديد بدل الذهبي القديم */
  --resume-ring-grad-start: #6F7752;
  --resume-ring-grad-end: #7C4E27;
}
.resume-ring svg {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  transform: rotate(-90deg);
  overflow: visible;
}
.resume-ring circle { fill: none; stroke-width: 3.2; }
.resume-ring-bg { stroke: rgba(111, 119, 82, .18); }
.resume-ring-fg {
  stroke: url(#resume-ring-grad);
  stroke-linecap: round;
  transition: stroke-dashoffset .6s cubic-bezier(.4, 0, .2, 1);
}
body.theme-night .resume-ring {
  --resume-ring-grad-start: #98A278;
  --resume-ring-grad-end: #A9743F;
}
body.theme-night .resume-ring-bg { stroke: rgba(152, 162, 120, .2); }
.resume-ring-num {
  position: relative;
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 800;
  color: #201810;
  font-variant-numeric: tabular-nums;
}
body.theme-night .resume-ring-num { color: var(--ink); }

.resume-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.resume-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .3px;
  color: var(--gold-deep);
}
body.theme-night .resume-label { color: var(--gold-soft); }
.resume-title {
  font-family: var(--font-kufic), var(--font-ui);
  font-size: 17px;
  font-weight: 700;
  line-height: 1.3;
  color: #201810;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
body.theme-night .resume-title { color: var(--ink); }
.resume-sub {
  font-size: 12px;
  font-weight: 600;
  color: #8A8272;
  min-width: 0;
  white-space: nowrap;
  line-height: 1.3;
  overflow: visible;
}
.resume-go {
  flex: 0 0 auto;
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 30%;
  background: rgba(111, 128, 73, .14);
  box-shadow: none;
  color: #59663B;
}
body.theme-night .resume-go {
  background: rgba(152, 162, 120, .16);
  box-shadow: none;
  color: #98A278;
}
.resume-go svg { width: 18px; height: 18px; stroke-width: 2.3; }
#view-tools[dir="ltr"] .resume-go svg { transform: scaleX(-1); }

/* شعار "القرآن الكريم" الخطّي — بين نص الكارت وسهم الفتح، بشفافية جزئية
   عشان يبقى "علامة مائية" هادئة مش عنصر لافت للنظر. بنستخدمه كـ mask
   (بدل صورة ملوّنة جاهزة) عشان نقدر نغيّر لونه حسب الوضع النهاري/الليلي
   ونسخة الأوليد من نفس ملف PNG واحد (خلفيته شفافة والرسمة سودة) */
.resume-quran-mark {
  flex: 0 0 auto;
  /* مقاس ثابت (80×80) بيساوي بالظبط ارتفاع الكارت الكامل (بادينج 14px
     فوق وتحت + ٥٢px ارتفاع دايرة التقدّم = 80px)، وبعدين مارجن سالب
     بيساوي بادينج الكارت الرأسي (14px) عشان يخلّي المربّع ده "يبلع" مساحة
     البادينج ويوصل لحافة الكارت العليا والسفلى بالظبط، من غير ما يكبّر
     ارتفاع الكارت نفسه (الحساب: 80px مقاس + (-14px) مارجن من فوق ومن تحت
     = 52px مساهمة فعلية في ارتفاع السطر، زي دايرة التقدّم بالظبط) */
  width: 80px;
  height: 80px;
  margin-block: -14px;
  background-color: var(--brown-light);
  opacity: .5;
  -webkit-mask-image: url("quran-logo-mark.png");
  mask-image: url("quran-logo-mark.png");
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
}
/* الوضع الليلي العادي (خلفية رمادية غامقة، مش أسود خالص): أبيض بشفافية أقل */
body.theme-night .resume-quran-mark {
  background-color: #FFFFFF;
  opacity: .44;
}
/* وضع الأوليد (أسود خالص): رمادي بدل الأبيض عشان يفضل هادئ ومتناسق مع
   عمق الأسود، من غير تباين حاد زي الأبيض */
body.theme-night.oled-true-black .resume-quran-mark {
  background-color: #9A9A9A;
  opacity: .35;
}

/* أنيميشن الدخول الموجود أصلًا للصفحة يشمل الكارت الجديد كمان */
.view.view-enter-active .resume-card {
  animation: navItemEnterAnim .42s cubic-bezier(.16, 1, .3, 1) backwards;
}

/* ============================================================================
   2) كارت مواقيت الصلاة — نص الحجم تقريبًا، بترتيب عمودين بدل التوسيط الطولي
   (الألوان والخامات والسما المتحركة زي ما هي بالظبط — تصغير وترتيب بس)
   ========================================================================= */
#view-tools .prayer-hero-card {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    "top  top"
    "lab  cd"
    "time sun"
    "grid grid"
    "date date";
  align-items: center;
  padding: 8px 4px 9px;
  text-align: start;

  /* --- الكارت بلا خلفية أو حدود خاصة به — بيبقى امتداد طبيعي لخلفية
     الصفحة العادية (--paper) زي أي محتوى تاني فيها، مش صندوق منفصل --- */
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0;
  overflow: visible !important;
}
#view-tools .prayer-hero-card:active { transform: none; box-shadow: none; }
body.theme-night #view-tools .prayer-hero-card { background: none !important; box-shadow: none !important; }

/* شيل توهّج الضوء ومسيلويت المسجد الشفافين — كانوا متصمّمين يبانوا فوق
   خلفية سما ملوّنة، وعلى الخلفية العادية بيبانوا كبقعة غريبة */
#view-tools .prayer-hero-card::before,
#view-tools .prayer-hero-card::after { content: none !important; display: none !important; }

/* السما (شمس/سحاب/قمر/نجوم) بتفضل شغالة زي ما هي بالظبط — بتتغيّر أوتوماتيك
   حسب وقت اليوم الفعلي من نفس منطق app.js — بس دلوقتي مقصورة في شريطها
   الخاص (badge) أعلى الكارت بحجم صغير ثابت، مش بتتحرك في قوس عريض فوق باقي
   المحتوى زي الأصل، عشان متغطيش أي نص (اسم الموقع / العداد / الصلاة
   القادمة) مهما كان وقت اليوم */
