#audio-category-overlay,
#mushaf-editions-overlay,
#reciter-surahs-overlay,
#playlist-detail-overlay,
#ibtihalat-tracks-overlay,
#islamic-occasions-overlay,
#sunnah-books-overlay,
#sunnah-kutub-overlay,
#sunnah-chapters-overlay,
#sunnah-hadiths-overlay,
#sunnah-hadith-detail-overlay,
#reminders-overlay,
#settings-overlay,
#index-overlay,
#bookmarks-overlay,
#notes-overlay,
#view-prayer,
#view-hadith,
#nawawi-overlay,
#nawawi-detail-overlay,
#explore-category-overlay,
#tasmee-overlay,
