.ap-sheet {
  padding: 0 16px calc(120px + env(safe-area-inset-bottom)) !important;
  background: transparent !important;
  overflow-y: auto;
}
.ap-sheet button { font-family: var(--ap-font); }
.ap-ico { width: 20px; height: 20px; fill: none; stroke: currentColor; flex-shrink: 0; }

/* ------------------------------ الهيرو ------------------------------ */
.ap-hero {
  position: relative;
  min-height: 218px;
  padding-top: calc(38px + env(safe-area-inset-top));
  margin: 0 -16px 6px;
  padding-inline: 20px;
  overflow: hidden;
}
.ap-hero-art {
  position: absolute;
  top: 0;
  inset-inline-end: 0;
  width: 66%;
  max-width: 340px;
  aspect-ratio: 520 / 420;
  background: url('images/audio/hero-quran.webp') left top / 100% 100% no-repeat;
  -webkit-mask-image: linear-gradient(to bottom, #000 62%, transparent 100%), linear-gradient(to left, transparent 0, #000 22%);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to bottom, #000 62%, transparent 100%), linear-gradient(to left, transparent 0, #000 22%);
  mask-composite: intersect;
  pointer-events: none;
}
[dir="ltr"] .ap-hero-art { transform: scaleX(-1); }
body.theme-night .ap-hero-art { filter: brightness(.5) saturate(.8); opacity: .8; }
.ap-hero-text { position: relative; z-index: 1; max-width: 58%; }
.ap-audio-home-back {
  position: absolute;
  z-index: 2;
  inset-inline-start: 18px;
  top: calc(16px + env(safe-area-inset-top));
  width: 44px;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--ap-line);
  border-radius: 15px;
  background: var(--ap-card);
  color: var(--ap-olive);
  box-shadow: var(--ap-shadow);
}
.ap-audio-home-back svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-audio-home-back:active { transform: scale(.94); }
#audio-category-overlay { z-index: 262; }
/* صفحة سور القارئ تظل فوق تبويب الصوتيات الذي فتحها، ويظل التبويب
   ظاهرًا خلفها أثناء الإغلاق والعودة إليه. */
#reciter-surahs-overlay.overlay-fullpage.open { z-index: 263 !important; }
#ap-category-hero { padding-top: calc(88px + env(safe-area-inset-top)); }
.ap-title {
  margin: 0 0 12px;
  font-family: var(--ap-font);
  font-size: 34px;
  font-weight: 900;
  line-height: 1.25;
  color: var(--ap-ink);
}
.ap-subtitle {
  margin: 0;
  font-size: 14px;
  line-height: 1.75;
  color: var(--ap-ink-2);
}

/* ------------------------------ التبويبات ------------------------------ */
.ap-tabs {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 6px;
  justify-content: flex-start;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  padding: 5px;
  margin-bottom: 16px;
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 999px;
  box-shadow: var(--ap-shadow);
}
.ap-tab {
  flex: 0 0 auto;
  min-width: max-content;
  display: flex; align-items: center; justify-content: center; gap: 5px;
  height: 44px;
  padding: 0 12px;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: var(--ap-ink);
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  transition: background .2s, color .2s;
}
.ap-tab .ap-ico { width: 16px; height: 16px; color: var(--ap-gold); }
.ap-tab.active { background: var(--ap-olive); color: #fff; }
body.theme-night .ap-tab.active { color: #15160f; }
.ap-tab.active .ap-ico { color: currentColor; }
.ap-panel.hidden { display: none; }
#audio-page-tabs .ap-tab { font-family: var(--ap-font); }

/* All audio sections stay visible together on narrow screens; labels wrap
   beneath their icons instead of making the tab strip scroll sideways. */
#audio-page-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  overflow: hidden;
  overscroll-behavior-inline: auto;
  padding: 8px;
  border-radius: 26px;
}
#audio-page-tabs .ap-tab {
  min-width: 0;
  width: 100%;
  min-height: 58px;
  height: auto;
  padding: 9px 12px;
  flex-direction: row;
  justify-content: flex-start;
  gap: 9px;
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  background: color-mix(in srgb, var(--ap-card) 88%, var(--ap-olive-soft));
  white-space: normal;
  text-align: start;
  font-size: clamp(12px, 3.5vw, 14px);
  line-height: 1.35;
  transition: transform .18s ease, background .2s ease, border-color .2s ease, box-shadow .2s ease;
}
#audio-page-tabs .ap-tab:active { transform: scale(.98); }
#audio-page-tabs .ap-tab .ap-ico {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  padding: 8px;
  border-radius: 12px;
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
}
#audio-page-tabs .ap-tab.active {
  border-color: color-mix(in srgb, var(--ap-olive) 54%, var(--ap-line));
  background: linear-gradient(135deg, var(--ap-olive-soft), var(--ap-card));
  color: var(--ap-ink);
  box-shadow: 0 5px 15px rgba(67, 79, 43, .10), inset 0 0 0 1px rgba(111, 128, 73, .08);
}
#audio-page-tabs .ap-tab.active .ap-ico { background: var(--ap-olive); color: #fff; }
body.theme-night #audio-page-tabs .ap-tab.active .ap-ico { color: #15160f; }
.ap-translation-controls { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; padding: 16px; }
.ap-translation-field { display: grid; gap: 7px; min-width: 0; color: var(--ap-muted, #777); font-size: 13px; }
.ap-translation-field select { min-width: 0; width: 100%; min-height: 44px; padding: 8px 10px; border: 1px solid var(--ap-line); border-radius: 13px; color: var(--ap-ink); background: var(--ap-card); font: inherit; }
.ap-translation-controls > .ap-add { grid-column: 1 / -1; justify-self: start; }
.ap-translation-source { grid-column: 1 / -1; font-size: 12px; color: var(--ap-muted, #777); }
.ap-translation-source a { color: var(--ap-olive); font-weight: 700; }
.ap-translation-player { display: grid; gap: 10px; padding: 14px 16px; margin: 12px 0; color: var(--ap-ink); }
.ap-translation-player audio { width: 100%; min-height: 40px; }
.ap-translation-ayah { display: flex; align-items: center; gap: 12px; min-height: 62px; padding: 8px 14px; border-bottom: 1px solid var(--ap-line); }
.ap-translation-ayah:last-child { border-bottom: 0; }
.ap-translation-number { flex: 0 0 38px; width: 38px; height: 38px; display: grid; place-items: center; border-radius: 50%; background: var(--ap-olive-soft); color: var(--ap-olive); font-weight: 700; }
.ap-translation-ayah-title { flex: 1; color: var(--ap-ink); }
.ap-translation-play, .ap-translation-download { flex: 0 0 40px; width: 40px; height: 40px; display: grid; place-items: center; border: 0; border-radius: 50%; background: var(--ap-olive-soft); color: var(--ap-olive); font: inherit; font-weight: 700; text-decoration: none; cursor: pointer; }
@media (max-width: 350px) {
  #audio-page-tabs { gap: 6px; padding: 6px; }
  #audio-page-tabs .ap-tab { gap: 7px; padding: 8px; font-size: 11.5px; }
  #audio-page-tabs .ap-tab .ap-ico { width: 29px; height: 29px; flex-basis: 29px; padding: 7px; }
}

.ap-source-link {
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--ap-line);
  border-radius: 12px;
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
  font-size: 20px;
  font-weight: 800;
  text-decoration: none;
  transition: transform .16s ease, background .16s ease;
}
.ap-source-link:active { transform: scale(.94); }

/* ------------------------------ عناصر مشتركة ------------------------------ */
.ap-section-title {
  margin: 20px 4px 10px;
  font-size: 16px;
  font-weight: 800;
  color: var(--ap-ink);
}
.ap-note { margin: 0 4px 10px; font-size: 12.5px; line-height: 1.7; color: var(--ap-ink-3); }
.ap-card {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 26px;
  box-shadow: var(--ap-shadow);
}
.ap-list { padding: 4px 14px; }
.ap-empty { padding: 22px 14px; text-align: center; font-size: 13px; color: var(--ap-ink-3); line-height: 1.8; }

.ap-avatar {
  flex-shrink: 0;
  width: 56px; height: 56px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
  border: 2px solid var(--ap-card);
  box-shadow: 0 0 0 1px var(--ap-line);
}
.ap-avatar img { width: 100%; height: 100%; object-fit: cover; }
.ap-avatar svg { width: 26px; height: 26px; fill: none; stroke: currentColor; }

.ap-round {
  flex-shrink: 0;
  width: 44px; height: 44px;
  border-radius: 50%;
  border: none;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-olive);
  color: #fff;
  transition: transform .12s;
}
body.theme-night .ap-round { color: #15160f; }
.ap-round:active { transform: scale(.92); }
.ap-round svg { width: 18px; height: 18px; fill: currentColor; stroke: none; }
.ap-round.soft { background: var(--ap-olive-soft); color: var(--ap-ink); }
body.theme-night .ap-round.soft { color: var(--ap-ink); }
.ap-round.gold { background: var(--ap-gold); color: #fff; }
.ap-round.sm { width: 38px; height: 38px; }

/* صفحة تحديث التطبيق: لوحة مستقلة بألوان الزيتوني والعاجي من هوية الصوتيات */
#update-check-overlay { z-index: 275 !important; }
#update-check-overlay .update-check-sheet {
  position: relative;
  width: 100%;
  max-width: 600px;
  min-height: 100%;
  margin: 0 auto;
  padding: 0 18px calc(34px + env(safe-area-inset-bottom));
  overflow-x: hidden;
  overflow-y: auto;
  box-sizing: border-box;
  color: var(--ap-ink);
  background: var(--ap-bg);
  font-family: var(--ap-font);
}
.update-check-hero {
  position: relative;
  display: flex;
  min-height: 325px;
  margin: 0 -18px 22px;
  padding: calc(74px + env(safe-area-inset-top)) 26px 30px;
  box-sizing: border-box;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(145deg, #76805c 0%, #929c70 58%, #b4b991 100%);
  border-radius: 0 0 34px 34px;
  isolation: isolate;
}
.update-check-hero::after {
  position: absolute;
  z-index: -1;
  inset: auto -14% -60% 30%;
  height: 95%;
  content: "";
  background: radial-gradient(ellipse, rgba(255,255,255,.22), transparent 68%);
}
.update-check-back {
  position: absolute;
  top: calc(17px + env(safe-area-inset-top));
  inset-inline-start: 18px;
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.35);
  border-radius: 15px;
  color: #fff;
  background: rgba(255,255,255,.15);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.update-check-back svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.update-check-brand {
  display: grid;
  width: 62px;
  height: 62px;
  margin-bottom: 21px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.42);
  border-radius: 22px;
  color: #fff;
  background: rgba(255,255,255,.2);
  box-shadow: 0 12px 32px rgba(37,42,24,.16), inset 0 1px rgba(255,255,255,.24);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}
.update-check-brand svg { width: 32px; height: 32px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.update-check-orbit { position: absolute; z-index: -1; display: block; border: 1px solid rgba(255,255,255,.15); border-radius: 50%; }
.update-check-orbit-one { width: 285px; height: 285px; inset-inline-end: -95px; top: 12px; }
.update-check-orbit-two { width: 205px; height: 205px; inset-inline-end: -55px; top: 52px; }
.update-check-eyebrow { margin: 0 0 6px; color: rgba(255,255,255,.76); font-size: 12px; font-weight: 700; letter-spacing: .08em; }
.update-check-hero h1 { margin: 0; color: #fff; font-size: clamp(28px, 8vw, 36px); font-weight: 900; line-height: 1.25; }
.update-check-subtitle { max-width: 330px; margin: 10px 0 0; color: rgba(255,255,255,.88); font-size: 14px; line-height: 1.75; }
.update-check-content { width: min(100%, 490px); margin: 0 auto; }
.update-check-status-card,
.update-check-version-card {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 19px;
  border: 1px solid var(--ap-line);
  border-radius: 23px;
  background: var(--ap-card);
  box-shadow: var(--ap-shadow);
}
.update-check-status-card { min-height: 91px; transition: border-color .24s, transform .24s; }
.update-check-status-card[data-state="available"] { border-color: var(--ap-olive); }
.update-check-status-card[data-state="latest"] .update-check-status-icon { background: var(--ap-olive); color: #fff; }
.update-check-status-card[data-state="error"] .update-check-status-icon { color: #a66549; background: rgba(166,101,73,.12); }
.update-check-status-icon {
  display: grid;
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  place-items: center;
  border-radius: 17px;
  color: var(--ap-olive-2);
  background: var(--ap-olive-soft);
}
.update-check-status-icon svg { width: 25px; height: 25px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.update-check-status-card[data-state="checking"] .update-check-status-icon svg { animation: update-check-spin 1.5s linear infinite; }
@keyframes update-check-spin { to { transform: rotate(360deg); } }
.update-check-status-copy { min-width: 0; }
.update-check-status-copy h2 { margin: 0 0 4px; color: var(--ap-ink); font-size: 16px; font-weight: 850; }
.update-check-status-copy p { margin: 0; color: var(--ap-ink-2); font-size: 13px; line-height: 1.65; }
.update-check-version-card { justify-content: space-between; gap: 10px; margin-top: 13px; padding: 15px 18px; }
.update-check-version-card > div { display: flex; min-width: 0; flex-direction: column; gap: 5px; }
.update-check-version-card span { color: var(--ap-ink-3); font-size: 11px; }
.update-check-version-card strong { color: var(--ap-ink); font-size: 15px; direction: ltr; unicode-bidi: isolate; }
.update-check-version-arrow { width: 19px; height: 19px; flex: 0 0 19px; fill: none; stroke: var(--ap-olive); }
.update-check-actions { display: grid; gap: 10px; margin-top: 20px; }
.update-check-primary,
.update-check-secondary {
  min-height: 54px;
  border: 0;
  border-radius: 18px;
  font: inherit;
  font-size: 15px;
  font-weight: 850;
  transition: transform .16s, filter .16s, opacity .16s;
}
.update-check-primary { color: #fff; background: linear-gradient(135deg, var(--ap-olive-2), var(--ap-olive)); box-shadow: 0 10px 24px rgba(111,117,80,.26); }
body.theme-night .update-check-primary { color: #17180f; }
.update-check-primary:active, .update-check-secondary:active { transform: scale(.985); }
.update-check-primary:disabled { opacity: .58; }
.update-check-secondary { color: var(--ap-olive-2); border: 1px solid var(--ap-line); background: var(--ap-card); }
.update-check-footnote { margin: 15px 6px 0; color: var(--ap-ink-3); font-size: 11px; line-height: 1.7; text-align: center; }
body.theme-night .update-check-hero { background: linear-gradient(145deg, #62694c 0%, #777f59 58%, #929a70 100%); }
@media (prefers-reduced-motion: reduce) {
  #update-check-overlay *, #update-check-overlay *::before, #update-check-overlay *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

/* صف قارئ (الصورة 2) */
.ap-row {
  display: flex; align-items: center; gap: 12px;
  width: 100%;
  padding: 14px 0;
  border: none;
  border-bottom: 1px solid var(--ap-line);
  background: none;
  text-align: start;
  color: inherit;
}
.ap-row:last-child { border-bottom: none; }
.ap-row-text { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.ap-row-name {
  font-size: 16px; font-weight: 800; color: var(--ap-ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ap-row-sub { font-size: 12.5px; color: var(--ap-ink-2); line-height: 1.5; }
.ap-row-badge {
  display: inline-flex; vertical-align: middle;
  width: 16px; height: 16px; margin-inline-start: 5px;
  color: var(--ap-gold);
}
.ap-row-badge svg { width: 16px; height: 16px; }
.ap-fav {
  flex-shrink: 0;
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border: none; background: none; border-radius: 50%;
  color: var(--ap-gold);
}
.ap-fav svg { width: 20px; height: 20px; fill: none; stroke: currentColor; }
.ap-fav.on svg { fill: currentColor; }
.ap-chev { width: 20px; height: 20px; color: var(--ap-ink-3); flex-shrink: 0; }
[dir="ltr"] .ap-chev { transform: rotate(180deg); }

/* فلتر الكل / المفضلة */
.ap-filter { display: flex; gap: 8px; margin: 0 2px 12px; }
.ap-chip {
  height: 36px; padding: 0 16px;
  border: 1px solid var(--ap-line); border-radius: 999px;
  background: var(--ap-card); color: var(--ap-ink-2);
  font-size: 13px; font-weight: 700;
  display: inline-flex; align-items: center; gap: 6px;
}
.ap-chip svg { width: 15px; height: 15px; fill: none; stroke: var(--ap-gold); }
.ap-chip.active { background: var(--ap-olive-soft); color: var(--ap-ink); border-color: var(--ap-olive); }

/* بطاقة الابتهالات الترويجية (الصورة 2) */
.ap-promo {
  display: flex; align-items: center; gap: 12px;
  margin-top: 16px; padding: 16px;
  background: var(--ap-olive-soft);
  border: 1px solid var(--ap-line);
  border-radius: 24px;
}
.ap-promo-icon {
  width: 54px; height: 54px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-card); color: var(--ap-olive); flex-shrink: 0;
}
.ap-promo-icon svg { width: 26px; height: 26px; fill: none; stroke: currentColor; }
.ap-promo-text { flex: 1; min-width: 0; }
.ap-promo-text h4 { margin: 0 0 3px; font-size: 17px; font-weight: 800; color: var(--ap-gold); }
.ap-promo-text p { margin: 0; font-size: 12.5px; color: var(--ap-ink-2); line-height: 1.6; }
.ap-promo-btn {
  flex-shrink: 0; height: 40px; padding: 0 16px;
  border: 1px solid var(--ap-gold); border-radius: 999px;
  background: transparent; color: var(--ap-gold);
  font-size: 13px; font-weight: 800;
  display: inline-flex; align-items: center; gap: 4px;
}
.ap-promo-btn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; }
[dir="ltr"] .ap-promo-btn svg { transform: rotate(180deg); }

/* متابعة الاستماع (الصورة 1) */
.ap-resume { display: flex; align-items: center; gap: 14px; padding: 16px; margin-bottom: 14px; }
.ap-resume .ap-avatar { width: 64px; height: 64px; }
.ap-resume-body { flex: 1; min-width: 0; }
.ap-resume-label { font-size: 12px; color: var(--ap-ink-2); }
.ap-resume-title { font-size: 17px; font-weight: 800; margin: 2px 0; }
.ap-resume-sub { font-size: 12.5px; color: var(--ap-ink-2); }
.ap-resume-bar { height: 4px; border-radius: 4px; background: var(--ap-line); margin-top: 10px; overflow: hidden; }
.ap-resume-bar i { display: block; height: 100%; background: var(--ap-olive); border-radius: 4px; }
.ap-resume-times { display: flex; justify-content: space-between; margin-top: 4px; font-size: 11.5px; color: var(--ap-ink-2); direction: ltr; }
.ap-resume .ap-round { width: 52px; height: 52px; }

/* المكتبة السمعية */
.ap-lib { padding: 14px; }
.ap-lib-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.ap-lib-head h4 { margin: 0; font-size: 16px; font-weight: 800; }
.ap-add {
  height: 36px; padding: 0 16px; border: none; border-radius: 999px;
  background: var(--ap-olive); color: #fff; font-size: 13px; font-weight: 800;
  display: inline-flex; align-items: center; gap: 5px;
}
body.theme-night .ap-add { color: #15160f; }
.ap-add svg { width: 14px; height: 14px; fill: none; stroke: currentColor; }
.ap-search { position: relative; }
.ap-search input {
  width: 100%; height: 44px; padding: 0 16px; padding-inline-end: 44px;
  border: 1px solid var(--ap-line); border-radius: 999px;
  background: var(--ap-bg); color: var(--ap-ink);
  font-family: var(--ap-font); font-size: 14px; outline: none;
}
.ap-search svg { position: absolute; inset-inline-end: 16px; top: 50%; margin-top: -9px; width: 18px; height: 18px; fill: none; stroke: var(--ap-ink-3); }

/* قوائم التشغيل */
.ap-pl { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--ap-line); }
.ap-pl:last-child { border-bottom: none; }
.ap-pl-icon {
  width: 46px; height: 46px; border-radius: 16px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-gold-soft); color: var(--ap-gold);
}
.ap-pl-icon svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-pl-info { flex: 1; min-width: 0; border: none; background: none; text-align: start; color: inherit; display: flex; flex-direction: column; gap: 3px; }
.ap-pl-name { font-size: 15px; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ap-pl-sub { font-size: 12px; color: var(--ap-ink-2); }

/* ------------------------------ صفحة سور القارئ (الصورة 4) ------------------------------ */
.ap-topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: calc(12px + env(safe-area-inset-top));
  position: relative;
}
.ap-iconbtn {
  width: 42px; height: 42px; border: none; background: none; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; color: var(--ap-ink);
}
.ap-iconbtn svg { width: 24px; height: 24px; fill: none; stroke: currentColor; }
.ap-iconbtn svg.dots { fill: currentColor; stroke: none; }
[dir="rtl"] .ap-back svg { transform: none; }
.ap-menu {
  position: absolute; top: calc(56px + env(safe-area-inset-top)); inset-inline-end: 0; z-index: 10;
  min-width: 200px; padding: 6px;
  background: var(--ap-card); border: 1px solid var(--ap-line); border-radius: 18px; box-shadow: 0 14px 34px rgba(0,0,0,.18);
}
.ap-menu button {
  display: flex; align-items: center; gap: 10px; width: 100%; height: 44px; padding: 0 12px;
  border: none; background: none; border-radius: 12px; color: var(--ap-ink); font-size: 14px; font-weight: 700; text-align: start;
}
.ap-menu button:active { background: var(--ap-olive-soft); }
.ap-menu svg { width: 18px; height: 18px; fill: none; stroke: var(--ap-gold); }

.ap-rhero { display: flex; align-items: flex-start; gap: 16px; padding: 8px 4px 18px; }
.ap-rhero .ap-photo {
  width: 132px; height: 132px; flex-shrink: 0; border-radius: 50%; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-olive-soft); color: var(--ap-olive);
  border: 4px solid var(--ap-olive-2); box-shadow: var(--ap-shadow);
}
.ap-rhero .ap-photo img { width: 100%; height: 100%; object-fit: cover; }
.ap-rhero .ap-photo svg { width: 54px; height: 54px; fill: none; stroke: currentColor; }
.ap-rhero-info { flex: 1; min-width: 0; }
.ap-rname { margin: 6px 0 8px; font-size: 22px; font-weight: 900; line-height: 1.45; }
.ap-rname small { display: block; font-size: 22px; font-weight: 900; }
.ap-rdesc { margin: 0; font-size: 13px; line-height: 1.85; color: var(--ap-ink-2); }
.ap-dlall {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; height: 52px; margin: 0 0 18px;
  border: none; border-radius: 16px;
  background: var(--ap-olive-2); color: #fff; font-size: 17px; font-weight: 800;
  box-shadow: 0 6px 16px rgba(80, 76, 50, .22);
}
body.theme-night .ap-dlall { color: #15160f; }
.ap-dlall svg { width: 20px; height: 20px; fill: none; stroke: currentColor; }
.ap-dlprog { margin: 0 0 18px; }
.ap-dlprog-bar { height: 8px; border-radius: 8px; background: var(--ap-line); overflow: hidden; }
.ap-dlprog-fill { height: 100%; width: 0; background: var(--ap-olive); border-radius: 8px; transition: width .3s; }
.ap-dlprog-bar.indeterminate .ap-dlprog-fill { width: 35%; animation: ap-slide 1.1s ease-in-out infinite alternate; }
@keyframes ap-slide { from { margin-inline-start: 0; } to { margin-inline-start: 65%; } }
.ap-dlprog-text { margin: 8px 0; font-size: 13px; font-weight: 700; color: var(--ap-ink-2); }
.ap-dlprog-cancel {
  height: 38px; padding: 0 16px; border: 1px solid var(--ap-line); border-radius: 999px;
  background: var(--ap-card); color: var(--ap-ink); font-size: 13px; font-weight: 700;
  display: inline-flex; align-items: center; gap: 6px;
}
.ap-dlprog-cancel svg { width: 14px; height: 14px; fill: none; stroke: currentColor; }

.ap-listhead { display: flex; align-items: center; justify-content: space-between; margin: 4px 4px 6px; }
.ap-listhead h4 { margin: 0; font-size: 20px; font-weight: 900; }
.ap-sort { position: relative; }
.ap-sort-btn {
  display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 6px;
  border: none; background: none; color: var(--ap-ink-2); font-size: 14px; font-weight: 700;
}
.ap-sort-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; }
.ap-sort .ap-menu { top: 42px; inset-inline-end: auto; inset-inline-start: 0; }

.ap-surahs { padding: 0; overflow: hidden; }
.ap-srow {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--ap-line);
}
.ap-srow:last-child { border-bottom: none; }
.ap-srow.current { background: var(--ap-hl); }
.ap-num {
  flex-shrink: 0; width: 40px; height: 40px; position: relative;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; font-weight: 800; color: var(--ap-ink);
}
.ap-num::before, .ap-num::after {
  content: ''; position: absolute; inset: 5px;
  border: 1.5px solid var(--ap-olive-2); border-radius: 6px;
}
.ap-num::after { transform: rotate(45deg); }
.ap-sinfo { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.ap-sname { font-size: 17px; font-weight: 800; }
.ap-smeta { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ap-ink-2); }
.ap-smeta i { width: 1px; height: 12px; background: var(--ap-ink-3); }
.ap-sstat { font-size: 11.5px; padding: 1px 8px; border-radius: 999px; background: var(--ap-olive-soft); color: var(--ap-ink-3); }
.ap-sstat.downloaded { background: var(--ap-gold-soft); color: var(--ap-gold); }
.ap-sprog { display: none; align-items: center; gap: 8px; }
.ap-sprog.active { display: flex; }
.ap-sprog-track { flex: 1; height: 4px; border-radius: 4px; background: var(--ap-line); overflow: hidden; }
.ap-sprog-fill { display: block; height: 100%; width: 35%; background: var(--ap-olive); border-radius: 4px; animation: ap-slide 1.1s ease-in-out infinite alternate; }
.ap-sprog-speed { font-size: 11px; color: var(--ap-ink-3); direction: ltr; }
.ap-sdl {
  width: 38px; height: 38px; flex-shrink: 0; border: none; background: none; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; color: var(--ap-ink-2);
  overflow: hidden; transition: width .34s cubic-bezier(.2,.75,.25,1), height .34s, margin .34s, opacity .22s, transform .34s;
}
.ap-sdl svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-sdl.downloaded { color: var(--ap-gold); }
.ap-sdl.loading { opacity: .5; pointer-events: none; }
.ap-srow .ap-round { width: 46px; height: 46px; background: var(--ap-olive-soft); color: var(--ap-ink); }
.ap-srow > [data-listen-surah] { transition: transform .38s cubic-bezier(.2,.75,.25,1); }
.ap-srow.is-downloaded > .ap-sdl[data-download-surah],
.ap-plrow.is-downloaded > [data-item-download] {
  width: 0; height: 0; margin-inline-start: -12px; opacity: 0; transform: scale(.45); pointer-events: none;
}
/* بعد إخفاء زر التنزيل يعيد flex توزيع المساحة تلقائيًا؛ لا نحتاج إزاحة
   إضافية لزر التشغيل قد تدفعه خارج حدود الصف على الشاشات الضيقة. */
[dir="rtl"] .ap-plrow.is-downloaded > .ap-round { transform: translateX(-46px); }
[dir="ltr"] .ap-plrow.is-downloaded > .ap-round { transform: translateX(46px); }
.ap-srow.current .ap-round { background: var(--ap-olive-2); color: #fff; }

/* ------------------------------ صفحة الابتهالات + المشغّل (الصورة 5) ------------------------------ */
.ap-player { text-align: center; padding: 6px 4px 18px; }
.ap-cover {
  width: 190px; height: 190px; margin: 6px auto 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
  background: var(--ap-card); border: 2px solid var(--ap-gold); box-shadow: var(--ap-shadow);
  color: var(--ap-olive);
}
.ap-cover img { width: 100%; height: 100%; object-fit: cover; }
.ap-cover svg { width: 130px; height: 130px; }
.ap-pname { display: flex; align-items: center; justify-content: center; gap: 10px; margin: 0; font-size: 26px; font-weight: 900; }
.ap-verified { width: 26px; height: 26px; color: var(--ap-gold); }
.ap-psub { margin: 4px 0 0; font-size: 15px; font-weight: 700; color: var(--ap-olive); }
.ap-ptitle { margin: 22px 0 14px; font-size: 26px; font-weight: 900; line-height: 1.5; }
.ap-seek { padding: 0 6px; }
.ap-seek input[type=range] {
  -webkit-appearance: none; appearance: none; width: 100%; height: 22px; background: transparent; direction: ltr; margin: 0;
}
.ap-seek input[type=range]::-webkit-slider-runnable-track {
  height: 3px; border-radius: 3px;
  background: linear-gradient(to right, var(--ap-olive) var(--pct, 0%), var(--ap-line) var(--pct, 0%));
}
.ap-seek input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none; width: 18px; height: 18px; margin-top: -7.5px; border-radius: 50%;
  background: var(--ap-gold); border: 2px solid var(--ap-card); box-shadow: 0 1px 4px rgba(0,0,0,.3);
}
.ap-seek input[type=range]::-moz-range-track { height: 3px; background: var(--ap-line); }
.ap-seek input[type=range]::-moz-range-progress { height: 3px; background: var(--ap-olive); }
.ap-seek input[type=range]::-moz-range-thumb { width: 16px; height: 16px; border-radius: 50%; background: var(--ap-gold); border: 2px solid var(--ap-card); }
.ap-times { display: flex; justify-content: space-between; direction: ltr; font-size: 14px; color: var(--ap-olive); font-variant-numeric: tabular-nums; }
.ap-controls { display: flex; align-items: center; justify-content: space-between; direction: ltr; padding: 12px 4px 4px; }
.ap-ctl { width: 46px; height: 46px; border: none; background: none; color: var(--ap-olive); display: flex; align-items: center; justify-content: center; border-radius: 50%; position: relative; }
.ap-ctl svg { width: 26px; height: 26px; }
.ap-ctl.on { color: var(--ap-gold); }
.ap-ctl.on::after { content: ''; position: absolute; bottom: 4px; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.ap-ctl-sk { width: 60px; height: 60px; border: 1px solid var(--ap-line); background: var(--ap-card); color: var(--ap-ink); }
.ap-ctl-sk svg { width: 24px; height: 24px; fill: currentColor; stroke: none; }
.ap-ctl-sk[disabled] { opacity: .35; }
.ap-ctl-main {
  width: 84px; height: 84px; border: 3px solid var(--ap-card); box-shadow: 0 0 0 1.5px var(--ap-gold);
  background: var(--ap-olive); color: #fff;
}
body.theme-night .ap-ctl-main { color: #15160f; }
.ap-ctl-main svg { width: 34px; height: 34px; fill: currentColor; stroke: none; }
.ap-ctl svg.st { fill: none; stroke: currentColor; }

.ap-tracks { padding: 12px 14px 4px; }
.ap-tracks-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; color: var(--ap-olive); }
.ap-tracks-head h4 { margin: 0; font-size: 17px; font-weight: 800; color: var(--ap-olive); }
.ap-tracks-head svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-trow {
  display: flex; align-items: center; gap: 10px; padding: 12px 8px; margin: 0 -8px;
  border-bottom: 1px solid var(--ap-line); border-radius: 14px;
}
.ap-trow:last-child { border-bottom: none; }
.ap-trow.current { background: var(--ap-hl); border-bottom-color: transparent; }
.ap-tnum {
  width: 34px; height: 34px; flex-shrink: 0; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-olive-soft); font-size: 14px; font-weight: 800; color: var(--ap-ink-2); border: none;
}
.ap-trow.current .ap-tnum { background: var(--ap-olive); color: #fff; }
body.theme-night .ap-trow.current .ap-tnum { color: #15160f; }
.ap-tplay { flex: 1; min-width: 0; border: none; background: none; color: inherit; text-align: start; font-size: 17px; font-weight: 700; padding: 0; line-height: 1.5; }
.ap-tplay { transition: flex-basis .34s cubic-bezier(.2,.75,.25,1), padding .34s; }
.ap-tdur { font-size: 12.5px; color: var(--ap-olive); direction: ltr; min-width: 40px; text-align: center; font-variant-numeric: tabular-nums; }
.ap-eq { width: 22px; height: 22px; color: var(--ap-olive); display: none; }
.ap-trow.current .ap-eq { display: block; }
.ap-eq rect { transform-box: fill-box; transform-origin: bottom; }
.ap-trow.playing .ap-eq rect { animation: ap-eq .9s ease-in-out infinite alternate; }
.ap-trow.playing .ap-eq rect:nth-child(2) { animation-delay: .2s; }
.ap-trow.playing .ap-eq rect:nth-child(3) { animation-delay: .4s; }
@keyframes ap-eq { from { transform: scaleY(.35); } to { transform: scaleY(1); } }
.ap-tdl {
  width: 38px; height: 38px; border: none; background: none; border-radius: 50%; color: var(--ap-ink-2);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden;
  transition: width .34s cubic-bezier(.2,.75,.25,1), height .34s, margin .34s, opacity .22s, transform .34s;
}
.ap-tdl svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-tdl.downloaded { color: var(--ap-gold); }
.ap-trow.is-downloaded .ap-tdl { width: 22px; height: 22px; margin-inline-start: 0; opacity: .7; transform: scale(.85); }
.ap-tdl.unsupported { opacity: .35; pointer-events: none; }
.ap-source { margin: 14px 4px 0; display: flex; gap: 8px; font-size: 12px; line-height: 1.7; color: var(--ap-ink-3); }
.ap-source svg { width: 16px; height: 16px; flex-shrink: 0; fill: none; stroke: currentColor; margin-top: 3px; }

/* المشغّل العائم للابتهالات يختفي وصفحة الابتهالات نفسها مفتوحة (فيها مشغّل كامل) */
body:has(#ibtihalat-tracks-overlay.open) #ibtihalat-audio-bar { display: none !important; }

/* ------------------------------ إضافات ------------------------------ */
.ap-row-main {
  flex: 1 1 auto; min-width: 0;
  display: flex; align-items: center; gap: 12px;
  padding: 0; border: none; background: none;
  color: inherit; text-align: start; cursor: pointer;
}
.ap-panel.hidden, .ap-menu.hidden, .ap-dlall.hidden, .ap-dlprog.hidden, #ap-resume-card.hidden,
#downloaded-reciters-section.hidden { display: none !important; }
.ap-sstat:not(.downloaded) { display: none; }
.ap-meta-hidden, .ap-smeta.hidden { display: none; }
.ap-ctl[data-mode="one"]::before {
  content: '1'; position: absolute; top: 9px; inset-inline-end: 12px;
  font-size: 10px; font-weight: 900; color: var(--ap-gold);
}
.ap-ctl .ibtihalat-audio-spin { width: 26px; height: 26px; }
.ap-ctl-main .ibtihalat-audio-spin { border-color: rgba(255,255,255,.35); border-top-color: #fff; }
[dir="ltr"] .ap-topbar { flex-direction: row-reverse; }
.ap-tplay { cursor: pointer; }
.ap-tdl.downloading { pointer-events: none; }
.ap-tdl .ibtihalat-audio-spin { width: 20px; height: 20px; }

/* ضبط نهائي */
body.theme-night .ap-srow .ap-round { color: var(--ap-ink); }
body.theme-night .ap-srow.current .ap-round { color: #fff; }
.ap-rname, .ap-rname small { font-size: 20px; }
.ap-ptitle { font-size: 22px; }
.ap-tplay { font-size: 15.5px; }


/* ------------------------------ صفحة تفاصيل قائمة التشغيل ------------------------------
   نفس لغة صفحة سور القارئ: شريط علوي + هيرو + زر تشغيل + صفوف ap-srow.
   كل القواعد محصورة تحت #playlist-detail-overlay عشان ما تلمسش محرِّر القوائم
   (اللي لسه بيستخدم كلاسات playlist-detail-search-* القديمة في style.css) */
#playlist-detail-overlay .ap-topbar-side { display: flex; align-items: center; gap: 2px; }
#playlist-detail-overlay .ap-fav.active svg { fill: currentColor; }

.ap-plcover {
  flex-shrink: 0; width: 112px; height: 112px; border-radius: 32px;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-gold-soft); color: var(--ap-gold);
  border: 2px solid var(--ap-card); box-shadow: var(--ap-shadow), 0 0 0 1px var(--ap-line);
}
.ap-plcover svg { width: 50px; height: 50px; fill: none; stroke: currentColor; }

/* الأزرار: تشغيل (عريض) + تحميل الكل / تكرار / عشوائي */
.ap-plactions { display: flex; align-items: center; gap: 10px; margin: 0 0 14px; }
#playlist-detail-overlay .ap-plplay {
  flex: 1 1 auto; width: auto; min-width: 0; margin: 0; height: 52px; font-size: 17px;
}
#playlist-detail-overlay .ap-plplay svg { width: 17px; height: 17px; fill: currentColor; stroke: none; }
.ap-tile {
  flex-shrink: 0; width: 52px; height: 52px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--ap-line); background: var(--ap-card); color: var(--ap-ink-2);
  box-shadow: var(--ap-shadow); transition: transform .12s, background .2s, color .2s;
}
.ap-tile:active { transform: scale(.94); }
.ap-tile svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
.ap-tile[data-active="true"] { background: var(--ap-olive); border-color: var(--ap-olive); color: #fff; }
body.theme-night .ap-tile[data-active="true"] { color: #15160f; }
.ap-tile.is-busy { opacity: .45; pointer-events: none; }

/* إحصائيات: محمّلة / المساحة على الجهاز */
.ap-stats { display: flex; gap: 8px; margin: 0 0 14px; flex-wrap: wrap; }
.ap-pill {
  display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 14px;
  border-radius: 999px; border: 1px solid var(--ap-line); background: var(--ap-card);
  font-size: 12.5px; font-weight: 700; color: var(--ap-ink-2);
}
.ap-pill svg { width: 15px; height: 15px; fill: none; stroke: var(--ap-gold); flex-shrink: 0; }

.ap-plsearch { margin: 0 0 12px; }
#playlist-detail-overlay .ap-filter { margin-inline: 0; flex-wrap: wrap; }
#playlist-detail-overlay .ap-chip { padding: 0 12px; gap: 8px; }
.ap-chip-count {
  min-width: 22px; height: 22px; padding: 0 6px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ap-olive-soft); color: var(--ap-ink-2); font-size: 11.5px; font-weight: 800;
}
.ap-chip.active .ap-chip-count { background: var(--ap-card); color: var(--ap-ink); }

/* صفوف السور: القائمة المنسدلة لازم تطلع بره الكارت (مش تتقص) */
#playlist-detail-overlay .ap-plitems { overflow: visible; }
.ap-plrow { position: relative; gap: 8px; padding: 12px; }
.ap-plrow .ap-num { width: 38px; height: 38px; font-size: 14px; }
.ap-plrow .ap-sname { font-size: 16px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ap-plrow .ap-smeta { min-width: 0; font-size: 12.5px; }
.ap-plrow .ap-smeta > span { white-space: nowrap; flex-shrink: 0; }
.ap-plrow .ap-smeta > span:first-child { flex-shrink: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.ap-plrow .ap-round { width: 42px; height: 42px; }
.ap-plrow .ap-round svg { width: 16px; height: 16px; }
.ap-plrow .ap-sdl { width: 34px; height: 34px; }
.ap-plrow .ap-sdl svg { width: 21px; height: 21px; }
.ap-plrow .ap-sdl svg.dots { fill: currentColor; stroke: none; width: 20px; height: 20px; }
.ap-sdl.is-busy { opacity: .45; pointer-events: none; }

/* القوائم المنسدلة (قائمة القائمة + قائمة كل سورة) بنفس شكل .ap-menu */
#playlist-detail-overlay .ap-menu.playlist-item-menu-panel {
  position: absolute; z-index: 10; min-width: 210px; padding: 6px;
  display: flex; flex-direction: column;
  background: var(--ap-card); border: 1px solid var(--ap-line); border-radius: 18px;
  box-shadow: 0 14px 34px rgba(0, 0, 0, .18);
}
#playlist-detail-overlay .ap-menu.hidden { display: none !important; }
#playlist-detail-overlay .ap-topbar > .ap-menu { top: calc(56px + env(safe-area-inset-top)); inset-inline-start: 0; inset-inline-end: auto; }
#playlist-detail-overlay .ap-plrow > .ap-menu { top: 50px; inset-inline-end: 8px; inset-inline-start: auto; }
/* آخر سورتين في قائمة طويلة: القائمة تفتح لفوق عشان ما تنزلش تحت الشاشة */
#playlist-detail-overlay .ap-plrow:nth-last-child(-n+2):not(:nth-child(-n+3)) > .ap-menu { top: auto; bottom: 50px; }
#playlist-detail-overlay .ap-menu button { justify-content: flex-start; padding: 0 12px; height: 44px; font-size: 14px; font-weight: 700; color: var(--ap-ink); }
#playlist-detail-overlay .ap-menu button svg { width: 18px; height: 18px; fill: none; stroke: var(--ap-gold); color: inherit; }
#playlist-detail-overlay .ap-menu button.hidden { display: none; }
#playlist-detail-overlay .ap-menu hr { border: none; border-top: 1px solid var(--ap-line); margin: 4px 2px; }
#playlist-detail-overlay .ap-menu .playlist-item-menu-danger { color: #C0392B !important; }
#playlist-detail-overlay .ap-menu .playlist-item-menu-danger svg { stroke: #C0392B; color: #C0392B !important; }

/* ==========================================================================
   المشغّل الموحَّد (#ibtihalat-tracks-overlay): نفس الصفحة للابتهالات ولتلاوات
   القرّاء. data-mode="ibt" | "quran" بيتحدد من setPlayerPageMode() في app.js
   ========================================================================== */
#ibtihalat-tracks-overlay[data-mode="quran"] .ibt-ibt-only,
#ibtihalat-tracks-overlay[data-mode="ibt"] .ibt-quran-only { display: none !important; }

/* اسم القارئ في وضع القرآن بيفتح قائمة اختيار القارئ */
#ibtihalat-tracks-overlay[data-mode="quran"] #ibt-pname { cursor: pointer; }

/* سطر "من قائمة كذا — ٢/١٠" تحت العنوان */
#ibt-playlist-context { margin: -6px 0 10px; font-size: 13px; color: var(--ap-olive-2); }

/* البحث داخل قائمة السور */
.ap-tracks-search { padding: 4px 0 10px; }
.ap-tracks-search input {
  width: 100%; box-sizing: border-box; height: 42px; border-radius: 12px;
  border: 1px solid var(--ap-line); background: var(--ap-bg); color: var(--ap-ink);
  padding: 0 14px; font: 600 15px var(--ap-font); outline: none;
}
.ap-tracks-search input::placeholder { color: var(--ap-ink-3); }
.ap-tracks-search input:focus { border-color: var(--ap-gold); }

/* صفوف السور (وضع القرآن): عدد الآيات بدل المدة، وعلامة ✓ للمحمَّل للاستماع بدون إنترنت */
.ap-trow .ap-tdur.q { direction: rtl; min-width: 52px; }
.ap-trow.dl .ap-tdur.q::after { content: ' ✓'; color: var(--ap-gold); font-weight: 800; }

/* قائمة اختيار القارئ لازم تظهر فوق المشغّل الموحَّد (كلهم z-index: 200 والأحدث في الـ DOM بيغطّي) */
#reciter-quick-picker-overlay { z-index: 210; }

/* ==========================================================================
   المشغّل المصغّر فوق صفحة القرآن (#surah-audio-bar): بنفس ألوان وطابع وشكل
   المشغّل الكبير (زيتوني + ذهبي، بطاقة فاتحة، خط تجوال، صورة القارئ الدايرية بإطار
   ذهبي، زرار تشغيل زيتوني بحلقة ذهبية، شريط تقدّم زيتوني بمقبض ذهبي).
   الـ HTML وكل الأيدي فضلت زي ما هي — ده تغيير شكل بس
   ========================================================================== */
#surah-audio-bar {
  --ap-card: #FFFFFF;
  --ap-line: rgba(90, 84, 60, .13);
  --ap-ink: #211F1A;
  --ap-ink-2: #5A574D;
  --ap-olive: #6F7752;
  --ap-olive-2: #8A8768;
  --ap-olive-soft: #F0F2E8;
  --ap-gold: #B8892B;
  --ap-gold-soft: rgba(184, 137, 43, .14);
  --ap-font: 'Tajawal', sans-serif;
}
body.theme-night #surah-audio-bar {
  --ap-card: #1C1C1A;
  --ap-line: rgba(255, 255, 255, .09);
  --ap-ink: #EFEDE6;
  --ap-ink-2: #B5B2A6;
  --ap-olive: #98A278;
  --ap-olive-2: #6F7550;
  --ap-olive-soft: #262820;
  --ap-gold: #D6AE55;
  --ap-gold-soft: rgba(214, 174, 85, .16);
}

#surah-audio-bar.gp-bar {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 999px;
  padding: 8px 12px;
  box-shadow: 0 14px 34px rgba(70, 60, 30, .16), 0 1px 2px rgba(70, 60, 30, .06);
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
body.theme-night #surah-audio-bar.gp-bar { box-shadow: 0 14px 34px rgba(0, 0, 0, .5); }
#surah-audio-bar button { font-family: var(--ap-font); }

/* شريط التقدّم: خط زيتوني رفيع بمقبض ذهبي جوه البطاقة (بيتملّي من الشمال زي المشغّل الكبير) */
#surah-audio-bar .gp-progress-track {
  top: 11px; left: 18px; right: 18px; height: 3px;
  border-radius: 3px; overflow: visible;
  background: var(--ap-line);
}
#surah-audio-bar .gp-progress-fill {
  left: 0; right: auto;
  border-radius: 3px;
  background: var(--ap-olive);
}
#surah-audio-bar .gp-progress-fill::after {
  content: ''; position: absolute; right: -7px; top: 50%;
  width: 14px; height: 14px; margin-top: -7px; border-radius: 50%;
  background: var(--ap-gold); border: 2px solid var(--ap-card);
  box-shadow: 0 1px 4px rgba(0, 0, 0, .3);
}
#surah-audio-bar .gp-seek-top {
  top: 2px; left: 8px; right: 8px; height: 22px;
  direction: ltr; /* نفس اتجاه الخط المرسوم (يبدأ من الشمال) */
}

/* صف الرأس: صورة القارئ + اسم السورة والقارئ + زرار فتح المشغّل الكامل */
#surah-audio-bar .gp-progress-track,
#surah-audio-bar .gp-seek-top,
#surah-audio-bar .gp-info-row,
#surah-audio-bar .gp-divider,
#surah-audio-bar .gp-controls { display: none !important; }
#surah-audio-bar .gp-head-row {
  align-items: center;
  gap: clamp(6px, 2vw, 12px);
  margin: 0;
  direction: ltr;
}
.gp-transport-controls { display: flex; flex: 0 0 auto; align-items: center; gap: 4px; }
#surah-audio-bar .gp-head-main {
  direction: rtl;
  align-items: flex-start;
  gap: 1px;
  overflow: hidden;
}
.gp-cover {
  width: 48px; height: 48px; flex-shrink: 0; padding: 0;
  border-radius: 50%; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
  background: var(--ap-card); border: 2px solid var(--ap-gold);
  color: var(--ap-olive); cursor: pointer;
  box-shadow: 0 2px 8px rgba(70, 60, 30, .14);
}
.gp-cover img { width: 100%; height: 100%; object-fit: cover; display: block; }
.gp-cover svg { width: 32px; height: 32px; }
#surah-audio-bar .gp-title {
  width: 100%;
  font-family: var(--ap-font);
  font-weight: 500;
  font-size: 12px;
  line-height: 1.25;
  color: var(--ap-ink-2);
}
#surah-audio-bar .gp-reciter { font-weight: 900; font-size: 16px; line-height: 1.25; color: var(--ap-ink); }
body.theme-night #surah-audio-bar .gp-reciter { color: var(--ap-olive); }
#surah-audio-bar .gp-head-actions { align-items: center; }
#surah-audio-bar .gp-expand-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 24px;
  width: 24px;
  height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ap-olive);
}
#surah-audio-bar .gp-expand-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; }

/* صف التحكّم: زرار تشغيل زيتوني بحلقة ذهبية، وأزرار السابق/التالي دواير بيضا بحد رفيع */
#surah-audio-bar .gp-transport-controls .gp-icon-btn { width: 28px; height: 34px; color: var(--ap-ink); }
#surah-audio-bar .gp-transport-controls .gp-icon-btn svg { width: 20px; height: 20px; }
#surah-audio-bar #surah-audio-jump-end,
#surah-audio-bar #surah-audio-jump-start {
  width: 28px; height: 34px; border-radius: 0;
  border: 0; background: transparent; color: var(--ap-ink);
}
#surah-audio-bar #surah-audio-jump-end svg,
#surah-audio-bar #surah-audio-jump-start svg { width: 18px; height: 18px; fill: currentColor; stroke: none; }
#surah-audio-bar .gp-play-btn {
  width: 48px; height: 48px;
  background: var(--ap-olive); color: #fff;
  border: 3px solid var(--ap-card);
  box-shadow: 0 0 0 1.5px var(--ap-gold);
  filter: none;
}
body.theme-night #surah-audio-bar .gp-play-btn { color: #15160f; }
#surah-audio-bar .gp-play-btn svg { width: 24px; height: 24px; fill: currentColor; stroke: none; }
#surah-audio-bar .gp-play-btn:active { box-shadow: 0 0 0 1.5px var(--ap-gold); filter: none; transform: scale(.94); }
/* حالة التحميل/جاري التشغيل: حلقة ذهبية بتلف حوالين الزرار الدائري (بديل
   الساعة الرملية القديمة) — بتتفعّل بكلاس loading من app.js */
#surah-audio-bar .gp-play-btn { position: relative; overflow: visible; }
#surah-audio-bar .gp-play-btn.loading::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 3px solid color-mix(in srgb, var(--ap-gold) 22%, transparent);
  border-top-color: var(--ap-gold);
  border-right-color: var(--ap-gold);
  animation: gpPlayRingSpin .9s linear infinite;
  pointer-events: none;
}
@keyframes gpPlayRingSpin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  #surah-audio-bar .gp-play-btn.loading::after { animation-duration: 2.4s; }
}
#surah-audio-bar .gp-stop-btn {
  width: 26px; height: 26px;
  background: var(--ruby); color: #fff;
}
#surah-audio-bar .gp-stop-btn svg { width: 11px; height: 11px; fill: currentColor; stroke: none; }
#surah-audio-bar .gp-speed-btn {
  font-family: var(--ap-font); font-size: 13px; font-weight: 800;
  color: var(--ap-olive); background: none;
  border: 1px solid var(--ap-line); padding: 5px 12px;
}
body.theme-night #surah-audio-bar .gp-stop-btn { color: #fff; }

/* ==========================================================================
   شريط تشغيل الابتهالات العائم (#ibtihalat-audio-bar): نفس ألوان وطابع
   المشغّل المصغّر فوق صفحة القرآن (#surah-audio-bar فوق) — بطاقة فاتحة،
   زيتوني + ذهبي، خط تجوال، زرار تشغيل زيتوني بحلقة ذهبية، أزرار تنقّل
   دواير بيضا بحد رفيع، زرار إيقاف زيتوني فاتح. الموضع الثابت/السحب/القفل
   على حافة الشاشة فضل زي ما هو من style.css — ده تغيير الشكل واللون
   والطابع البصري بس، مش السلوك ========================================================================== */
#ibtihalat-audio-bar {
  --ap-card: #FFFFFF;
  --ap-line: rgba(90, 84, 60, .13);
  --ap-ink: #211F1A;
  --ap-ink-2: #5A574D;
  --ap-olive: #6F7752;
  --ap-olive-2: #8A8768;
  --ap-olive-soft: #F0F2E8;
  --ap-gold: #B8892B;
  --ap-gold-soft: rgba(184, 137, 43, .14);
  --ap-font: 'Tajawal', sans-serif;
}
body.theme-night #ibtihalat-audio-bar {
  --ap-card: #1C1C1A;
  --ap-line: rgba(255, 255, 255, .09);
  --ap-ink: #EFEDE6;
  --ap-ink-2: #B5B2A6;
  --ap-olive: #98A278;
  --ap-olive-2: #6F7550;
  --ap-olive-soft: #262820;
  --ap-gold: #D6AE55;
  --ap-gold-soft: rgba(214, 174, 85, .16);
}

/* بطاقة الشريط نفسها: أبيض/كارت داكن بدل الخلفية المحايدة، حد وظل ذهبيّ
   الطابع بدل الظل العام، وخط تجوال بدل الخط الافتراضي */
#ibtihalat-audio-bar.gp-bar {
  border: 1px solid var(--ap-line);
  border-radius: 26px;
  background: var(--ap-card);
  box-shadow: 0 14px 34px rgba(70, 60, 30, .16), 0 1px 2px rgba(70, 60, 30, .06);
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
body.theme-night #ibtihalat-audio-bar.gp-bar {
  box-shadow: 0 14px 34px rgba(0, 0, 0, .5);
}
#ibtihalat-audio-bar button { font-family: var(--ap-font); }

/* زرار إخفاء المشغّل: دايرة زيتونية فاتحة بدل الرمادي المحايد */
#ibtihalat-audio-bar .ibtihalat-audio-hide-btn {
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
}

/* عنوان الابتهال واسم المبتهل وعداد الوقت المتبقي */
#ibtihalat-audio-bar .gp-title {
  font-family: var(--ap-font);
  font-weight: 900;
  font-size: 15.5px;
  color: var(--ap-ink);
}
#ibtihalat-audio-bar .gp-reciter {
  font-weight: 700;
  font-size: 12.5px;
  color: var(--ap-olive);
}
body.theme-night #ibtihalat-audio-bar .gp-reciter { color: var(--ap-olive); }
#ibtihalat-audio-bar .ibtihalat-audio-time-remaining {
  font-family: var(--ap-font);
  color: var(--ap-olive-2);
}

/* صف التحكّم: زرار تشغيل زيتوني بحلقة ذهبية زي المشغّل الكبير/المصغّر،
   وزرارَي تالي/سابق دواير بيضا بحد رفيع، وزرار إيقاف زيتوني فاتح */
#ibtihalat-audio-bar .gp-play-btn {
  background: var(--ap-olive);
  color: #fff;
  border: 3px solid var(--ap-card);
  box-shadow: 0 0 0 1.5px var(--ap-gold);
  filter: none;
}
body.theme-night #ibtihalat-audio-bar .gp-play-btn { color: #15160f; }
#ibtihalat-audio-bar .gp-play-btn svg { fill: currentColor; stroke: none; }
#ibtihalat-audio-bar .gp-play-btn:active {
  box-shadow: 0 0 0 1.5px var(--ap-gold);
  filter: none;
  transform: scale(.94);
}

#ibtihalat-audio-bar .gp-icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--ap-line);
  background: var(--ap-card);
  color: var(--ap-ink);
}
#ibtihalat-audio-bar .gp-icon-btn svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
  stroke: none;
}

#ibtihalat-audio-bar .gp-stop-btn {
  background: var(--ap-olive-soft);
  color: var(--ruby);
}
body.theme-night #ibtihalat-audio-bar .gp-stop-btn { color: #E3818E; }
#ibtihalat-audio-bar .gp-stop-btn svg { fill: currentColor; stroke: none; }

/* ==========================================================================
   صفحة "اختر القارئ" (#reciter-quick-picker-overlay): تُفتح بالضغط على اسم
   القارئ في شريط تلاوة السورة المصغّر فوق صفحة القرآن. كانت بشكل الصفحات
   القديم (خط زخرفي + أخضر)، دلوقتي بنفس هوية الصوتيات الجديدة: خلفية فاتحة
   دافية، بطاقات بيضا، زيتوني + ذهبي، وخط تجوال في كل حاجة
   ========================================================================== */
#reciter-quick-picker-overlay {
  --ap-bg: #FFFFFF;
  --ap-card: #FFFFFF;
  --ap-line: rgba(90, 84, 60, .11);
  --ap-ink: #211F1A;
  --ap-ink-2: #5A574D;
  --ap-ink-3: #8E8A7D;
  --ap-olive: #6F7752;
  --ap-olive-2: #8A8768;
  --ap-olive-soft: #F0F2E8;
  --ap-gold: #B8892B;
  --ap-gold-soft: rgba(184, 137, 43, .14);
  --ap-shadow: 0 8px 26px rgba(70, 60, 30, .07), 0 1px 2px rgba(70, 60, 30, .05);
  --ap-font: 'Tajawal', sans-serif;
}
body.theme-night #reciter-quick-picker-overlay {
  --ap-bg: #121211;
  --ap-card: #1C1C1A;
  --ap-line: rgba(255, 255, 255, .08);
  --ap-ink: #EFEDE6;
  --ap-ink-2: #B5B2A6;
  --ap-ink-3: #85826F;
  --ap-olive: #98A278;
  --ap-olive-2: #6F7550;
  --ap-olive-soft: #262820;
  --ap-gold: #D6AE55;
  --ap-gold-soft: rgba(214, 174, 85, .16);
  --ap-shadow: 0 8px 26px rgba(0, 0, 0, .4);
}

#reciter-quick-picker-overlay.overlay.overlay-fullpage {
  background: var(--ap-bg);
}
#reciter-quick-picker-overlay .overlay-sheet {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#reciter-quick-picker-overlay button { font-family: var(--ap-font); }

/* رأس الصفحة: زرار إغلاق دائري بسيط + عنوان بخط تجوال بدل الخط الزخرفي والأخضر */
#reciter-quick-picker-overlay .overlay-head h3 {
  font-family: var(--ap-font);
  font-weight: 900;
  font-size: 20px;
  color: var(--ap-ink);
}
#reciter-quick-picker-overlay .icon-btn {
  color: var(--ap-ink);
  background: var(--ap-olive-soft);
}
#reciter-quick-picker-overlay .icon-btn:hover,
#reciter-quick-picker-overlay .icon-btn:active {
  background: var(--ap-olive-soft);
}

/* حقل البحث: نفس شكل حقل البحث في صفحات الصوتيات الجديدة */
#reciter-quick-picker-overlay .rqp-search-input {
  border: 1px solid var(--ap-line);
  background: var(--ap-card);
  color: var(--ap-ink);
  font-family: var(--ap-font);
  box-shadow: var(--ap-shadow);
}
body.theme-night #reciter-quick-picker-overlay .rqp-search-input { background: var(--ap-card); }
#reciter-quick-picker-overlay .rqp-search-input::placeholder { color: var(--ap-ink-3); }
#reciter-quick-picker-overlay .rqp-search-icon,
body.theme-night #reciter-quick-picker-overlay .rqp-search-icon {
  color: var(--ap-gold);
}

/* صفوف القرّاء: بطاقات بيضا بحد رفيع بدل الخلفية الرمادية المسطّحة القديمة،
   وصورة/أيقونة دائرية بخلفية زيتونية فاتحة زي باقي دواير الصوتيات الجديدة */
#reciter-quick-picker-overlay .reciter-quick-picker-list {
  gap: 8px;
}
#reciter-quick-picker-overlay .reciter-quick-picker-item {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  box-shadow: var(--ap-shadow);
  font-family: var(--ap-font);
}
#reciter-quick-picker-overlay .reciter-quick-picker-item.active {
  border-color: var(--ap-gold);
  background: var(--ap-gold-soft);
}
#reciter-quick-picker-overlay .reciter-quick-picker-item-icon {
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
}
#reciter-quick-picker-overlay .reciter-quick-picker-item-name {
  font-family: var(--ap-font);
  font-weight: 800;
  font-size: 14.5px;
  color: var(--ap-ink);
}
#reciter-quick-picker-overlay .reciter-quick-picker-arrow {
  color: var(--ap-ink-3);
}
#reciter-quick-picker-overlay .reciter-quick-picker-check {
  background: var(--ap-gold);
  color: #fff;
}
body.theme-night #reciter-quick-picker-overlay .reciter-quick-picker-check { color: #15160f; }

/* ==========================================================================
   محرِّر قائمة التشغيل (#playlist-editor-overlay): صفحة "قائمة جديدة" اللي
   بتفتح بالضغط على "أضف" في المكتبة السمعية. كانت بألوان الذهبي/الكريمي
   القديمة، دلوقتي بنفس هوية تصميم الصوتيات الجديدة — زيتوني + ذهبي، بطاقات
   بيضا، وخط تجوال في كل حاجة
   ========================================================================== */
#playlist-editor-overlay {
  --ap-bg: #FFFFFF;
  --ap-card: #FFFFFF;
  --ap-line: rgba(90, 84, 60, .11);
  --ap-ink: #211F1A;
  --ap-ink-2: #5A574D;
  --ap-ink-3: #8E8A7D;
  --ap-olive: #6F7752;
  --ap-olive-2: #8A8768;
  --ap-olive-soft: #F0F2E8;
  --ap-gold: #B8892B;
  --ap-gold-soft: rgba(184, 137, 43, .14);
  --ap-shadow: 0 8px 26px rgba(70, 60, 30, .07), 0 1px 2px rgba(70, 60, 30, .05);
  --ap-font: 'Tajawal', sans-serif;
}
body.theme-night #playlist-editor-overlay {
  --ap-bg: #121211;
  --ap-card: #1C1C1A;
  --ap-line: rgba(255, 255, 255, .08);
  --ap-ink: #EFEDE6;
  --ap-ink-2: #B5B2A6;
  --ap-ink-3: #85826F;
  --ap-olive: #98A278;
  --ap-olive-2: #6F7550;
  --ap-olive-soft: #262820;
  --ap-gold: #D6AE55;
  --ap-gold-soft: rgba(214, 174, 85, .16);
  --ap-shadow: 0 8px 26px rgba(0, 0, 0, .4);
}

#playlist-editor-overlay.overlay.overlay-fullpage { background: var(--ap-bg); }
#playlist-editor-overlay .overlay-sheet { font-family: var(--ap-font); color: var(--ap-ink); }
#playlist-editor-overlay button,
#playlist-editor-overlay input { font-family: var(--ap-font); }

/* الرأس: عنوان "قائمة جديدة" بخط تجوال، زرار حفظ زيتوني معبّأ، زرار إغلاق دائري */
#playlist-editor-overlay .playlist-editor-head-v2 h3 {
  font-family: var(--ap-font);
  font-weight: 900;
  color: var(--ap-ink);
}
#playlist-editor-overlay .playlist-editor-save-btn {
  background: var(--ap-olive);
  color: #fff;
  font-family: var(--ap-font);
}
body.theme-night #playlist-editor-overlay .playlist-editor-save-btn { color: #15160F; }
#playlist-editor-overlay .icon-btn {
  color: var(--ap-ink);
  background: var(--ap-olive-soft);
}

/* اسم القائمة وصورة الغلاف المصغّرة جنبه */
#playlist-editor-overlay .playlist-name-input {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  color: var(--ap-ink);
  font-family: var(--ap-font);
}
#playlist-editor-overlay .playlist-name-input::placeholder { color: var(--ap-ink-3); }
#playlist-editor-overlay .playlist-name-input:focus { border-color: var(--ap-gold); }
#playlist-editor-overlay .playlist-cover-preview {
  background: var(--ap-gold-soft);
  border: 1.5px solid var(--ap-gold);
  color: var(--ap-gold);
}

/* عنوان "الغلاف" وشريط اختيار الأيقونات */
#playlist-editor-overlay .playlist-cover-title {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#playlist-editor-overlay .playlist-cover-choice {
  background: var(--ap-card);
  border: 1.5px solid var(--ap-line);
  color: var(--ap-olive);
}
#playlist-editor-overlay .playlist-cover-choice.active {
  border-color: var(--ap-gold);
  background: var(--ap-gold-soft);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ap-gold) 30%, transparent);
  color: var(--ap-gold);
}

/* كبسولات الإحصائيات (القراء/الآيات/السور) */
#playlist-editor-overlay .playlist-editor-stat-pill {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  color: var(--ap-ink-2);
  font-family: var(--ap-font);
}
#playlist-editor-overlay .playlist-editor-stat-pill b { color: var(--ap-gold); }

/* زرارَي "إضافة سور كاملة" (مفرّغ) و"إضافة مقطع" (معبّأ) */
#playlist-editor-overlay .playlist-editor-add-btn {
  font-family: var(--ap-font);
}
#playlist-editor-overlay .playlist-editor-add-btn-outline {
  background: var(--ap-card);
  color: var(--ap-ink);
  border: 1.3px solid var(--ap-line);
}
#playlist-editor-overlay .playlist-editor-add-btn-filled {
  background: var(--ap-olive);
  color: #fff;
}
body.theme-night #playlist-editor-overlay .playlist-editor-add-btn-filled { color: #15160F; }

/* عناصر القائمة المُضافة: كارت أبيض بحد رفيع، دايرة الترقيم زيتونية فاتحة */
#playlist-editor-overlay .playlist-editor-item {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
}
#playlist-editor-overlay .playlist-editor-item-num {
  background: var(--ap-olive-soft);
  color: var(--ap-olive);
}
#playlist-editor-overlay .playlist-editor-item-name {
  font-family: var(--ap-font);
  color: var(--ap-ink);
}
#playlist-editor-overlay .playlist-editor-item-sub { color: var(--ap-ink-2); }
#playlist-editor-overlay .playlist-editor-item-remove { color: var(--ap-ink-3); }

/* صندوق الحالة الفاضية ("أضف مقطعًا من الآيات...") */
#playlist-editor-overlay .playlist-editor-empty-box {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  color: var(--ap-ink-2);
  font-family: var(--ap-font);
}

/* =========================================================================
   صفحة "التفسير" — بنفس روح صفحة الصوتيات: خلفية دافئة (نهاري/ليلي)، هيرو
   بعنوان كبير ورسمة المصحف، كبسولة اختيار النوع بشكل تبويبات الصوتيات،
   وكل آية في بطاقة بيضا مدوّرة (ap-card) بلمسات زيتونية/ذهبية.
   الألوان كلها من متغيّرات --ap-* اللي فوق (شوف قايمة #page-tafsir-overlay)
   ========================================================================= */
#page-tafsir-overlay .tf-sheet { background: transparent; position: relative; }

/* شريط الإغلاق: عايم فوق الهيرو، وشفاف تمامًا */
#page-tafsir-overlay .fullpage-shell > .overlay-head.tf-topbar {
  position: absolute;
  top: 0; inset-inline: 0;
  z-index: 6;
  justify-content: flex-end;
  padding: calc(12px + env(safe-area-inset-top)) 16px 0;
  border-bottom: none;
  background: transparent;
}
#page-tafsir-overlay .tf-close {
  width: 42px; height: 42px;
  border-radius: 50%;
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  box-shadow: var(--ap-shadow);
  color: var(--ap-ink);
}
#page-tafsir-overlay .tf-close svg { width: 20px; height: 20px; }

#page-tafsir-overlay .fullpage-shell > .fullpage-scroll { padding: 0 16px 24px; }
#page-tafsir-overlay .tf-hero { min-height: 196px; }

/* =========================================================================
   صفحة "الأربعون النووية" — نفس هيرو صفحة الصوتيات بالظبط (ap-hero)، بس
   بدل رسمة المصحف: صورة قبة المسجد النبوي الشريف والمئذنة تحت هلال رمضان.
   الألوان كلها من متغيّرات --ap-* (نفس قايمة #nawawi-overlay اللي فوق)
   ========================================================================= */
#nawawi-overlay .nawawi-sheet,
#sunnah-books-overlay .nawawi-sheet,
#explore-category-overlay .nawawi-sheet { background: transparent; position: relative; }

/* شريط الإغلاق: عايم فوق الهيرو، وشفاف تمامًا — بيفضل موجود عشان مقبض سحب
   الصفحة لتحت للإغلاق (initDragToClose)
   نفس الإصلاح مطبّق على #sunnah-books-overlay (شاشة "كتب السنة" الرئيسية)
   لأنها بتستخدم نفس كلاسات nawawi-topbar/nawawi-close/nawawi-hero بالظبط،
   وكانت من غير السكوب ده بتاخد شريط .overlay-head الافتراضي (بادينج +
   بوردر) فبيظهر فراغ كبير فاضي فوق الصفحة قبل الهيرو، بنفس المشكلة اللي
   كانت في #view-hadith وتصلّحت هناك */
#nawawi-overlay .fullpage-shell > .overlay-head.nawawi-topbar,
#sunnah-books-overlay .fullpage-shell > .overlay-head.nawawi-topbar,
#tafsir-books-overlay .fullpage-shell > .overlay-head.nawawi-topbar,
#explore-category-overlay .fullpage-shell > .overlay-head.nawawi-topbar {
  position: absolute;
  top: 0; inset-inline: 0;
  z-index: 6;
  justify-content: flex-end;
  padding: calc(12px + env(safe-area-inset-top)) 16px 0;
  border-bottom: none;
  background: transparent;
}
#nawawi-overlay .nawawi-close,
#sunnah-books-overlay .nawawi-close,
#tafsir-books-overlay .nawawi-close,
#explore-category-overlay .nawawi-close {
  width: 42px; height: 42px;
  border-radius: 50%;
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  box-shadow: var(--ap-shadow);
  color: var(--ap-ink);
}
#nawawi-overlay .nawawi-close svg,
#sunnah-books-overlay .nawawi-close svg,
#tafsir-books-overlay .nawawi-close svg,
#explore-category-overlay .nawawi-close svg { width: 20px; height: 20px; }

#nawawi-overlay .fullpage-shell > .fullpage-scroll,
#sunnah-books-overlay .fullpage-shell > .fullpage-scroll,
#tafsir-books-overlay .fullpage-shell > .fullpage-scroll,
#explore-category-overlay .fullpage-shell > .fullpage-scroll { padding: 0 16px 24px; }
#nawawi-overlay .nawawi-hero,
#sunnah-books-overlay .nawawi-hero,
#tafsir-books-overlay .nawawi-hero,
#explore-category-overlay .nawawi-hero { min-height: 196px; }
#explore-category-overlay.sunnah-dashboard-open .nawawi-hero {
  min-height: 168px;
  margin-bottom: 0;
}

/* =========================================================================
   صفحة عنصر قسم واحد من "استكشف الأشرف" (explore-category-overlay):
   نفس هيرو الأربعون النووية/كتب السنة بالظبط، بس بدل صورة فوتوغرافية
   بأيقونة القسم نفسها مكبّرة وشفافة (مفيش صورة مخصّصة لكل قسم)، وقائمة
   العناصر تحتها بشكل صفوف بطاقات (settings-card) بدل شبكة الأيقونات
   القديمة — تلوين موحّد ذهبي/زيتوني زي باقي صفحات الصوتيات تمامًا
   ========================================================================= */
#explore-category-overlay .ap-hero-art.explore-cat-hero-art {
  background: none;
  -webkit-mask-image: none;
  mask-image: none;
  width: 100%;
  max-width: none;
  inset-inline-end: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
}
#explore-category-overlay .explore-cat-hero-icon {
  width: 118px; height: 118px;
  margin-top: 18px;
  color: var(--ap-olive);
  opacity: .16;
  fill: none;
  stroke: currentColor;
}
body.theme-night #explore-category-overlay .ap-hero-art { filter: none; opacity: 1; }
body.theme-night #explore-category-overlay .explore-cat-hero-icon { opacity: .2; }
#explore-category-overlay .ap-hero-text { max-width: 100%; position: relative; z-index: 2; }

/* قائمة عناصر القسم: صفوف بطاقات بدل شبكة الأيقونات المربّعة القديمة —
   الشبكة (.nav-grid) والأزرار (.nav-item) هي نفس العناصر الأصلية المنقولة
   من المخزن المخفي #explore-tpl-stash (مش نسخة جديدة)، فأحداث الضغط
   (data-tab/data-action) بتفضل شغالة زي ما هي من غير أي تعديل في app.js */
#explore-category-content .nav-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 4px;
}
#explore-category-content .nav-item {
  width: 100%;
  display: flex;
  /* لازم نفرض row هنا صراحةً، لأن .nav-item الأساسي (بتاع شبكة الأيقونات
     المدمجة) بيحط flex-direction: column افتراضيًا، وده كان بيتسرّب هنا
     من غير قصد (السطر ده مكنش موجود) فيخلي كل كارت يرتّب عنوانه ووصفه في
     مكان مختلف حسب طول النص بدل صف واحد ثابت */
  flex-direction: row;
  /* flex-start (مش center) عشان الأيقونة تفضل ثابتة على أقصى يمين الكارت
     دايمًا، والعنوان يمتد جنبها، بدل ما الكتلة كلها (أيقونة+عنوان) تتوسّط
     أفقيًا وتتحرّك مكانها حسب طول النص المكتوب جوه كل كارت */
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 14px 16px;
  border-radius: 20px;
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  box-shadow: var(--ap-shadow);
  text-align: start;
  color: inherit;
  overflow: visible;
}
#explore-category-content .nav-item:active {
  transform: scale(.985);
  background: var(--ap-olive-soft);
}
#explore-category-content .nav-item::after { display: none; }
#explore-category-content .settings-card-label { flex: 1 1 auto; min-width: 0; }
#explore-category-content .settings-card-text { flex: 1 1 auto; min-width: 0; }
#explore-category-content .settings-card-icon {
  width: 46px; height: 46px;
  border-radius: 15px;
  background: var(--ap-olive-soft) !important;
  color: var(--ap-olive) !important;
}
#explore-category-content .settings-card-icon svg { width: 22px; height: 22px; }
#explore-category-content .settings-card-icon img { width: 26px; height: 26px; }
#explore-category-content .settings-card-title {
  font-family: var(--ap-font);
  font-size: 15px;
  font-weight: 800;
  color: var(--ap-ink);
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  -webkit-line-clamp: initial;
  display: block;
}
#explore-category-content .settings-card-sub {
  font-family: var(--ap-font);
  font-size: 12px;
  color: var(--ap-ink-2);
  line-height: 1.5;
}
#explore-category-content .acc-chevron { display: none; }

/* صفّ المسبحة + أدعية الأحبة أعلى صفحة "الأذكار والأدعية": كارت كل واحدة
   ياخد 50% من عرض الصفحة جنب التانية، بدل صفّ مستقل كامل العرض زي باقي
   عناصر القسم — شوف data-cat="azkar_duas" في explore-tpl-stash */
#explore-category-content .explore-duo-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 4px;
}
#explore-category-content .explore-duo-row .nav-item {
  padding: 14px 10px;
  /* الكارتين دول شكلهم مربّع (أيقونة فوق، اسم تحتها، الاتنين في النص)،
     فبنرجّع flex-direction:column وalign-items:center هنا تحديدًا عشان
     الـ row المفروضة فوق لباقي كروت القسم ميأثرش عليهم */
  flex-direction: column;
  align-items: center;
}
#explore-category-content .explore-duo-row .settings-card-label { flex-direction: column; text-align: center; gap: 6px; }
#explore-category-content .explore-duo-row .settings-card-text { align-items: center; }
#explore-category-content .explore-duo-row .settings-card-title { font-size: 13.5px; }
#explore-category-content .explore-duo-row .settings-card-sub { text-align: center; }
#explore-category-content .explore-duo-row .acc-chevron { display: none; }

/* تابّات "الأذكار / الأدعية" أعلى قائمة عناصرهم — نفس شكل segmented-control
   العام لكن بتلوين ap-* الموحّد لصفحات الصوتيات/استكشف الأشرف */
#explore-category-content .explore-azkar-duas-tabs {
  background: var(--ap-card);
  border-color: var(--ap-line);
  margin: 2px 0 4px;
}
#explore-category-content .explore-azkar-duas-tabs .segmented-btn {
  flex: 1;
  text-align: center;
  color: var(--ap-ink-2);
}
#explore-category-content .explore-azkar-duas-tabs .segmented-btn.active {
  background: var(--ap-olive);
  color: #fff;
  box-shadow: none;
}

/* لوحة السنة: حديث اليوم في المقدمة، ثم مجموعات واضحة بدل قائمة طويلة */
#explore-category-content .nav-grid[data-sunnah-dashboard="true"] {
  display: flex;
  flex-direction: column;
  gap: 22px;
}
#explore-category-content .sunnah-home-hadith { margin: 2px 0 4px; }
#explore-category-content .sunnah-hub-group { min-width: 0; }
#explore-category-content .sunnah-hub-heading { margin: 0 2px 11px; }
#explore-category-content .sunnah-hub-heading h2 {
  margin: 0;
  color: var(--ap-ink);
  font: 800 19px/1.5 var(--ap-font);
}
#explore-category-content .sunnah-hub-heading p {
  margin: 2px 0 0;
  color: var(--ap-ink-2);
  font: 500 12px/1.7 var(--ap-font);
}
#explore-category-content .sunnah-hub-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
#explore-category-content .sunnah-hub-grid > .nav-item {
  box-sizing: border-box;
  min-width: 0;
  min-height: 132px;
  height: auto;
  padding: 14px 12px;
  flex-direction: column;
  justify-content: flex-start;
  gap: 11px;
  border-radius: 20px;
  text-align: start;
}
#explore-category-content .sunnah-hub-grid .settings-card-label {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  width: 100%;
}
#explore-category-content .sunnah-hub-grid .settings-card-icon { width: 40px; height: 40px; border-radius: 14px; }
#explore-category-content .sunnah-hub-grid .settings-card-text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  min-width: 0;
  overflow: visible;
  -webkit-line-clamp: unset;
  line-clamp: none;
}
#explore-category-content .sunnah-hub-grid .settings-card-title,
#explore-category-content .sunnah-hub-grid .settings-card-sub {
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
}
