}
#permissions-overlay .permissions-primary-btn {
  width: 100%;
  height: 54px;
  border: none;
  border-radius: 999px;
  background: var(--ap-olive);
  color: #fff;
  font-family: var(--ap-font);
  font-size: 16px;
  font-weight: 800;
  box-shadow: none;
  transition: transform .16s ease, opacity .16s ease;
}
body.theme-night #permissions-overlay .permissions-primary-btn { color: #15160f; }
#permissions-overlay .permissions-primary-btn:active { transform: scale(.97); }
#permissions-overlay .permissions-primary-btn:disabled { opacity: .6; }
#permissions-overlay .permissions-skip-btn {
  width: 100%;
  height: 44px;
  border: none;
  background: none;
  color: var(--ap-ink-2);
  font-family: var(--ap-font);
  font-size: 14px;
  font-weight: 700;
}

/* =========================================================================
   معالج الإعداد الأول متعدد الخطوات (location / calc / madhab / notif /
   battery) — يعيد استخدام نفس متغيّرات --ap-* وكلاسات ap-card الموجودة
   ========================================================================= */
#permissions-overlay .onb-progress { padding: 14px 4px 2px; }
#permissions-overlay .onb-progress-label {
  display: block; margin: 0 0 8px; font-family: var(--ap-font);
  font-size: 13px; font-weight: 700; color: var(--ap-ink-2);
}
#permissions-overlay .onb-progress-bar {
  height: 5px; border-radius: 999px; background: var(--ap-olive-soft); overflow: hidden;
}
#permissions-overlay .onb-progress-fill {
  height: 100%; background: var(--ap-olive); border-radius: 999px;
  transition: width .25s ease;
}

#permissions-overlay .onb-step-head { text-align: center; padding: 8px 6px 18px; }
#permissions-overlay .onb-step-icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 52px; height: 52px; margin: 0 auto 10px;
  border-radius: 50%; background: var(--ap-olive-soft); color: var(--ap-gold);
  font-size: 22px; font-weight: 800;
}
#permissions-overlay .onb-step-icon svg { width: 24px; height: 24px; fill: none; stroke: currentColor; }
#permissions-overlay .onb-step-title {
  font-family: var(--ap-font); font-size: 18px; font-weight: 800; color: var(--ap-ink); margin: 0 0 6px;
}
#permissions-overlay .onb-step-sub {
  font-family: var(--ap-font); font-size: 13.5px; color: var(--ap-ink-2); margin: 0; line-height: 1.7;
}

#permissions-overlay .onb-location-card,
#permissions-overlay .onb-madhab-card,
#permissions-overlay .onb-permit-card { padding: 16px; }

#permissions-overlay .onb-permit-card { text-align: center; }
#permissions-overlay .onb-permit-status {
  font-family: var(--ap-font); font-size: 14.5px; font-weight: 700;
  color: var(--ap-ink-2); margin: 0 0 14px;
}
#permissions-overlay .onb-permit-status.is-granted { color: #2e7d32; }
#permissions-overlay .onb-permit-btn {
  width: 100%; height: 50px; border: none; border-radius: 999px;
  background: var(--ap-olive); color: #fff;
  font-family: var(--ap-font); font-size: 15px; font-weight: 800;
}
#permissions-overlay .onb-permit-btn:disabled { opacity: .6; }
body.theme-night #permissions-overlay .onb-permit-btn { color: #15160f; }

#permissions-overlay .onb-nav-row { display: flex; gap: 10px; }
#permissions-overlay .onb-nav-row .permissions-primary-btn { flex: 1; }
#permissions-overlay .onb-back-btn {
  flex: 0 0 96px; height: 54px; border-radius: 999px;
  border: 1px solid var(--ap-line); background: transparent; color: var(--ap-ink);
  font-family: var(--ap-font); font-size: 15px; font-weight: 800;
}

/* شاشة تحديد الموقع في الإعداد الأول: أبيض وزيتوني، مع زر GPS واضح ودبوس مجوّف. */
#permissions-overlay.is-location-step {
  --ap-bg: #fff;
  --ap-card: #fff;
  --ap-line: rgba(95, 112, 69, .18);
  --ap-ink: #25271f;
  --ap-ink-2: #68705d;
  --ap-ink-3: #8c9184;
  --ap-olive: #6f7752;
  --ap-olive-soft: #f0f2e9;
  background: #fff;
}
#permissions-overlay.is-location-step .permissions-sheet,
#permissions-overlay.is-location-step .permissions-scroll,
#permissions-overlay.is-location-step .permissions-footer { background: var(--ap-bg); }
#permissions-overlay.is-location-step .onb-step-icon { color: var(--ap-olive); border: 1px solid var(--ap-line); }
#permissions-overlay.is-location-step .onb-step-title { font-size: 20px; }
#permissions-overlay.is-location-step .onb-step-sub { font-size: 14px; }
#permissions-overlay.is-location-step .onb-location-card { border: 1px solid var(--ap-line); background: var(--ap-card); box-shadow: var(--ap-shadow); }
#permissions-overlay.is-location-step .city-gps-btn {
  min-height: 56px; justify-content: flex-start; gap: 12px; margin: 0; padding: 9px 12px;
  border: 1px solid var(--ap-line); border-radius: 16px; background: var(--ap-card); color: var(--ap-olive);
  font: 700 15px/1.4 var(--ap-font); box-shadow: 0 5px 16px rgba(58, 72, 40, .07);
}
#permissions-overlay.is-location-step .city-gps-btn:active { background: var(--ap-olive-soft); }
#permissions-overlay.is-location-step .city-gps-btn:disabled { opacity: .7; }
#permissions-overlay.is-location-step .city-gps-icon {
  display: grid; place-items: center; width: 38px; height: 38px; flex: 0 0 38px;
  border: 1px solid var(--ap-line); border-radius: 12px; background: var(--ap-olive-soft); color: var(--ap-olive);
}
#permissions-overlay.is-location-step .city-gps-icon svg,
#permissions-overlay.is-location-step .city-gps-icon svg path,
#permissions-overlay.is-location-step .city-gps-icon svg circle { fill: none !important; stroke: currentColor; }
#permissions-overlay.is-location-step .city-search-divider { color: var(--ap-ink-3); font: 600 13px/1.4 var(--ap-font); }
#permissions-overlay.is-location-step .city-search-divider::before,
#permissions-overlay.is-location-step .city-search-divider::after { background: var(--ap-line); }
#permissions-overlay.is-location-step .city-search-input {
  min-width: 0; border-color: var(--ap-line); border-radius: 14px; background: var(--ap-card); color: var(--ap-ink);
  font: 500 15px/1.4 var(--ap-font);
}
#permissions-overlay.is-location-step .city-search-input:focus { border-color: var(--ap-olive); box-shadow: 0 0 0 3px rgba(111, 119, 82, .12); }
#permissions-overlay.is-location-step .city-search-btn { width: 48px; border-radius: 14px; background: var(--ap-olive); color: #fff; }
#permissions-overlay.is-location-step .city-result-item { border: 1px solid var(--ap-line); background: var(--ap-card); color: var(--ap-ink); font: 500 14px/1.55 var(--ap-font); }
#permissions-overlay.is-location-step .city-result-item:active { background: var(--ap-olive-soft); }
.onb-location-confirmation {
  display: flex; align-items: flex-start; justify-content: center; gap: 7px; margin: 12px auto 0;
  padding: 9px 12px; width: fit-content; max-width: 100%; border: 1px solid var(--ap-line);
  border-radius: 13px; background: var(--ap-olive-soft); color: var(--ap-ink-2);
  font: 600 12px/1.6 var(--ap-font); text-align: start;
}
.onb-location-confirmation svg { width: 17px; height: 17px; flex: 0 0 17px; margin-top: 1px; fill: none; stroke: var(--ap-olive); color: var(--ap-olive); }
.onb-location-confirmation svg path,
.onb-location-confirmation svg circle { fill: none; stroke: currentColor; }

/* =========================================================================
   حاجز تحميل صفحات المصحف (أول تشغيل بعد التثبيت) — نفس طابع صفحة الصوتيات
   وشاشة الأذونات: خلفية دافئة (نهاري/ليلي) من متغيّرات --ap-* (شوف قايمة
   #quran-offline-gate أول الملف)، هيرو بعنوان كبير ورسمة المصحف، بطاقة
   مدوّرة، وزر زيتوني عريض على شكل كبسولة
   ========================================================================= */
#quran-offline-gate {
  position: fixed;
  inset: 0;
  z-index: 1000;
  transition: opacity .4s ease;
}
#quran-offline-gate.fade-out { opacity: 0; pointer-events: none; }
#quran-offline-gate .gate-shell {
  height: 100%;
  display: flex;
  flex-direction: column;
}
#quran-offline-gate .gate-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 0 16px 20px;
}
#quran-offline-gate .gate-hero { min-height: 210px; }

#quran-offline-gate .gate-card { padding: 18px 16px 16px; }
#quran-offline-gate .gate-edition-fieldset { min-width: 0; margin: 20px 0 4px; padding: 0; border: 0; }
#quran-offline-gate .gate-edition-fieldset legend { margin-bottom: 10px; color: var(--ap-ink); font-size: 15px; font-weight: 800; }
#quran-offline-gate .gate-edition-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
#quran-offline-gate .gate-edition-option { position: relative; display: flex; align-items: center; gap: 9px; min-height: 54px; padding: 9px 11px; border: 1px solid var(--ap-line); border-radius: 14px; background: var(--ap-bg); color: var(--ap-ink); cursor: pointer; transition: border-color .16s, background .16s, box-shadow .16s; }
#quran-offline-gate .gate-edition-option:has(input:checked) { border-color: var(--ap-olive); background: var(--ap-olive-soft); box-shadow: 0 0 0 1px var(--ap-olive); }
#quran-offline-gate .gate-edition-option input { width: 17px; height: 17px; flex: 0 0 auto; accent-color: var(--ap-olive); }
#quran-offline-gate .gate-edition-option span { min-width: 0; font-size: 12px; font-weight: 700; line-height: 1.45; }
#quran-offline-gate .gate-edition-option small { display: block; color: var(--ap-ink-3); font-size: 10px; font-weight: 500; }
#quran-offline-gate .gate-card-head {
  display: flex; align-items: center; gap: 14px;
  margin: 0 2px 14px;
}
#quran-offline-gate .gate-card-icon {
  flex-shrink: 0;
  width: 48px; height: 48px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: var(--ap-olive-soft);
  color: var(--ap-gold);
}
#quran-offline-gate .gate-card-icon svg { width: 22px; height: 22px; fill: none; stroke: currentColor; }
#quran-offline-gate .gate-card-copy { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
#quran-offline-gate .gate-card-copy strong {
  font-family: var(--ap-font);
  font-size: 16px;
  font-weight: 800;
  color: var(--ap-ink);
}
#quran-offline-gate .gate-card-copy small {
  font-family: var(--ap-font);
  font-size: 13px;
  line-height: 1.7;
  color: var(--ap-ink-2);
}
#quran-offline-gate .gate-sub {
  margin: 0 2px;
  padding-top: 14px;
  border-top: 1px solid var(--ap-line);
  font-family: var(--ap-font);
  font-size: 14px;
  line-height: 1.85;
  color: var(--ap-ink-2);
}

/* شريط التقدّم: مسار زيتوني فاتح وتعبئة زيتونية (بدل ذهبي/أبيض الحاجز القديم) */
#quran-offline-gate .dl-progress-wrap { width: 100%; padding: 16px 2px 0; }
#quran-offline-gate .dl-progress-bar { height: 10px; background: var(--ap-olive-soft); }
#quran-offline-gate .dl-progress-fill { background: var(--ap-olive); }
#quran-offline-gate .dl-progress-bar.indeterminate .dl-progress-fill { background-color: var(--ap-olive); }
#quran-offline-gate .dl-progress-text {
  margin-top: 10px;
  font-family: var(--ap-font);
  font-size: 15px;
  font-weight: 800;
  color: var(--ap-ink);
}
#quran-offline-gate .dl-cancel-btn {
  height: 46px;
  padding: 0 14px;
  margin-top: 14px;
  border-radius: 999px;
  background: var(--ap-olive-soft);
  border: 1px solid var(--ap-line);
  color: var(--ap-ink-2);
  font-family: var(--ap-font);
  font-size: 14px;
  font-weight: 700;
}
#quran-offline-gate .dl-cancel-btn:active { background: var(--ap-hl); }

#quran-offline-gate .gate-footer {
  flex: 0 0 auto;
  padding: 12px 16px calc(14px + env(safe-area-inset-bottom));
  background: var(--ap-bg);
  border-top: 1px solid var(--ap-line);
}
/* أثناء التحميل زر "تحميل" بيتخفي — نخفي الفوتر كله عشان مايفضلش شريط فاضي */
#quran-offline-gate .gate-footer:has(> .gate-primary-btn.hidden) { display: none; }
#quran-offline-gate .gate-primary-btn {
  width: 100%;
  height: 54px;
  border: none;
  border-radius: 999px;
  background: var(--ap-olive);
  color: #fff;
  font-family: var(--ap-font);
  font-size: 16px;
  font-weight: 800;
  box-shadow: none;
  transition: transform .16s ease, opacity .16s ease;
}
body.theme-night #quran-offline-gate .gate-primary-btn { color: #15160f; }
#quran-offline-gate .gate-primary-btn:active { transform: scale(.97); }
#quran-offline-gate .gate-primary-btn:disabled { opacity: .6; }

/* =========================================================================
   خيارات الآية (الشيت + بوب أبات الاستماع/المشاركة/الحفظ والملاحظة):
   بنفس هوية صفحة الصوتيات بالظبط — خلفية كريمية دافئة/داكنة، بطاقات بيضاء
   (أو داكنة ليلًا) بحواف دائرية وظل ناعم، لمسة ذهبية/زيتونية للتمييز،
   وخط Tajawal — بدل الألوان الزمردية/الذهبية وخط العرض القديم. الأربعة
   عناصر دي بقوا فوق ضمن قائمة عناصر --ap-* (أول الملف)؛ القواعد تحت بس
   بترجع خلفية الـ backdrop الشفافة الأصلية (بما إن دول مش صفحات كاملة
   overlay-fullpage زي باقي عناصر القائمة)، وتُلبس بطاقات/عناصر الشيت نفسه
   بألوان وخطوط صفحة الصوتيات
   ========================================================================= */
#ayah-overlay.overlay { background: rgba(6, 14, 11, .36); }
#ayah-listen-popup.tilawa-popup-overlay,
#ayah-share-popup.tilawa-popup-overlay { background: rgba(6, 14, 11, .55); }
#ayah-note-popup.ayah-note-popup-overlay { background: rgba(6, 14, 11, .68); }

/* -------- شيت خيارات الآية نفسه -------- */
#ayah-overlay .overlay-sheet { background: var(--ap-bg); }
#ayah-overlay .ayah-sheet-handle { background: var(--ap-line); }

/* نص الآية أعلى الشيت */
#ayah-overlay .ayah-modal-text {
  font-family: var(--font-quran);
  color: var(--ap-ink);
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  box-shadow: var(--ap-shadow);
}
#ayah-overlay .ayah-modal-text::before {
  background: var(--ap-gold);
  box-shadow: 0 0 9px var(--ap-gold-soft);
}

/* كل أزرار الخيارات عمومًا */
#ayah-overlay .option-btn { font-family: var(--ap-font); color: var(--ap-ink); }

/* بطاقات الإجراءات (استماع/ابدأ من هنا/علامة/ملاحظة...) */
#ayah-overlay .ayah-action-btn {
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
#ayah-overlay .ayah-action-btn.active {
  border: 0;
  box-shadow: none;
}
#ayah-overlay .ayah-action-icon { color: var(--ap-gold); }

/* عنوان "التفسير والترجمات" */
#ayah-overlay .ayah-tafsir-header {
  font-family: var(--ap-font);
  color: var(--ap-olive);
  border-bottom: 1px solid var(--ap-line);
}
#ayah-overlay .ayah-tafsir-header svg { color: var(--ap-gold); }

/* كبسولات التفسير/الترجمات — نفس الشكل الدائري وخط تجاول، وألوانها
   الباستيل الأصلية اتسابت لتمييز كل قسم عن التاني، بس الحدّ الفاصل وظل
   التفعيل بقوا بنفس لمسة صفحة الصوتيات */
#ayah-overlay .ayah-tafsir-pill { font-family: var(--ap-font); border-radius: 16px; }
#ayah-overlay .ayah-tafsir-pill.active { box-shadow: 0 4px 12px var(--ap-line); }

/* كبسولات التنقل الأفقي بين لوحات الاستكشاف */
#ayah-overlay .ayah-tab-pill {
  font-family: var(--ap-font);
  background: var(--ap-card);
  border-color: var(--ap-line);
  color: var(--ap-ink);
}
#ayah-overlay .ayah-tab-pill.active {
  background: var(--ap-olive);
  border-color: var(--ap-olive);
  color: #fff;
}

/* -------- بوب أبات "خيارات التلاوة" و"خيارات المشاركة" -------- */
#ayah-listen-popup .overlay-sheet,
#ayah-share-popup .overlay-sheet { background: var(--ap-bg); }
#ayah-listen-popup .tilawa-popup-handle,
#ayah-share-popup .tilawa-popup-handle { background: var(--ap-line); }

#ayah-listen-popup .tilawa-popup-close,
#ayah-share-popup .tilawa-popup-close {
  background: var(--ap-olive-soft);
  color: var(--ap-ink);
}
#ayah-listen-popup .tilawa-popup-close:active,
#ayah-share-popup .tilawa-popup-close:active { background: var(--ap-line); }

#ayah-listen-popup .tilawa-popup-titles h3,
#ayah-share-popup .tilawa-popup-titles h3 {
  font-family: var(--ap-font);
  color: var(--ap-olive);
}
#ayah-listen-popup .tilawa-popup-titles p,
#ayah-share-popup .tilawa-popup-titles p {
  font-family: var(--ap-font);
  color: var(--ap-ink-2);
}
#ayah-listen-popup .tilawa-popup-emblem,
#ayah-share-popup .tilawa-popup-emblem {
  background: var(--ap-gold);
  color: #fff;
  box-shadow: 0 4px 12px var(--ap-gold-soft);
}

#ayah-listen-popup .tilawa-popup-card,
#ayah-share-popup .tilawa-popup-card {
  background: var(--ap-card);
  border: 1px solid var(--ap-line);
  border-radius: 18px;
  box-shadow: var(--ap-shadow);
}
#ayah-listen-popup .tilawa-popup-row,
#ayah-share-popup .tilawa-popup-row { font-family: var(--ap-font); }
#ayah-listen-popup .tilawa-popup-row:active,
#ayah-share-popup .tilawa-popup-row:active { background: var(--ap-olive-soft); }
#ayah-listen-popup .tilawa-popup-row-text,
#ayah-share-popup .tilawa-popup-row-text { color: var(--ap-ink); }
#ayah-listen-popup .tilawa-popup-row-icon,
#ayah-share-popup .tilawa-popup-row-icon { color: var(--ap-gold); }
#ayah-listen-popup .tilawa-popup-row-chevron,
#ayah-share-popup .tilawa-popup-row-chevron { color: var(--ap-ink-3); }
#ayah-listen-popup .tilawa-popup-divider,
#ayah-share-popup .tilawa-popup-divider { background: var(--ap-line); }

#ayah-listen-popup .tilawa-popup-more,
#ayah-share-popup .tilawa-popup-more {
  background: var(--ap-olive);
  color: #fff;
  box-shadow: 0 6px 16px rgba(80, 76, 50, .3);
}
#ayah-listen-popup .tilawa-popup-more .tilawa-popup-row-chevron,
#ayah-share-popup .tilawa-popup-more .tilawa-popup-row-chevron { color: #fff; }
#ayah-share-popup .tilawa-popup-back { font-family: var(--ap-font); color: var(--ap-ink-2); }

/* -------- بوب أب حفظ علامة / ملاحظة على الآية -------- */
#ayah-note-popup .overlay-sheet { background: var(--ap-card); }
#ayah-note-popup .overlay-head h3 { font-family: var(--ap-font); color: var(--ap-olive); }
#ayah-note-popup .panel-text,
#ayah-note-popup .panel-text.muted { font-family: var(--ap-font); color: var(--ap-ink-2); }
#ayah-note-popup .text-input {
  font-family: var(--ap-font);
  color: var(--ap-ink);
  background: var(--ap-bg);
  border: 1px solid var(--ap-line);
  border-radius: 14px;
}
#ayah-note-popup .text-input:focus { outline: 2px solid var(--ap-gold); }
#ayah-note-popup .btn-primary {
  background: var(--ap-olive);
  color: #fff;
  font-family: var(--ap-font);
  box-shadow: 0 4px 12px rgba(80, 76, 50, .25);
}
body.theme-night #ayah-note-popup .btn-primary { color: #15160f; }

/* =========================================================================
   نافذة "تحديد المقطع" (تُفتح من زر "المزيد من خيارات الاستماع" في بوب أب
   "خيارات التلاوة" فوق شيت الآية): نفس هوية صفحة الصوتيات بالظبط — بطاقات
   بيضاء (أو داكنة ليلًا) بحواف دائرية وظل ناعم، لمسة زيتونية/ذهبية للتمييز،
   وخط Tajawal — بدل الألوان والخطوط القديمة المستخدمة في نافذة "إضافة
   مقطع" الأصلية اللي بتشارك معاها نفس الأصناف. الصفحة بقت فوق ضمن قائمة
   عناصر --ap-* (أول الملف)، والقواعد دي بس بتُلبس عناصرها الخاصة
   ========================================================================= */
#listen-segment-overlay .overlay-head h3 {
  font-family: var(--ap-font);
  font-weight: 800;
  color: var(--ap-olive);
  font-size: 19px;
}
#listen-segment-overlay .icon-btn {
  background: var(--ap-olive-soft);
  color: var(--ap-ink);
}
