/* بطاقات مربعة لطبعات المصحف */
#mushaf-editions-overlay .editions-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.ed-row {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  min-width: 0;
  aspect-ratio: 1;
  padding: 12px;
  overflow: hidden;
  border: 1px solid var(--ap-line);
  border-radius: 20px;
  background: var(--ap-card);
  box-shadow: var(--ap-shadow);
  text-align: center;
}
.ed-row.is-current { border-color: var(--ap-olive); box-shadow: 0 0 0 1px var(--ap-olive), var(--ap-shadow); }
.ed-cover {
  position: relative;
  flex-shrink: 0;
  width: 58px; height: 58px;
  border-radius: 15px;
  background: linear-gradient(140deg, var(--ed-c1, #24573b), var(--ed-c2, #0f2b1c));
  box-shadow: 0 5px 12px rgba(40, 30, 10, .2), inset 2px 0 0 rgba(255, 255, 255, .14);
}
.ed-cover::before {
  content: '';
  position: absolute; inset: 5px;
  border: 1.5px solid #C9A24B;
  border-radius: 11px;
  opacity: .9;
}
.ed-cover::after {
  content: '';
  position: absolute; top: 50%; left: 50%;
  width: 23px; height: 23px;
  transform: translate(-50%, -50%);
  border: 1.5px solid #E3C170;
  border-radius: 7px;
  background: radial-gradient(circle at 50% 50%, rgba(227, 193, 112, .5) 0 18%, transparent 21%);
}
.ed-cover.green { --ed-c1: #24573b; --ed-c2: #0f2b1c; }
.ed-cover.black { --ed-c1: #1c2320; --ed-c2: #070a09; }
.ed-cover.red   { --ed-c1: #7a1f24; --ed-c2: #3a0a0d; }
.ed-cover.navy  { --ed-c1: #1f2f57; --ed-c2: #0c1430; }

.ed-row .ap-row-text { flex: 0 0 auto; width: 100%; min-height: 34px; justify-content: center; }
.ed-name { display: -webkit-box; width: 100%; overflow: hidden; color: var(--ap-ink); font-size: 13px; line-height: 1.35; text-align: center; text-overflow: ellipsis; white-space: normal; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.ed-btn {
  flex: 0 0 auto;
  width: 100%;
  min-height: 34px;
  padding: 5px 8px;
  border: 1px solid var(--ap-olive);
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ap-olive);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
  transition: transform .12s, filter .2s;
}
body.theme-night .ed-btn { color: #15160f; }
.ed-btn.is-current { border-color: var(--ap-olive-soft); background: var(--ap-olive-soft); color: var(--ap-olive); }
body.theme-night .ed-btn.is-current { color: var(--ap-ink); }
.ed-btn:active { transform: scale(.96); filter: brightness(.96); }
.ed-btn:disabled { cursor: default; }
.ed-btn:disabled:not(.is-loading) { opacity: .88; }
.ed-btn.is-loading { background: linear-gradient(to left, var(--ap-gold) var(--ed-p, 0%), var(--ap-olive) var(--ed-p, 0%)); font-size: 10px; }
@media (min-width: 620px) { #mushaf-editions-overlay .editions-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; } .ed-row { padding: 16px; } }
@media (max-width: 350px) { .ed-row { gap: 5px; padding: 9px; border-radius: 16px; } .ed-cover { width: 52px; height: 52px; } .ed-name { font-size: 11.5px; } .ed-btn { min-height: 31px; font-size: 11px; } }

