#view-tools #btn-menu-khatma-card .khatma-reference-text { top: 8% !important; height: 50% !important; gap: clamp(5px, 1.4cqi, 9px) !important; justify-content: center !important; overflow: visible !important; }
#view-tools #btn-menu-khatma-card #khatma-home-card-name,
