#view-tools #btn-menu-khatma-card .khatma-reference-sub { flex: 0 0 auto !important; margin: 0 !important; font-size: clamp(10px, 2.5cqi, 15px) !important; line-height: 1.3 !important; }
#view-tools #btn-menu-khatma-card .khatma-reference-progress { top: 65% !important; }
