/* مساحة مضغوطة لكارت الصلاة تحافظ على العنوان والمدينة والعدّاد كاملين. */
#view-tools #btn-menu-prayer-widget {
  display: grid !important;
  grid-template-rows: auto auto minmax(0, 1fr) auto !important;
  justify-items: center;
  align-content: stretch;
  gap: 0 !important;
  padding: clamp(10px, 2.6vw, 16px) 12px 14px !important;
}
#view-tools #btn-menu-prayer-widget .prayer-mini-top { margin: 0 !important; gap: 5px !important; }
#view-tools #btn-menu-prayer-widget #home-mini-city-name {
  flex: 0 0 auto !important;
  align-self: center !important;
  min-height: 0 !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 2px !important;
  line-height: 1.15 !important;
}
#view-tools #btn-menu-prayer-widget .prayer-mini-mid {
  align-self: stretch;
  justify-content: center;
  gap: clamp(4px, 1vw, 7px) !important;
  padding-top: clamp(7px, 1.5vw, 12px);
}
#view-tools #btn-menu-prayer-widget .prayer-mini-countdown {
  align-self: center;
  max-width: 100%;
  margin: 0 !important;
  padding: 4px 8px !important;
  line-height: 1.2;
}
#view-tools .home-row-60-40 .home-quiz-cta {
  bottom: 6%;
  box-shadow: 0 5px 14px rgba(0,0,0,.16);
}
#view-tools .khatma-reference-continue {
  box-shadow: 0 6px 15px rgba(54,79,55,.14);
}

body.theme-night #view-tools #btn-menu-prayer-widget #home-mini-city-name {
  color: var(--gold-soft) !important;
}

/* التنقل من البار السفلي يكتفي بتلاشي سريع؛ بقية الفتح والإغلاق رأسيان. */
@keyframes app-page-fade-enter {
  from { opacity: 0; }
  to { opacity: 1; }
}
.view.view-fade-enter-active {
  animation: app-page-fade-enter 120ms ease-out both;
}
#view-tools.view-fade-enter-active { animation: none !important; }
#view-tools.view-fade-enter-active .tools-page {
  animation: app-page-fade-enter 120ms ease-out both;
}
.overlay.overlay-bottom-bar-fade {
  opacity: 1 !important;
  transition: none !important;
  animation: app-page-fade-enter 120ms ease-out both;
}
.overlay.overlay-fullpage.overlay-bottom-bar-fade {
  transform: translate3d(0, 0, 0) !important;
}
.overlay.overlay-bottom-bar-fade::before { transition: none !important; }
/* مسافة بسيطة بين وقت الصلاة وكبسولة العدّاد في بطاقة الصفحة الرئيسية. */
#view-tools #btn-menu-prayer-widget .prayer-mini-countdown {
  position: relative;
  top: 3px;
}
/* تسميات البوتومبار أوضح بوزن متوسط، والزر النشط أقرب لجاره من غير فراغ كبير. */
.tools-bottom-bar > .tools-bar-btn > span:last-child,
.mushaf-quick-bar > .tools-bar-btn > span:last-child {
  font-weight: 600;
}
.tools-bottom-bar > .tools-bar-btn.active,
.mushaf-quick-bar > .tools-bar-btn.active {
  flex: 1.65 1 0;
  gap: 3px;
}

/* صفحة مباشر: واجهة تحريرية جديدة وقائمة محطات أفقية بدل شبكة الكروت المزخرفة. */
#view-live {
  --live-forest: #213E32;
  --live-forest-2: #315744;
  --live-forest-3: #496A50;
  --live-surface: var(--ap-card, #fff);
  --live-line: color-mix(in srgb, var(--ap-olive, #6F7752) 16%, transparent);
  --live-soft-ink: var(--ap-ink-2, #777568);
  --live-gold: #D8B66A;
}
body.theme-night #view-live {
  --live-forest: #202B25;
  --live-forest-2: #2C3B31;
  --live-forest-3: #52634A;
  --live-surface: #23251F;
  --live-line: rgba(255,255,255,.1);
  --live-soft-ink: #B4B3A8;
  --live-gold: #D9C17E;
}
#view-live .list-page.live-radio-page {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 100%;
  padding: calc(12px + env(safe-area-inset-top, 0px)) 18px calc(104px + env(safe-area-inset-bottom, 0px));
  background: var(--ap-bg, var(--paper)) !important;
  overflow-x: hidden;
}
#view-live .live-radio-deco { display: none !important; }
#view-live .page-topbar { margin: 0 0 8px; }
#view-live .page-close-btn {
  width: 38px;
  height: 38px;
  border: 1px solid var(--live-line);
  border-radius: 13px;
  background: var(--live-surface);
  color: var(--ap-ink);
  box-shadow: 0 3px 12px rgba(31,43,32,.07);
}
#view-live .live-radio-head {
  padding: 5px 2px 18px;
  text-align: right;
}
#view-live .live-radio-eyebrow {
  display: inline-flex;
  margin: 0 0 10px;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: var(--ap-olive);
  font-size: 11px;
  font-weight: 800;
}
body.theme-night #view-live .live-radio-eyebrow { color: var(--live-gold); }
#view-live .live-radio-eyebrow-dot { width: 7px; height: 7px; }
#view-live .live-radio-title {
  margin: 0 0 5px;
  color: var(--ap-ink);
  font-size: clamp(25px, 6.8vw, 33px);
  line-height: 1.25;
  letter-spacing: -.45px;
}
#view-live .live-radio-subtitle {
  max-width: 420px;
  margin: 0;
  color: var(--live-soft-ink);
  font-size: 12px;
  line-height: 1.7;
}

/* لوحة افتتاحية خضراء داكنة تعطي الصفحة هوية مختلفة عن بقية صفحات البطاقات. */
#view-live .live-radio-feature {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 142px;
  margin: 0 0 18px;
  padding: 18px 20px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 25px;
  color: #F8F5E9;
  background: linear-gradient(120deg, var(--live-forest), var(--live-forest-2) 70%, var(--live-forest-3));
  box-shadow: 0 15px 30px rgba(32,58,43,.16);
}
#view-live .live-radio-feature::before,
#view-live .live-radio-feature::after {
  content: '';
  position: absolute;
  z-index: -1;
  border: 1px solid rgba(222,196,127,.14);
  border-radius: 50%;
  pointer-events: none;
}
#view-live .live-radio-feature::before { width: 215px; height: 215px; inset-inline-end: -67px; top: -112px; }
#view-live .live-radio-feature::after { width: 160px; height: 160px; inset-inline-end: -40px; top: -85px; }
#view-live .live-radio-feature-copy { position: relative; z-index: 1; min-width: 0; }
#view-live .live-radio-feature-kicker {
  display: block;
  margin-bottom: 7px;
  color: var(--live-gold);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .15px;
}
#view-live .live-radio-feature-copy h3 {
  max-width: 265px;
  margin: 0 0 13px;
  color: #fffdf6;
  font: 850 clamp(17px, 4.8vw, 22px)/1.45 var(--ap-font);
}
#view-live .live-radio-feature-meta { display: flex; flex-wrap: wrap; gap: 7px; }
#view-live .live-radio-feature-meta > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 25px;
  padding: 3px 9px;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 999px;
  color: rgba(255,255,255,.84);
  background: rgba(255,255,255,.075);
  font-size: 10px;
  font-weight: 700;
}
#view-live .live-radio-feature-meta i { width: 6px; height: 6px; border-radius: 50%; background: #E36F61; box-shadow: 0 0 0 4px rgba(227,111,97,.15); }
#view-live .live-radio-feature-art {
  position: relative;
  display: grid;
  flex: 0 0 116px;
  width: 116px;
  height: 116px;
  place-items: center;
  margin-inline-start: 8px;
}
#view-live .live-radio-feature-orbit {
  position: absolute;
  border: 1px solid rgba(230,207,151,.3);
  border-radius: 50%;
}
#view-live .live-radio-feature-orbit-a { inset: 4px; }
#view-live .live-radio-feature-orbit-b { inset: 17px; border-style: dashed; opacity: .75; }
#view-live .live-radio-feature-icon {
  display: grid;
  width: 61px;
  height: 61px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 20px;
  color: var(--live-gold);
  background: rgba(255,255,255,.09);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.13), 0 8px 22px rgba(0,0,0,.12);
  transform: rotate(-8deg);
}
#view-live .live-radio-feature-icon svg { width: 33px; height: 33px; }
#view-live .live-radio-feature-wave {
  position: absolute;
  inset-inline-end: -1px;
  bottom: 19px;
  display: flex;
  align-items: center;
  gap: 3px;
  height: 24px;
  transform: rotate(-8deg);
}
#view-live .live-radio-feature-wave i { width: 3px; border-radius: 5px; background: #F0D99B; opacity: .9; }
#view-live .live-radio-feature-wave i:nth-child(1),
#view-live .live-radio-feature-wave i:nth-child(7) { height: 7px; }
#view-live .live-radio-feature-wave i:nth-child(2),
#view-live .live-radio-feature-wave i:nth-child(6) { height: 13px; }
#view-live .live-radio-feature-wave i:nth-child(3),
#view-live .live-radio-feature-wave i:nth-child(5) { height: 19px; }
#view-live .live-radio-feature-wave i:nth-child(4) { height: 24px; }

/* المشغل يظهر كلوحة مستقلة واضحة بعد اختيار محطة. */
#view-live .live-now-playing {
  min-height: 72px;
  gap: 12px;
  margin: 0 0 22px;
  padding: 10px 13px;
  border: 1px solid var(--live-line);
  border-radius: 18px;
  color: var(--ap-ink);
  background: var(--live-surface);
  box-shadow: 0 8px 22px rgba(33,45,31,.07);
}
#view-live .live-now-playing-art { width: 48px; height: 48px; flex-basis: 48px; border-radius: 14px; background: var(--ap-olive-soft); color: var(--ap-olive); box-shadow: none; }
#view-live .live-now-playing-art img { background: #fff; }
#view-live .live-now-playing-label { color: var(--ap-olive); font-size: 10px; font-weight: 800; }
#view-live .live-now-playing-name { color: var(--ap-ink); font-size: 14px; }
#view-live .live-now-playing-vis { flex-basis: 68px; height: 30px; color: var(--ap-olive); }
#view-live .live-now-playing-vis span { background: var(--ap-olive); }
#view-live .live-now-playing-btn { width: 40px; height: 40px; color: white; background: var(--live-forest-2); box-shadow: none; }
body.theme-night #view-live .live-now-playing-btn { color: #172019; background: var(--live-gold); }

#view-live .live-radio-list-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin: 0 1px 11px;
}
#view-live .live-radio-list-kicker { display: block; margin-bottom: 2px; color: var(--ap-olive); font-size: 10px; font-weight: 800; }
#view-live .live-radio-list-heading h3 { margin: 0; color: var(--ap-ink); font: 850 19px/1.35 var(--ap-font); }
#view-live .live-radio-station-count {
  flex: 0 0 auto;
  padding: 6px 10px;
  border: 1px solid var(--live-line);
  border-radius: 999px;
  color: var(--live-soft-ink);
  background: var(--live-surface);
  font: 700 10px/1.2 var(--ap-font);
}
#view-live .live-radio-station-count b { margin-inline-end: 3px; color: var(--ap-olive); font-weight: 900; }
#view-live .live-radio-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  gap: 9px;
}
#view-live .live-radio-card {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) 42px;
  grid-template-rows: minmax(56px, auto);
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 82px;
  padding: 10px 12px;
  overflow: hidden;
  border: 1px solid var(--live-line);
  border-radius: 19px;
  color: var(--ap-ink);
  background: var(--live-surface);
  box-shadow: 0 5px 15px rgba(33,45,31,.045);
  text-align: start;
  direction: rtl;
  transition: transform .16s ease, border-color .18s ease, box-shadow .18s ease, background .18s ease;
}
#view-live .live-radio-card-banner { display: none; }
#view-live .live-radio-card-art {
  grid-column: 1;
  grid-row: 1;
  width: 56px;
  height: 56px;
  max-width: none;
  border: 1px solid rgba(60,70,45,.09);
  border-radius: 16px;
  background: #fff;
  box-shadow: none;
}
#view-live .live-radio-card-body { grid-column: 2; grid-row: 1; width: auto; margin: 0; text-align: right; }
#view-live .live-radio-card-name {
  display: block;
  overflow: hidden;
  color: var(--ap-ink);
  font-size: 14px;
  font-weight: 850;
  line-height: 1.5;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#view-live .live-radio-card-desc { display: block; margin-top: 3px; color: var(--live-soft-ink); font: 600 10px/1.4 var(--ap-font); }
#view-live .live-radio-card-play {
  position: static;
  grid-column: 3;
  grid-row: 1;
  width: 40px;
  height: 40px;
  border: 1px solid color-mix(in srgb, var(--ap-olive) 17%, transparent);
  border-radius: 14px;
  color: var(--ap-olive);
  background: var(--ap-olive-soft);
  box-shadow: none;
}
#view-live .live-radio-card-play svg { width: 15px; height: 15px; }
#view-live .live-radio-card.playing {
  border-color: color-mix(in srgb, var(--ap-olive) 50%, var(--live-line));
  background: color-mix(in srgb, var(--ap-olive-soft) 45%, var(--live-surface));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--ap-olive) 14%, transparent), 0 8px 20px rgba(33,45,31,.07);
}
#view-live .live-radio-card.playing .live-radio-card-play { color: #fff; background: var(--live-forest-2); }
body.theme-night #view-live .live-radio-card.playing .live-radio-card-play { color: #192019; background: var(--live-gold); }
#view-live .live-radio-card-badge {
  top: 7px;
  inset-inline-start: 8px;
  left: auto;
  transform: none;
  height: 19px;
  padding: 0 7px;
  color: #fff;
  background: #BD4C42;
  box-shadow: none;
  font-size: 8px;
}
body.theme-night #view-live .live-radio-card-badge { color: #fff; }
#view-live .live-radio-card-dot { width: 5px; height: 5px; }
