/* لوحة التحكم العمودية الحديثة للتمرير التلقائي، مثبتة على الشاشة كي لا
   تقصّها حاوية شريط المصحف أو حافة الجهاز. */
.autoscroll-speed-pill {
  position: fixed;
  z-index: 12000;
  width: 56px;
  max-height: calc(100dvh - 24px);
  padding: 11px 0 8px;
  border: 1px solid color-mix(in srgb, var(--olive) 24%, transparent);
  border-radius: 24px;
  background: color-mix(in srgb, var(--paper) 90%, white);
  color: var(--olive-deep);
  box-shadow: 0 12px 30px color-mix(in srgb, var(--shadow) 28%, transparent), inset 0 1px 0 rgba(255,255,255,.8);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
.autoscroll-speed-track { background: color-mix(in srgb, var(--olive) 18%, white); }
.autoscroll-speed-fill { background: var(--olive); }
.autoscroll-speed-thumb { border-color: var(--olive); }
.autoscroll-speed-divider { background: color-mix(in srgb, var(--olive) 24%, transparent); }
.autoscroll-playpause-btn { color: var(--olive-deep); }
body.theme-night .autoscroll-speed-pill { background: rgba(38,42,32,.95); color: var(--gold-soft); border-color: rgba(214,193,123,.24); }
body.theme-night .autoscroll-speed-track { background: rgba(255,255,255,.14); }
body.theme-night .autoscroll-speed-fill { background: var(--gold-soft); }
body.theme-night .autoscroll-speed-thumb { background: #292c22; border-color: var(--gold-soft); }
body.theme-night .autoscroll-playpause-btn { color: var(--gold-soft); }

/* لوحة سرعة صغيرة قابلة للطي؛ زر التشغيل يبقى ظاهرًا بجانبها أثناء القراءة. */
#mushaf-fab-autoscroll.is-active { background: color-mix(in srgb, var(--olive) 18%, var(--paper)); color: var(--olive-deep); }
.autoscroll-speed-pill {
  width: 44px;
  min-height: 0;
  max-height: calc(100dvh - 24px);
  gap: 6px;
  padding: 6px 0;
  border-radius: 17px;
  overflow: hidden;
  transition: width .2s ease, padding .2s ease, border-radius .2s ease;
}
.autoscroll-collapse-btn {
  display: grid;
  place-items: center;
  width: 26px;
  height: 22px;
  flex: 0 0 22px;
  padding: 0;
  border: 0;
  border-radius: 10px;
  background: color-mix(in srgb, var(--olive) 10%, transparent);
  color: inherit;
  cursor: pointer;
}
.autoscroll-collapse-btn svg { width: 15px; height: 15px; transition: transform .2s ease; }
.autoscroll-speed-track { width: 5px; height: 72px; flex: 0 0 72px; }
.autoscroll-speed-thumb { width: 14px; height: 14px; left: 50%; transform: translate(-50%, 50%); }
.autoscroll-speed-num { font-size: 11px; }
.autoscroll-speed-divider { width: 18px; margin: 0; }
.autoscroll-playpause-btn { width: 27px; height: 27px; min-width: 27px; min-height: 27px; }
.autoscroll-playpause-btn svg { width: 13px; height: 13px; }
.autoscroll-speed-pill.is-collapsed { width: 32px; gap: 5px; padding: 5px 0; border-radius: 15px; }
.autoscroll-speed-pill.is-collapsed .autoscroll-collapse-btn { width: 22px; }
.autoscroll-speed-pill.is-collapsed .autoscroll-collapse-btn svg { transform: rotate(180deg); }
.autoscroll-speed-pill.is-collapsed .autoscroll-speed-num,
.autoscroll-speed-pill.is-collapsed .autoscroll-speed-track,
.autoscroll-speed-pill.is-collapsed .autoscroll-speed-divider { display: none; }
.autoscroll-speed-pill.is-collapsed .autoscroll-playpause-btn { width: 23px; height: 23px; min-width: 23px; min-height: 23px; }
body.theme-night #mushaf-fab-autoscroll.is-active { background: rgba(214,193,123,.16); color: var(--gold-soft); }
@media (prefers-reduced-motion: reduce) {
  .autoscroll-speed-pill, .autoscroll-collapse-btn svg { transition: none; }
}

/* الجولة التعريفية الجديدة: إرشاد قصير بخمس محطات، وبطاقة واحدة هادئة
   تتكيّف مع الهاتف والتابلت وسطح المكتب. */
#feature-tour-overlay { background: rgba(20,24,18,.48) !important; backdrop-filter: blur(5px) !important; -webkit-backdrop-filter: blur(5px) !important; }
.feature-tour-spotlight { border: 1.5px solid color-mix(in srgb, var(--olive) 70%, var(--gold)); border-radius: 18px; box-shadow: 0 0 0 100vmax rgba(23,28,20,.58), 0 0 0 5px rgba(251,246,231,.76), 0 8px 28px rgba(0,0,0,.16); }
.feature-tour-dialog {
  width: min(390px, calc(100vw - 28px));
  max-height: min(330px, calc(100dvh - 28px));
  padding: 20px 22px 16px;
  border: 1px solid color-mix(in srgb, var(--olive) 22%, var(--gold) 34%);
  border-radius: 26px;
  background: linear-gradient(145deg, #fffefa 0%, #fbf8ef 72%, #f3f0e5 100%);
  box-shadow: 0 22px 64px rgba(19,27,18,.28), inset 0 1px 0 rgba(255,255,255,.9);
  direction: rtl;
  text-align: right;
}
.feature-tour-close { top: 14px; inset-inline-end: 14px; width: 34px; height: 34px; border-radius: 12px; }
.feature-tour-brand, .feature-tour-dialog > h2, .feature-tour-intro { display: none; }
.feature-tour-slides { min-height: 160px; align-items: center; }
.feature-tour-slide { padding: 8px 2px 14px; text-align: center; }
.feature-tour-icon { width: 58px; height: 58px; margin: 0 auto 12px; border-radius: 19px; background: linear-gradient(145deg, color-mix(in srgb, var(--olive) 12%, white), color-mix(in srgb, var(--gold) 18%, white)); color: var(--olive-deep); box-shadow: inset 0 1px 0 rgba(255,255,255,.9); }
.feature-tour-icon svg { width: 29px; height: 29px; }
.feature-tour-slide h3 { margin: 0 0 6px; color: var(--olive-deep); font-size: 19px; }
.feature-tour-slide p { max-width: 320px; font-size: 13.5px; line-height: 1.75; }
.feature-tour-progress { height: 4px; margin: 2px 0 14px; background: color-mix(in srgb, var(--olive) 12%, white); }
.feature-tour-progress span { background: linear-gradient(90deg, var(--olive-deep), color-mix(in srgb, var(--gold) 74%, var(--olive))); }
.feature-tour-step-label { margin: 0 0 10px; color: var(--gold-deep); font-size: 11px; }
.feature-tour-actions { gap: 9px; }
.feature-tour-actions button { min-height: 42px; border-radius: 14px; }
.feature-tour-back { min-width: 88px; }
.feature-tour-next { background: linear-gradient(135deg, #66774b, #4e603d); box-shadow: 0 7px 18px rgba(67,83,49,.2); }
.feature-tour-later { margin-top: 7px; padding: 6px 10px; }
body.theme-night .feature-tour-dialog { background: linear-gradient(145deg,#292b24,#20211c 74%); border-color: rgba(214,193,123,.25); }
body.theme-night .feature-tour-slide h3 { color: #d2d8b0; }
body.theme-night .feature-tour-icon { background: rgba(214,193,123,.12); color: var(--gold-soft); }
@media (max-width: 520px) {
  .feature-tour-dialog { width: calc(100vw - 24px); padding: 17px 17px 13px; border-radius: 23px; }
  .feature-tour-slides { min-height: 145px; }
  .feature-tour-slide p { font-size: 13px; }
}
@media (max-height: 560px) {
  .feature-tour-dialog { max-height: calc(100dvh - 16px); padding-block: 12px; }
  .feature-tour-slides { min-height: 112px; }
  .feature-tour-icon { width: 46px; height: 46px; margin-bottom: 7px; }
