/* Progressive intro كاملة الشاشة، ثم coach marks بسيطة تركز على عناصر محددة. */
#feature-tour-overlay.is-onboarding,
#feature-tour-overlay.is-coachmark {
  position: fixed !important;
  inset: 0 !important;
  z-index: 10000 !important;
  display: none;
  align-items: stretch !important;
  justify-content: center !important;
  padding: 0 !important;
  overflow: hidden !important;
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
#feature-tour-overlay.is-onboarding.open { display: flex !important; background: #fff !important; }
#feature-tour-overlay.is-onboarding .feature-tour-spotlight { display: none !important; }
#feature-tour-overlay.is-onboarding .feature-tour-dialog {
  position: relative !important; inset: auto !important; display: flex; flex-direction: column;
  width: 100% !important; max-width: 600px; height: 100dvh !important; max-height: 100dvh !important;
  margin: 0 auto; padding: max(20px, env(safe-area-inset-top)) clamp(24px, 7vw, 48px) max(18px, env(safe-area-inset-bottom)) !important;
