/* Every QCF-style page uses the reader viewport as a fixed fit box. The SVG
   viewBox remains authoritative and preserveAspectRatio="xMidYMid meet" fits
   the page without cropping or distortion. This keeps any unavoidable
   letterboxing balanced instead of leaving it as a large bottom-only gap. */
#mushaf-wrap:has(> #mushaf-page.qcf-page-image-layout) {
  display: block;
  width: 100%;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  touch-action: pan-y;
}
#mushaf-page.qcf-page-image-layout:not(.mushaf-neighbor-preview) {
  position: relative;
  inset: auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0;
  overflow: hidden;
  clip-path: none;
  transform: none;
}
#mushaf-wrap > #mushaf-page.qcf-page-image-layout.mushaf-neighbor-preview {
  position: absolute;
  inset: 0 auto auto 50%;
  width: 100%;
  height: 100%;
  min-height: 0;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0;
  overflow: hidden;
  clip-path: none;
}
#mushaf-page.qcf-page-image-layout #ayat-container {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}
#mushaf-page.qcf-page-image-layout :is(.qcf-page-image-svg, .warsh-svg-page, .riwaya-svg-page) {
  display: block;
  width: auto !important;
  height: 96% !important;
  max-width: 100%;
  max-height: 96% !important;
  margin: 0;

}
/* Keep page and hizb references visible for full-page SVG editions. The
   footer takes its own flex row so it never covers the final Quran line. */
#mushaf-page.qcf-page-image-layout #page-foot-bar {
  display: flex !important;
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  box-sizing: border-box;
  min-height: 30px;
  margin-top: 0;
  padding: 4px 12px max(6px, env(safe-area-inset-bottom));
  font-size: 12px;
}
#mushaf-page.qcf-page-image-layout #ayat-container {
  height: auto !important;
  flex: 1 1 auto;
}
.autoscroll-page.qcf-page-image-layout :is(.qcf-page-image-svg, .warsh-svg-page, .riwaya-svg-page) {
  display: block;
  width: 100% !important;
  height: auto !important;
  max-width: 100%;
  max-height: none !important;
  margin: 0;
}

/* Wide reading layout: fill the viewport width without distorting or
   cropping the SVG. Tall page proportions continue in the vertical scroller. */
#mushaf-wrap:has(> #mushaf-page.qcf-page-image-layout) {
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior-y: contain;
}
#mushaf-page.qcf-page-image-layout:not(.mushaf-neighbor-preview),
#mushaf-wrap > #mushaf-page.qcf-page-image-layout.mushaf-neighbor-preview {
  display: flex;
  flex-direction: column;
  height: auto;
  min-height: 100%;
  max-height: none;
  overflow: visible;
}
#mushaf-page.qcf-page-image-layout #ayat-container {
  display: block;
  flex: 0 0 auto;
  height: auto !important;
  min-height: 0;
  overflow: visible;
}
#mushaf-page.qcf-page-image-layout :is(.qcf-page-image-svg, .warsh-svg-page, .riwaya-svg-page) {
  width: 100% !important;
  height: var(--qcf-svg-height, auto) !important;
  max-width: 100% !important;
  max-height: none !important;
}
#mushaf-page.qcf-page-image-layout #page-foot-bar {
  position: relative;
  inset: auto;
  z-index: 2;
  flex: 0 0 auto;
  width: auto;
  min-height: 30px;
  margin-top: auto;
  padding: 5px 14px max(6px, env(safe-area-inset-bottom));
  background: color-mix(in srgb, var(--paper) 90%, transparent);
  pointer-events: auto;
}
/* A small responsive gutter keeps Quran glyphs away from the screen edges. */
#mushaf-page.qcf-page-image-layout #ayat-container {
  padding-inline: clamp(8px, 1vw, 16px);
}

/* In portrait, phone drags turn pages on the selected axis. Landscape
   overrides this with native vertical scrolling and custom horizontal turns. */
@media (max-width: 768px) and (pointer: coarse) {
  #mushaf-wrap {
    touch-action: none;
  }
}

/* Landscape reading needs a slightly wider inner gutter than portrait. */
body.mushaf-landscape-mode #mushaf-page.qcf-page-image-layout #ayat-container {
  padding-inline: clamp(22px, 3vw, 42px);
}

/* حافظ على مسافة جانبية مريحة في الصفحات النصية أيضًا عند القراءة بالعرض؛
   fitMushafPage يخصم هذا الـ padding قبل حساب حجم الخط، فلا تُقص الأسطر. */
body.mushaf-landscape-mode #mushaf-page:not(.qcf-page-image-layout) {
  padding-inline: clamp(16px, 3vw, 40px);
}

/* Normalize imported Warsh/Qalun drawings to the same viewport box. */
#mushaf-page.qcf-page-image-layout :is(.warsh-svg-page, .riwaya-svg-page) {
  width: 100% !important;
  height: var(--qcf-svg-height, auto) !important;
  max-width: 100% !important;
  max-height: none !important;
  transform: none !important;
}

/* Opening API pages keep their original image bounds and fit. */
#mushaf-page.qcf-page-image-layout #ayat-container:has(> svg.qcf-page-image-svg[data-mushaf-page="1"], > svg.qcf-page-image-svg[data-mushaf-page="2"]) {
  padding-inline: clamp(12px, 1.5vw, 20px);
}

/* Page turns are owned by the reader so the browser cannot claim a drag on
   the user's selected axis before the active page follows the finger. */
#mushaf-wrap { touch-action: none; }
body.mushaf-landscape-mode #mushaf-wrap { touch-action: pan-y; }

/* Tasmee Hafs pages use the QCF4 line/word stream directly. Keep this after
   the normal SVG reader rules: invisible words retain their exact layout. */
#mushaf-page.tasmee-qcf-page-layout #ayat-container {
  display: flex;
  flex: 1 1 auto;
  align-items: stretch;
  justify-content: center;
  width: 100%;
  height: auto !important;
  min-height: 0;
  overflow: hidden;
  padding-inline: clamp(8px, 1.2vw, 18px);
}
.tasmee-qcf-page {
  box-sizing: border-box;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  justify-content: center;
  width: 100%;
  height: 100%;
  min-height: 100%;
  padding-inline: clamp(8px, 2.4vw, 22px);
  overflow: hidden;
  color: var(--mushaf-ink, #171310);
  background: var(--paper, #fff);
}
.tasmee-qcf-line {
  box-sizing: border-box;
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  direction: rtl;
  white-space: nowrap;
  overflow: hidden;
  font-size: var(--tasmee-qcf-font-size, 24px);
  line-height: 1;
}
.tasmee-qcf-glyph {
  display: inline-block;
  flex: 0 0 auto;
  white-space: pre;
  line-height: 1;
}
.tasmee-qcf-word.tasmee-word-correct {
  background: rgba(47, 150, 93, .22);
  border-radius: 4px;
}
.tasmee-qcf-word.tasmee-word-wrong {
  background: rgba(214, 55, 55, .24);
  border-radius: 4px;
}
.tasmee-qcf-surah-header,
.tasmee-qcf-bismillah { justify-content: center; }
.tasmee-qcf-surah-header .tasmee-qcf-glyph { font-size: 1.18em; }
.tasmee-qcf-bismillah .tasmee-qcf-glyph { font-size: 1.08em; }
body.mushaf-landscape-mode #mushaf-page.tasmee-qcf-page-layout #ayat-container {
  height: auto !important;
  min-height: 0;
  overflow: visible;
}
body.mushaf-landscape-mode .tasmee-qcf-page {
  height: auto;
  min-height: 100%;
  justify-content: flex-start;
  overflow: visible;
}

